INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89625, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阻挡", "is_correct": true, "explanation": "阻挡：拦住道路，使车辆不能通过，与“一辆大车”和“前面的路”的情境相符。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：“帮助”的对象须是人，不能说帮助前面的路。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”需要有人作为对象，路不能被欢迎。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“前面的路”作宾语。"}], "explanations": {"阻挡": "阻挡：拦住道路，使车辆不能通过，与“一辆大车”和“前面的路”的情境相符。", "帮助": "语义：“帮助”的对象须是人，不能说帮助前面的路。", "欢迎": "语义：“欢迎”需要有人作为对象，路不能被欢迎。", "散步": "配价：“散步”是不及物动词，不能带“前面的路”作宾语。"}, "sentence_index": 0, "correct_answer": "阻挡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他阻挡了一场电影。", "explanation": "这里应该用〈看〉。阻挡指挡住去路，电影不能被阻挡，应说“看一场电影”。"}, {"text": "他阻挡了一封信。", "explanation": "这里应该用〈写〉。阻挡指挡住去路，信不能被阻挡，应说“写一封信”。"}, {"text": "他阻挡了一支歌。", "explanation": "这里应该用〈唱〉。阻挡指挡住去路，歌不能被阻挡，应说“唱一支歌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阻挡", "is_correct": true, "explanation": "阻挡：挡住去路，与“大雪”和“回家的路”的情境相符。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”的主语须是有感情的人，大雪不能怀念回家的路。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”的对象须是人或动物，不能照顾一条路。"}, {"text": "收获", "is_correct": false, "explanation": "搭配：“收获”多用于庄稼或成果，不能说收获“回家的路”。"}], "explanations": {"阻挡": "阻挡：挡住去路，与“大雪”和“回家的路”的情境相符。", "怀念": "语义：“怀念”的主语须是有感情的人，大雪不能怀念回家的路。", "照顾": "语义：“照顾”的对象须是人或动物，不能照顾一条路。", "收获": "搭配：“收获”多用于庄稼或成果，不能说收获“回家的路”。"}, "sentence_index": 6, "correct_answer": "阻挡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他阻挡了一盘菜。", "explanation": "这里应该用〈做〉。阻挡指挡住去路，菜不能被阻挡，应说“做一盘菜”。"}, {"text": "老师要阻挡学生的错误。", "explanation": "这里应该用〈纠正〉。阻挡指挡住有形的去路，改正学生的错误要用纠正。"}, {"text": "他阻挡了一张照片。", "explanation": "这里应该用〈拍〉。阻挡指挡住去路，照片不能被阻挡，应说“拍一张照片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89625, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这堵墙阻挡了住风沙。", "corrected_sentence": "这堵墙阻挡住了风沙。", "error_description": "错误：“阻挡了住”。结果补语“住”要紧跟动词，应为“阻挡住了”，表示墙把风沙挡住了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89625, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们没有阻挡了他的去路。", "corrected_sentence": "我们没有阻挡他的去路。", "error_description": "体标错误：“没有”表示否定，与“了”不能同用，应说“没有阻挡他的去路”，不能说“没有阻挡了他的去路”。错误在“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
