INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89627, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "村是农村里很多人家住在一起的地方。", "primary_collocate": null, "pronunciation": "cūn", "ipa": "tsʰwən˥", "syllable_count": 1, "sentences": [{"text": "这个村住着一百多户人家。", "target_word": "村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我奶奶住在村里。", "target_word": "村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村中间有一口老井。", "target_word": "村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个村隔着一座山。", "target_word": "村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里新修了一条路。", "target_word": "村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天,村里的孩子常去河边玩。", "target_word": "村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村有一所小学。", "target_word": "村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出了村,往城里走去。", "target_word": "村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进了村,我听到了狗叫声。", "target_word": "村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里种了很多苹果树。", "target_word": "村", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "村庄", "label": "复合"}, {"form": "农村", "label": "复合"}], "register": "中性", "sense_fingerprint": "农村里人家聚居之处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b6d23d-90ac-4dc8-9c4e-4b812c474339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89627, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "村", "is_correct": true, "explanation": "村（cūn）：农村里人家聚居的地方，即词目本身。"}, {"text": "春", "is_correct": false, "explanation": "chūn 与 cūn 的声母不同（ch 与 c），意思是春天。"}, {"text": "存", "is_correct": false, "explanation": "cún（第二声）与 cūn（第一声）声调不同，意思是保存。"}, {"text": "寸", "is_correct": false, "explanation": "cùn（第四声）与 cūn（第一声）声调不同，意思是长度单位“寸”。"}], "explanations": {"村": "村（cūn）：农村里人家聚居的地方，即词目本身。", "春": "chūn 与 cūn 的声母不同（ch 与 c），意思是春天。", "存": "cún（第二声）与 cūn（第一声）声调不同，意思是保存。", "寸": "cùn（第四声）与 cūn（第一声）声调不同，意思是长度单位“寸”。"}, "sentence_index": null, "correct_answer": "村"}, "level_3": {"options": [{"text": "公园", "is_correct": false, "explanation": "语义：公园不是住户聚居的地方，与“住着一百多户人家”矛盾。"}, {"text": "村", "is_correct": true, "explanation": "村：农村里人家聚居之处，与“住着一百多户人家”相符。"}, {"text": "寺庙", "is_correct": false, "explanation": "语义：寺庙不是住一百多户人家的地方。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“住着一百多户人家”只能用于居住地，不能说“桌子”住着人家。"}], "explanations": {"公园": "语义：公园不是住户聚居的地方，与“住着一百多户人家”矛盾。", "村": "村：农村里人家聚居之处，与“住着一百多户人家”相符。", "寺庙": "语义：寺庙不是住一百多户人家的地方。", "桌子": "搭配：“住着一百多户人家”只能用于居住地，不能说“桌子”住着人家。"}, "sentence_index": 0, "correct_answer": "村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村里林立着几十栋摩天大楼，夜晚灯火通明。", "explanation": "这里应该用〈城市〉。村是农民聚居的地方，不会林立着摩天大楼；这是城市的景观。"}, {"text": "这个村的路口红绿灯很多，车流不息。", "explanation": "这里应该用〈街道〉。村的道路少有红绿灯，车流密集、路口林立的景象是街道的特点。"}, {"text": "上海是一个有两千多万人口的大村。", "explanation": "这里应该用〈城市〉。村是农村里人家聚居的小地方，有两千多万人口的上海是城市，不是村。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89627, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的房间，不可能“有一所小学”。"}, {"text": "村", "is_correct": true, "explanation": "村：农村里人家聚居之处，村里有小学，与语境相符。"}, {"text": "监狱", "is_correct": false, "explanation": "语义：监狱里不会设置小学。"}, {"text": "车", "is_correct": false, "explanation": "搭配：“有一所小学”只能用于可以设置学校的地方，“车”不能与之搭配。"}], "explanations": {"厨房": "语义：厨房是做饭的房间，不可能“有一所小学”。", "村": "村：农村里人家聚居之处，村里有小学，与语境相符。", "监狱": "语义：监狱里不会设置小学。", "车": "搭配：“有一所小学”只能用于可以设置学校的地方，“车”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "村"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村的地下停车场能停放几百辆汽车。", "explanation": "这里应该用〈城市〉。村是农民聚居的地方，不会有能停放几百辆车的地下停车场；这是城市的设施。"}, {"text": "北京是中国的首都，是一个很大的村。", "explanation": "这里应该用〈城市〉。首都北京是大城市，村只指农村里人家聚居的地方。"}, {"text": "这个村的十字路口每到下班时都堵得水泄不通。", "explanation": "这里应该用〈街道〉。村的道路车流少，下班高峰堵塞的十字路口是街道的景象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89627, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那所村的河水很清。", "corrected_sentence": "那个村的河水很清。", "error_description": "错误：村的量词用了“所”，“所”用于学校、房屋等。应为“那个村”，村用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89627, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只村的小学很有名。", "corrected_sentence": "这个村的小学很有名。", "error_description": "错误：村的量词用了“只”，“只”用于动物。应为“这个村”，村用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
