INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89630, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向有关部门申诉意见或不满。", "primary_collocate": null, "pronunciation": "tóu sù", "ipa": "tʰou̯˧˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "他向消费者协会投诉了这家店。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以打电话投诉。", "target_word": "投诉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买到坏东西，可以向市场管理部门投诉。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居天天很吵，我已经向物业投诉了。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他投诉过这家公司三次。", "target_word": "投诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人向有关部门投诉这家工厂的噪音。", "target_word": "投诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅客向航空公司投诉行李丢了。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人投诉这家饭店太脏。", "target_word": "投诉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她写信向教育局投诉这所学校。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家长们到市政府投诉老师乱收费。", "target_word": "投诉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "投诉了", "label": "体标"}, {"form": "投诉过", "label": "体标"}, {"form": "投诉电话", "label": "复合"}], "register": "中性", "sense_fingerprint": "投诉：向有关部门申诉意见或不满", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '464d8e31-3b58-4903-948d-c22c693dcaf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投诉", "is_correct": true, "explanation": "投诉：向有关部门反映不满，与“消费者协会”和不满的情境相符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”是清理场所的动作，不能向协会去打扫一家店。"}, {"text": "批发", "is_correct": false, "explanation": "搭配：“批发”用于成批卖出的货物，不能说批发一家店。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，不能用来说对现成的店。"}], "explanations": {"投诉": "投诉：向有关部门反映不满，与“消费者协会”和不满的情境相符。", "打扫": "语义：“打扫”是清理场所的动作，不能向协会去打扫一家店。", "批发": "搭配：“批发”用于成批卖出的货物，不能说批发一家店。", "发明": "语义：“发明”指创造新事物，不能用来说对现成的店。"}, "sentence_index": 0, "correct_answer": "投诉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "王老师教得特别好，家长们向教育局投诉她。", "explanation": "这里应该用〈表扬〉。投诉表示对不好的事申诉不满，老师教得好应该表扬。"}, {"text": "他想买车，就向银行投诉了一笔贷款。", "explanation": "这里应该用〈申请〉。投诉指表达不满，为了买车向银行要贷款要用申请。"}, {"text": "我向老师投诉，作业已经全部做完了。", "explanation": "这里应该用〈报告〉。投诉指对不满的事表达意见，中性地说明作业完成的情况要用报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投诉", "is_correct": true, "explanation": "投诉：向有关部门反映不满，与“航空公司”和“行李丢了”的情境相符。"}, {"text": "尊重", "is_correct": false, "explanation": "语义：“尊重”的宾语须是人或权利，不能用于“行李丢了”这件事。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”的对象是文字或文件，不能删除“行李丢了”。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是庄稼，不能说收割行李。"}], "explanations": {"投诉": "投诉：向有关部门反映不满，与“航空公司”和“行李丢了”的情境相符。", "尊重": "语义：“尊重”的宾语须是人或权利，不能用于“行李丢了”这件事。", "删除": "语义：“删除”的对象是文字或文件，不能删除“行李丢了”。", "收割": "搭配：“收割”的对象是庄稼，不能说收割行李。"}, "sentence_index": 6, "correct_answer": "投诉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把全部精力投诉到学习中。", "explanation": "这里应该用〈投入〉。投诉指向有关部门表达不满，把精力放到某件事上要用投入。"}, {"text": "小明向池塘里投诉了一块石头。", "explanation": "这里应该用〈投掷〉。投诉指表达意见，把东西扔出去要用投掷。"}, {"text": "球员在比赛中投诉了三个球。", "explanation": "这里应该用〈投进〉。投诉指表达不满，把球投进篮筐要用投进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想向物业投诉了楼下的噪音。", "corrected_sentence": "我想向物业投诉楼下的噪音。", "error_description": "错误：“投诉了”。“想”表示打算，动作尚未发生，不能加“了”，应为“我想向物业投诉楼下的噪音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们可以向平台投诉了这家网店。", "corrected_sentence": "我们可以向平台投诉这家网店。", "error_description": "错误：“投诉了”。“可以”表示可能或许可，动作尚未完成，不能在动词后加“了”，应为“我们可以向平台投诉这家网店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89631, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89631, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89631, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "陷阱是挖好的坑，人或动物不小心会掉进去。", "primary_collocate": null, "pronunciation": "xiàn jǐng", "ipa": "ɕjɛn˥˩ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "山上有一个陷阱。", "target_word": "陷阱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小马不小心掉进了陷阱。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猎人在路边挖了一个陷阱。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个陷阱又深又大。", "target_word": "陷阱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老虎掉进陷阱，出不来了。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走路的时候要小心，草丛里可能有陷阱。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸用树叶盖住了陷阱。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们不要去山里玩，那里有陷阱。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在田边挖陷阱，想抓野猪。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗掉进陷阱里，大家用绳子把它拉了上来。", "target_word": "陷阱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "挖好的坑，人或动物会掉进去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '898186d7-746b-41f1-9872-48aa0b237dc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89631, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陷阱", "is_correct": true, "explanation": "山上设置挖好的坑，“陷阱”符合语境。"}, {"text": "主意", "is_correct": false, "explanation": "语义：主意是想法，是抽象的，不能说“山上有一个主意”。"}, {"text": "意见", "is_correct": false, "explanation": "语义：意见是抽象的看法，不能存在于山上，“山上有一个意见”不成立。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，“山上有一个饺子”不合常理。"}], "explanations": {"陷阱": "山上设置挖好的坑，“陷阱”符合语境。", "主意": "语义：主意是想法，是抽象的，不能说“山上有一个主意”。", "意见": "语义：意见是抽象的看法，不能存在于山上，“山上有一个意见”不成立。", "饺子": "语义：饺子是食物，“山上有一个饺子”不合常理。"}, "sentence_index": 0, "correct_answer": "陷阱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在院子里挖了一个陷阱，准备种树。", "explanation": "这里应该用〈坑〉。陷阱是为捕捉动物而设的，种树要挖坑，不能说“挖陷阱种树”。"}, {"text": "小老鼠住在墙角的一个陷阱里。", "explanation": "这里应该用〈洞〉。陷阱不是住所，老鼠住的是洞。"}, {"text": "村里的陷阱很深，大家用桶打水。", "explanation": "这里应该用〈水井〉。陷阱是捕捉用的坑，不能用来打水，打水要用水井。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89631, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陷阱", "is_correct": true, "explanation": "“爸爸用树叶盖住了陷阱”，“陷阱”是可以被树叶盖住的坑，符合语境。"}, {"text": "道理", "is_correct": false, "explanation": "搭配：“盖住”一般用于具体的东西，“道理”是抽象的，不能用树叶盖住。"}, {"text": "理想", "is_correct": false, "explanation": "搭配：“盖住”一般用于具体的东西，“理想”是抽象的，不能用树叶盖住。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“盖住”一般用于具体的东西，不能与“空气”搭配。"}], "explanations": {"陷阱": "“爸爸用树叶盖住了陷阱”，“陷阱”是可以被树叶盖住的坑，符合语境。", "道理": "搭配：“盖住”一般用于具体的东西，“道理”是抽象的，不能用树叶盖住。", "理想": "搭配：“盖住”一般用于具体的东西，“理想”是抽象的，不能用树叶盖住。", "空气": "搭配：“盖住”一般用于具体的东西，不能与“空气”搭配。"}, "sentence_index": 6, "correct_answer": "陷阱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把钱存进了陷阱，准备下个月去取。", "explanation": "这里应该用〈银行〉。陷阱是挖好的坑，人或动物会掉进去；存钱要存进银行。"}, {"text": "衣服上破了一个陷阱，要赶快缝好。", "explanation": "这里应该用〈口子〉。陷阱是挖好的坑，衣服上破开的地方要说口子。"}, {"text": "施工队在路边挖陷阱，修地铁。", "explanation": "这里应该用〈隧道〉。陷阱是挖好的坑，修地铁要挖的是隧道，不能说挖陷阱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猎人在林子里设了一张陷阱。", "corrected_sentence": "猎人在林子里设了一个陷阱。", "error_description": "量词错误：“张”；正确：“个”。“张”用于平面的东西，陷阱是挖好的坑，应说“设了一个陷阱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猎人把陷阱好挖了。", "corrected_sentence": "猎人把陷阱挖好了。", "error_description": "错误：“好”放在了“挖”前面；正确：“挖好”。结果补语要放在动词后面，应说“把陷阱挖好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89632, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89632, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89632, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为捕捉野兽或敌人而挖的坑；也比喻害人的圈套。", "primary_collocate": null, "pronunciation": "xiàn jǐng", "ipa": "ɕjɛn˥˩ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "猎人挖陷阱抓野兽。", "target_word": "陷阱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是坏人设的陷阱。", "target_word": "陷阱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他没发现那是一个陷阱。", "target_word": "陷阱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小心，这个电话可能是陷阱。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们为他设了一个陷阱。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不小心掉进了朋友的陷阱。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "低价常常是商家的陷阱。", "target_word": "陷阱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师提醒我们，网上有很多陷阱。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌人在路上挖了很多陷阱。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他发现自己走进了对方设的陷阱。", "target_word": "陷阱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "捕捉野兽或敌人的坑，比喻害人的圈套", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '898186d7-746b-41f1-9872-48aa0b237dc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陷阱", "is_correct": true, "explanation": "“猎人挖陷阱抓野兽”，“陷阱”是为捕捉野兽而挖的坑，符合语境。"}, {"text": "树", "is_correct": false, "explanation": "语义：挖树是把树挖出来，不能用来抓野兽，与“抓野兽”的语境不符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不能挖来抓野兽。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“挖”一般搭配“坑”“洞”等，不说“挖地图”。"}], "explanations": {"陷阱": "“猎人挖陷阱抓野兽”，“陷阱”是为捕捉野兽而挖的坑，符合语境。", "树": "语义：挖树是把树挖出来，不能用来抓野兽，与“抓野兽”的语境不符。", "房子": "语义：房子是建筑，不能挖来抓野兽。", "地图": "搭配：“挖”一般搭配“坑”“洞”等，不说“挖地图”。"}, "sentence_index": 0, "correct_answer": "陷阱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一个难得的陷阱，我们要抓住它。", "explanation": "这里应该用〈机会〉。陷阱指害人的圈套，不能说“难得的陷阱”。"}, {"text": "朋友的陷阱让我很感动。", "explanation": "这里应该用〈帮助〉。陷阱指害人的圈套，不能用来形容朋友的好意。"}, {"text": "我们在地里挖了一个陷阱，用来存放土豆。", "explanation": "这里应该用〈菜窖〉。陷阱是为捕捉野兽或敌人而挖的坑，存放土豆要挖菜窖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陷阱", "is_correct": true, "explanation": "“低价常常是商家的陷阱”，“陷阱”指害人的圈套，符合语境。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是穿的东西，不是手段，不能说“低价是商家的鞋子”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是手段，与“低价”不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“商家的”后面一般接手段、广告等，不说“商家的颜色”。"}], "explanations": {"陷阱": "“低价常常是商家的陷阱”，“陷阱”指害人的圈套，符合语境。", "鞋子": "语义：鞋子是穿的东西，不是手段，不能说“低价是商家的鞋子”。", "空气": "语义：空气不是手段，与“低价”不符。", "颜色": "搭配：“商家的”后面一般接手段、广告等，不说“商家的颜色”。"}, "sentence_index": 6, "correct_answer": "陷阱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上设了一个陷阱，准时起床。", "explanation": "这里应该用〈闹钟〉。陷阱是为捕捉或害人而设的坑或圈套，定时起床要用闹钟。"}, {"text": "他渴了，就喝陷阱。", "explanation": "这里应该用〈水〉。陷阱是挖好的坑或设下的圈套，不能喝，渴了喝的是水。"}, {"text": "他在墙上挂了陷阱。", "explanation": "这里应该用〈画〉。陷阱不能挂在墙上，挂在墙上的是画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一眼就看了破那个陷阱。", "corrected_sentence": "他一眼就看破了那个陷阱。", "error_description": "错误：“看了破”；正确：“看破”。结果补语“破”要紧跟动词“看”，中间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在生意上被人设了一杯陷阱。", "corrected_sentence": "他在生意上被人设了一个陷阱。", "error_description": "量词错误：“杯”；正确：“个”。“杯”用于盛装饮料的容器，陷阱应用“个”计量，应说“设了一个陷阱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89635, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
