INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89636, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为机关、企业等选择并购买物资。", "primary_collocate": null, "pronunciation": "cǎi gòu", "ipa": "tsʰai˨˩˦ kou˥˩", "syllable_count": 2, "sentences": [{"text": "公司每个月都要采购一批办公用品。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校已经采购了五十台新电脑。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院从国外采购了一批医疗设备。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂要采购便宜又好的原料。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府今年打算采购一批新的公交车。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司采购东西，都要先比较价格。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店每周采购一次新鲜的水果和肉。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司采购的这批布料，质量很好。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理让小李去采购办公室要用的纸。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店向农民采购蔬菜，价格公道。", "target_word": "采购", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "采购了", "label": "体标"}, {"form": "采购过", "label": "体标"}, {"form": "採購", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机关、企业等单位挑选并购买物资", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc993ad-d691-45ca-87b5-147139094920') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：办公用品不能吃，“吃”与“办公用品”无法搭配。"}, {"text": "采购", "is_correct": true, "explanation": "正确：采购指机关、企业为单位选购物资，与“每个月都要买一批办公用品”相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象多是衣物、餐具，不说洗办公用品。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与为公司准备办公用品无关。"}], "explanations": {"吃": "语义：办公用品不能吃，“吃”与“办公用品”无法搭配。", "采购": "正确：采购指机关、企业为单位选购物资，与“每个月都要买一批办公用品”相符。", "洗": "搭配：“洗”的对象多是衣物、餐具，不说洗办公用品。", "唱": "语义：“唱”指发出歌声，与为公司准备办公用品无关。"}, "sentence_index": 0, "correct_answer": "采购"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想采购一个朋友。", "explanation": "这里应该用〈结交〉。采购买的是物资，朋友不能采购，要用结交。"}, {"text": "这家大公司采购了一个小工厂。", "explanation": "这里应该用〈收购〉。采购买的是物资，买下整个企业要用收购。"}, {"text": "他采购了一片果园。", "explanation": "这里应该用〈承包〉。采购买的是物资，接下果园的经营要用承包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象是器物，不说修水果和肉。"}, {"text": "采购", "is_correct": true, "explanation": "正确：采购指为单位选购物资，与“每周买一次新鲜的水果和肉”相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，与水果和肉无关。"}, {"text": "讲", "is_correct": false, "explanation": "语义：“讲”指说话，不能表示购买水果和肉。"}], "explanations": {"修": "搭配：“修”的对象是器物，不说修水果和肉。", "采购": "正确：采购指为单位选购物资，与“每周买一次新鲜的水果和肉”相符。", "写": "语义：“写”指书写文字，与水果和肉无关。", "讲": "语义：“讲”指说话，不能表示购买水果和肉。"}, "sentence_index": 6, "correct_answer": "采购"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司采购了一种新的管理方法。", "explanation": "这里应该用〈采用〉。采购的对象是物资，接受方法、意见要用采用。"}, {"text": "学校采购了一位优秀的学生。", "explanation": "这里应该用〈录取〉。采购买的是物资，招收学生要用录取。"}, {"text": "记者采购了一位老人。", "explanation": "这里应该用〈采访〉。采访是向人提问，采购只用于买物资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校上个月采购着一批教学设备。", "corrected_sentence": "学校上个月采购了一批教学设备。", "error_description": "体标错误：“上个月”指已经完成的动作，应用完成体“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅每天都要采购了一批新鲜的蔬菜。", "corrected_sentence": "这家餐厅每天都要采购一批新鲜的蔬菜。", "error_description": "体标错误：“了”表示动作已完成，不能用在“每天都要”这种表示习惯的句子里，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
