INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89637, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电车是用电开动的车，在街上跑，可以坐很多人。", "primary_collocate": null, "pronunciation": "diàn chē", "ipa": "tjɛn⁵¹ ʈʂʰɤ⁵⁵", "syllable_count": 2, "sentences": [{"text": "电车沿着街上的铁轨慢慢开过来。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天坐电车去上班。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面来了一辆电车，我们快上去吧。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电车是用电开的，不用汽油。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的电车很老了，已经开了五十年。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电车上的人太多，我没有座位。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，电车走得很慢。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢看着电车从街上开过。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在路边等电车，等了很久。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电车的票很便宜，只要两块钱。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "有轨电车", "label": "复合"}, {"form": "電車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用电力开动、在城市街上行驶的载客车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94079a68-bf10-4746-bd88-8d31e031ef14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89637, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电车", "is_correct": true, "explanation": "正确。电车是用电开动、在街上行驶的车。"}, {"text": "练车", "is_correct": false, "explanation": "liàn 与 diàn 声母不同（l 与 d），意思是练习驾驶。"}, {"text": "单车", "is_correct": false, "explanation": "dān（第一声）与 diàn（第四声）韵母不同，意思是自行车。"}, {"text": "电池", "is_correct": false, "explanation": "chí（第二声）与 chē（第一声）韵母与声调都不同，意思是电池。"}], "explanations": {"电车": "正确。电车是用电开动、在街上行驶的车。", "练车": "liàn 与 diàn 声母不同（l 与 d），意思是练习驾驶。", "单车": "dān（第一声）与 diàn（第四声）韵母不同，意思是自行车。", "电池": "chí（第二声）与 chē（第一声）韵母与声调都不同，意思是电池。"}, "sentence_index": null, "correct_answer": "电车"}, "level_3": {"options": [{"text": "电车", "is_correct": true, "explanation": "正确。电车沿铁轨行驶，“开过来”符合车辆行驶的说法。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不走铁轨，与“沿着街上的铁轨”冲突。"}, {"text": "自行车", "is_correct": false, "explanation": "搭配：自行车说“骑”，不说“开”，与“慢慢开过来”不搭配。"}, {"text": "卡车", "is_correct": false, "explanation": "语义：卡车是载货车辆，不走铁轨，与“沿着街上的铁轨”冲突。"}], "explanations": {"电车": "正确。电车沿铁轨行驶，“开过来”符合车辆行驶的说法。", "汽车": "语义：汽车不走铁轨，与“沿着街上的铁轨”冲突。", "自行车": "搭配：自行车说“骑”，不说“开”，与“慢慢开过来”不搭配。", "卡车": "语义：卡车是载货车辆，不走铁轨，与“沿着街上的铁轨”冲突。"}, "sentence_index": 0, "correct_answer": "电车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆电车要从北京开到上海。", "explanation": "这里应该用〈火车〉。电车在城市街道上行驶，不用于跨城长途，跨城要说〈火车〉。"}, {"text": "我们的电车用汽油开，很省钱。", "explanation": "这里应该用〈汽车〉。电车靠电力驱动，不用汽油；用汽油开的要说〈汽车〉。"}, {"text": "电车是用电开的，在地下跑。", "explanation": "这里应该用〈地铁〉。电车在街上行驶，在地下行驶的要说〈地铁〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电车", "is_correct": true, "explanation": "正确。电车在地面上行驶，“走得很慢”符合下雨时车辆的状况。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能自己行走，与“走得很慢”冲突。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是电器，不能自己行走，与“走得很慢”冲突。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：大楼不能行走，与“走得很慢”冲突。"}], "explanations": {"电车": "正确。电车在地面上行驶，“走得很慢”符合下雨时车辆的状况。", "石头": "语义：石头不能自己行走，与“走得很慢”冲突。", "电视": "语义：电视是电器，不能自己行走，与“走得很慢”冲突。", "大楼": "语义：大楼不能行走，与“走得很慢”冲突。"}, "sentence_index": 6, "correct_answer": "电车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天骑电车上学，顺便锻炼身体。", "explanation": "这里应该用〈自行车〉。电车不能骑，也不能锻炼身体；骑着锻炼的是自行车。"}, {"text": "我们坐电车飞过大海去上海，一路很顺利。", "explanation": "这里应该用〈飞机〉。电车在地面的城市道路上行驶，不能飞过大海；飞越海洋要说〈飞机〉。"}, {"text": "我们去电车买了几件衣服。", "explanation": "这里应该用〈商店〉。电车是载客的公共交通车辆，不是卖东西的地方，买衣服要去商店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街角来了一只电车，我们快上去吧。", "corrected_sentence": "街角来了一辆电车，我们快上去吧。", "error_description": "“电车”应用量词“辆”，不能说“一只电车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们坐着电车们去动物园。", "corrected_sentence": "孩子们坐着电车去动物园。", "error_description": "“们”只用于指人，“电车”是车辆，不能加“们”表示复数，应说“坐着电车去动物园”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
