INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89638, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以电力驱动、在城市道路上行驶的公共交通车辆。", "primary_collocate": null, "pronunciation": "diàn chē", "ipa": "tjɛn⁵¹ ʈʂʰɤ⁵⁵", "syllable_count": 2, "sentences": [{"text": "这个城市有很多老电车。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电车头上有一根线，线上有电。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐电车去上学，一次要二十分钟。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前这里有电车，现在只有公共汽车。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电车停了，因为街上没有电。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢站在电车里看街上的人。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们坐着电车参观老城区。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电车的声音很大，我在房间里都听得到。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一辆电车五分钟以后才来。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把行李搬上了电车。", "target_word": "电车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "无轨电车", "label": "复合"}, {"form": "電車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以电力驱动、在城市道路上行驶的公共交通车辆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94079a68-bf10-4746-bd88-8d31e031ef14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89638, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电车", "is_correct": true, "explanation": "正确。电车是以电力驱动、在城市道路上行驶的公共交通车辆。"}, {"text": "练车", "is_correct": false, "explanation": "liàn 与 diàn 声母不同（l 与 d），意思是练习驾驶。"}, {"text": "单车", "is_correct": false, "explanation": "dān（第一声）与 diàn（第四声）韵母不同，意思是自行车。"}, {"text": "电池", "is_correct": false, "explanation": "chí（第二声）与 chē（第一声）韵母与声调都不同，意思是电池。"}], "explanations": {"电车": "正确。电车是以电力驱动、在城市道路上行驶的公共交通车辆。", "练车": "liàn 与 diàn 声母不同（l 与 d），意思是练习驾驶。", "单车": "dān（第一声）与 diàn（第四声）韵母不同，意思是自行车。", "电池": "chí（第二声）与 chē（第一声）韵母与声调都不同，意思是电池。"}, "sentence_index": null, "correct_answer": "电车"}, "level_3": {"options": [{"text": "电车", "is_correct": true, "explanation": "正确。“这个城市有很多”说明数量，“老电车”指旧的电车，符合。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不在城市里，不能说“这个城市有很多老海洋”。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“很多”不能修饰空气这类不可数的物质。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：天上只有一个月亮，不能说“城市有很多老月亮”。"}], "explanations": {"电车": "正确。“这个城市有很多”说明数量，“老电车”指旧的电车，符合。", "海洋": "语义：海洋不在城市里，不能说“这个城市有很多老海洋”。", "空气": "搭配：“很多”不能修饰空气这类不可数的物质。", "月亮": "语义：天上只有一个月亮，不能说“城市有很多老月亮”。"}, "sentence_index": 0, "correct_answer": "电车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条高速公路上有很多电车。", "explanation": "这里应该用〈卡车〉。电车只在城市道路上行驶，不上高速公路。"}, {"text": "这辆电车加满汽油就能开很远。", "explanation": "这里应该用〈汽车〉。电车靠电力驱动，不用汽油；加汽油才能开的是〈汽车〉。"}, {"text": "他是我们城市的电车。", "explanation": "这里应该用〈司机〉。电车是车辆，不能指人；开电车的人要说〈司机〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电车", "is_correct": true, "explanation": "正确。“坐着”后接交通工具，电车可以载游客参观城区。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发不能移动，不能用来参观老城区。"}, {"text": "板凳", "is_correct": false, "explanation": "语义：板凳不是交通工具，不能用来参观老城区。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，不是交通工具，不能用来坐着参观老城区。"}], "explanations": {"电车": "正确。“坐着”后接交通工具，电车可以载游客参观城区。", "沙发": "语义：沙发不能移动，不能用来参观老城区。", "板凳": "语义：板凳不是交通工具，不能用来参观老城区。", "书桌": "语义：书桌是家具，不是交通工具，不能用来坐着参观老城区。"}, "sentence_index": 6, "correct_answer": "电车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐电车飞到北京，一路很快。", "explanation": "这里应该用〈飞机〉。电车在城市道路上行驶，不能飞；飞到外地要说〈飞机〉。"}, {"text": "电车把煤运到了工厂。", "explanation": "这里应该用〈货车〉。电车是载客的公共交通车辆，不用于运煤。"}, {"text": "电车在地下运行，很快就到站。", "explanation": "这里应该用〈地铁〉。电车在城市街道上行驶，不在地下运行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站里停着一只电车，司机在等人。", "corrected_sentence": "车站里停着一辆电车，司机在等人。", "error_description": "“电车”应用量词“辆”，不能说“一只电车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村民们坐着电车们进城。", "corrected_sentence": "村民们坐着电车进城。", "error_description": "“们”只用于指人，“电车”是车辆，不能加“们”表示复数，应说“坐着电车进城”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
