INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89639, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把原来的东西打倒，不再用它。", "primary_collocate": null, "pronunciation": "tuī fān", "ipa": "tʰweɪ̯˥ fan˥", "syllable_count": 2, "sentences": [{"text": "他们推翻了原来的计划。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把原来的想法全推翻了。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旧规定该推翻了。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明推翻了第一次的答案，重新写。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们决定推翻旧方案，再做一个。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把以前做好的设计全部推翻了。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个新发现推翻了原来的结论。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她推翻了之前的所有安排。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想推翻这个不公平的办法。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理推翻了上个月定下的办法。", "target_word": "推翻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推翻了", "label": "体标"}, {"form": "推翻过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把原来的东西打倒、不再沿用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc3263d-b0b9-4fc5-b37b-119d6a479c93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89639, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推翻", "is_correct": true, "explanation": "推翻：把原来的计划否定掉，不再沿用，符合句意。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：计划不能被吃掉，“吃掉”的对象须是可吞咽之物。"}, {"text": "擦亮", "is_correct": false, "explanation": "搭配：“擦亮”用于物体表面，不说擦亮计划。"}, {"text": "喝完", "is_correct": false, "explanation": "语义：“喝完”的对象须是饮品，与计划不搭。"}], "explanations": {"推翻": "推翻：把原来的计划否定掉，不再沿用，符合句意。", "吃掉": "语义：计划不能被吃掉，“吃掉”的对象须是可吞咽之物。", "擦亮": "搭配：“擦亮”用于物体表面，不说擦亮计划。", "喝完": "语义：“喝完”的对象须是饮品，与计划不搭。"}, "sentence_index": 0, "correct_answer": "推翻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把旧衣服推翻了。", "explanation": "这里应该用〈扔掉〉。推翻只用于计划、规定、结论这类抽象事物，不用于衣服。"}, {"text": "他推翻了一杯热茶的香味。", "explanation": "这里应该用〈闻到〉。推翻只用于计划、规定、结论这类可否定的事物，不用于气味。"}, {"text": "他推翻了明天的天气。", "explanation": "这里应该用〈查看〉。推翻只用于计划、规定、结论这类可否定的事物，不用于天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推翻", "is_correct": true, "explanation": "推翻：否定原来的结论，符合句意。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是建筑或设施，不说修建结论。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，与结论无关。"}, {"text": "烧烤", "is_correct": false, "explanation": "语义：“烧烤”的对象是食物，与结论不搭。"}], "explanations": {"推翻": "推翻：否定原来的结论，符合句意。", "修建": "搭配：“修建”的对象是建筑或设施，不说修建结论。", "唱": "语义：“唱”的对象是歌曲，与结论无关。", "烧烤": "语义：“烧烤”的对象是食物，与结论不搭。"}, "sentence_index": 6, "correct_answer": "推翻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他推翻了一首歌。", "explanation": "这里应该用〈唱〉。推翻只用于计划、规定、结论，不用于歌曲。"}, {"text": "他推翻了一份人情。", "explanation": "这里应该用〈还〉。推翻不用于人情往来，它否定的是原有的决定或说法。"}, {"text": "他推翻了一次握手。", "explanation": "这里应该用〈拒绝〉。推翻只用于计划、规定、结论，不用于握手这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校推翻着旧规定。", "corrected_sentence": "学校推翻了旧规定。", "error_description": "“推翻”是一次完成的动作，应用“了”表示完成，说“推翻了”；用“着”表示持续，说“推翻着”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经推翻着那个旧计划。", "corrected_sentence": "他们已经推翻了那个旧计划。", "error_description": "“推翻”是一次完成的动作，应用“了”表示完成，说“推翻了”；用“着”表示持续，说“推翻着”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
