INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89641, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "面具是戴在脸上，把脸遮住的东西。", "primary_collocate": null, "pronunciation": "miàn jù", "ipa": "mjɛn⁵¹ tɕy⁵¹", "syllable_count": 2, "sentences": [{"text": "小明戴了一个老虎面具，很像真的老虎。", "target_word": "面具", "complexity_tier": "T3", "furigana": "Xiǎo Míng dài le yí ge lǎohǔ miànjù, hěn xiàng zhēn de lǎohǔ.", "sentence_source": "generated"}, {"text": "这个面具把她的脸都遮住了。", "target_word": "面具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳舞的人都戴着面具。", "target_word": "面具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面具后面是一张年轻的脸。", "target_word": "面具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多老面具。", "target_word": "面具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从包里拿出面具，戴在脸上。", "target_word": "面具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节时，孩子们戴着面具去朋友家。", "target_word": "面具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个面具太小，我戴不上。", "target_word": "面具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他戴上面具，大家都笑了。", "target_word": "面具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢哪个面具？我喜欢白色的。", "target_word": "面具", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "防毒面具", "label": "复合"}], "register": "中性", "sense_fingerprint": "戴在脸上、把脸遮住的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94079a68-bf10-4746-bd88-8d31e031ef14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "云", "is_correct": false, "explanation": "语义：云是天上的水汽，不能戴在头上或脸上。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“戴了一个”只能接可以戴的物件，“声音”不能说“戴”。"}, {"text": "面具", "is_correct": true, "explanation": "面具是戴在脸上的物品，与“戴了一个老虎”组合通顺，符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是一块地方，不能被戴在身上。"}], "explanations": {"云": "语义：云是天上的水汽，不能戴在头上或脸上。", "声音": "搭配：“戴了一个”只能接可以戴的物件，“声音”不能说“戴”。", "面具": "面具是戴在脸上的物品，与“戴了一个老虎”组合通顺，符合句意。", "花园": "语义：花园是一块地方，不能被戴在身上。"}, "sentence_index": 0, "correct_answer": "面具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天太冷了，我戴上面具让手暖和一点。", "explanation": "这里应该用〈手套〉。让手暖和要戴手套；面具是戴在脸上、遮住脸的东西，不能戴在手上。"}, {"text": "天冷了，他戴上面具保护耳朵。", "explanation": "这里应该用〈耳罩〉。保护耳朵防寒要戴耳罩；面具是用来遮盖或装扮脸部的，不能用来保护耳朵。"}, {"text": "他用面具擦干了脸上的水。", "explanation": "这里应该用〈毛巾〉。擦干脸上的水要用毛巾；面具是用来遮盖或装扮脸部的，不能用来擦脸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼睛", "is_correct": false, "explanation": "搭配：“戴着”不能用于眼睛，眼睛不是可以戴的物件。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能戴着去朋友家。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是地理景物，不能被戴着去朋友家。"}, {"text": "面具", "is_correct": true, "explanation": "面具是戴在脸上的物品，“戴着面具去朋友家”符合常理，句意通顺。"}], "explanations": {"眼睛": "搭配：“戴着”不能用于眼睛，眼睛不是可以戴的物件。", "月亮": "语义：月亮是天体，不能戴着去朋友家。", "河流": "语义：河流是地理景物，不能被戴着去朋友家。", "面具": "面具是戴在脸上的物品，“戴着面具去朋友家”符合常理，句意通顺。"}, "sentence_index": 6, "correct_answer": "面具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "感冒了，我出门前戴上面具防止传染。", "explanation": "这里应该用〈口罩〉。防止传染要戴口罩；面具用于装扮或遮脸，不起防护作用。"}, {"text": "下大雨了，他用面具挡雨。", "explanation": "这里应该用〈雨伞〉。挡雨要用雨伞；面具遮的是脸部，不能用来挡雨。"}, {"text": "开车时，他戴上面具挡住阳光。", "explanation": "这里应该用〈墨镜〉。开车挡阳光要戴墨镜；面具是用来遮盖或装扮脸部的，不能用来挡阳光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她戴上一根面具，走进了房间。", "corrected_sentence": "她戴上一个面具，走进了房间。", "error_description": "量词错误：面具的量词应用“个”或“张”，不说“根”（“根”用于细长的东西，如“一根绳子”）。正确说法是：她戴上一个面具，走进了房间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一条白色的面具。", "corrected_sentence": "我买了一个白色的面具。", "error_description": "量词错误：面具的量词应用“个”或“张”，不说“条”（“条”用于细长的东西，如“一条鱼”“一条路”）。正确说法是：我买了一个白色的面具。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
