INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89643, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说出自己的办法，请大家想一想。", "primary_collocate": null, "pronunciation": "tí yì", "ipa": "tʰi˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "我提议大家一起去公园。", "target_word": "提议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明提议明天早上去爬山。", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他提议我们先吃饭，再看电影。", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气很热，妹妹提议去游泳。", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我提议用投票的办法来决定，大家都同意。", "target_word": "提议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来提议一下，周末做什么？", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师提议大家轮流打扫教室。", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他提议把聚会改到周六，大家都说好。", "target_word": "提议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前也提议过这样做。", "target_word": "提议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们提议送老师一份小礼物。", "target_word": "提议", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "提议了", "label": "体标"}, {"form": "提议过", "label": "体标"}, {"form": "提議", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说出自己的办法，请大家考虑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb81bd1-7443-4fba-9b2e-42070bd1a607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89643, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能带“大家一起去公园”这样的动作。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指弄破易碎的东西，与句中“去公园”的意思不相容。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”接的是地方或展览，不能接“大家一起去公园”这类活动。"}, {"text": "提议", "is_correct": true, "explanation": "“提议”表示提出办法请大家考虑，与“我……大家一起去公园”相符。"}], "explanations": {"吃": "语义：“吃”的对象是食物，不能带“大家一起去公园”这样的动作。", "打碎": "语义：“打碎”指弄破易碎的东西，与句中“去公园”的意思不相容。", "参观": "搭配：“参观”接的是地方或展览，不能接“大家一起去公园”这类活动。", "提议": "“提议”表示提出办法请大家考虑，与“我……大家一起去公园”相符。"}, "sentence_index": 0, "correct_answer": "提议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈提议了我的成绩。", "explanation": "这里应该用〈评价〉。“提议”的对象是办法或建议，不能接“成绩”，评价成绩要用评价。"}, {"text": "我提议他很聪明。", "explanation": "这里应该用〈认为〉。提议后面接的是要做的事或办法，表示看法要用认为，不能接一个状态。"}, {"text": "大家提议老师的帮助。", "explanation": "这里应该用〈感谢〉。提议的对象是办法或建议，对别人的帮助要用感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89643, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物或新方法，不能用来说老师安排值日。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”接机器、房屋等具体物品，不接“大家轮流打扫教室”这样的安排。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”指失去或扔掉，与“老师……大家轮流打扫教室”的意思不符。"}, {"text": "提议", "is_correct": true, "explanation": "“提议”表示提出办法请大家考虑，与“老师……大家轮流打扫教室”相符。"}], "explanations": {"发明": "语义：“发明”指创造新事物或新方法，不能用来说老师安排值日。", "修理": "搭配：“修理”接机器、房屋等具体物品，不接“大家轮流打扫教室”这样的安排。", "丢": "语义：“丢”指失去或扔掉，与“老师……大家轮流打扫教室”的意思不符。", "提议": "“提议”表示提出办法请大家考虑，与“老师……大家轮流打扫教室”相符。"}, "sentence_index": 6, "correct_answer": "提议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我提议这本书很好看。", "explanation": "这里应该用〈觉得〉。“提议”后面接要做的事或办法，表达看法要用觉得。"}, {"text": "弟弟提议了一个苹果。", "explanation": "这里应该用〈要〉。“提议”的对象是办法，不能接具体的东西，想得到东西要用要。"}, {"text": "朋友们提议了我的生日。", "explanation": "这里应该用〈记得〉。“提议”不能接“生日”，不忘记某事要用记得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我曾经提议了这个办法。", "corrected_sentence": "我曾经提议过这个办法。", "error_description": "错误：“曾经”表示有过的经历，动词后应用“过”，这里误用了“了”。正确：“我曾经提议过这个办法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前提议了很多次这样做，可是没人听。", "corrected_sentence": "他以前提议过很多次这样做，可是没人听。", "error_description": "错误：“以前”表示过去的经历，动词后应用“过”。正确：“他以前提议过很多次这样做”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
