INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89645, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89645, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "骑兵是骑着马打仗的兵。", "primary_collocate": null, "pronunciation": "qí bīng", "ipa": "tɕʰi˧˥ piŋ˥", "syllable_count": 2, "sentences": [{"text": "骑兵骑着马冲向了对面的山坡。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代打仗时，骑兵跑得比步兵快。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位骑兵拿着长枪，站在城门口。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军派了一队骑兵去送信。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑兵的马很高，也很有力气。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的骑兵从北边来了。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的骑兵一起冲过了河。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些骑兵每天都要照顾自己的马。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "步兵走得慢，骑兵先到了城外。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候最想当骑兵，骑着马打仗。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "骑兵队", "label": "复合"}], "register": "中性", "sense_fingerprint": "骑着马打仗的士兵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89645, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骑兵", "is_correct": true, "explanation": "骑兵：骑着马作战的兵，与“骑着马冲向了山坡”相符。"}, {"text": "步兵", "is_correct": false, "explanation": "语义：步兵是步行作战的兵，不会骑着马冲锋。"}, {"text": "小船", "is_correct": false, "explanation": "语义：小船不会骑马，也不能冲向山坡。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会骑马，也不能冲向山坡。"}], "explanations": {"骑兵": "骑兵：骑着马作战的兵，与“骑着马冲向了山坡”相符。", "步兵": "语义：步兵是步行作战的兵，不会骑着马冲锋。", "小船": "语义：小船不会骑马，也不能冲向山坡。", "石头": "语义：石头不会骑马，也不能冲向山坡。"}, "sentence_index": 0, "correct_answer": "骑兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位骑兵在饭店里端上了一碗面。", "explanation": "这里应该用〈服务员〉。端面上桌的是服务员，骑兵是骑马作战的士兵。"}, {"text": "骑兵在水底悄悄靠近码头。", "explanation": "这里应该用〈蛙人〉。在水下潜行的是蛙人，骑兵是骑马作战的兵，不会在水底行动。"}, {"text": "他每天给骑兵喂草。", "explanation": "这里应该用〈马〉。喂草的对象是马，骑兵是人，不能给他喂草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骑兵", "is_correct": true, "explanation": "骑兵：骑马作战的兵，影片中的骑兵一起冲过河，与语境相符。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众坐在座位上看电影，不会冲过河。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能冲过河。"}, {"text": "乐队", "is_correct": false, "explanation": "搭配：“冲过河”不能用于乐队，乐队不是冲锋的队伍。"}], "explanations": {"骑兵": "骑兵：骑马作战的兵，影片中的骑兵一起冲过河，与语境相符。", "观众": "语义：观众坐在座位上看电影，不会冲过河。", "钢琴": "语义：钢琴是乐器，不能冲过河。", "乐队": "搭配：“冲过河”不能用于乐队，乐队不是冲锋的队伍。"}, "sentence_index": 6, "correct_answer": "骑兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "骑兵驾驶飞机升空。", "explanation": "这里应该用〈飞行员〉。驾驶飞机的是飞行员，骑兵是骑马作战的兵。"}, {"text": "骑兵指挥军舰驶向港口。", "explanation": "这里应该用〈舰长〉。指挥军舰的是舰长，骑兵不驾驶船只。"}, {"text": "骑兵在甲板上拉起了帆。", "explanation": "这里应该用〈船员〉。拉帆的是船员，骑兵不在船上劳作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位骑着马骑兵很勇敢。", "corrected_sentence": "那位骑着马的骑兵很勇敢。", "error_description": "修饰语错误：“骑着马”修饰“骑兵”时要加“的”，应写作“骑着马的骑兵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只骑兵在草原上奔跑。", "corrected_sentence": "一名骑兵在草原上奔跑。", "error_description": "量词错误：“骑兵”指人，应用人的量词“名”，不用动物量词“只”，应写作“一名骑兵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
