INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "骑马作战的士兵或兵种。", "primary_collocate": null, "pronunciation": "qí bīng", "ipa": "tɕʰi˧˥ piŋ˥", "syllable_count": 2, "sentences": [{"text": "骑兵是一个很老的兵种。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蒙古骑兵在草原上打过很多仗。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的军队里已经没有骑兵了。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一张骑兵的旧照片。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支骑兵有三千人，都很年轻。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在军队里是骑兵，不是步兵。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车出现以后，骑兵就用得少了。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，骑兵的速度是打仗的关键。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在书上读到骑兵怎么在雪地里作战。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争里，骑兵和步兵一起打败了敌人。", "target_word": "骑兵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "骑兵队", "label": "复合"}], "register": "中性", "sense_fingerprint": "骑马作战的兵种或其士兵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骑兵", "is_correct": true, "explanation": "骑兵：骑马作战的兵种，句中说它是很老的兵种，与语境相符。"}, {"text": "马", "is_correct": false, "explanation": "语义：马是动物，不是兵种。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“兵种”指军队中的兵类，不能用来说老师。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不是兵种。"}], "explanations": {"骑兵": "骑兵：骑马作战的兵种，句中说它是很老的兵种，与语境相符。", "马": "语义：马是动物，不是兵种。", "老师": "搭配：“兵种”指军队中的兵类，不能用来说老师。", "厨房": "语义：厨房是场所，不是兵种。"}, "sentence_index": 0, "correct_answer": "骑兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位骑兵在教室里给学生讲数学课。", "explanation": "这里应该用〈老师〉。上课讲解的是老师，骑兵是骑马作战的兵。"}, {"text": "骑兵的军舰驶入了港口。", "explanation": "这里应该用〈海军〉。军舰属于海军，骑兵是骑马作战的兵，不会拥有军舰。"}, {"text": "骑兵开车送乘客去车站。", "explanation": "这里应该用〈司机〉。开车送乘客的是司机，骑兵是骑马作战的兵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骑兵", "is_correct": true, "explanation": "骑兵：骑马作战的兵，汽车出现后骑兵使用减少，符合句意。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是作品，不是可以用于作战或代步的事物。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能用于作战或代步，句意不通。"}, {"text": "诗人", "is_correct": false, "explanation": "配价：“用得少”需要被使用的事物作宾语，诗人不能被这样使用。"}], "explanations": {"骑兵": "骑兵：骑马作战的兵，汽车出现后骑兵使用减少，符合句意。", "歌曲": "语义：歌曲是作品，不是可以用于作战或代步的事物。", "石头": "语义：石头不能用于作战或代步，句意不通。", "诗人": "配价：“用得少”需要被使用的事物作宾语，诗人不能被这样使用。"}, "sentence_index": 6, "correct_answer": "骑兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房里，骑兵正在切菜。", "explanation": "这里应该用〈厨师〉。切菜的是厨师，骑兵是骑马作战的兵，不会在厨房切菜。"}, {"text": "工厂里，骑兵正在修理机器。", "explanation": "这里应该用〈工人〉。修理机器的是工人，骑兵不在工厂工作。"}, {"text": "田里，骑兵正在插秧。", "explanation": "这里应该用〈农民〉。插秧的是农民，骑兵是骑马作战的兵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只骑兵很英勇。", "corrected_sentence": "这位骑兵很英勇。", "error_description": "量词错误：“只”用于动物，骑兵是人，应把量词“只”改为“位”，写作“这位骑兵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三个骑兵们在草原上列队出发。", "corrected_sentence": "三个骑兵在草原上列队出发。", "error_description": "“们”用法错误：“们”表示复数，不能与数词“三个”同用，应去掉“们”，写作“三个骑兵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
