INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89647, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个东西很快地碰到另一个东西，会疼。", "primary_collocate": null, "pronunciation": "zhuàng", "ipa": "ʈʂwɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我走得太快，一头撞在门上，好疼。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑了，我的膝盖撞到了桌子，很疼。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟跑得太快，撞了我一下，我的胳膊很疼。", "target_word": "撞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她低头玩手机，头撞到了电线杆。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心点儿，别撞到头！", "target_word": "撞", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "楼梯太黑，我的脚趾撞在椅子腿上了。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他进门时没低头，额头撞到了门框。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手撞到了桌角，现在还疼。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他撞过玻璃门，疼了好几天，现在很小心。", "target_word": "撞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她转身太快，鼻子撞在我的肩上，疼得直流泪。", "target_word": "撞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撞了", "label": "体标（了）"}, {"form": "撞过", "label": "体标（过）"}, {"form": "撞着", "label": "体标（着）"}], "register": "口语", "sense_fingerprint": "身体很快碰到东西而感到疼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc993ad-d691-45ca-87b5-147139094920') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89647, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "撞", "is_correct": true, "explanation": "正确：撞（zhuàng，第四声）指身体很快碰到东西而感到疼。"}, {"text": "庄", "is_correct": false, "explanation": "庄（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是村庄、庄重。"}, {"text": "胀", "is_correct": false, "explanation": "胀（zhàng）比撞（zhuàng）少了 u 介音，意思是肿胀、胀大。"}, {"text": "赚", "is_correct": false, "explanation": "赚（zhuàn）与撞（zhuàng）韵尾不同，-n 与 -ng，意思是赚钱。"}], "explanations": {"撞": "正确：撞（zhuàng，第四声）指身体很快碰到东西而感到疼。", "庄": "庄（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是村庄、庄重。", "胀": "胀（zhàng）比撞（zhuàng）少了 u 介音，意思是肿胀、胀大。", "赚": "赚（zhuàn）与撞（zhuàng）韵尾不同，-n 与 -ng，意思是赚钱。"}, "sentence_index": null, "correct_answer": "撞"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "配价：“写”要求带文字类宾语，不能说“一头写在门上”。"}, {"text": "撞", "is_correct": true, "explanation": "正确：撞指头部很快碰到门上，并且感到疼，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与头碰到门无关。"}, {"text": "讲", "is_correct": false, "explanation": "语义：“讲”指说话，不能表示身体碰到门。"}], "explanations": {"写": "配价：“写”要求带文字类宾语，不能说“一头写在门上”。", "撞": "正确：撞指头部很快碰到门上，并且感到疼，与句意相符。", "唱": "语义：“唱”指发出歌声，与头碰到门无关。", "讲": "语义：“讲”指说话，不能表示身体碰到门。"}, "sentence_index": 0, "correct_answer": "撞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把贴纸撞在了本子上。", "explanation": "这里应该用〈贴〉。撞是很快地碰到、会疼，把贴纸轻轻粘上要用贴。"}, {"text": "他在黑板上撞了一行字。", "explanation": "这里应该用〈写〉。撞是很快地碰到、会疼，写字要用写。"}, {"text": "她慢慢地撞到了椅子上。", "explanation": "这里应该用〈坐〉。撞是很快地碰到、会疼，慢慢坐下要用坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89647, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "撞", "is_correct": true, "explanation": "正确：撞（zhuàng，第四声）指身体很快碰到东西而感到疼。"}, {"text": "装", "is_correct": false, "explanation": "装（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是装东西、装饰。"}, {"text": "账", "is_correct": false, "explanation": "账（zhàng）比撞（zhuàng）少了 u 介音，意思是账目。"}, {"text": "妆", "is_correct": false, "explanation": "妆（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是化妆、梳妆。"}], "explanations": {"撞": "正确：撞（zhuàng，第四声）指身体很快碰到东西而感到疼。", "装": "装（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是装东西、装饰。", "账": "账（zhàng）比撞（zhuàng）少了 u 介音，意思是账目。", "妆": "妆（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是化妆、梳妆。"}, "sentence_index": null, "correct_answer": "撞"}, "level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象多是衣物、餐具，不说额头洗到门框。"}, {"text": "撞", "is_correct": true, "explanation": "正确：撞指额头碰到门框，并且感到疼，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，与额头碰到门框无关。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指把液体咽下去，与身体碰到东西无关。"}], "explanations": {"洗": "搭配：“洗”的对象多是衣物、餐具，不说额头洗到门框。", "撞": "正确：撞指额头碰到门框，并且感到疼，与句意相符。", "吃": "语义：“吃”指把食物咽下去，与额头碰到门框无关。", "喝": "语义：“喝”指把液体咽下去，与身体碰到东西无关。"}, "sentence_index": 6, "correct_answer": "撞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "理发师撞了我的头发。", "explanation": "这里应该用〈剪〉。撞是很快地碰到、会疼，剪头发要用剪。"}, {"text": "他小心地撞着桌角走过去，没有碰到。", "explanation": "这里应该用〈绕〉。撞是很快地碰到、会疼，小心地避开要用绕。"}, {"text": "妈妈轻轻撞了撞我的额头，怕我疼。", "explanation": "这里应该用〈摸〉。撞会让人感到疼，与“轻轻”“怕我疼”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑得太快，撞了到桌角，好疼。", "corrected_sentence": "他跑得太快，撞到了桌角，好疼。", "error_description": "补语与“了”的位置错误：应说“撞到了”，不能说“撞了到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年撞了过一次玻璃门，疼了好几天。", "corrected_sentence": "他去年撞过一次玻璃门，疼了好几天。", "error_description": "体标错误：经历体“过”要紧跟动词，不能说“撞了过”，应改为“撞过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
