INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89648, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "运动的物体猛然碰到另一物体。", "primary_collocate": null, "pronunciation": "zhuàng", "ipa": "ʈʂwɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "小汽车撞了前面的卡车。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机没看见，车撞到了路边的树。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风太大，门猛地撞在墙上。", "target_word": "撞", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两辆自行车在路口撞上了。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小船撞到石头，马上就进水了。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞来的球撞在玻璃上，玻璃碎了。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货车撞倒了路边的电线杆。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开车太快，差点儿撞上前面的车。", "target_word": "撞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车撞过护栏，所以前面坏了。", "target_word": "撞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨天路滑，小货车把栏杆撞坏了。", "target_word": "撞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撞了", "label": "体标（了）"}, {"form": "撞过", "label": "体标（过）"}, {"form": "撞着", "label": "体标（着）"}, {"form": "撞车", "label": "复合"}], "register": "中性", "sense_fingerprint": "车辆或物体猛然碰到另一物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc993ad-d691-45ca-87b5-147139094920') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89648, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "撞", "is_correct": true, "explanation": "正确：撞（zhuàng，第四声）指运动的物体猛然碰到另一物体。"}, {"text": "装", "is_correct": false, "explanation": "装（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是装东西、装饰。"}, {"text": "创", "is_correct": false, "explanation": "创（chuàng）与撞（zhuàng）声母不同，ch 与 zh，意思是创造、创伤。"}, {"text": "账", "is_correct": false, "explanation": "账（zhàng）比撞（zhuàng）少了 u 介音，意思是账目。"}, {"text": "赚", "is_correct": false, "explanation": "赚（zhuàn）与撞（zhuàng）韵尾不同，-n 与 -ng，意思是赚钱。"}], "explanations": {"撞": "正确：撞（zhuàng，第四声）指运动的物体猛然碰到另一物体。", "装": "装（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是装东西、装饰。", "创": "创（chuàng）与撞（zhuàng）声母不同，ch 与 zh，意思是创造、创伤。", "账": "账（zhàng）比撞（zhuàng）少了 u 介音，意思是账目。", "赚": "赚（zhuàn）与撞（zhuàng）韵尾不同，-n 与 -ng，意思是赚钱。"}, "sentence_index": null, "correct_answer": "撞"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "配价：“写”要求带文字类宾语，不能带“卡车”。"}, {"text": "撞", "is_correct": true, "explanation": "正确：撞指车辆猛然碰到另一物体，与“小汽车撞了前面的卡车”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，与车辆碰撞无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，不能用于车辆碰到卡车。"}], "explanations": {"写": "配价：“写”要求带文字类宾语，不能带“卡车”。", "撞": "正确：撞指车辆猛然碰到另一物体，与“小汽车撞了前面的卡车”相符。", "吃": "语义：“吃”指把食物咽下去，与车辆碰撞无关。", "唱": "语义：“唱”指发出歌声，不能用于车辆碰到卡车。"}, "sentence_index": 0, "correct_answer": "撞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把外套撞在门后。", "explanation": "这里应该用〈挂〉。撞是猛然相碰，把外套轻轻挂起来要用挂。"}, {"text": "他把杯子慢慢地撞在桌上，没有一点声音。", "explanation": "这里应该用〈放〉。撞是猛然相碰、有声响，慢慢无声地把杯子放下要用放。"}, {"text": "他小心地撞了一下窗户，怕吵醒大家。", "explanation": "这里应该用〈碰〉。撞是猛然相碰，与“小心地”“怕吵醒大家”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89648, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "撞", "is_correct": true, "explanation": "正确：撞（zhuàng，第四声）指运动的物体猛然碰到另一物体。"}, {"text": "妆", "is_correct": false, "explanation": "妆（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是化妆、梳妆。"}, {"text": "胀", "is_correct": false, "explanation": "胀（zhàng）比撞（zhuàng）少了 u 介音，意思是膨胀、胀大。"}, {"text": "庄", "is_correct": false, "explanation": "庄（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是村庄、庄重。"}], "explanations": {"撞": "正确：撞（zhuàng，第四声）指运动的物体猛然碰到另一物体。", "妆": "妆（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是化妆、梳妆。", "胀": "胀（zhàng）比撞（zhuàng）少了 u 介音，意思是膨胀、胀大。", "庄": "庄（zhuāng，第一声）与撞（zhuàng，第四声）声调不同，意思是村庄、庄重。"}, "sentence_index": null, "correct_answer": "撞"}, "level_3": {"options": [{"text": "讲", "is_correct": false, "explanation": "语义：“讲”指说话，不能用来表示车辆撞倒电线杆。"}, {"text": "撞", "is_correct": true, "explanation": "正确：撞指货车猛然碰到路边的电线杆，与句意相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指把液体咽下去，与车辆碰撞无关。"}, {"text": "弹", "is_correct": false, "explanation": "搭配：“弹”不与“倒”组合表示车辆撞倒物体，这里不说“弹倒”。"}], "explanations": {"讲": "语义：“讲”指说话，不能用来表示车辆撞倒电线杆。", "撞": "正确：撞指货车猛然碰到路边的电线杆，与句意相符。", "喝": "语义：“喝”指把液体咽下去，与车辆碰撞无关。", "弹": "搭配：“弹”不与“倒”组合表示车辆撞倒物体，这里不说“弹倒”。"}, "sentence_index": 6, "correct_answer": "撞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里撞了一锅粥。", "explanation": "这里应该用〈煮〉。撞是猛然相碰，不能用于煮粥。"}, {"text": "车子撞着墙边慢慢开过去，没有一点声音。", "explanation": "这里应该用〈擦〉。撞是猛然相碰、有声响，与“慢慢开过去”“没有一点声音”矛盾。"}, {"text": "他轻轻撞了撞孩子的头，怕惊醒他。", "explanation": "这里应该用〈摸〉。撞是猛然相碰，与“轻轻”“怕惊醒他”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卡车在高速路上撞了坏一辆小轿车。", "corrected_sentence": "卡车在高速路上撞坏了一辆小轿车。", "error_description": "补语位置错误：结果补语“坏”应紧跟动词，说“撞坏了”，不能说“撞了坏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大风天，树枝把窗户撞。", "corrected_sentence": "大风天，树枝把窗户撞破了。", "error_description": "补语缺失：“把”字句中的动词“撞”后面要有结果补语等成分，应说“把窗户撞破了”，不能只说“把窗户撞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
