INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89649, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "惊是突然碰到没想到的事，吓了一跳。", "primary_collocate": null, "pronunciation": "jīng", "ipa": "tɕiŋ˥", "syllable_count": 1, "sentences": [{"text": "听到这个消息，我心里一惊。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看到门开着，不由得一惊。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜里电话响了，她猛地一惊。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人突然在背后喊我，我一惊，回头一看。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话让我心里一惊。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到成绩单，妈妈心里一惊。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门外突然有响声，大家都一惊。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见桌上的钱不见了，心里一惊。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她回头看见一个陌生人，不禁一惊。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说老板要来，大家心里都一惊。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惊了", "label": "体标（了）"}, {"form": "惊过", "label": "体标（过）"}, {"form": "驚", "label": "繁体"}], "register": "口语", "sense_fingerprint": "突然遇到意外的事而吓一跳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89649, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "惊", "is_correct": true, "explanation": "惊：突然遇到意外而吓一跳，正是本句所用的词。"}, {"text": "景", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是景色。"}, {"text": "静", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是安静。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（-n 与 -ng），意思是金子。"}, {"text": "青", "is_correct": false, "explanation": "qīng 与 jīng 声母不同（q 与 j），意思是青色。"}, {"text": "星", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是星星。"}], "explanations": {"惊": "惊：突然遇到意外而吓一跳，正是本句所用的词。", "景": "jǐng（第三声）与 jīng（第一声）声调不同，意思是景色。", "静": "jìng（第四声）与 jīng（第一声）声调不同，意思是安静。", "金": "jīn 与 jīng 韵母不同（-n 与 -ng），意思是金子。", "青": "qīng 与 jīng 声母不同（q 与 j），意思是青色。", "星": "xīng 与 jīng 声母不同（x 与 j），意思是星星。"}, "sentence_index": null, "correct_answer": "惊"}, "level_3": {"options": [{"text": "惊", "is_correct": true, "explanation": "惊：突然受到意外消息而吓一跳，符合「听到这个消息」的语境。"}, {"text": "喊", "is_correct": false, "explanation": "语义：喊要出声，不能用在「心里」的内心活动上。"}, {"text": "瞪", "is_correct": false, "explanation": "语义：瞪是眼睛的动作，不能用来指心里的反应。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔是身体跌落，与听到消息后的心理反应不符。"}], "explanations": {"惊": "惊：突然受到意外消息而吓一跳，符合「听到这个消息」的语境。", "喊": "语义：喊要出声，不能用在「心里」的内心活动上。", "瞪": "语义：瞪是眼睛的动作，不能用来指心里的反应。", "摔": "语义：摔是身体跌落，与听到消息后的心理反应不符。"}, "sentence_index": 0, "correct_answer": "惊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个消息，他脸色一惊，没说话。", "explanation": "这里应该用〈变〉。脸色一变是常用说法，惊指受刺激而吓一跳，不能用来描写脸色的变化。"}, {"text": "他的手一惊，茶杯差点掉到地上。", "explanation": "这里应该用〈抖〉。惊指人受刺激而吓一跳，手的颤动要用〈抖〉，不能说手一惊。"}, {"text": "他一直对着镜子，惊着自己的样子。", "explanation": "这里应该用〈欣赏〉。惊指受刺激而吓一跳，不表示观看或赞叹自己的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89649, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "惊", "is_correct": true, "explanation": "惊：突然遇到意外而吓一跳，正是本句所用的词。"}, {"text": "警", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是警察。"}, {"text": "镜", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是镜子。"}, {"text": "今", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（-n 与 -ng），意思是今天。"}, {"text": "清", "is_correct": false, "explanation": "qīng 与 jīng 声母不同（q 与 j），意思是清楚。"}, {"text": "兴", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是兴旺。"}], "explanations": {"惊": "惊：突然遇到意外而吓一跳，正是本句所用的词。", "警": "jǐng（第三声）与 jīng（第一声）声调不同，意思是警察。", "镜": "jìng（第四声）与 jīng（第一声）声调不同，意思是镜子。", "今": "jīn 与 jīng 韵母不同（-n 与 -ng），意思是今天。", "清": "qīng 与 jīng 声母不同（q 与 j），意思是清楚。", "兴": "xīng 与 jīng 声母不同（x 与 j），意思是兴旺。"}, "sentence_index": null, "correct_answer": "惊"}, "level_3": {"options": [{"text": "惊", "is_correct": true, "explanation": "惊：突然受到意外而吓一跳，符合「门外突然有响声」的语境。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛掷东西，与门外响声引起的反应不符。"}, {"text": "抬", "is_correct": false, "explanation": "配价：抬要带宾语（抬什么），「大家都一抬」缺少宾语，不成句。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿的动作，不能用来形容听到响声的反应。"}], "explanations": {"惊": "惊：突然受到意外而吓一跳，符合「门外突然有响声」的语境。", "扔": "语义：扔是抛掷东西，与门外响声引起的反应不符。", "抬": "配价：抬要带宾语（抬什么），「大家都一抬」缺少宾语，不成句。", "咬": "语义：咬是用牙齿的动作，不能用来形容听到响声的反应。"}, "sentence_index": 6, "correct_answer": "惊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙惊进兜里。", "explanation": "这里应该用〈揣〉。惊指受刺激而吓一跳，不能表示把东西放进口袋。"}, {"text": "老师走过来，惊了他一眼。", "explanation": "这里应该用〈瞪〉。惊指受刺激而吓一跳，不能用来表示瞪视别人。"}, {"text": "他去教室，惊了一下黑板。", "explanation": "这里应该用〈擦〉。惊指受刺激吓一跳，不表示擦拭黑板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89649, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他突然听见敲门声，心里很惊。", "corrected_sentence": "他突然听见敲门声，心里一惊。", "error_description": "应为「一惊」。单音节动词「惊」不能直接受「很」修饰，表示突然吓一跳要说「心里一惊」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89649, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听到这个消息，惊说不出话来。", "corrected_sentence": "他听到这个消息，惊得说不出话来。", "error_description": "应为「惊得」。「惊」后要用「得」引出补语，「惊说不出话」缺少「得」，不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
