INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89650, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因突然受到刺激而紧张、害怕；使人吃惊。", "primary_collocate": null, "pronunciation": "jīng", "ipa": "tɕiŋ˥", "syllable_count": 1, "sentences": [{"text": "马突然惊了，把人摔了下来。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗听到鞭炮声，一下子惊了。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛惊了，在路上乱跑。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别大声说话，会惊了孩子。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脚步声惊了树上的鸟。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小声点儿，别惊着孩子。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的雷声惊了全村的狗。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑马的人一喊，路边的羊都惊了。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车喇叭一响，马就惊了。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他轻轻开门，怕惊了屋里的人。", "target_word": "惊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惊了", "label": "体标（了）"}, {"form": "惊着", "label": "体标（着）"}, {"form": "驚", "label": "繁体"}], "register": "口语", "sense_fingerprint": "牲畜等受刺激而受惊，或惊扰了别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89650, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "惊", "is_correct": true, "explanation": "惊：受刺激而慌乱，或惊扰他人，正是本句所用的词。"}, {"text": "井", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。"}, {"text": "敬", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是尊敬。"}, {"text": "斤", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（-n 与 -ng），意思是斤（重量单位）。"}, {"text": "轻", "is_correct": false, "explanation": "qīng 与 jīng 声母不同（q 与 j），意思是轻重的轻。"}, {"text": "兴", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是兴旺。"}], "explanations": {"惊": "惊：受刺激而慌乱，或惊扰他人，正是本句所用的词。", "井": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。", "敬": "jìng（第四声）与 jīng（第一声）声调不同，意思是尊敬。", "斤": "jīn 与 jīng 韵母不同（-n 与 -ng），意思是斤（重量单位）。", "轻": "qīng 与 jīng 声母不同（q 与 j），意思是轻重的轻。", "兴": "xīng 与 jīng 声母不同（x 与 j），意思是兴旺。"}, "sentence_index": null, "correct_answer": "惊"}, "level_3": {"options": [{"text": "惊", "is_correct": true, "explanation": "惊：马受刺激而慌乱，与「把人摔了下来」的语境相连。"}, {"text": "笑", "is_correct": false, "explanation": "语义：马笑与「把人摔了下来」的因果不合，语义上不成立。"}, {"text": "给", "is_correct": false, "explanation": "配价：给要带接受者（给谁），「马突然给了」缺少宾语，不成句。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡是休息的动作，无法导致马把人摔下来。"}], "explanations": {"惊": "惊：马受刺激而慌乱，与「把人摔了下来」的语境相连。", "笑": "语义：马笑与「把人摔了下来」的因果不合，语义上不成立。", "给": "配价：给要带接受者（给谁），「马突然给了」缺少宾语，不成句。", "睡": "语义：睡是休息的动作，无法导致马把人摔下来。"}, "sentence_index": 0, "correct_answer": "惊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他轻轻惊了一下门，没有出声。", "explanation": "这里应该用〈碰〉。惊指牲畜或人受刺激而慌乱，不能表示用手轻触东西。"}, {"text": "他小心地把杯子惊下。", "explanation": "这里应该用〈放〉。惊指使牲畜或人受惊，不能表示把东西轻轻放下。"}, {"text": "妈妈惊着孩子睡觉。", "explanation": "这里应该用〈哄〉。惊指受惊扰而慌乱，不能表示安抚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89650, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "惊", "is_correct": true, "explanation": "惊：受刺激而慌乱，或惊扰他人，正是本句所用的词。"}, {"text": "景", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是景色。"}, {"text": "静", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是安静。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（-n 与 -ng），意思是金子。"}, {"text": "清", "is_correct": false, "explanation": "qīng 与 jīng 声母不同（q 与 j），意思是清楚。"}, {"text": "星", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是星星。"}], "explanations": {"惊": "惊：受刺激而慌乱，或惊扰他人，正是本句所用的词。", "景": "jǐng（第三声）与 jīng（第一声）声调不同，意思是景色。", "静": "jìng（第四声）与 jīng（第一声）声调不同，意思是安静。", "金": "jīn 与 jīng 韵母不同（-n 与 -ng），意思是金子。", "清": "qīng 与 jīng 声母不同（q 与 j），意思是清楚。", "星": "xīng 与 jīng 声母不同（x 与 j），意思是星星。"}, "sentence_index": null, "correct_answer": "惊"}, "level_3": {"options": [{"text": "惊", "is_correct": true, "explanation": "惊：雷声使狗受刺激而慌乱，符合「夜里的雷声」的语境。"}, {"text": "喂", "is_correct": false, "explanation": "语义：喂是给食物，雷声不会喂狗，与句意不符。"}, {"text": "买", "is_correct": false, "explanation": "语义：买是花钱购置，与雷声对狗的影响毫无关系。"}, {"text": "坐", "is_correct": false, "explanation": "配价：坐不带「狗」作宾语，「坐了全村的狗」不成立。"}], "explanations": {"惊": "惊：雷声使狗受刺激而慌乱，符合「夜里的雷声」的语境。", "喂": "语义：喂是给食物，雷声不会喂狗，与句意不符。", "买": "语义：买是花钱购置，与雷声对狗的影响毫无关系。", "坐": "配价：坐不带「狗」作宾语，「坐了全村的狗」不成立。"}, "sentence_index": 6, "correct_answer": "惊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不小心惊了手，去医院包扎。", "explanation": "这里应该用〈伤〉。惊指受刺激而慌乱或惊扰他人，不能指身体受伤。"}, {"text": "他小心地惊着那碗汤。", "explanation": "这里应该用〈捧〉。惊指受刺激而慌乱或惊扰别人，不表示用双手托着东西。"}, {"text": "消防员冲进火场，惊开了门。", "explanation": "这里应该用〈推〉。惊开不成词，惊指受刺激或惊扰别人，不表示用力推开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "突然的喊声惊了了院子里的鸡。", "corrected_sentence": "突然的喊声惊了院子里的鸡。", "error_description": "体标重复：动词「惊」后只能用一个「了」表示完成，「惊了了」应改为「惊了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他轻轻地走，怕醒惊屋里的人。", "corrected_sentence": "他轻轻地走，怕惊醒屋里的人。", "error_description": "应为「惊醒」。「惊醒」是动补式复合词，「醒」在后，「醒惊」语序颠倒，不成词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
