INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89651, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "昨天的晚上。", "primary_collocate": null, "pronunciation": "zuó wǎn", "ipa": "tswɔ˧˥ wan˨˩˦", "syllable_count": 2, "sentences": [{"text": "昨晚的风很大。", "target_word": "昨晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨晚我没有睡好。", "target_word": "昨晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨晚电视里有一个很好看的节目。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚弟弟哭了很久。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚你为什么没接电话？", "target_word": "昨晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨晚我做了一个奇怪的梦。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚我作业太多，写到很晚才睡。", "target_word": "昨晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚老师发了一条短信给我。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚他们在公园里散步了。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚的饭很好吃，今天我还想去那家饭馆。", "target_word": "昨晚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "昨天的晚上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc993ad-d691-45ca-87b5-147139094920') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昨晚", "is_correct": true, "explanation": "昨晚：指昨天夜里，与“风很大”所描述的时间相符。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：咖啡不会刮风，“咖啡的风”无法搭配。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是刮风的事物，“电视的风很大”说不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不会刮风，句中“的风很大”无法用来修饰钥匙。"}], "explanations": {"昨晚": "昨晚：指昨天夜里，与“风很大”所描述的时间相符。", "咖啡": "搭配：咖啡不会刮风，“咖啡的风”无法搭配。", "电视": "语义：电视不是刮风的事物，“电视的风很大”说不通。", "钥匙": "语义：钥匙不会刮风，句中“的风很大”无法用来修饰钥匙。"}, "sentence_index": 0, "correct_answer": "昨晚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天昨晚都给我讲故事。", "explanation": "〈每天晚上〉。昨晚只指过去的一个夜晚，不能表示经常性的动作；表示习惯应说“每天晚上”。"}, {"text": "昨晚一早，妈妈就去了菜市场。", "explanation": "〈昨天〉。昨晚指夜间，不能与表示清晨的“一早”搭配，应说“昨天一早”。"}, {"text": "昨晚下午，我们去公园散步了。", "explanation": "〈昨天〉。昨晚指夜间，不能与“下午”搭配，应说“昨天下午”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨晚", "is_correct": true, "explanation": "昨晚：指昨天夜里，与“写到很晚才睡”的时间相符。"}, {"text": "早上", "is_correct": false, "explanation": "语义：早上写到很晚才睡，时间上自相矛盾。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午写到很晚才睡，与“很晚才睡”的时间描述矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：桌子不会“作业太多”，句首的桌子与“我作业太多”搭配不当。"}], "explanations": {"昨晚": "昨晚：指昨天夜里，与“写到很晚才睡”的时间相符。", "早上": "语义：早上写到很晚才睡，时间上自相矛盾。", "中午": "语义：中午写到很晚才睡，与“很晚才睡”的时间描述矛盾。", "桌子": "搭配：桌子不会“作业太多”，句首的桌子与“我作业太多”搭配不当。"}, "sentence_index": 6, "correct_answer": "昨晚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨晚弟弟将去奶奶家。", "explanation": "〈明晚〉。昨晚指已经过去的夜晚，不能与表示将来的“将”搭配；将来的安排应说“明晚”。"}, {"text": "昨晚我们去看电影吧。", "explanation": "〈今晚〉。“吧”用于提议将来或现在的事，昨晚已经过去，提议应说“今晚”。"}, {"text": "昨晚我现在正在写作业。", "explanation": "这里应该用〈今晚〉。昨晚指已经过去的夜晚，不能用来指此刻正在进行的写作业；指这个夜晚应说“今晚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我那个昨晚洗衣服洗了一个小时。", "corrected_sentence": "我昨晚洗衣服洗了一个小时。", "error_description": "错误：“那个”这类指示词加量词不能修饰“昨晚”这样的时间词。正确：应去掉“那个”，说“我昨晚洗衣服洗了一个小时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨晚我们会聊天聊到很晚。", "corrected_sentence": "昨晚我们聊天聊到很晚。", "error_description": "时间错误：“昨晚”指已经过去的夜晚，不能和表示将来的“会”一起用，应去掉“会”，说“昨晚我们聊天聊到很晚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89653, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "干净", "is_correct": true, "explanation": "“干净”与“肮脏”是反义词，指东西没有污垢。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线强或颜色鲜亮，与“肮脏”无关。"}, {"text": "狭窄", "is_correct": false, "explanation": "“狭窄”指空间小，与“肮脏”无关。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”指牢固、不易损坏，与“肮脏”无关。"}], "correct_answer": "干净", "explanations": {"干净": "“干净”与“肮脏”是反义词，指东西没有污垢。", "明亮": "“明亮”指光线强或颜色鲜亮，与“肮脏”无关。", "狭窄": "“狭窄”指空间小，与“肮脏”无关。", "结实": "“结实”指牢固、不易损坏，与“肮脏”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89653, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "干净", "is_correct": true, "explanation": "“干净”与“肮脏”是反义词，指没有污垢。"}, {"text": "响亮", "is_correct": false, "explanation": "“响亮”指声音大，与“肮脏”无关。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”指质地不硬，与“肮脏”无关。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”指速度快，与“肮脏”无关。"}], "correct_answer": "干净", "explanations": {"干净": "“干净”与“肮脏”是反义词，指没有污垢。", "响亮": "“响亮”指声音大，与“肮脏”无关。", "柔软": "“柔软”指质地不硬，与“肮脏”无关。", "迅速": "“迅速”指速度快，与“肮脏”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89653, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "肮脏是说很不干净，有很多泥和脏东西。", "primary_collocate": null, "pronunciation": "āng zāng", "ipa": "ɑŋ˥ tsɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这条河又黑又臭，水很肮脏。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的衣服上全是泥，非常肮脏。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩了一天，手变得很肮脏。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的垃圾桶又肮脏又难闻。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间屋子好久没打扫，地板很肮脏。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别用肮脏的手摸食物。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，街上到处都是肮脏的泥水。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的袜子肮脏得不能再穿了。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里肮脏的碗堆得像山一样。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们从矿里出来，脸上很肮脏。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "肮肮脏脏", "label": "重叠"}, {"form": "骯髒", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西很不干净，满是泥和脏东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89653, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明亮", "is_correct": false, "explanation": "语义：水又黑又臭，“明亮”说水清亮有光，与前一分句的描述矛盾。"}, {"text": "肮脏", "is_correct": true, "explanation": "“肮脏”指很不干净，与“又黑又臭”的描述相符。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：“清澈”指水清得见底，与“又黑又臭”正好相反。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”形容空间小，不能用来形容水。"}], "explanations": {"明亮": "语义：水又黑又臭，“明亮”说水清亮有光，与前一分句的描述矛盾。", "肮脏": "“肮脏”指很不干净，与“又黑又臭”的描述相符。", "清澈": "语义：“清澈”指水清得见底，与“又黑又臭”正好相反。", "狭窄": "搭配：“狭窄”形容空间小，不能用来形容水。"}, "sentence_index": 0, "correct_answer": "肮脏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块刚消过毒的手术台很肮脏。", "explanation": "语义：手术台刚消过毒，是干净的；“肮脏”表示很不干净，此处应说“干净”，不能用“肮脏”。"}, {"text": "这碗刚煮好的白粥很肮脏。", "explanation": "语义：白粥刚煮好，是干净的；“肮脏”表示很不干净，此处应说“干净”，不能用“肮脏”。"}, {"text": "他刚换上的新白衬衫很肮脏。", "explanation": "语义：刚换上的新衬衫是干净的；“肮脏”表示很不干净，此处应说“干净”，不能用“肮脏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89653, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明", "is_correct": false, "explanation": "语义：泥水浑浊，不可能透明，与“泥水”矛盾。"}, {"text": "肮脏", "is_correct": true, "explanation": "“肮脏”指很不干净，与“泥水”相符。"}, {"text": "崭新", "is_correct": false, "explanation": "搭配：“崭新”多用于新的物品，不能修饰“泥水”。"}, {"text": "洁白", "is_correct": false, "explanation": "体貌：泥水是浑浊的土色，不会洁白。"}], "explanations": {"透明": "语义：泥水浑浊，不可能透明，与“泥水”矛盾。", "肮脏": "“肮脏”指很不干净，与“泥水”相符。", "崭新": "搭配：“崭新”多用于新的物品，不能修饰“泥水”。", "洁白": "体貌：泥水是浑浊的土色，不会洁白。"}, "sentence_index": 6, "correct_answer": "肮脏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气很肮脏。", "explanation": "这里应该用〈糟糕〉或〈阴沉〉。“肮脏”只用于东西、地方或人的不干净，不能用来形容天气。"}, {"text": "妈妈刚把地板拖得干干净净，地板很肮脏。", "explanation": "语义：地板刚拖得干干净净，应说“干净”；“肮脏”表示很不干净，与前句矛盾。"}, {"text": "他把衣服洗得肮脏。", "explanation": "语义：“洗”的结果应是干净，“洗得肮脏”与常理相反；把东西弄得不干净要说“弄脏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的鞋子非常肮脏地。", "corrected_sentence": "他的鞋子非常肮脏。", "error_description": "错误：“肮脏”作谓语时，后面不能加“地”。“地”用于修饰动词，不用于句末的形容词谓语；正确说法是“非常肮脏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双鞋肮脏的得不能穿了。", "corrected_sentence": "这双鞋肮脏得不能穿了。", "error_description": "错误：补语“得不能穿了”前不能用“的”，应说“肮脏得不能穿了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
