INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89654, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "比喻思想、手段或行为卑劣，不光明正大。", "primary_collocate": null, "pronunciation": "āng zāng", "ipa": "ɑŋ˥ tsɑŋ˥", "syllable_count": 2, "sentences": [{"text": "他用肮脏的手段赢了比赛。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个肮脏的交易。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心思太肮脏了。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个官员做了很多肮脏的事。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不愿意参加这种肮脏的游戏。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了钱，他变得越来越肮脏。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠肮脏的办法赚了很多钱。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社会上有不少肮脏的事。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的灵魂早已肮脏不堪。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条小巷里常有坏人做肮脏的事。", "target_word": "肮脏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "肮肮脏脏", "label": "重叠"}, {"form": "骯髒", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比喻思想、手段、行为卑劣不光彩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”形容颜色，手段没有颜色，不能说“雪白的手段”。"}, {"text": "肮脏", "is_correct": true, "explanation": "“肮脏”指手段卑劣、不光明，与“赢了比赛”的语境相符。"}, {"text": "宽阔", "is_correct": false, "explanation": "搭配：“宽阔”形容空间大，不能修饰“手段”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰“手段”。"}], "explanations": {"雪白": "体貌：“雪白”形容颜色，手段没有颜色，不能说“雪白的手段”。", "肮脏": "“肮脏”指手段卑劣、不光明，与“赢了比赛”的语境相符。", "宽阔": "搭配：“宽阔”形容空间大，不能修饰“手段”。", "清脆": "搭配：“清脆”形容声音，不能修饰“手段”。"}, "sentence_index": 0, "correct_answer": "肮脏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他主动帮助了一位迷路的老人，这是一件很肮脏的好事。", "explanation": "语义：“肮脏”表示卑劣，不能用来形容“好事”；这里应说“高尚”或“善良”。"}, {"text": "他拾金不昧，人品非常肮脏。", "explanation": "语义：“拾金不昧”是品德高尚的表现，用“肮脏”（卑劣）形容“人品”与之矛盾；此处应说“高尚”。"}, {"text": "他诚实守信，我很佩服他的肮脏。", "explanation": "语义：“肮脏”表示卑劣，这里用“佩服”来称赞，与“肮脏”的意思相反；此处应说“正直”或“高尚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笔直", "is_correct": false, "explanation": "搭配：“笔直”形容线条或姿态，不能修饰“办法”。"}, {"text": "肮脏", "is_correct": true, "explanation": "“肮脏”指手段卑劣、不光明正大，与“靠……赚了很多钱”相符。"}, {"text": "漆黑", "is_correct": false, "explanation": "体貌：“漆黑”形容颜色，办法没有颜色。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容山坡等地形，不能修饰“办法”。"}], "explanations": {"笔直": "搭配：“笔直”形容线条或姿态，不能修饰“办法”。", "肮脏": "“肮脏”指手段卑劣、不光明正大，与“靠……赚了很多钱”相符。", "漆黑": "体貌：“漆黑”形容颜色，办法没有颜色。", "陡峭": "搭配：“陡峭”形容山坡等地形，不能修饰“办法”。"}, "sentence_index": 6, "correct_answer": "肮脏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的时间很肮脏。", "explanation": "这里应该用〈不巧〉。“肮脏”形容东西、地方、人或行为的不干净或卑劣，不能用来形容“时间”。"}, {"text": "他对朋友一向真诚，大家都说他的人品很肮脏。", "explanation": "语义：“真诚”与“肮脏”（卑劣）意思相反，此处应说“高尚”或“正直”。"}, {"text": "他把自己的名誉洗得肮脏。", "explanation": "这里误用“肮脏”表示“弄脏”的结果；“洗”的结果应是干净，应说“洗清名誉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的心思越来越肮脏着。", "corrected_sentence": "他的心思越来越肮脏了。", "error_description": "错误：表示“越来越”的变化已经发生，句末应用“了”，“肮脏”作谓语后不能用“着”；正确说法是“越来越肮脏了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔交易非常肮脏地。", "corrected_sentence": "这笔交易非常肮脏。", "error_description": "错误：“肮脏”作谓语时，后面不能加“地”；应说“非常肮脏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
