INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89655, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有好办法，做得对。", "primary_collocate": null, "pronunciation": "yǒu dào", "ipa": "jou˨˩˦ tau˥˩", "syllable_count": 2, "sentences": [{"text": "这家店经营有道，生意越来越好。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他教子有道，两个孩子都很听话。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理管理有道，员工都愿意留下来。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她理财有道，三年就买了房子。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人养生有道，八十岁还爬山。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板用人有道，每个人都做得很好。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位店长待客有道，客人都愿意再来。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶持家有道，家里总是干干净净。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师教学有道，学生进步很快。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他养花有道，院子里一年四季都有花。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经营有道", "label": "复合"}, {"form": "教子有道", "label": "复合"}], "register": "书面", "sense_fingerprint": "做某事有好办法、做得对，多接在“经营、教子”等词后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc993ad-d691-45ca-87b5-147139094920') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89655, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有道", "is_correct": true, "explanation": "有道 yǒu dào 指做事有好办法、做得对。"}, {"text": "游到", "is_correct": false, "explanation": "游到 yóu dào 与 yǒu dào 第一音节声调不同（第二声与第三声），意思是游动到某处。"}, {"text": "诱导", "is_correct": false, "explanation": "诱导 yòu dǎo 两个音节的声调都不同，意思是引导，与“有道”意思不同。"}, {"text": "油道", "is_correct": false, "explanation": "油道 yóu dào 第一音节声调不同（第二声），意思是润滑油的通道，与“有道”不同。"}], "explanations": {"有道": "有道 yǒu dào 指做事有好办法、做得对。", "游到": "游到 yóu dào 与 yǒu dào 第一音节声调不同（第二声与第三声），意思是游动到某处。", "诱导": "诱导 yòu dǎo 两个音节的声调都不同，意思是引导，与“有道”意思不同。", "油道": "油道 yóu dào 第一音节声调不同（第二声），意思是润滑油的通道，与“有道”不同。"}, "sentence_index": null, "correct_answer": "有道"}, "level_3": {"options": [{"text": "有道", "is_correct": true, "explanation": "有道指做事有办法，与“生意越来越好”相符。"}, {"text": "混乱", "is_correct": false, "explanation": "语义：经营混乱与“生意越来越好”矛盾。"}, {"text": "草率", "is_correct": false, "explanation": "语义：经营草率不会让生意越来越好。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场面或气氛，不用来说经营方式。"}], "explanations": {"有道": "有道指做事有办法，与“生意越来越好”相符。", "混乱": "语义：经营混乱与“生意越来越好”矛盾。", "草率": "语义：经营草率不会让生意越来越好。", "冷清": "搭配：“冷清”形容场面或气氛，不用来说经营方式。"}, "sentence_index": 0, "correct_answer": "有道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌很有道，大家都爱听。", "explanation": "这里应该用〈动听〉。“有道”形容人做事有办法，不用来形容歌曲的好听程度。"}, {"text": "这种药很有道，吃了两天就好了。", "explanation": "这里应该用〈有效〉。“有道”形容人做事有办法，不用来说药物的效果。"}, {"text": "这件衣服很有道，穿出去很有气质。", "explanation": "这里应该用〈精致〉。“有道”形容人的做法有讲究，不用来形容衣服的做工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89655, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有道", "is_correct": true, "explanation": "有道指待客有办法，与“客人都愿意再来”相符。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：待客冷淡与“客人都愿意再来”矛盾。"}, {"text": "粗鲁", "is_correct": false, "explanation": "语义：待客粗鲁不会让客人都愿意再来。"}, {"text": "凶猛", "is_correct": false, "explanation": "搭配：“凶猛”多形容动物或力量，不说“待客凶猛”。"}], "explanations": {"有道": "有道指待客有办法，与“客人都愿意再来”相符。", "冷淡": "语义：待客冷淡与“客人都愿意再来”矛盾。", "粗鲁": "语义：待客粗鲁不会让客人都愿意再来。", "凶猛": "搭配：“凶猛”多形容动物或力量，不说“待客凶猛”。"}, "sentence_index": 6, "correct_answer": "有道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的做工很有道，用了很多年都没坏。", "explanation": "这里应该用〈精良〉。“有道”形容人的做事方法，不用来评价机器的做工。"}, {"text": "这家店的价格很有道，大家都爱来买。", "explanation": "这里应该用〈实惠〉。“有道”不用来说价格，只能说人做事有办法。"}, {"text": "这张床很有道，躺上去很放松。", "explanation": "这里应该用〈舒适〉。“有道”形容人的做法，不用来形容床的舒适程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位大夫有道，病人都很信任他。", "corrected_sentence": "这位大夫看病有道，病人都很信任他。", "error_description": "成分缺失：“有道”前面要有表示做法的词，说“看病有道”，不能只说“大夫有道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位大姐有道，全家都爱吃她做的菜。", "corrected_sentence": "这位大姐做饭有道，全家都爱吃她做的菜。", "error_description": "成分缺失：“有道”前面要有表示做法的词，说“做饭有道”，不能只说“大姐有道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
