INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89656, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有门路、有办法；合乎事理。", "primary_collocate": null, "pronunciation": "yǒu dào", "ipa": "jou˨˩˦ tau˥˩", "syllable_count": 2, "sentences": [{"text": "他生财有道，不上班也能赚到钱。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "君子爱财，取之有道。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱要花得好，也要用之有道。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做人进退有道，从不乱说乱动。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张处世有道，和谁都合得来。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位县长为官有道，百姓都很信他。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她办事有道，大家的难题她都能解决。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赚钱有道，每一分都来得正当。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家人人都守规矩，真是治家有道。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他进货有道，总能拿到便宜的货。", "target_word": "有道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生财有道", "label": "复合"}, {"form": "取之有道", "label": "复合"}], "register": "书面", "sense_fingerprint": "有门路、有办法，做法合乎事理，多见于固定说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc993ad-d691-45ca-87b5-147139094920') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89656, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有道", "is_correct": true, "explanation": "有道 yǒu dào 指有门路、有办法，或做法合乎事理。"}, {"text": "游到", "is_correct": false, "explanation": "游到 yóu dào 与 yǒu dào 第一音节声调不同（第二声与第三声），意思是游动到某处。"}, {"text": "诱导", "is_correct": false, "explanation": "诱导 yòu dǎo 两个音节的声调都不同，意思是引导，与“有道”意思不同。"}, {"text": "油道", "is_correct": false, "explanation": "油道 yóu dào 第一音节声调不同（第二声），意思是润滑油的通道，与“有道”不同。"}], "explanations": {"有道": "有道 yǒu dào 指有门路、有办法，或做法合乎事理。", "游到": "游到 yóu dào 与 yǒu dào 第一音节声调不同（第二声与第三声），意思是游动到某处。", "诱导": "诱导 yòu dǎo 两个音节的声调都不同，意思是引导，与“有道”意思不同。", "油道": "油道 yóu dào 第一音节声调不同（第二声），意思是润滑油的通道，与“有道”不同。"}, "sentence_index": null, "correct_answer": "有道"}, "level_3": {"options": [{"text": "有道", "is_correct": true, "explanation": "有道指有门路、有办法，与“能赚到钱”相符。"}, {"text": "无方", "is_correct": false, "explanation": "语义：生财无方与“不上班也能赚到钱”矛盾。"}, {"text": "乏术", "is_correct": false, "explanation": "语义：生财乏术与“不上班也能赚到钱”的结果矛盾。"}, {"text": "吝啬", "is_correct": false, "explanation": "搭配：“吝啬”形容人的性情，不用来修饰“生财”的方式。"}], "explanations": {"有道": "有道指有门路、有办法，与“能赚到钱”相符。", "无方": "语义：生财无方与“不上班也能赚到钱”矛盾。", "乏术": "语义：生财乏术与“不上班也能赚到钱”的结果矛盾。", "吝啬": "搭配：“吝啬”形容人的性情，不用来修饰“生财”的方式。"}, "sentence_index": 0, "correct_answer": "有道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把刀很有道，切菜很快。", "explanation": "这里应该用〈锋利〉。“有道”形容人的做法，不用来形容刀的锋利程度。"}, {"text": "这张桌子很有道，搬家也不怕。", "explanation": "这里应该用〈结实〉。“有道”形容人处事有办法，不用来形容桌子的坚固程度。"}, {"text": "这道菜很有道，大家都夸好吃。", "explanation": "这里应该用〈可口〉。“有道”形容人做事有办法，不用来形容菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有道", "is_correct": true, "explanation": "有道指办事有办法，与“大家的难题她都能解决”相符。"}, {"text": "愚笨", "is_correct": false, "explanation": "语义：办事愚笨与“难题都能解决”矛盾。"}, {"text": "糊涂", "is_correct": false, "explanation": "语义：办事糊涂，与“大家的难题她都能解决”矛盾。"}, {"text": "拙劣", "is_correct": false, "explanation": "语义：办事拙劣，与“大家的难题她都能解决”矛盾。"}], "explanations": {"有道": "有道指办事有办法，与“大家的难题她都能解决”相符。", "愚笨": "语义：办事愚笨与“难题都能解决”矛盾。", "糊涂": "语义：办事糊涂，与“大家的难题她都能解决”矛盾。", "拙劣": "语义：办事拙劣，与“大家的难题她都能解决”矛盾。"}, "sentence_index": 6, "correct_answer": "有道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画很有道，挂在客厅很合适。", "explanation": "这里应该用〈漂亮〉。“有道”形容人做事有办法，不用来形容画的美观。"}, {"text": "这条毯子很有道，冬天盖着很暖和。", "explanation": "这里应该用〈柔软〉。“有道”不用来形容毯子的质地，只能说人做事有办法。"}, {"text": "这个花瓶很有道，摆在桌上很好看。", "explanation": "这里应该用〈精美〉。“有道”形容人的做法，不用来形容花瓶的做工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位商人有道，几年就发了财。", "corrected_sentence": "这位商人经商有道，几年就发了财。", "error_description": "成分缺失：“有道”前面要有表示做法的词，说“经商有道”，不能只说“商人有道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老李有道，找他帮忙总能办成。", "corrected_sentence": "老李办事有道，找他帮忙总能办成。", "error_description": "成分缺失：“有道”前面要有表示做法的词，说“办事有道”，不能只说“老李有道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89658, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低落", "is_correct": true, "explanation": "正确：低落指情绪、士气下降，与“情绪高涨”的“高涨”构成反义关系。"}, {"text": "坚固", "is_correct": false, "explanation": "坚固指不容易损坏，与“高涨”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐指排列有序，与“高涨”没有反义关系。"}, {"text": "轻便", "is_correct": false, "explanation": "轻便指分量轻、便于携带，与“高涨”没有反义关系。"}], "correct_answer": "低落", "explanations": {"低落": "正确：低落指情绪、士气下降，与“情绪高涨”的“高涨”构成反义关系。", "坚固": "坚固指不容易损坏，与“高涨”没有反义关系。", "整齐": "整齐指排列有序，与“高涨”没有反义关系。", "轻便": "轻便指分量轻、便于携带，与“高涨”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89658, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低落", "is_correct": true, "explanation": "正确：低落指情绪向下降，与“高涨”构成反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰指明白、不模糊，与“高涨”没有反义关系。"}, {"text": "深厚", "is_correct": false, "explanation": "深厚指程度深，与“高涨”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭指坡度大，与“高涨”没有反义关系。"}], "correct_answer": "低落", "explanations": {"低落": "正确：低落指情绪向下降，与“高涨”构成反义关系。", "清晰": "清晰指明白、不模糊，与“高涨”没有反义关系。", "深厚": "深厚指程度深，与“高涨”没有反义关系。", "陡峭": "陡峭指坡度大，与“高涨”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89658, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "水位、物价或情绪等迅速上升、增长。", "primary_collocate": null, "pronunciation": "gāo zhǎng", "ipa": "kau˥ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "比赛开始前，大家的情绪十分高涨。", "target_word": "高涨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，河里的水位迅速高涨。", "target_word": "高涨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，城里的物价一直高涨。", "target_word": "高涨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，工人们的热情更加高涨。", "target_word": "高涨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一夸，孩子们学习的热情高涨起来。", "target_word": "高涨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物价高涨，很多人买东西更小心了。", "target_word": "高涨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱起歌来，大家的情绪越来越高涨。", "target_word": "高涨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨一直下，河水高涨，村民很担心。", "target_word": "高涨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价高涨的时候，他没有买房子。", "target_word": "高涨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队赢了，球迷的热情空前高涨。", "target_word": "高涨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高涨了", "label": "体标"}], "register": "中性", "sense_fingerprint": "高涨：水位、物价、情绪等迅速上升增长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e48683c-72c5-47cf-8ca9-695253ccc13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高涨", "is_correct": true, "explanation": "正确：高涨指情绪迅速上升，“情绪十分高涨”搭配自然。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：坚硬形容物体的质地，不能形容情绪。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：狭窄指空间小，与情绪无关。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：干燥多用于空气、土地，不说“情绪十分干燥”。"}], "explanations": {"高涨": "正确：高涨指情绪迅速上升，“情绪十分高涨”搭配自然。", "坚硬": "语义：坚硬形容物体的质地，不能形容情绪。", "狭窄": "语义：狭窄指空间小，与情绪无关。", "干燥": "搭配：干燥多用于空气、土地，不说“情绪十分干燥”。"}, "sentence_index": 0, "correct_answer": "高涨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重高涨了三公斤。", "explanation": "这里应该用〈增加〉。高涨用于水位、物价、情绪，体重的变化要用“增加”。"}, {"text": "这次训练以后，他的身高高涨了不少。", "explanation": "这里应该用〈增长〉。高涨用于水位、物价、情绪，身高的增加要用“增长”。"}, {"text": "最近他的成绩高涨得很快。", "explanation": "这里应该用〈上升〉。高涨多指水位、物价、情绪，成绩的提升要用“上升”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高涨", "is_correct": true, "explanation": "正确：高涨指情绪迅速上升，“情绪越来越高涨”搭配自然。"}, {"text": "笔直", "is_correct": false, "explanation": "语义：笔直形容线条或姿态，不能形容情绪。"}, {"text": "浑浊", "is_correct": false, "explanation": "搭配：浑浊多指水或空气，说情绪不用“浑浊”。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：陡峭形容坡度大，与情绪无关。"}], "explanations": {"高涨": "正确：高涨指情绪迅速上升，“情绪越来越高涨”搭配自然。", "笔直": "语义：笔直形容线条或姿态，不能形容情绪。", "浑浊": "搭配：浑浊多指水或空气，说情绪不用“浑浊”。", "陡峭": "语义：陡峭形容坡度大，与情绪无关。"}, "sentence_index": 6, "correct_answer": "高涨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段路程高涨了一半。", "explanation": "这里应该用〈延长〉。高涨用于水位、物价、情绪，路程变长要用“延长”。"}, {"text": "这场比赛高涨了一个星期才开始。", "explanation": "这里应该用〈推迟〉。高涨不用于比赛的时间，时间往后移要用“推迟”。"}, {"text": "这块地的面积高涨了不少。", "explanation": "这里应该用〈扩大〉。高涨用于水位、物价、情绪，面积变大要用“扩大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天到了，小河的水位慢慢高涨起去。", "corrected_sentence": "春天到了，小河的水位慢慢高涨起来。", "error_description": "“高涨起去”错误，应为“高涨起来”。表示状态逐渐开始出现，要用趋向补语“起来”，不用“起去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛结束后，观众高涨地热情让人感动。", "corrected_sentence": "比赛结束后，观众高涨的热情让人感动。", "error_description": "“高涨地热情”错误，应为“高涨的热情”。形容词修饰名词时要用“的”，不用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
