INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89660, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指所在的这篇文章。", "primary_collocate": null, "pronunciation": "běn wén", "ipa": "pən˨˩˦ wən˧˥", "syllable_count": 2, "sentences": [{"text": "本文主要介绍北京的三个公园。", "target_word": "本文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本文想说明锻炼身体的好处。", "target_word": "本文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本文先说原因，再说办法。", "target_word": "本文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在本文中，我会用三个小故事说明这件事。", "target_word": "本文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本文所说的“学习”，指的是学汉语。", "target_word": "本文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本文的目的是帮助大家多读书。", "target_word": "本文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本文用到的图片都是我自己拍的。", "target_word": "本文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于这个问题，本文不再多说。", "target_word": "本文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本文分成三部分，下面先说第一部分。", "target_word": "本文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本文的意见只是我一个人的想法。", "target_word": "本文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "作者在文中指称自己所写的这篇文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6df07d-0870-46ca-9127-847b9f9f2ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鱼", "is_correct": false, "explanation": "语义：鱼不能介绍公园。"}, {"text": "本文", "is_correct": true, "explanation": "正确：“本文”指作者所写的这篇文章，可以介绍公园，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能介绍公园。"}, {"text": "出租车", "is_correct": false, "explanation": "搭配：“介绍……公园”的主语应是文字或节目，出租车不能做主语。"}], "explanations": {"鱼": "语义：鱼不能介绍公园。", "本文": "正确：“本文”指作者所写的这篇文章，可以介绍公园，符合句意。", "冰箱": "语义：冰箱是家电，不能介绍公园。", "出租车": "搭配：“介绍……公园”的主语应是文字或节目，出租车不能做主语。"}, "sentence_index": 0, "correct_answer": "本文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本文一共有十二章，我们先读第一章。", "explanation": "这里应该用〈本书〉。本文指所在的这篇文章，不能分成章节。"}, {"text": "本文每周播出一次。", "explanation": "这里应该用〈本节目〉。本文只指文章，不能说每周播出。"}, {"text": "本文周末不营业。", "explanation": "这里应该用〈本店〉。本文不指店铺，不能说营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不能“用到”图片。"}, {"text": "本文", "is_correct": true, "explanation": "正确：“本文”指作者所写的这篇文章，文章里可以用到图片，符合句意。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能用图片。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“用到图片”的对象是文章或演示，饼干不能用图片。"}], "explanations": {"厨房": "语义：厨房是房间，不能“用到”图片。", "本文": "正确：“本文”指作者所写的这篇文章，文章里可以用到图片，符合句意。", "沙发": "语义：沙发是家具，不能用图片。", "饼干": "搭配：“用到图片”的对象是文章或演示，饼干不能用图片。"}, "sentence_index": 6, "correct_answer": "本文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本文今年的销售额增长了一倍。", "explanation": "这里应该用〈本公司〉。本文只指所在的这篇文章，不能指公司，也不能说销售额增长。"}, {"text": "本文今年招收了两百名新生。", "explanation": "这里应该用〈本校〉。本文不指学校，不能招收学生。"}, {"text": "本文今年有很多新公园。", "explanation": "这里应该用〈本市〉。本文不指城市，不能说城市里有公园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一篇本文主要讨论城市交通的问题。", "corrected_sentence": "本文主要讨论城市交通的问题。", "error_description": "错误：“一篇本文”。正确：“本文”。“本文”已指所在的这篇文章，所指确定，不能再用数量词“一篇”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
