INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89661, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "上半年是一年里前面的六个月。", "primary_collocate": null, "pronunciation": "shàng bàn nián", "ipa": "ʂɑŋ˥˩ pan˥˩ njɛn˧˥", "syllable_count": 3, "sentences": [{"text": "我上半年一直在北京工作。", "target_word": "上半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年上半年雨很多。", "target_word": "上半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司上半年卖了很多车。", "target_word": "上半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上半年学了三百个汉字。", "target_word": "上半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上半年我很忙，下半年会好一点。", "target_word": "上半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年上半年我去过上海。", "target_word": "上半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店上半年的客人比较少。", "target_word": "上半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上半年的考试已经结束了。", "target_word": "上半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打算上半年学会游泳。", "target_word": "上半年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上半年她每个周末都去爬山。", "target_word": "上半年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一年的前六个月，指一月到六月的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a37e-859d-480a-acef-93c3977707a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上半年", "is_correct": true, "explanation": "正确答案。“上半年”指一年的前六个月，“我上半年一直在北京工作”成立。"}, {"text": "上半身", "is_correct": false, "explanation": "语义：“上半身”指人体的上半部分，不能表示时间，“我上半身一直在北京工作”不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，不能作时间状语。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能放在“我”之后作时间状语，“我天气一直在北京工作”不通。"}], "explanations": {"上半年": "正确答案。“上半年”指一年的前六个月，“我上半年一直在北京工作”成立。", "上半身": "语义：“上半身”指人体的上半部分，不能表示时间，“我上半身一直在北京工作”不通。", "体重": "语义：“体重”是身体的重量，不能作时间状语。", "天气": "搭配：“天气”不能放在“我”之后作时间状语，“我天气一直在北京工作”不通。"}, "sentence_index": 0, "correct_answer": "上半年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他上半年七月去了北京。", "explanation": "这里应该用〈下半年〉。“上半年”指一月到六月，不包括七月，七月属于下半年。"}, {"text": "我今天上半年很忙，下午有空。", "explanation": "这里应该用〈上午〉。“上半年”指一年的前六个月，不能指一天中的上午。"}, {"text": "他上半年的十二月去了北京。", "explanation": "这里应该用〈年末〉。“上半年”指一月到六月，不包括十二月，十二月属于年末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上半年", "is_correct": true, "explanation": "正确答案。“这家店上半年的客人”指这家店一年前六个月的客人，“比较少”说得通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的身体高矮，不能修饰“客人”的数量，“这家店身高的客人”不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能与“客人”组成时间修饰语，“这家店年龄的客人”不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是人体的温度，不能修饰“客人”，“这家店体温的客人”不通。"}], "explanations": {"上半年": "正确答案。“这家店上半年的客人”指这家店一年前六个月的客人，“比较少”说得通。", "身高": "语义：“身高”指人的身体高矮，不能修饰“客人”的数量，“这家店身高的客人”不通。", "年龄": "搭配：“年龄”不能与“客人”组成时间修饰语，“这家店年龄的客人”不通。", "体温": "语义：“体温”是人体的温度，不能修饰“客人”，“这家店体温的客人”不通。"}, "sentence_index": 6, "correct_answer": "上半年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "球队在比赛的上半年领先了三分。", "explanation": "这里应该用〈上半场〉。“上半年”指一年的前六个月，不指比赛的一段时间。"}, {"text": "今天的上半年我一直在学校。", "explanation": "这里应该用〈上半天〉。“上半年”是六个月，不能指一天之内的时段。"}, {"text": "这部电影的上半年很精彩。", "explanation": "这里应该用〈上半部〉。“上半年”指一年的时段，不能用来指电影的一部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她上半年半年一直在学校上课。", "corrected_sentence": "她上半年一直在学校上课。", "error_description": "多余的“半年”：“上半年”本身已含“半年”，后面不能重复。应说“她上半年一直在学校上课”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司上半年半年的收入增长了一倍。", "corrected_sentence": "这家公司上半年的收入增长了一倍。", "error_description": "多余的“半年”：“上半年”本身已含“半年”，后面不能重复。应说“上半年的收入”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
