INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89665, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "上司是工作的时候管着你的人。", "primary_collocate": null, "pronunciation": "shàng si", "ipa": "ʂɑŋ˥˩ sɿ", "syllable_count": 2, "sentences": [{"text": "上司在办公室里等你。", "target_word": "上司", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "上司在会上表扬了我。", "target_word": "上司", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的上司对工作要求很高。", "target_word": "上司", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上司每天看着我们工作。", "target_word": "上司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你应该把这件事告诉上司。", "target_word": "上司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的上司明天要去上海出差。", "target_word": "上司", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上司说今天的会很重要，大家都要来。", "target_word": "上司", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作的时候，上司管着我们。", "target_word": "上司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做得好的话，上司会给你机会。", "target_word": "上司", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他换了工作，新的上司是位女士。", "target_word": "上司", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "顶头上司", "label": "复合"}], "register": "中性", "sense_fingerprint": "工作时管着你的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '898186d7-746b-41f1-9872-48aa0b237dc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89665, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上司", "is_correct": true, "explanation": "上司 shàngsi，工作时管着你的人，是正确答案。"}, {"text": "上次", "is_correct": false, "explanation": "上次 shàngcì 与 上司 shàngsi 第二音节声母不同（c 与 s），意思是“上一回”。"}, {"text": "上市", "is_correct": false, "explanation": "上市 shàngshì 与 上司 shàngsi 第二音节声母不同（sh 与 s），意思是“商品投放市场”。"}, {"text": "上诉", "is_correct": false, "explanation": "上诉 shàngsù 与 上司 shàngsi 第二音节韵母不同（u 与 i），意思是“向上级法院申请重新审理”。"}, {"text": "上色", "is_correct": false, "explanation": "上色 shàngsè 与 上司 shàngsi 第二音节韵母不同（e 与 i）且声调不同，意思是“涂上颜色”。"}], "explanations": {"上司": "上司 shàngsi，工作时管着你的人，是正确答案。", "上次": "上次 shàngcì 与 上司 shàngsi 第二音节声母不同（c 与 s），意思是“上一回”。", "上市": "上市 shàngshì 与 上司 shàngsi 第二音节声母不同（sh 与 s），意思是“商品投放市场”。", "上诉": "上诉 shàngsù 与 上司 shàngsi 第二音节韵母不同（u 与 i），意思是“向上级法院申请重新审理”。", "上色": "上色 shàngsè 与 上司 shàngsi 第二音节韵母不同（e 与 i）且声调不同，意思是“涂上颜色”。"}, "sentence_index": null, "correct_answer": "上司"}, "level_3": {"options": [{"text": "上司", "is_correct": true, "explanation": "正确：工作时管着你的人，可以在办公室里等你，句意合理。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会等人，不能在办公室里等你。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不会在办公室里等人。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指身体外形，不能在办公室里等人。"}], "explanations": {"上司": "正确：工作时管着你的人，可以在办公室里等你，句意合理。", "窗户": "语义：窗户不会等人，不能在办公室里等你。", "月亮": "语义：月亮不会在办公室里等人。", "身材": "体貌：“身材”指身体外形，不能在办公室里等人。"}, "sentence_index": 0, "correct_answer": "上司"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的上司是住在隔壁的老王，我们常常一起散步。", "explanation": "这里应该用〈邻居〉。上司指工作中直接管你的人；住在隔壁、不管你工作的人要用邻居。"}, {"text": "我的上司都是新招的员工，我负责教他们。", "explanation": "这里应该用〈下属〉。上司是管别人的人；被你带着、管着的员工要用下属。"}, {"text": "我和小王是这家公司的上司，我们平分利润。", "explanation": "这里应该用〈合伙人〉。上司指职位比自己高的人；共同出资、地位平等的人要用合伙人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89665, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上司", "is_correct": true, "explanation": "正确：工作中管着你的人可以说会议很重要，要大家都来，句意合理。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不会说话，不能说会议很重要。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形特征，不会说话。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会讲会议的重要性。"}], "explanations": {"上司": "正确：工作中管着你的人可以说会议很重要，要大家都来，句意合理。", "黑板": "语义：黑板不会说话，不能说会议很重要。", "身高": "体貌：“身高”是人的外形特征，不会说话。", "小猫": "语义：小猫不会讲会议的重要性。"}, "sentence_index": 6, "correct_answer": "上司"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爸爸自己开了一家工厂，他是上司。", "explanation": "这里应该用〈老板〉。上司指职场中管你的人；自己开工厂的人是老板，不是上司。"}, {"text": "那位上司统治了三十年。", "explanation": "这里应该用〈皇帝〉。上司是职场中的上级，不能用来指统治国家的君主。"}, {"text": "那群海盗的上司很凶。", "explanation": "这里应该用〈首领〉。上司是职场中的上级，不用于海盗团伙的头目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天一只上司来找我谈话。", "corrected_sentence": "今天一位上司来找我谈话。", "error_description": "量词错误：“上司”指人，应用量词“位”，“只”多用于动物，不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们科新来上司很温和。", "corrected_sentence": "我们科新来的上司很温和。", "error_description": "定语错误：“新来”修饰名词“上司”时要加“的”，应说“新来的上司”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
