INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "职位比自己高、直接管辖自己的人。", "primary_collocate": null, "pronunciation": "shàng si", "ipa": "ʂɑŋ˥˩ sɿ", "syllable_count": 2, "sentences": [{"text": "上司的职位比我高。", "target_word": "上司", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新来的上司管我们三个人。", "target_word": "上司", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我做错事，上司很生气。", "target_word": "上司", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "上司让我今天把工作做完。", "target_word": "上司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对上司说了自己的想法。", "target_word": "上司", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上司不同意我请假。", "target_word": "上司", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想先问问上司，再决定。", "target_word": "上司", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "上司常常加班，我们也不能早走。", "target_word": "上司", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和同事都很尊敬我们的上司。", "target_word": "上司", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想让上司知道自己很努力。", "target_word": "上司", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "顶头上司", "label": "复合"}], "register": "中性", "sense_fingerprint": "职位比自己高、直接管自己的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '898186d7-746b-41f1-9872-48aa0b237dc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89666, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上司", "is_correct": true, "explanation": "上司 shàngsi，职位比自己高、直接管你的人，是正确答案。"}, {"text": "上次", "is_correct": false, "explanation": "上次 shàngcì 与 上司 shàngsi 第二音节声母不同（c 与 s），意思是“上一回”。"}, {"text": "上市", "is_correct": false, "explanation": "上市 shàngshì 与 上司 shàngsi 第二音节声母不同（sh 与 s），意思是“商品投放市场”。"}, {"text": "上诉", "is_correct": false, "explanation": "上诉 shàngsù 与 上司 shàngsi 第二音节韵母不同（u 与 i），意思是“向上级法院申请重新审理”。"}, {"text": "上色", "is_correct": false, "explanation": "上色 shàngsè 与 上司 shàngsi 第二音节韵母不同（e 与 i）且声调不同，意思是“涂上颜色”。"}], "explanations": {"上司": "上司 shàngsi，职位比自己高、直接管你的人，是正确答案。", "上次": "上次 shàngcì 与 上司 shàngsi 第二音节声母不同（c 与 s），意思是“上一回”。", "上市": "上市 shàngshì 与 上司 shàngsi 第二音节声母不同（sh 与 s），意思是“商品投放市场”。", "上诉": "上诉 shàngsù 与 上司 shàngsi 第二音节韵母不同（u 与 i），意思是“向上级法院申请重新审理”。", "上色": "上色 shàngsè 与 上司 shàngsi 第二音节韵母不同（e 与 i）且声调不同，意思是“涂上颜色”。"}, "sentence_index": null, "correct_answer": "上司"}, "level_3": {"options": [{"text": "上司", "is_correct": true, "explanation": "正确：职位比自己高、直接管你的人，与“职位比我高”相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有职位，不能说职位比我高。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指身体外形，不是有职位的人，不能与“职位”比高低。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“学历”指教育程度，不与“职位比我高”搭配。"}], "explanations": {"上司": "正确：职位比自己高、直接管你的人，与“职位比我高”相符。", "窗户": "语义：窗户没有职位，不能说职位比我高。", "身材": "体貌：“身材”指身体外形，不是有职位的人，不能与“职位”比高低。", "学历": "搭配：“学历”指教育程度，不与“职位比我高”搭配。"}, "sentence_index": 0, "correct_answer": "上司"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈开了一家餐馆，她是上司。", "explanation": "这里应该用〈老板〉。上司指职位比自己高、直接管你的人；自己开餐馆的人是老板，不是上司。"}, {"text": "这个国家的上司很受欢迎。", "explanation": "这里应该用〈领导〉。上司指工作中直接管你的人，不用于指一个国家的领导人。"}, {"text": "那个部落的上司很勇敢。", "explanation": "这里应该用〈首领〉。上司是职场中的上级，不用于部落的首领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上司", "is_correct": true, "explanation": "正确：职位比自己高、能给意见和决定的人，符合“再决定”的语境。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能给意见，问它之后再决定没有意义。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会回答问题，不能被问问。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“问”的对象应是能回答的人，“课本”不能说问问。"}], "explanations": {"上司": "正确：职位比自己高、能给意见和决定的人，符合“再决定”的语境。", "小猫": "语义：小猫不能给意见，问它之后再决定没有意义。", "桌子": "语义：桌子不会回答问题，不能被问问。", "课本": "搭配：“问”的对象应是能回答的人，“课本”不能说问问。"}, "sentence_index": 6, "correct_answer": "上司"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的上司是我的老同学，我们常一起吃饭。", "explanation": "这里应该用〈同学〉。上司指工作中管你的人；老同学不管你的工作，应用同学。"}, {"text": "我刚进公司，我的上司是个和我一样的新人，我们一起学习。", "explanation": "这里应该用〈同事〉。上司指职位比自己高的人；职位相同、一起工作的人要用同事。"}, {"text": "我的上司只有三个，他们都归我管。", "explanation": "这里应该用〈下属〉。上司是管别人的人；被你管的人要用下属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新来上司很严格。", "corrected_sentence": "新来的上司很严格。", "error_description": "定语错误：“新来”修饰名词“上司”时要加“的”，应说“新来的上司”，不能说“新来上司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们科今天来了一把上司。", "corrected_sentence": "我们科今天来了一位上司。", "error_description": "量词错误：“上司”指人，应用量词“位”，“把”用于有柄的东西，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
