INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89667, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因为别人和自己不一样，就看不起他、不公平地对他。", "primary_collocate": null, "pronunciation": "qí shì", "ipa": "tɕʰi˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "有些人因为他的口音歧视他。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们不应该因为小明很穷就歧视他。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从不歧视和自己不一样的人。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是外国人，常常有人歧视他。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别因为朋友的肤色不同就歧视他。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈教我，不要歧视穷人。", "target_word": "歧视", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小时候有人歧视过我，因为我说话有口音。", "target_word": "歧视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿不好，但是没有人歧视他。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么歧视新来的同事？", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她穿得很旧，同学们就歧视她，不跟她玩。", "target_word": "歧视", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "歧视了", "label": "体标（了）"}, {"form": "歧视过", "label": "体标（过）"}, {"form": "歧视着", "label": "体标（着）"}], "register": "书面", "sense_fingerprint": "因为别人不一样而看不起、不公平地对待他", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc993ad-d691-45ca-87b5-147139094920') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89667, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "歧视", "is_correct": true, "explanation": "歧视：正确答案，意思是因为别人与自己不一样而看不起他、不公平地对待他。"}, {"text": "其实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“其实”意思是实际上，与“歧视”不同。"}, {"text": "气势", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，“气势”指气派和声势。"}, {"text": "启示", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，“启示”指给人的提示或教导。"}], "explanations": {"歧视": "歧视：正确答案，意思是因为别人与自己不一样而看不起他、不公平地对待他。", "其实": "shí（第二声）与 shì（第四声）声调不同，“其实”意思是实际上，与“歧视”不同。", "气势": "qì（第四声）与 qí（第二声）声调不同，“气势”指气派和声势。", "启示": "qǐ（第三声）与 qí（第二声）声调不同，“启示”指给人的提示或教导。"}, "sentence_index": null, "correct_answer": "歧视"}, "level_3": {"options": [{"text": "歧视", "is_correct": true, "explanation": "歧视：因为口音不同而看不起他，符合句中的因果关系。"}, {"text": "同情", "is_correct": false, "explanation": "语义：因为口音而同情他，与句中的负面对待不符。"}, {"text": "疼爱", "is_correct": false, "explanation": "语义：因为口音而疼爱他，与句中的负面对待不符。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”针对事件或成就，不能用于“因为他的口音”这样的原因。"}], "explanations": {"歧视": "歧视：因为口音不同而看不起他，符合句中的因果关系。", "同情": "语义：因为口音而同情他，与句中的负面对待不符。", "疼爱": "语义：因为口音而疼爱他，与句中的负面对待不符。", "庆祝": "搭配：“庆祝”针对事件或成就，不能用于“因为他的口音”这样的原因。"}, "sentence_index": 0, "correct_answer": "歧视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师歧视这个学生的作文。", "explanation": "〈欣赏〉。歧视的对象必须是人；评价作文应说“欣赏”。"}, {"text": "我每天歧视我的鱼。", "explanation": "〈喂养〉。歧视只用于人，动物不能作宾语；照顾鱼应说“喂养”。"}, {"text": "我们歧视这次活动。", "explanation": "〈评价〉。歧视的对象必须是人，不能是活动；对活动发表看法应说“评价”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89667, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歧视", "is_correct": true, "explanation": "歧视：因为口音不同而不公平地对待我，符合句意。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：因为口音而表扬，与句中“歧视”所表达的因果关系不符。"}, {"text": "赞颂", "is_correct": false, "explanation": "语义：不会因为别人说话有口音而赞颂他；句子描写的是被不公平对待的经历，与“赞颂”不符。"}, {"text": "疼爱", "is_correct": false, "explanation": "语义：因为口音而疼爱我，与句中的负面对待不符。"}], "explanations": {"歧视": "歧视：因为口音不同而不公平地对待我，符合句意。", "表扬": "语义：因为口音而表扬，与句中“歧视”所表达的因果关系不符。", "赞颂": "语义：不会因为别人说话有口音而赞颂他；句子描写的是被不公平对待的经历，与“赞颂”不符。", "疼爱": "语义：因为口音而疼爱我，与句中的负面对待不符。"}, "sentence_index": 6, "correct_answer": "歧视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈歧视我快点写作业。", "explanation": "这里应该用〈催促〉。歧视表示不公平地对待，不能带“快点写作业”这种催促内容；催人快点做事应说“催促”。"}, {"text": "他热情地歧视我们。", "explanation": "这里应该用〈欢迎〉。歧视是不公平地对待，与“热情地”的语气矛盾；热情迎接客人应说“欢迎”。"}, {"text": "我生病了，朋友来医院歧视我。", "explanation": "这里应该用〈看望〉。歧视是因为别人不一样而不公平地对待他，与朋友到医院来关心病人的情境矛盾；去医院探望病人应说“看望”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们歧视很厉害。", "corrected_sentence": "同学们歧视得很厉害。", "error_description": "错误：程度补语前漏掉了“得”。正确：“得”应紧跟动词，说“歧视得很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一直歧视我着，我很难过。", "corrected_sentence": "她一直歧视着我，我很难过。", "error_description": "错误：动态助词“着”放错了位置。正确：“着”应紧跟动词，说“一直歧视着我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d1d199-a2ce-4d6e-bae0-8e9773a2fc66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89669, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正确", "is_correct": true, "explanation": "“正确”与“不正确”相对，是反义词。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”说心情，与“不正确”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”说外貌，与“不正确”没有反义关系。"}, {"text": "方便", "is_correct": false, "explanation": "“方便”说便利，与“不正确”没有反义关系。"}], "correct_answer": "正确", "explanations": {"正确": "“正确”与“不正确”相对，是反义词。", "高兴": "“高兴”说心情，与“不正确”没有反义关系。", "漂亮": "“漂亮”说外貌，与“不正确”没有反义关系。", "方便": "“方便”说便利，与“不正确”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89669, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正确", "is_correct": true, "explanation": "“正确”与“不正确”相对，是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”说明晰，与“不正确”没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”说坚固，与“不正确”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”说光线，与“不正确”没有反义关系。"}], "correct_answer": "正确", "explanations": {"正确": "“正确”与“不正确”相对，是反义词。", "清楚": "“清楚”说明晰，与“不正确”没有反义关系。", "结实": "“结实”说坚固，与“不正确”没有反义关系。", "明亮": "“明亮”说光线，与“不正确”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89669, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不正确是说不对，有错。", "primary_collocate": null, "pronunciation": "bù zhèng què", "ipa": "pu˥˩ ʈʂɤŋ˥˩ tɕʰɥe˥˩", "syllable_count": 3, "sentences": [{"text": "这道题的答案不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的发音有点儿不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的这个字不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样用药是不正确的。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的坐姿不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子的写法不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "方法不正确，学得很慢。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答不正确，大家都笑了。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个说法不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表上的电话号码不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不正确的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "答案、发音、写法等不对、有错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e48683c-72c5-47cf-8ca9-695253ccc13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89669, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不正确", "is_correct": true, "explanation": "“不正确”说答案有错，与句意相符。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“湿”说含水，答案没有干湿，“答案湿”不通。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，答案不说速度，“答案快”不通。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”说厚度，答案没有厚度，“答案厚”不通。"}], "explanations": {"不正确": "“不正确”说答案有错，与句意相符。", "湿": "语义：“湿”说含水，答案没有干湿，“答案湿”不通。", "快": "语义：“快”说速度，答案不说速度，“答案快”不通。", "厚": "语义：“厚”说厚度，答案没有厚度，“答案厚”不通。"}, "sentence_index": 0, "correct_answer": "不正确"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的笑容很不正确。", "explanation": "笑容没有对错，“不正确”只用于说答案、做法、说法等有错的事，这里说不通。"}, {"text": "这块石头很不正确。", "explanation": "石头没有对错，“不正确”只用于说答案、做法、说法等有错的事，这里说不通。"}, {"text": "他的身体很不正确。", "explanation": "这里应该用〈不舒服〉。“不正确”指事情、说法有错，说身体状况要用“不舒服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89669, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不正确", "is_correct": true, "explanation": "“不正确”说方法有错，与前半句一致。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”说味道，方法没有咸淡，“方法咸”不通。"}, {"text": "宽", "is_correct": false, "explanation": "语义：“宽”说宽度，方法没有宽窄，“方法宽”不通。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说温度，方法没有温度，“方法冷”不通。"}], "explanations": {"不正确": "“不正确”说方法有错，与前半句一致。", "咸": "语义：“咸”说味道，方法没有咸淡，“方法咸”不通。", "宽": "语义：“宽”说宽度，方法没有宽窄，“方法宽”不通。", "冷": "语义：“冷”说温度，方法没有温度，“方法冷”不通。"}, "sentence_index": 6, "correct_answer": "不正确"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的个子很不正确。", "explanation": "个子没有对错，“不正确”只用于说答案、做法、说法等有错的事，这里说不通。"}, {"text": "这只猫的脾气很不正确。", "explanation": "这里应该用〈不好〉。“不正确”说说法、做法有错，形容脾气要用“不好”。"}, {"text": "今天的天气很不正确。", "explanation": "这里应该用〈不好〉。天气没有对错，“不正确”只用于说答案、做法、说法等有错的事，说天气要用“不好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个不正确数字需要重新算一下。", "corrected_sentence": "这个不正确的数字需要重新算一下。", "error_description": "“不正确数字”错误，应为“不正确的数字”。形容词“不正确”修饰名词时，中间要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个答案不正确得，老师要求改一下。", "corrected_sentence": "这个答案不正确，老师要求改一下。", "error_description": "“得”用错：“不正确得”后面缺少补语，“得”悬空，应去掉“得”，说“这个答案不正确，老师要求改一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89670, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正确", "is_correct": true, "explanation": "“正确”与“不正确”相对，是反义词。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”说心情，与“不正确”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”说外貌，与“不正确”没有反义关系。"}, {"text": "方便", "is_correct": false, "explanation": "“方便”说便利，与“不正确”没有反义关系。"}], "correct_answer": "正确", "explanations": {"正确": "“正确”与“不正确”相对，是反义词。", "高兴": "“高兴”说心情，与“不正确”没有反义关系。", "漂亮": "“漂亮”说外貌，与“不正确”没有反义关系。", "方便": "“方便”说便利，与“不正确”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89670, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正确", "is_correct": true, "explanation": "“正确”与“不正确”相对，是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”说明晰，与“不正确”没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”说坚固，与“不正确”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”说光线，与“不正确”没有反义关系。"}], "correct_answer": "正确", "explanations": {"正确": "“正确”与“不正确”相对，是反义词。", "清楚": "“清楚”说明晰，与“不正确”没有反义关系。", "结实": "“结实”说坚固，与“不正确”没有反义关系。", "明亮": "“明亮”说光线，与“不正确”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89670, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不符合事实或标准，有错误。", "primary_collocate": null, "pronunciation": "bù zhèng què", "ipa": "pu˥˩ ʈʂɤŋ˥˩ tɕʰɥe˥˩", "syllable_count": 3, "sentences": [{"text": "报纸上的这条消息不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这件事的看法不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方的地图不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭时看手机是不正确的做法。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有些信息不正确，别全信。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用筷子的方法不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表上的年龄不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话不正确，我要告诉大家。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对这个词的理解不正确。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样跑步的姿势不正确，容易受伤。", "target_word": "不正确", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不正确的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "信息、看法、做法等不符合事实或标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e48683c-72c5-47cf-8ca9-695253ccc13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不正确", "is_correct": true, "explanation": "“不正确”说消息有错，与句意相符。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度或水平，消息不说高度，“消息高”不通。"}, {"text": "窄", "is_correct": false, "explanation": "语义：“窄”说宽度，消息没有宽窄，“消息窄”不通。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说温度，消息没有温度，“消息冷”不通。"}], "explanations": {"不正确": "“不正确”说消息有错，与句意相符。", "高": "搭配：“高”说高度或水平，消息不说高度，“消息高”不通。", "窄": "语义：“窄”说宽度，消息没有宽窄，“消息窄”不通。", "冷": "语义：“冷”说温度，消息没有温度，“消息冷”不通。"}, "sentence_index": 0, "correct_answer": "不正确"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只杯子很不正确。", "explanation": "杯子没有对错，“不正确”只用于说消息、做法等有错的事，这里说不通。"}, {"text": "这朵花开得很不正确。", "explanation": "花开没有对错，“不正确”不用于描写花的开放，这里说不通。"}, {"text": "这座山的颜色很不正确。", "explanation": "山的颜色没有对错，“不正确”只用于说消息、做法等有错的事，这里说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不正确", "is_correct": true, "explanation": "“不正确”说年龄有错，与句意相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”说外貌好看，年龄没有外貌，“年龄漂亮”不通。"}, {"text": "宽", "is_correct": false, "explanation": "语义：“宽”说宽度，年龄没有宽窄，“年龄宽”不通。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”说硬度，年龄没有软硬，“年龄硬”不通。"}], "explanations": {"不正确": "“不正确”说年龄有错，与句意相符。", "漂亮": "体貌：“漂亮”说外貌好看，年龄没有外貌，“年龄漂亮”不通。", "宽": "语义：“宽”说宽度，年龄没有宽窄，“年龄宽”不通。", "硬": "语义：“硬”说硬度，年龄没有软硬，“年龄硬”不通。"}, "sentence_index": 6, "correct_answer": "不正确"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的脾气很不正确。", "explanation": "这里应该用〈不好〉。“不正确”说说法、做法有错，形容脾气要用“不好”。"}, {"text": "这片云的形状很不正确。", "explanation": "云的形状没有对错，“不正确”只用于说答案、做法、说法等有错的事，这里说不通。"}, {"text": "她的鼻子很不正确。", "explanation": "鼻子没有对错，“不正确”不用于描写身体的样子，这里说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张地图上有不正确路线，我们换一张吧。", "corrected_sentence": "这张地图上有不正确的路线，我们换一张吧。", "error_description": "“不正确路线”错误，应为“不正确的路线”。形容词“不正确”修饰名词时，中间要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写的地址不正确得，信寄不出去了。", "corrected_sentence": "他写的地址不正确，信寄不出去了。", "error_description": "“得”用错：“不正确”后面缺少补语，“得”悬空，应去掉“得”，说“他写的地址不正确，信寄不出去了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
