INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89671, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "圆圆的东西转着往前走。", "primary_collocate": null, "pronunciation": "gǔn", "ipa": "kwən˨˩˦", "syllable_count": 1, "sentences": [{"text": "球滚到桌子下面去了。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果从桌子上滚下来了。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车轮滚得很快。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小球往前滚了几米就停了。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把球一推，球就滚远了。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硬币掉在地上，滚进了床底。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个圆石头一直滚到河边。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球在草地上慢慢滚着。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西瓜从车上滚了出来。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看着球滚过马路。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滚了", "label": "完成体"}, {"form": "滚着", "label": "持续体"}, {"form": "滚过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "球、轮子等圆形物体转动着向前移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47d4b2a1-6f38-41cd-9617-8e355af68395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89671, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "滚", "is_correct": true, "explanation": "正确：滚 gǔn，圆形物体转动着向前移动。"}, {"text": "棍", "is_correct": false, "explanation": "棍 gùn（第四声）与 gǔn（第三声）声调不同，意思是棍子。"}, {"text": "捆", "is_correct": false, "explanation": "捆 kǔn 与 gǔn 声母不同（k 与 g），意思是捆绑。"}, {"text": "管", "is_correct": false, "explanation": "管 guǎn 与 gǔn 韵母不同（uan 与 un），意思是管子。"}], "explanations": {"滚": "正确：滚 gǔn，圆形物体转动着向前移动。", "棍": "棍 gùn（第四声）与 gǔn（第三声）声调不同，意思是棍子。", "捆": "捆 kǔn 与 gǔn 声母不同（k 与 g），意思是捆绑。", "管": "管 guǎn 与 gǔn 韵母不同（uan 与 un），意思是管子。"}, "sentence_index": null, "correct_answer": "滚"}, "level_3": {"options": [{"text": "滚", "is_correct": true, "explanation": "正确：“滚”指圆形物体转动着向前移动，球滚到桌子下面符合语义。"}, {"text": "走", "is_correct": false, "explanation": "语义：“走”指人或动物用脚移动，球不能走。"}, {"text": "躺", "is_correct": false, "explanation": "搭配：“躺”指人或动物横卧，不能以球为主语。"}, {"text": "站", "is_correct": false, "explanation": "语义：“站”指立定不动，与球滚动前进的意思相反。"}], "explanations": {"滚": "正确：“滚”指圆形物体转动着向前移动，球滚到桌子下面符合语义。", "走": "语义：“走”指人或动物用脚移动，球不能走。", "躺": "搭配：“躺”指人或动物横卧，不能以球为主语。", "站": "语义：“站”指立定不动，与球滚动前进的意思相反。"}, "sentence_index": 0, "correct_answer": "滚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "风扇滚得很快。", "explanation": "这里应该用〈转〉。“滚”指圆形物体转着往前走，风扇只是原地旋转，应说“转”。"}, {"text": "汤滚了，香味飘出来了。", "explanation": "这是“滚”的另一个义项“沸腾”，指液体烧开，与圆形物体转动前进无关，不能用来描述物体的移动。"}, {"text": "他把书滚到第五页。", "explanation": "这里应该用〈翻〉。“翻”指把书页翻过去，书不是圆形，不能“滚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滚", "is_correct": true, "explanation": "正确：“滚”指圆石头转动着向前移动，滚到河边符合语义。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”指腿部发力跃起，石头不能跳。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指靠腿脚快速移动，石头没有腿，不能跑。"}, {"text": "漂", "is_correct": false, "explanation": "搭配：“漂”多用于浮在水面上的东西，圆石头会沉，不能漂到河边。"}], "explanations": {"滚": "正确：“滚”指圆石头转动着向前移动，滚到河边符合语义。", "跳": "语义：“跳”指腿部发力跃起，石头不能跳。", "跑": "语义：“跑”指靠腿脚快速移动，石头没有腿，不能跑。", "漂": "搭配：“漂”多用于浮在水面上的东西，圆石头会沉，不能漂到河边。"}, "sentence_index": 6, "correct_answer": "滚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看着风筝滚过天空。", "explanation": "这里应该用〈飞〉。风筝靠风在空中飞行，不是圆物转动前进，应说“飞过天空”。"}, {"text": "我看着小船滚过湖面。", "explanation": "这里应该用〈漂〉。小船在水面上漂行，不能说“滚”。"}, {"text": "我看着冰箱滚过马路。", "explanation": "这里应该用〈搬〉。冰箱不是圆形，要靠人搬运过马路，不能说“滚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "苹果滚着到墙角了。", "corrected_sentence": "苹果滚到墙角了。", "error_description": "错误形式：“滚着到”；正确形式：“滚到”。表示滚动到达终点时，“滚”后面直接加结果补语“到+地点”，中间不能插入表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "橘子滚了到椅子下面。", "corrected_sentence": "橘子滚到了椅子下面。", "error_description": "错误形式：“滚了到”；正确形式：“滚到了”。“了”应放在结果补语“到”之后，不能插在“滚”和“到”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
