INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89672, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体翻转着移动。", "primary_collocate": null, "pronunciation": "gǔn", "ipa": "kwən˨˩˦", "syllable_count": 1, "sentences": [{"text": "孩子在草地上滚来滚去。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从楼梯上滚了下来。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在雪地里滚了几圈。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头从山上滚下来了。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔倒后在地上滚了一下。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫在床上滚来滚去，不想起床。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢在沙子里滚着玩。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从山坡上一直滚到了下面。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小马在泥地里滚得全身都是泥。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在地上滚了两圈才站起来。", "target_word": "滚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滚了", "label": "完成体"}, {"form": "滚着", "label": "持续体"}, {"form": "滚过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "人或物体一边翻转一边移动，如滚下楼梯、在地上翻滚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47d4b2a1-6f38-41cd-9617-8e355af68395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89672, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "滚", "is_correct": true, "explanation": "正确：滚 gǔn，物体翻转着移动。"}, {"text": "棍", "is_correct": false, "explanation": "棍 gùn（第四声）与 gǔn（第三声）声调不同，意思是棍子。"}, {"text": "捆", "is_correct": false, "explanation": "捆 kǔn 与 gǔn 声母不同（k 与 g），意思是捆绑。"}, {"text": "馆", "is_correct": false, "explanation": "馆 guǎn 与 gǔn 韵母不同（uan 与 un），意思是饭馆。"}], "explanations": {"滚": "正确：滚 gǔn，物体翻转着移动。", "棍": "棍 gùn（第四声）与 gǔn（第三声）声调不同，意思是棍子。", "捆": "捆 kǔn 与 gǔn 声母不同（k 与 g），意思是捆绑。", "馆": "馆 guǎn 与 gǔn 韵母不同（uan 与 un），意思是饭馆。"}, "sentence_index": null, "correct_answer": "滚"}, "level_3": {"options": [{"text": "滚", "is_correct": true, "explanation": "正确：“滚”指人或物体翻转着移动，孩子在草地上翻来翻去符合语义。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中移动，草地上不能游。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指凭翅膀在空中飞行，孩子不能飞。"}, {"text": "驶", "is_correct": false, "explanation": "搭配：“驶”用于车船等交通工具，不能以孩子为主语。"}], "explanations": {"滚": "正确：“滚”指人或物体翻转着移动，孩子在草地上翻来翻去符合语义。", "游": "语义：“游”指在水中移动，草地上不能游。", "飞": "语义：“飞”指凭翅膀在空中飞行，孩子不能飞。", "驶": "搭配：“驶”用于车船等交通工具，不能以孩子为主语。"}, "sentence_index": 0, "correct_answer": "滚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把饼干滚了个面。", "explanation": "这里应该用〈翻〉。“翻”指把物体翻转过来，只是翻个面没有移动，应说“翻”。"}, {"text": "汽车在路上滚得很快。", "explanation": "这里应该用〈开〉。汽车靠发动机行驶，不会翻转着移动，应说“开得很快”。"}, {"text": "烟从山上滚下来了。", "explanation": "这里应该用〈飘〉。烟是气体，不会翻转着移动，应说“飘下来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滚", "is_correct": true, "explanation": "正确：“滚”指翻转着移动或玩耍，在沙子里滚着玩符合语义。"}, {"text": "冲", "is_correct": false, "explanation": "语义：“冲”指猛烈向前，与在沙子里悠闲玩耍的意思不符。"}, {"text": "漂", "is_correct": false, "explanation": "搭配：“漂”需要水或空气作介质，沙子里不能漂。"}, {"text": "飘", "is_correct": false, "explanation": "语义：“飘”指轻物随风浮动，与在沙子里滚动玩耍不符。"}], "explanations": {"滚": "正确：“滚”指翻转着移动或玩耍，在沙子里滚着玩符合语义。", "冲": "语义：“冲”指猛烈向前，与在沙子里悠闲玩耍的意思不符。", "漂": "搭配：“漂”需要水或空气作介质，沙子里不能漂。", "飘": "语义：“飘”指轻物随风浮动，与在沙子里滚动玩耍不符。"}, "sentence_index": 6, "correct_answer": "滚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小猫在墙上滚来滚去。", "explanation": "这里应该用〈爬〉。小猫要靠四肢攀爬竖直的墙面，不会在墙上翻转着移动，应说“爬来爬去”。"}, {"text": "水在地上滚来滚去。", "explanation": "这里应该用〈流〉。水是液体，不会像物体一样翻转着移动，应说“流来流去”。"}, {"text": "电脑在桌子上滚来滚去。", "explanation": "这里应该用〈挪〉。电脑是方形机器，不会自己翻转着移动，应说“挪来挪去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫从沙发上滚下了来。", "corrected_sentence": "小猫从沙发上滚了下来。", "error_description": "错误形式：“滚下了来”；正确形式：“滚了下来”。复合趋向补语“下来”不能被“了”拆开，“了”应紧跟动词“滚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子在草地上过滚两次。", "corrected_sentence": "孩子在草地上滚过两次。", "error_description": "错误形式：“过滚两次”；正确形式：“滚过两次”。动态助词“过”应紧跟动词“滚”，不能放在动词之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
