INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89673, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "中立是吵架的时候，不站在哪一边。", "primary_collocate": null, "pronunciation": "zhōng lì", "ipa": "ʈʂʊŋ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "朋友吵架时，我选择中立，谁也不帮。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和妈妈吵架，我只能保持中立。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵得很凶，你不能一直中立。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同桌和我吵架，小王在旁边保持中立。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐和弟弟吵架时，奶奶总是很中立。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李不想得罪人，吵架时一直中立。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师很中立，没有帮吵架的任何一个孩子。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架，我想保持中立，所以没说话。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "室友吵架的时候，你为什么总是中立？", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架时保持中立的人，有时两边都不高兴。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中立国", "label": "复合"}, {"form": "中立性", "label": "复合"}], "register": "中性", "sense_fingerprint": "中立|形容词|吵架时不站在哪一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89673, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中立", "is_correct": true, "explanation": "zhōng lì，意思是不站在哪一边。"}, {"text": "重力", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，重力指物体受到的地球引力。"}, {"text": "张力", "is_correct": false, "explanation": "zhāng 与 zhōng 韵母不同（ang 与 ong），张力指拉紧或对抗的力。"}, {"text": "冲力", "is_correct": false, "explanation": "chōng 与 zhōng 声母不同（ch 与 zh），冲力指物体向前冲的力。"}, {"text": "站立", "is_correct": false, "explanation": "zhàn（第四声）与 zhōng 韵母和声调都不同，站立指直着身体站着。"}], "explanations": {"中立": "zhōng lì，意思是不站在哪一边。", "重力": "zhòng（第四声）与 zhōng（第一声）声调不同，重力指物体受到的地球引力。", "张力": "zhāng 与 zhōng 韵母不同（ang 与 ong），张力指拉紧或对抗的力。", "冲力": "chōng 与 zhōng 声母不同（ch 与 zh），冲力指物体向前冲的力。", "站立": "zhàn（第四声）与 zhōng 韵母和声调都不同，站立指直着身体站着。"}, "sentence_index": null, "correct_answer": "中立"}, "level_3": {"options": [{"text": "中立", "is_correct": true, "explanation": "中立指吵架时不站在任何一方，符合“谁也不帮”的语境。"}, {"text": "激进", "is_correct": false, "explanation": "语义：激进表示过激的做法，与“谁也不帮”的态度不符。"}, {"text": "偏袒", "is_correct": false, "explanation": "语义：偏袒指偏向一方，与“谁也不帮”的态度直接矛盾。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”不能作“选择”的对象，“选择热情”不说。"}], "explanations": {"中立": "中立指吵架时不站在任何一方，符合“谁也不帮”的语境。", "激进": "语义：激进表示过激的做法，与“谁也不帮”的态度不符。", "偏袒": "语义：偏袒指偏向一方，与“谁也不帮”的态度直接矛盾。", "热情": "搭配：“热情”不能作“选择”的对象，“选择热情”不说。"}, "sentence_index": 0, "correct_answer": "中立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很中立，吵架时也不发火。", "explanation": "这里应该用〈平和〉。中立指不偏向任何一方，不用来形容脾气。"}, {"text": "这瓶溶液很中立，不会腐蚀金属。", "explanation": "这里应该用〈中性〉。中立用于人的立场，溶液的酸碱性要说中性。"}, {"text": "他吵架时脸色很中立。", "explanation": "这里应该用〈冷静〉。中立不用于描述神情，脸色应说冷静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中立", "is_correct": true, "explanation": "中立指不偏向任何一方，符合老师在争吵中的处事态度。"}, {"text": "热心", "is_correct": false, "explanation": "语义：热心表示乐于帮助，与“没有帮任何一个孩子”相矛盾。"}, {"text": "慷慨", "is_correct": false, "explanation": "搭配：“慷慨”多用于给予财物或帮助，与“没有帮”自相矛盾。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：幼稚形容人不成熟，不能用来形容老师的处事态度。"}], "explanations": {"中立": "中立指不偏向任何一方，符合老师在争吵中的处事态度。", "热心": "语义：热心表示乐于帮助，与“没有帮任何一个孩子”相矛盾。", "慷慨": "搭配：“慷慨”多用于给予财物或帮助，与“没有帮”自相矛盾。", "幼稚": "语义：幼稚形容人不成熟，不能用来形容老师的处事态度。"}, "sentence_index": 6, "correct_answer": "中立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的生活很中立，几乎不买新衣服。", "explanation": "这里应该用〈节俭〉。中立指不偏向任何一方，生活习惯要说节俭。"}, {"text": "她学习很中立，每天都很早起床。", "explanation": "这里应该用〈努力〉。中立不用于形容学习的态度，应说努力。"}, {"text": "他很中立，总能很快解出难题。", "explanation": "这里应该用〈聪明〉。中立用于立场，形容人的智力应说聪明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吵架的时候，我对双方都保持的中立。", "corrected_sentence": "吵架的时候，我对双方都保持中立。", "error_description": "“保持中立”是动宾结构，中间不能加“的”。加了“的”，“保持的中立”变成名词短语，整句没有谓语，应删去“的”，说“对双方都保持中立”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她中立的劝两个人冷静下来。", "corrected_sentence": "她中立地劝两个人冷静下来。", "error_description": "“中立”修饰动词“劝”时要用“地”，应说“中立地劝”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
