INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89674, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在对立的双方之间不偏向任何一方。", "primary_collocate": null, "pronunciation": "zhōng lì", "ipa": "ʈʂʊŋ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "两个国家打仗时，瑞士保持中立。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判必须保持中立，不能帮任何一队。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报纸的报道很中立。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在两家公司之间一直很中立。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个中立的国家不参加双方的战争。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位专家的看法比较中立，没有偏向谁。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官应该站在中立的立场上说话。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方谈判时，我们需要一个中立的人来主持。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者写新闻时要尽量中立。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这场争论中，学校选择了中立。", "target_word": "中立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中立国", "label": "复合"}, {"form": "中立性", "label": "复合"}], "register": "中性", "sense_fingerprint": "中立|形容词|对立双方之间不偏向任何一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
