 DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中立", "is_correct": true, "explanation": "中立指不偏向任何一方，符合法官应有的立场。"}, {"text": "偏颇", "is_correct": false, "explanation": "语义：偏颇指有偏向，与法官应当公正的要求相反。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：幼稚形容人不成熟，不能用来形容法官的立场。"}, {"text": "疯狂", "is_correct": false, "explanation": "搭配：“疯狂”形容行为或情绪，不能修饰“立场”。"}], "explanations": {"中立": "中立指不偏向任何一方，符合法官应有的立场。", "偏颇": "语义：偏颇指有偏向，与法官应当公正的要求相反。", "幼稚": "语义：幼稚形容人不成熟，不能用来形容法官的立场。", "疯狂": "搭配：“疯狂”形容行为或情绪，不能修饰“立场”。"}, "sentence_index": 6, "correct_answer": "中立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的性格很中立，很少发脾气。", "explanation": "这里应该用〈温和〉。中立指不偏向任何一方，不用来形容性格。"}, {"text": "他的生活很中立，每月只花很少的钱。", "explanation": "这里应该用〈节俭〉。中立用于立场，生活习惯要说节俭。"}, {"text": "他面对质疑很中立，一直很冷静。", "explanation": "这里应该用〈沉着〉。中立指在对立双方之间不偏向任何一方，形容面对质疑时的情绪应说沉着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "记者中立的报道了这场争论。", "corrected_sentence": "记者中立地报道了这场争论。", "error_description": "“中立”修饰动词“报道”时要用“地”，应说“中立地报道”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "裁判在比赛中很保持中立。", "corrected_sentence": "裁判在比赛中一直保持中立。", "error_description": "“保持中立”是动宾结构，不能用程度副词“很”修饰，应说“一直保持中立”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
