INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89675, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "用来说做一件事是想得到什么。", "primary_collocate": null, "pronunciation": "wèi de shì", "ipa": "weɪ˥˩ tə ʂʅ˥˩", "syllable_count": 3, "sentences": [{"text": "他加班这么多，为的是那笔奖金。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读这么多书，为的是将来的好工作。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天练字，为的是一张奖状。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这么辛苦，为的是一个好成绩。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他排了三小时的队，为的是一张演唱会票。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我搬到城里，为的是孩子的教育。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打工，为的是一笔学费。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天练琴，为的是一笔奖学金。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我写这封信，为的是一句谢谢。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他翻遍了旧箱子，为的是一张老照片。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "为的是：说明做某事想得到的东西（后接名词性成分）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b48a4e59-1e2a-4b1f-9e51-871774232826') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89675, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "为的是", "is_correct": true, "explanation": "正确：为的是说明做这件事想得到的东西，后接“那笔奖金”，符合语境。"}, {"text": "免得", "is_correct": false, "explanation": "语义：“免得”引出要避免的后果，“那笔奖金”是想得到的东西。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”用于否定前句之后的更正，前句没有否定。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，与“加班”和“那笔奖金”的关系不合。"}], "explanations": {"为的是": "正确：为的是说明做这件事想得到的东西，后接“那笔奖金”，符合语境。", "免得": "语义：“免得”引出要避免的后果，“那笔奖金”是想得到的东西。", "而是": "搭配：“而是”用于否定前句之后的更正，前句没有否定。", "尽管": "语义：“尽管”表示让步，与“加班”和“那笔奖金”的关系不合。"}, "sentence_index": 0, "correct_answer": "为的是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早起跑步，为的是昨晚没睡好。", "explanation": "这里应该用〈因为〉。“为的是”引出想得到的东西，不用来说明原因；昨晚没睡好是早起的原因。"}, {"text": "我提前出门，为的是路上堵车了。", "explanation": "这里应该用〈因为〉。“为的是”引出想得到的东西，不用来说明原因；路上堵车是提前出门的原因。"}, {"text": "她每天早睡，为的是她病了。", "explanation": "这里应该用〈因为〉。“为的是”引出想得到的东西，不用来说明原因；她生病是早睡的原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89675, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为的是", "is_correct": true, "explanation": "正确：为的是引出做这件事想得到的东西，与“一笔学费”相合。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”用于否定前句之后的更正，前句“他们打工”没有否定。"}, {"text": "以致", "is_correct": false, "explanation": "语义：“以致”引出不好的结果，“一笔学费”不是不好的结果。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，与“打工”和“学费”的关系不合。"}], "explanations": {"为的是": "正确：为的是引出做这件事想得到的东西，与“一笔学费”相合。", "而是": "搭配：“而是”用于否定前句之后的更正，前句“他们打工”没有否定。", "以致": "语义：“以致”引出不好的结果，“一笔学费”不是不好的结果。", "虽然": "语义：“虽然”表示让步，与“打工”和“学费”的关系不合。"}, "sentence_index": 6, "correct_answer": "为的是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他多练一小时，为的是把腿练断了。", "explanation": "这里应该用〈以致〉。“为的是”引出想得到的东西，不用来说明意外造成的结果；把腿练断不是想得到的东西。"}, {"text": "她每晚复习，为的是把眼睛看坏了。", "explanation": "这里应该用〈以致〉。“为的是”引出想得到的东西，不用来说明意外造成的结果；把眼睛看坏不是想得到的东西。"}, {"text": "我每天买菜，为的是把钱花光了。", "explanation": "这里应该用〈以致〉。“为的是”引出想得到的东西，不用来说明意外造成的结果；把钱花光不是想得到的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他攒钱这么久，为的是了一辆新车。", "corrected_sentence": "他攒钱这么久，为的是一辆新车。", "error_description": "错误：“为的是”后多出了“了”。“为的是”后直接接所要得到的东西，应说“为的是一辆新车”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他省吃俭用，为的是的一套房子。", "corrected_sentence": "他省吃俭用，为的是一套房子。", "error_description": "“为的是”后不能加“的”，“的”多余。应说“为的是一套房子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
