INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89676, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89676, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "引出行为的目的。", "primary_collocate": null, "pronunciation": "wèi de shì", "ipa": "weɪ˥˩ tə ʂʅ˥˩", "syllable_count": 3, "sentences": [{"text": "他每天早起跑步，为的是保持身体健康。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我学中文，为的是以后去北京工作。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她存钱，为的是明年去旅行。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们早早出门，为的是不堵车。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做了很多菜，为的是让大家吃好。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我提前到了，为的是看看会场。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每晚看书，为的是考上大学。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师多讲一遍，为的是我们听懂。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们开着灯，为的是让孩子不怕黑。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把房子卖了，为的是给女儿治病。", "target_word": "为的是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "为的是：接在行为后，引出做这件事的目的（后接动词性成分）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b48a4e59-1e2a-4b1f-9e51-871774232826') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "为的是", "is_correct": true, "explanation": "正确：为的是引出做这件事的目的，与“保持身体健康”相合。"}, {"text": "免得", "is_correct": false, "explanation": "语义：“免得”引出要避免的不好结果，“保持身体健康”不是要避免的结果。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与后面的“但”“却”呼应，此处没有。"}, {"text": "不然", "is_correct": false, "explanation": "语义：“不然”引出不这样做时的后果，与“保持身体健康”不合。"}], "explanations": {"为的是": "正确：为的是引出做这件事的目的，与“保持身体健康”相合。", "免得": "语义：“免得”引出要避免的不好结果，“保持身体健康”不是要避免的结果。", "虽然": "搭配：“虽然”要与后面的“但”“却”呼应，此处没有。", "不然": "语义：“不然”引出不这样做时的后果，与“保持身体健康”不合。"}, "sentence_index": 0, "correct_answer": "为的是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迟到了，为的是路上堵车。", "explanation": "这里应该用〈因为〉。“为的是”引出做这件事的目的，不用来说明已经发生的原因；堵车是迟到的原因。"}, {"text": "她哭了很久，为的是摔了一跤。", "explanation": "这里应该用〈因为〉。“为的是”引出做这件事的目的，不用来说明已经发生的原因；摔跤是哭的原因。"}, {"text": "我们饿了，为的是中午没吃饭。", "explanation": "这里应该用〈因为〉。“为的是”引出做这件事的目的，不用来说明已经发生的原因；没吃饭是饿的原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为的是", "is_correct": true, "explanation": "正确：为的是引出做这件事的目的，与“考上大学”相合。"}, {"text": "只有", "is_correct": false, "explanation": "搭配：“只有”要与“才”呼应，此处没有“才”。"}, {"text": "以致", "is_correct": false, "explanation": "语义：“以致”引出不好的结果，“考上大学”不是不好的结果。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，与“看书”和“考上大学”的目的关系不合。"}], "explanations": {"为的是": "正确：为的是引出做这件事的目的，与“考上大学”相合。", "只有": "搭配：“只有”要与“才”呼应，此处没有“才”。", "以致": "语义：“以致”引出不好的结果，“考上大学”不是不好的结果。", "尽管": "语义：“尽管”表示让步，与“看书”和“考上大学”的目的关系不合。"}, "sentence_index": 6, "correct_answer": "为的是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摔了一跤，为的是把腿摔断了。", "explanation": "这里应该用〈以致〉。“为的是”引出做这件事的目的，不用来说明意外造成的结果；把腿摔断不是为了什么。"}, {"text": "她不停地喝水，为的是肚子变大了。", "explanation": "这里应该用〈以致〉。“为的是”引出做这件事的目的，不用来说明意外造成的结果；肚子变大不是喝水的目的。"}, {"text": "他努力工作，为的是身体变差了。", "explanation": "这里应该用〈以致〉。“为的是”引出做这件事的目的，不用来说明意外造成的结果；身体变差不是努力工作的目的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天复习，为的是的通过考试。", "corrected_sentence": "我每天复习，为的是通过考试。", "error_description": "“为的是”后不能再加“的”。应说“为的是通过考试”，多出的“的”使其不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天练习游泳，为的是是变得更强壮。", "corrected_sentence": "他每天练习游泳，为的是变得更强壮。", "error_description": "错误：“为的是”后多出了一个“是”，“是”重复。正确应为“为的是变得更强壮”，去掉多余的“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
