INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89677, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "漫画是画出来的有趣的画,常常有故事。", "primary_collocate": null, "pronunciation": "màn huà", "ipa": "man˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "我弟弟每天晚上都看漫画。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本漫画的故事很好看。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里有很多日本漫画。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最喜欢的漫画讲的是一只猫的故事。", "target_word": "漫画", "complexity_tier": "T3", "furigana": "màn huà", "sentence_source": "generated"}, {"text": "我借了朋友的漫画。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想长大以后画漫画。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套漫画一共有二十本。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们坐在地上看漫画。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不让我晚上看漫画。", "target_word": "漫画", "complexity_tier": "T3", "furigana": "màn huà", "sentence_source": "generated"}, {"text": "周末我在家看了一本漫画。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "漫畫", "label": "繁体"}, {"form": "漫画书", "label": "复合"}], "register": "口语", "sense_fingerprint": "有故事的连环画，孩子和年轻人爱看的漫画书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4412296-5735-4d77-9af9-beeaa2149034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89677, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "米饭", "is_correct": false, "explanation": "语义：“看米饭”不能指阅读，句意不通。"}, {"text": "漫画", "is_correct": true, "explanation": "正确：“看漫画”指阅读连环画，与“弟弟每天晚上”的情境相符。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不能“看”，句意不通。"}, {"text": "砖头", "is_correct": false, "explanation": "语义：砖头是建材，不是可以“看”的读物，句意不通。"}], "explanations": {"米饭": "语义：“看米饭”不能指阅读，句意不通。", "漫画": "正确：“看漫画”指阅读连环画，与“弟弟每天晚上”的情境相符。", "汽油": "语义：汽油是燃料，不能“看”，句意不通。", "砖头": "语义：砖头是建材，不是可以“看”的读物，句意不通。"}, "sentence_index": 0, "correct_answer": "漫画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套漫画每周六在电视上播出。", "explanation": "这里应该用〈动画片〉。漫画书是印刷品，不会在电视上播出；播出的是动画片。"}, {"text": "这套漫画我每天都穿着去上学。", "explanation": "这里应该用〈衣服〉。漫画是书，不能“穿”；能穿的是衣服。"}, {"text": "这套漫画是我的毕业论文，一共有三千字。", "explanation": "这里应该用〈论文〉。漫画是图文故事，不是学术文章；“毕业论文”才是学术文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89677, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钢琴", "is_correct": false, "explanation": "搭配：“本”是书的量词，不能用来数钢琴，与“一共有二十本”不搭配。"}, {"text": "漫画", "is_correct": true, "explanation": "正确：“这套漫画”指一整套连环画，可以用“本”计数。"}, {"text": "服装", "is_correct": false, "explanation": "量词：服装以“件”或“套”计，不用“本”，与“一共有二十本”不搭配。"}, {"text": "家具", "is_correct": false, "explanation": "搭配：“家具”不用“本”计量，与“一共有二十本”不搭配。"}], "explanations": {"钢琴": "搭配：“本”是书的量词，不能用来数钢琴，与“一共有二十本”不搭配。", "漫画": "正确：“这套漫画”指一整套连环画，可以用“本”计数。", "服装": "量词：服装以“件”或“套”计，不用“本”，与“一共有二十本”不搭配。", "家具": "搭配：“家具”不用“本”计量，与“一共有二十本”不搭配。"}, "sentence_index": 6, "correct_answer": "漫画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套漫画是我用相机拍的，每张都很清楚。", "explanation": "这里应该用〈照片〉。漫画是手绘的，不是相机拍的；“照片”才用相机拍。"}, {"text": "我每天查漫画，找答案。", "explanation": "这里应该用〈字典〉。“查”的对象是字典等工具书，漫画不是工具书。"}, {"text": "这套漫画是一首很好听的歌。", "explanation": "这里应该用〈歌曲〉。漫画是图画故事，不是歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书店里有很多日本画漫书。", "corrected_sentence": "书店里有很多日本漫画书。", "error_description": "复合词语序错误：“漫画书”中“漫画”修饰“书”，不能说成“画漫书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天买了三只漫画。", "corrected_sentence": "我昨天买了三本漫画。", "error_description": "量词错误：“漫画”是书，计量应用“本”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
