INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用简单夸张的手法描绘人物或故事的画,常带讽刺或幽默意味。", "primary_collocate": null, "pronunciation": "màn huà", "ipa": "man˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "报纸上有一幅讽刺官员的漫画。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅漫画很幽默，大家都笑了。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了一幅漫画来讽刺浪费食物。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅漫画把人物画得很夸张。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志最后一页有一幅政治漫画。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了这幅漫画，我明白了他的意思。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家用漫画批评了不好的现象。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅漫画的鼻子画得特别大。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一幅有趣的漫画。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅漫画虽然简单，却很有意思。", "target_word": "漫画", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幅", "label": "量词"}, {"form": "漫畫", "label": "繁体"}, {"form": "漫画家", "label": "复合"}], "register": "中性", "sense_fingerprint": "夸张、讽刺或幽默的单幅画作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4412296-5735-4d77-9af9-beeaa2149034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说明书", "is_correct": false, "explanation": "语义：说明书是说明用途的文字资料，不是讽刺官员的画，也不用“幅”计量。"}, {"text": "漫画", "is_correct": true, "explanation": "正确：“漫画”可以用来讽刺官员，且用“幅”计量。"}, {"text": "风景画", "is_correct": false, "explanation": "搭配：“讽刺”与“风景画”不搭配，风景画不针对人物讽刺。"}, {"text": "图纸", "is_correct": false, "explanation": "语义：图纸用于工程设计，不能用来讽刺官员。"}], "explanations": {"说明书": "语义：说明书是说明用途的文字资料，不是讽刺官员的画，也不用“幅”计量。", "漫画": "正确：“漫画”可以用来讽刺官员，且用“幅”计量。", "风景画": "搭配：“讽刺”与“风景画”不搭配，风景画不针对人物讽刺。", "图纸": "语义：图纸用于工程设计，不能用来讽刺官员。"}, "sentence_index": 0, "correct_answer": "漫画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部漫画每周六晚上播出。", "explanation": "这里应该用〈动画片〉。漫画是静态的画，不能播出；播出的是动画片。"}, {"text": "这幅漫画是用相机拍出来的，画面很清楚。", "explanation": "这里应该用〈照片〉。漫画是手绘的，不能说“拍出来”；“照片”才用相机拍。"}, {"text": "这幅漫画每天早上叫我起床。", "explanation": "这里应该用〈闹钟〉。漫画是画，不会叫人起床；叫人起床的是闹钟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜料", "is_correct": false, "explanation": "搭配：“用颜料批评”不搭配，颜料不能用来表达批评。"}, {"text": "漫画", "is_correct": true, "explanation": "正确：“画家用漫画批评不好的现象”，漫画可以用来表达批评。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：“用螺丝批评”不成立，螺丝是紧固件，不能用来表达批评。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“用水泥批评”不成立，水泥是建筑材料，不能用来表达批评。"}], "explanations": {"颜料": "搭配：“用颜料批评”不搭配，颜料不能用来表达批评。", "漫画": "正确：“画家用漫画批评不好的现象”，漫画可以用来表达批评。", "螺丝": "搭配：“用螺丝批评”不成立，螺丝是紧固件，不能用来表达批评。", "水泥": "搭配：“用水泥批评”不成立，水泥是建筑材料，不能用来表达批评。"}, "sentence_index": 6, "correct_answer": "漫画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅漫画有三千字，讲了一个道理。", "explanation": "这里应该用〈文章〉。漫画以画面为主，不按字数计算；有三千字的是文章。"}, {"text": "这幅漫画有四个声部，可以合唱。", "explanation": "这里应该用〈乐谱〉。漫画是画，没有声部；“声部”属于乐谱。"}, {"text": "这件漫画是用石头雕成的，很有立体感。", "explanation": "这里应该用〈雕塑〉。漫画是平面的画，不能用石头雕成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在报纸上看到一只有趣的漫画。", "corrected_sentence": "我昨天在报纸上看到一幅有趣的漫画。", "error_description": "量词错误：“漫画”是一幅画，应用“幅”；“只”多用于动物，不能用来数画。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只漫画的讽刺很尖锐。", "corrected_sentence": "这幅漫画的讽刺很尖锐。", "error_description": "量词错误：“漫画”是一幅画，应用“幅”；“只”多用于动物，不能用来数画。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
