INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89679, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "二副是大船上排第二位的管航行的人。", "primary_collocate": null, "pronunciation": "èr fù", "ipa": "ɚ˥˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "我叔叔是一条大船上的二副。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长、大副、二副都在开会。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二副站在船头，看着前面的海。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大船进港时，二副一直在看地图。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二副说今晚的海上风很大。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想先当二副，以后再当船长。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位二副第一次出海就遇到了大风。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二副告诉船长，前面有一座小岛。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮船上的二副每天都要写航行记录。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的二副跟老船长学了很多东西。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "专业", "sense_fingerprint": "大船上排第二位、管航行的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89679, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "二副", "is_correct": true, "explanation": "二副指大船上排第二位、管航行的人。"}, {"text": "二幕", "is_correct": false, "explanation": "二幕（èr mù）与二副（èr fù）只差声母 f 与 m，意思是戏剧的第二幕。"}, {"text": "二路", "is_correct": false, "explanation": "二路（èr lù）与二副只差声母 f 与 l，意思是第二条路线，如“二路公交”。"}, {"text": "二度", "is_correct": false, "explanation": "二度（èr dù）与二副只差声母 f 与 d，意思是第二次。"}, {"text": "二部", "is_correct": false, "explanation": "二部（èr bù）与二副只差声母 f 与 b，意思是第二部分或第二声部。"}], "explanations": {"二副": "二副指大船上排第二位、管航行的人。", "二幕": "二幕（èr mù）与二副（èr fù）只差声母 f 与 m，意思是戏剧的第二幕。", "二路": "二路（èr lù）与二副只差声母 f 与 l，意思是第二条路线，如“二路公交”。", "二度": "二度（èr dù）与二副只差声母 f 与 d，意思是第二次。", "二部": "二部（èr bù）与二副只差声母 f 与 b，意思是第二部分或第二声部。"}, "sentence_index": null, "correct_answer": "二副"}, "level_3": {"options": [{"text": "农民", "is_correct": false, "explanation": "语义：农民在田里干活，不会在大船上工作，与“大船上”矛盾。"}, {"text": "二副", "is_correct": true, "explanation": "二副是大船上排第二位、管航行的人，与句意相符。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：盘子是器皿，不能作为“我叔叔”的身份。"}, {"text": "车间", "is_correct": false, "explanation": "搭配：“车间”是工厂的生产场所，不说“大船上的车间”。"}], "explanations": {"农民": "语义：农民在田里干活，不会在大船上工作，与“大船上”矛盾。", "二副": "二副是大船上排第二位、管航行的人，与句意相符。", "盘子": "语义：盘子是器皿，不能作为“我叔叔”的身份。", "车间": "搭配：“车间”是工厂的生产场所，不说“大船上的车间”。"}, "sentence_index": 0, "correct_answer": "二副"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二副负责擦甲板，每天很辛苦。", "explanation": "这里应该用〈水手〉。擦甲板是水手的工作，二副负责航行值班。"}, {"text": "我叔叔是一条年轻的二副。", "explanation": "量词：这里应该用〈位〉。“条”用于船、鱼等，指人的职位要用“位”。"}, {"text": "二副每天都要给船上的发电机加油。", "explanation": "这里应该用〈轮机长〉。发电机由轮机部负责，二副负责航行值班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89679, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老手", "is_correct": false, "explanation": "语义：“老手”指经验丰富的人，与“第一次出海”矛盾。"}, {"text": "二副", "is_correct": true, "explanation": "二副是大船上的驾驶员，与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能用“位”，也不会“出海”。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：大楼是建筑物，不能用“位”，也不会“出海”。"}], "explanations": {"老手": "语义：“老手”指经验丰富的人，与“第一次出海”矛盾。", "二副": "二副是大船上的驾驶员，与句意相符。", "桌子": "语义：桌子是家具，不能用“位”，也不会“出海”。", "大楼": "语义：大楼是建筑物，不能用“位”，也不会“出海”。"}, "sentence_index": 6, "correct_answer": "二副"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位二副每天负责给船员看病。", "explanation": "这里应该用〈船医〉。给船员看病是船医的工作，二副负责航行值班。"}, {"text": "二副负责管理全船的货物和船员。", "explanation": "这里应该用〈大副〉。大副负责全船的货物和船员，二副负责航行值班。"}, {"text": "二副负责做出全船的最后决定。", "explanation": "这里应该用〈船长〉。做出最后决定的是船长，二副只负责航行值班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一位经验丰富二副。", "corrected_sentence": "这是一位经验丰富的二副。", "error_description": "错误：“经验丰富”修饰“二副”，中间要加“的”，应说“经验丰富的二副”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时曾当着二副。", "corrected_sentence": "他年轻时曾当过二副。", "error_description": "错误：表示“曾经做过”的经历要用“过”，应说“曾当过二副”；“着”表示动作持续或状态，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
