INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "商船上职位仅次于大副的驾驶员，负责航行值班等。", "primary_collocate": null, "pronunciation": "èr fù", "ipa": "ɚ˥˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "二副在船上负责夜里的航行值班。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大副生病了，二副来管船。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在货船上当二副已经三年了。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二副每天都要检查海图。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长让二副看好前面的航线。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘船的二副是一位年轻的女士。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从三副升到了二副。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二副的职位比大副低一级。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了半夜，二副还在驾驶台上值班。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二副要先把航线画在海图上。", "target_word": "二副", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "专业", "sense_fingerprint": "商船上仅次于大副、负责航行值班的驾驶员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89680, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "二副", "is_correct": true, "explanation": "二副指商船上仅次于大副的驾驶员。"}, {"text": "二幕", "is_correct": false, "explanation": "二幕（èr mù）与二副（èr fù）只差声母 f 与 m，意思是戏剧的第二幕。"}, {"text": "二路", "is_correct": false, "explanation": "二路（èr lù）与二副只差声母 f 与 l，意思是第二条路线，如“二路公交”。"}, {"text": "二度", "is_correct": false, "explanation": "二度（èr dù）与二副只差声母 f 与 d，意思是第二次。"}, {"text": "二部", "is_correct": false, "explanation": "二部（èr bù）与二副只差声母 f 与 b，意思是第二部分或第二声部。"}], "explanations": {"二副": "二副指商船上仅次于大副的驾驶员。", "二幕": "二幕（èr mù）与二副（èr fù）只差声母 f 与 m，意思是戏剧的第二幕。", "二路": "二路（èr lù）与二副只差声母 f 与 l，意思是第二条路线，如“二路公交”。", "二度": "二度（èr dù）与二副只差声母 f 与 d，意思是第二次。", "二部": "二部（èr bù）与二副只差声母 f 与 b，意思是第二部分或第二声部。"}, "sentence_index": null, "correct_answer": "二副"}, "level_3": {"options": [{"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，不负责夜里的航行值班。"}, {"text": "二副", "is_correct": true, "explanation": "二副负责船上夜里的航行值班，与句意相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客只是坐船，不承担航行值班的职责。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“司机”指开汽车等车辆的人，不在船上负责航行值班。"}], "explanations": {"厨师": "语义：厨师负责做饭，不负责夜里的航行值班。", "二副": "二副负责船上夜里的航行值班，与句意相符。", "乘客": "语义：乘客只是坐船，不承担航行值班的职责。", "司机": "语义：“司机”指开汽车等车辆的人，不在船上负责航行值班。"}, "sentence_index": 0, "correct_answer": "二副"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二副每天负责搬运船上的货物。", "explanation": "这里应该用〈水手〉。搬运货物由水手完成，二副负责航行值班。"}, {"text": "二副每天都要检修主机和锅炉。", "explanation": "这里应该用〈轮机长〉。主机和锅炉由轮机部负责，二副负责航行值班。"}, {"text": "二副每天负责给船员发工资。", "explanation": "这里应该用〈事务长〉。发工资由事务长负责，二副负责航行值班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水手", "is_correct": false, "explanation": "语义：水手是普通船员，职位低于三副，不是升职的目标。"}, {"text": "二副", "is_correct": true, "explanation": "二副是三副的上一级职位，与句意相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客不是船员，不存在从职务升为游客的说法。"}, {"text": "司令", "is_correct": false, "explanation": "搭配：商船上的职位不称“司令”，“司令”多用于军队。"}], "explanations": {"水手": "语义：水手是普通船员，职位低于三副，不是升职的目标。", "二副": "二副是三副的上一级职位，与句意相符。", "游客": "语义：游客不是船员，不存在从职务升为游客的说法。", "司令": "搭配：商船上的职位不称“司令”，“司令”多用于军队。"}, "sentence_index": 6, "correct_answer": "二副"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二副每天都在厨房里做饭。", "explanation": "这里应该用〈厨师〉。二副负责航行值班，不负责做饭。"}, {"text": "这位军官的二副每天都要给他整理文件。", "explanation": "这里应该用〈副官〉。“二副”是商船上的职位，不能指军队里的副官。"}, {"text": "我在码头上看见一只二副在跑。", "explanation": "量词：“只”用于动物，指人担任的职位要用“位”；这里应说“一位二副”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
