INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条二副很有经验。", "corrected_sentence": "这位二副很有经验。", "error_description": "错误：“二副”指人，量词应用“位”或“个”，不能用“条”（“条”多用于船、鱼等）；正确说法是“这位二副”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89681, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前任", "is_correct": true, "explanation": "前任：与“现任”相对，指从前担任该职务的人，是这一义项的反义词。"}, {"text": "安静", "is_correct": false, "explanation": "与“现任”没有反义关系，“安静”指没有声音或不吵闹。"}, {"text": "明亮", "is_correct": false, "explanation": "与“现任”没有反义关系，“明亮”指光线充足或明朗。"}, {"text": "聪明", "is_correct": false, "explanation": "与“现任”没有反义关系，“聪明”形容人的智力水平高。"}], "correct_answer": "前任", "explanations": {"前任": "前任：与“现任”相对，指从前担任该职务的人，是这一义项的反义词。", "安静": "与“现任”没有反义关系，“安静”指没有声音或不吵闹。", "明亮": "与“现任”没有反义关系，“明亮”指光线充足或明朗。", "聪明": "与“现任”没有反义关系，“聪明”形容人的智力水平高。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89681, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前任", "is_correct": true, "explanation": "前任：与“现任”相对，指从前担任该职务的人，是这一义项的反义词。"}, {"text": "富裕", "is_correct": false, "explanation": "与“现任”没有反义关系，“富裕”指财产充足或生活宽裕。"}, {"text": "严肃", "is_correct": false, "explanation": "与“现任”没有反义关系，“严肃”形容态度认真或庄重。"}, {"text": "健康", "is_correct": false, "explanation": "与“现任”没有反义关系，“健康”指身体状况良好。"}], "correct_answer": "前任", "explanations": {"前任": "前任：与“现任”相对，指从前担任该职务的人，是这一义项的反义词。", "富裕": "与“现任”没有反义关系，“富裕”指财产充足或生活宽裕。", "严肃": "与“现任”没有反义关系，“严肃”形容态度认真或庄重。", "健康": "与“现任”没有反义关系，“健康”指身体状况良好。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89681, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "现在正在做这个工作的。", "primary_collocate": null, "pronunciation": "xiàn rèn", "ipa": "ɕjɛn˥˩ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "现任校长下周要来我们班。", "target_word": "现任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现任校长比以前的校长年轻。", "target_word": "现任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现任经理是一位女士。", "target_word": "现任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位现任市长很受欢迎。", "target_word": "现任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "前任主任走了，现任主任刚来。", "target_word": "现任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家医院的现任院长是一位医生。", "target_word": "现任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现任总统昨天在电视上讲话了。", "target_word": "现任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的现任队长踢了十年球。", "target_word": "现任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现任院长对学生非常好。", "target_word": "现任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是我们公司的现任负责人。", "target_word": "现任", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "现任：放在名词前，指现在正做这份工作的人，与“前任”相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47d4b2a1-6f38-41cd-9617-8e355af68395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89681, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现任", "is_correct": true, "explanation": "现任：目前正在担任某职务，是这一读音对应的正确词形。"}, {"text": "信任", "is_correct": false, "explanation": "xìn（第四声）与 xiàn（第四声）韵母不同（in 与 ian），意思是相信、信赖。"}, {"text": "闲人", "is_correct": false, "explanation": "闲人 xián rén：两个音节声调都与 xiàn rèn 不同，意思是没有事做的人。"}, {"text": "线人", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同，意思是为警方或记者提供消息的人。"}], "explanations": {"现任": "现任：目前正在担任某职务，是这一读音对应的正确词形。", "信任": "xìn（第四声）与 xiàn（第四声）韵母不同（in 与 ian），意思是相信、信赖。", "闲人": "闲人 xián rén：两个音节声调都与 xiàn rèn 不同，意思是没有事做的人。", "线人": "rén（第二声）与 rèn（第四声）声调不同，意思是为警方或记者提供消息的人。"}, "sentence_index": null, "correct_answer": "现任"}, "level_3": {"options": [{"text": "现任", "is_correct": true, "explanation": "现任：目前担任校长，与“下周要来我们班”的句意相符。"}, {"text": "已故", "is_correct": false, "explanation": "语义：“已故”指已经去世，去世的人下周不能来班里。"}, {"text": "年幼", "is_correct": false, "explanation": "搭配：“年幼”只用于形容儿童或幼小的人，不能修饰担任校长的人。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体可以看穿，不能修饰担任校长的人。"}], "explanations": {"现任": "现任：目前担任校长，与“下周要来我们班”的句意相符。", "已故": "语义：“已故”指已经去世，去世的人下周不能来班里。", "年幼": "搭配：“年幼”只用于形容儿童或幼小的人，不能修饰担任校长的人。", "透明": "搭配：“透明”形容物体可以看穿，不能修饰担任校长的人。"}, "sentence_index": 0, "correct_answer": "现任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现任问题很多，需要尽快解决。", "explanation": "这里应该用〈存在的〉。“现任”只能修饰担任职务的人或职位，不能修饰“问题”，表示现有的问题应说“存在的问题”。"}, {"text": "我的现任同桌很爱笑。", "explanation": "这里应该用〈现在的〉。“现任”只用于正在担任职务的人，“同桌”不是职务，表示眼前的同桌应说“现在的同桌”。"}, {"text": "这座现任大楼很高。", "explanation": "这里应该用〈现有的〉。“现任”只修饰担任职务的人，建筑物不能担任职务，表示已经存在的大楼应说“现有的大楼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89681, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "现任", "is_correct": true, "explanation": "现任：目前正在担任某职务，是这一读音对应的正确词形。"}, {"text": "先人", "is_correct": false, "explanation": "先人 xiān rén：两个音节声调都与 xiàn rèn 不同，意思是祖先。"}, {"text": "县人", "is_correct": false, "explanation": "县人：xiàn rén，意思是同一个县的人；与 xiàn rèn 仅第二音节声调不同（rén 第二声，rèn 第四声）。"}, {"text": "贤人", "is_correct": false, "explanation": "贤人：xián rén，意思是有德才的人；两个音节的声调都与 xiàn rèn 不同。"}], "explanations": {"现任": "现任：目前正在担任某职务，是这一读音对应的正确词形。", "先人": "先人 xiān rén：两个音节声调都与 xiàn rèn 不同，意思是祖先。", "县人": "县人：xiàn rén，意思是同一个县的人；与 xiàn rèn 仅第二音节声调不同（rén 第二声，rèn 第四声）。", "贤人": "贤人：xián rén，意思是有德才的人；两个音节的声调都与 xiàn rèn 不同。"}, "sentence_index": null, "correct_answer": "现任"}, "level_3": {"options": [{"text": "现任", "is_correct": true, "explanation": "现任：目前担任总统，句子中“昨天讲话”的情境成立。"}, {"text": "新鲜", "is_correct": false, "explanation": "搭配：“新鲜”用于食物、空气等，不能修饰“总统”。"}, {"text": "年幼", "is_correct": false, "explanation": "搭配：“年幼”只用于形容儿童或幼小的人，不能修饰总统。"}, {"text": "未成年", "is_correct": false, "explanation": "语义：未成年人不能担任总统，这种说法与句子表达的身份不符。"}], "explanations": {"现任": "现任：目前担任总统，句子中“昨天讲话”的情境成立。", "新鲜": "搭配：“新鲜”用于食物、空气等，不能修饰“总统”。", "年幼": "搭配：“年幼”只用于形容儿童或幼小的人，不能修饰总统。", "未成年": "语义：未成年人不能担任总统，这种说法与句子表达的身份不符。"}, "sentence_index": 6, "correct_answer": "现任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现任情况很复杂，大家要注意。", "explanation": "这里应该用〈当前〉。“现任”只修饰担任职务的人或职位，不能修饰“情况”。"}, {"text": "现任规定和以前不一样了。", "explanation": "这里应该用〈现在的〉。“现任”只修饰担任职务的人，不能修饰“规定”。"}, {"text": "现任天气很好，我们去公园吧。", "explanation": "这里应该用〈目前的〉。“现任”不能修饰“天气”，描述眼前的情况应说“目前的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现任了经理明天会来参加会议。", "corrected_sentence": "现任经理明天会来参加会议。", "error_description": "错误：“现任”后面加了“了”。“现任”是修饰词，不能带“了”，正确写作“现任经理明天会来参加会议。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很现任秘书明天很忙。", "corrected_sentence": "现任秘书明天很忙。", "error_description": "错误：“现任”是修饰词，不能受“很”修饰。正确写作“现任秘书明天很忙”，“很”只修饰后面的“忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
