INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89682, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现任", "is_correct": true, "explanation": "现任：目前正在担任某职务，是这一读音对应的正确词形。"}, {"text": "闲人", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，rén 与 rèn 声调也不同，意思是没有事做的人。"}, {"text": "先人", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，rén 与 rèn 声调也不同，意思是祖先。"}, {"text": "县人", "is_correct": false, "explanation": "xiàn 与“现”读音相同，rén（第二声）与 rèn（第四声）声调不同，意思是同一个县的人。"}], "explanations": {"现任": "现任：目前正在担任某职务，是这一读音对应的正确词形。", "闲人": "xián（第二声）与 xiàn（第四声）声调不同，rén 与 rèn 声调也不同，意思是没有事做的人。", "先人": "xiān（第一声）与 xiàn（第四声）声调不同，rén 与 rèn 声调也不同，意思是祖先。", "县人": "xiàn 与“现”读音相同，rén（第二声）与 rèn（第四声）声调不同，意思是同一个县的人。"}, "sentence_index": null, "correct_answer": "现任"}, "level_3": {"options": [{"text": "现任", "is_correct": true, "explanation": "现任：目前担任部长，与“今天见了记者”的句意相符。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体可以看穿，不能修饰担任部长的人。"}, {"text": "年幼", "is_correct": false, "explanation": "搭配：“年幼”只用于形容儿童，不能用来修饰担任部长的人。"}, {"text": "已故", "is_correct": false, "explanation": "语义：“已故”指已经去世，去世的人不能今天见记者。"}], "explanations": {"现任": "现任：目前担任部长，与“今天见了记者”的句意相符。", "透明": "搭配：“透明”形容物体可以看穿，不能修饰担任部长的人。", "年幼": "搭配：“年幼”只用于形容儿童，不能用来修饰担任部长的人。", "已故": "语义：“已故”指已经去世，去世的人不能今天见记者。"}, "sentence_index": 0, "correct_answer": "现任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现任工作很重要，大家要认真完成。", "explanation": "这里应该用〈当前〉。“现任”只修饰担任职务的人，不能修饰“工作”，表示眼前的情况应说“当前的”。"}, {"text": "现任交通很拥挤，我们走路去吧。", "explanation": "这里应该用〈眼下的〉。“现任”不能修饰“交通”，表示眼前的情况应说“眼下的”。"}, {"text": "现任房价很高，大家都买不起。", "explanation": "这里应该用〈现在的〉。“现任”不能修饰“房价”，表示现在的情况应说“现在的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89682, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "现任", "is_correct": true, "explanation": "现任：目前正在担任某职务，是这一读音对应的正确词形。"}, {"text": "信任", "is_correct": false, "explanation": "xìn（第四声）与 xiàn（第四声）韵母不同（in 与 ian），意思是相信、信赖。"}, {"text": "贤人", "is_correct": false, "explanation": "贤人 xián rén：两个音节声调都与 xiàn rèn 不同，意思是有德才的人。"}, {"text": "线人", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同，意思是为警方或记者提供消息的人。"}], "explanations": {"现任": "现任：目前正在担任某职务，是这一读音对应的正确词形。", "信任": "xìn（第四声）与 xiàn（第四声）韵母不同（in 与 ian），意思是相信、信赖。", "贤人": "贤人 xián rén：两个音节声调都与 xiàn rèn 不同，意思是有德才的人。", "线人": "rén（第二声）与 rèn（第四声）声调不同，意思是为警方或记者提供消息的人。"}, "sentence_index": null, "correct_answer": "现任"}, "level_3": {"options": [{"text": "现任", "is_correct": true, "explanation": "现任：目前担任主席，与“把会议改到了明天”的句意相符。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容地方或场面，不能用来修饰担任主席的人。"}, {"text": "年幼", "is_correct": false, "explanation": "搭配：“年幼”只用于形容儿童或幼小的人，不能修饰担任主席的人。"}, {"text": "未成年", "is_correct": false, "explanation": "语义：未成年人不能担任主席，这种说法与句子表达的身份不符。"}], "explanations": {"现任": "现任：目前担任主席，与“把会议改到了明天”的句意相符。", "冷清": "搭配：“冷清”形容地方或场面，不能用来修饰担任主席的人。", "年幼": "搭配：“年幼”只用于形容儿童或幼小的人，不能修饰担任主席的人。", "未成年": "语义：未成年人不能担任主席，这种说法与句子表达的身份不符。"}, "sentence_index": 6, "correct_answer": "现任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的现任弟弟很高。", "explanation": "这里应该用〈现在的〉。“现任”只用于正在担任职务的人，“弟弟”不是职务，表示眼前的弟弟应说“现在的弟弟”或直接说“弟弟”。"}, {"text": "这只现任小猫很可爱。", "explanation": "这里应该用〈眼前的〉。“现任”只修饰担任职务的人，小猫不能担任职务，表示眼前这只小猫应说“眼前的小猫”。"}, {"text": "这座现任公园很大。", "explanation": "这里应该用〈现有的〉。“现任”不能修饰公园，公园不是担任职务的对象，表示已经存在的公园应说“现有的公园”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现任了院长明天去北京开会。", "corrected_sentence": "现任院长明天去北京开会。", "error_description": "错误：“现任”后面加了“了”。“现任”是修饰词，不能带“了”，正确写作“现任院长明天去北京开会。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很现任局长明天有空。", "corrected_sentence": "现任局长明天有空。", "error_description": "错误：“现任”是修饰词，不能受“很”修饰。正确写作“现任局长明天有空”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
