INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89683, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "翻译是把一种话的意思,换成另一种话说出来。", "primary_collocate": null, "pronunciation": "fān yì", "ipa": "fan˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "你能帮我翻译一下这句话吗？", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边听一边给客人翻译。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位外国客人说的话我自己翻译不了。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把老板的话翻译给大家听。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机能把中文翻译成英文。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把刚才的话翻译成韩语。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天要替客户翻译两个小时的会议。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他翻译得又快又准。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人的问题我都翻译好了。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的时候，谁来替我们翻译？", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "翻译了", "label": "体标（了）"}, {"form": "翻译过", "label": "体标（过）"}, {"form": "翻译翻译", "label": "重叠"}, {"form": "翻譯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把一种话的意思换成另一种话说出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89683, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "翻译", "is_correct": true, "explanation": "正确。翻译 fān yì 指把一种话的意思换成另一种话说出来。"}, {"text": "反义", "is_correct": false, "explanation": "fǎn（第三声）与 fān（第一声）声调不同，意思是相反的意思。"}, {"text": "犯意", "is_correct": false, "explanation": "fàn（第四声）与 fān（第一声）声调不同，意思是犯罪的意图。"}, {"text": "翻页", "is_correct": false, "explanation": "yè 与 yì 韵母不同（ie 与 i），意思是把书页翻过去。"}], "explanations": {"翻译": "正确。翻译 fān yì 指把一种话的意思换成另一种话说出来。", "反义": "fǎn（第三声）与 fān（第一声）声调不同，意思是相反的意思。", "犯意": "fàn（第四声）与 fān（第一声）声调不同，意思是犯罪的意图。", "翻页": "yè 与 yì 韵母不同（ie 与 i），意思是把书页翻过去。"}, "sentence_index": null, "correct_answer": "翻译"}, "level_3": {"options": [{"text": "翻译", "is_correct": true, "explanation": "正确。“帮我翻译一下这句话”表示把这句话换成另一种话说出来。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”指割开，不能用于处理一句话的意思。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”是烹调，不能用于这句话。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，后面不能直接带“这句话”作宾语。"}], "explanations": {"翻译": "正确。“帮我翻译一下这句话”表示把这句话换成另一种话说出来。", "切": "搭配：“切”指割开，不能用于处理一句话的意思。", "煮": "搭配：“煮”是烹调，不能用于这句话。", "哭": "配价：“哭”是不及物动词，后面不能直接带“这句话”作宾语。"}, "sentence_index": 0, "correct_answer": "翻译"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服务员把这碗汤翻译给了客人。", "explanation": "这里应该用〈端〉。翻译指把一种话换成另一种话，端汤给客人要说端。"}, {"text": "他把这块木头翻译成了桌子。", "explanation": "这里应该用〈做〉。翻译指把一种话换成另一种话，木头做成桌子要说做。"}, {"text": "妈妈给孩子翻译了一件毛衣。", "explanation": "这里应该用〈织〉。翻译指把一种话换成另一种话，给孩子织毛衣要说织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻译", "is_correct": true, "explanation": "正确。“替客户翻译两个小时的会议”表示把别人的话口头转换成另一种语言。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语多是食物，不能说吃会议。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语多是饮品，不能说喝会议。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，后面不能直接带“会议”作宾语。"}], "explanations": {"翻译": "正确。“替客户翻译两个小时的会议”表示把别人的话口头转换成另一种语言。", "吃": "搭配：“吃”的宾语多是食物，不能说吃会议。", "喝": "搭配：“喝”的宾语多是饮品，不能说喝会议。", "笑": "配价：“笑”是不及物动词，后面不能直接带“会议”作宾语。"}, "sentence_index": 6, "correct_answer": "翻译"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我翻译了那只小狗。", "explanation": "这里应该用〈遛〉。翻译指把一种话换成另一种话，带小狗出去走要说遛。"}, {"text": "老师翻译了那块黑板。", "explanation": "这里应该用〈擦〉。翻译指把一种话换成另一种话，清理黑板要说擦。"}, {"text": "我把这块布翻译成了窗帘。", "explanation": "这里应该用〈缝制〉。翻译指把一种话换成另一种话，布做成窗帘要说缝制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一边看一边大家翻译。", "corrected_sentence": "他一边看一边给大家翻译。", "error_description": "错误：“大家翻译”。正确：“给大家翻译”。“翻译”要用“给”引出受益的人，不能直接把人放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她翻译很流利。", "corrected_sentence": "她翻译得很流利。", "error_description": "错误：“翻译很流利”。正确：“翻译得很流利”。“翻译”后接程度补语时，中间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
