INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89684, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一种语言文字的意思用另一种语言文字表达出来。", "primary_collocate": null, "pronunciation": "fān yì", "ipa": "fan˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "请你把这篇文章翻译成英语。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是谁翻译成中文的？", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在翻译一封很长的信。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子很难翻译。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把课文翻译成中文。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她翻译过很多有名的小说。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词怎么翻译才自然？", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这首诗翻译出来。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把法语合同翻译了一遍。", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话用日语怎么翻译？", "target_word": "翻译", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "翻译了", "label": "体标（了）"}, {"form": "翻译过", "label": "体标（过）"}, {"form": "翻译翻译", "label": "重叠"}, {"form": "翻譯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把一种语言文字转换成另一种语言文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89684, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "翻译", "is_correct": true, "explanation": "正确。翻译 fān yì 指把一种语言文字的意思用另一种语言表达出来。"}, {"text": "反义", "is_correct": false, "explanation": "fǎn（第三声）与 fān（第一声）声调不同，意思是相反的意思。"}, {"text": "犯意", "is_correct": false, "explanation": "fàn（第四声）与 fān（第一声）声调不同，意思是犯罪的意图。"}, {"text": "翻页", "is_correct": false, "explanation": "yè 与 yì 韵母不同（ie 与 i），意思是把书页翻过去。"}], "explanations": {"翻译": "正确。翻译 fān yì 指把一种语言文字的意思用另一种语言表达出来。", "反义": "fǎn（第三声）与 fān（第一声）声调不同，意思是相反的意思。", "犯意": "fàn（第四声）与 fān（第一声）声调不同，意思是犯罪的意图。", "翻页": "yè 与 yì 韵母不同（ie 与 i），意思是把书页翻过去。"}, "sentence_index": null, "correct_answer": "翻译"}, "level_3": {"options": [{"text": "翻译", "is_correct": true, "explanation": "正确。“把文章翻译成英语”表示把文字转换成另一种语言。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”指割开，不能用于把文章变成另一种语言。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”是烹调，不能用于文章与语言。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修补器物，不指语言的转换。"}], "explanations": {"翻译": "正确。“把文章翻译成英语”表示把文字转换成另一种语言。", "切": "搭配：“切”指割开，不能用于把文章变成另一种语言。", "煮": "搭配：“煮”是烹调，不能用于文章与语言。", "修理": "语义：“修理”指修补器物，不指语言的转换。"}, "sentence_index": 0, "correct_answer": "翻译"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用计算器翻译了这笔账。", "explanation": "这里应该用〈计算〉。翻译指语言文字之间的转换，算账要说计算。"}, {"text": "他把这段乐谱翻译成了舞蹈。", "explanation": "这里应该用〈编排〉。翻译只用于语言文字之间，乐谱变成舞蹈要说编排。"}, {"text": "他用橡皮把错字翻译掉了。", "explanation": "这里应该用〈擦〉。翻译指语言文字之间的转换，用橡皮去掉错字要说擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻译", "is_correct": true, "explanation": "正确。“怎么翻译才自然”表示如何把词语转换成另一种语言。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”是烹调，不能用来处理词语。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”指用针线连接布料，不能用于词语。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，后面不能直接带“这个词”作宾语。"}], "explanations": {"翻译": "正确。“怎么翻译才自然”表示如何把词语转换成另一种语言。", "煮": "搭配：“煮”是烹调，不能用来处理词语。", "缝": "搭配：“缝”指用针线连接布料，不能用于词语。", "哭": "配价：“哭”是不及物动词，后面不能直接带“这个词”作宾语。"}, "sentence_index": 6, "correct_answer": "翻译"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把面粉翻译成了面包。", "explanation": "这里应该用〈加工〉。翻译指语言文字之间的转换，面粉做成面包要说加工。"}, {"text": "这台机器能把水翻译成冰。", "explanation": "这里应该用〈冷冻〉。翻译指语言文字之间的转换，水变成冰要说冷冻。"}, {"text": "他把这间屋子翻译了一遍。", "explanation": "这里应该用〈收拾〉。翻译指语言文字之间的转换，整理房间要说收拾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这篇小说翻译了中文。", "corrected_sentence": "他把这篇小说翻译成了中文。", "error_description": "错误：“翻译了中文”。正确：“翻译成了中文”。“翻译”后要用“成”引出译成的语言。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她翻译很快。", "corrected_sentence": "她翻译得很快。", "error_description": "错误：“翻译很快”。正确：“翻译得很快”。“翻译”后接程度补语时，中间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
