INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89685, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "具有保护作用的性质。", "primary_collocate": null, "pronunciation": "bǎo hù xìng", "ipa": "pɑʊ˨˩˦ xu˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "孩子骑车时要戴保护性头盔。", "target_word": "保护性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种薄膜对手机屏幕有保护性。", "target_word": "保护性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种外套的保护性很强，摔倒也不容易受伤。", "target_word": "保护性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个塑料盖子没有什么保护性。", "target_word": "保护性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们都戴着保护性眼镜。", "target_word": "保护性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的保护性不太好。", "target_word": "保护性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我给新手机买了保护性外壳。", "target_word": "保护性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护性的手套能防止受伤。", "target_word": "保护性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种护膝的保护性很高。", "target_word": "保护性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说这层药膜有保护性。", "target_word": "保护性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "保護性", "label": "繁体"}, {"form": "保护性措施", "label": "复合"}], "register": "书面", "sense_fingerprint": "有保护的作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a0ab2c6-267b-46f6-963b-75f6b1d7240e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89685, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护性", "is_correct": true, "explanation": "保护性：有保护作用，与骑车时戴头盔的语境相合。"}, {"text": "装饰的", "is_correct": false, "explanation": "语义：只为装饰的头盔护不了孩子，与“骑车时要戴”的保护要求相反。"}, {"text": "危险的", "is_correct": false, "explanation": "语义：头盔是为了安全，“危险的”与保护孩子的语境相反。"}, {"text": "易碎的", "is_correct": false, "explanation": "搭配：“易碎”多用于玻璃、瓷器等，不说“易碎的头盔”。"}], "explanations": {"保护性": "保护性：有保护作用，与骑车时戴头盔的语境相合。", "装饰的": "语义：只为装饰的头盔护不了孩子，与“骑车时要戴”的保护要求相反。", "危险的": "语义：头盔是为了安全，“危险的”与保护孩子的语境相反。", "易碎的": "搭配：“易碎”多用于玻璃、瓷器等，不说“易碎的头盔”。"}, "sentence_index": 0, "correct_answer": "保护性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的保护性很高，不容易碎。", "explanation": "这里应该用〈硬度〉。保护性指对他物起保护作用，不用来说石头自身的硬度。"}, {"text": "这首歌的保护性很强，听了让人想哭。", "explanation": "这里应该用〈感染力〉。保护性指对他物的防护作用，说歌曲打动人要说感染力。"}, {"text": "这块玻璃的保护性很好，摸上去很光滑。", "explanation": "这里应该用〈光滑度〉。保护性指对他物起保护作用，玻璃摸起来光滑要说光滑度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护性", "is_correct": true, "explanation": "保护性：起保护作用的外壳，与新手机的语境相合。"}, {"text": "好吃的", "is_correct": false, "explanation": "语义：外壳不是食物，不能说“好吃的外壳”，句意不通。"}, {"text": "破损的", "is_correct": false, "explanation": "搭配：“买”的对象一般不说“破损的”外壳，二者不搭。"}, {"text": "生锈的", "is_correct": false, "explanation": "语义：外壳生锈与买新手机的语境不符，也不会特意去买。"}], "explanations": {"保护性": "保护性：起保护作用的外壳，与新手机的语境相合。", "好吃的": "语义：外壳不是食物，不能说“好吃的外壳”，句意不通。", "破损的": "搭配：“买”的对象一般不说“破损的”外壳，二者不搭。", "生锈的": "语义：外壳生锈与买新手机的语境不符，也不会特意去买。"}, "sentence_index": 6, "correct_answer": "保护性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根铜线的保护性很好。", "explanation": "这里应该用〈导电性〉。保护性指保护作用，铜线传电要说导电性。"}, {"text": "这张床垫的保护性很高，买的人特别多。", "explanation": "这里应该用〈人气〉。保护性指保护作用，说商品受欢迎要用人气。"}, {"text": "这双鞋的保护性很好，穿起来很轻便。", "explanation": "这里应该用〈轻便性〉。保护性指对他物的防护作用，说鞋子穿着轻要用轻便性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这副手套有很强保护性。", "corrected_sentence": "这副手套有很强的保护性。", "error_description": "漏掉“的”：“很强”修饰“保护性”时要加“的”，应为“很强的保护性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这层薄膜有很强得保护性。", "corrected_sentence": "这层薄膜有很强的保护性。", "error_description": "“得”误用：修饰名词“保护性”要用“的”，应为“很强的保护性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
