INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89687, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "轻轻地挨到、撞到。", "primary_collocate": null, "pronunciation": "pèng", "ipa": "pʰɤŋ˥˩", "syllable_count": 1, "sentences": [{"text": "别碰我的书包。", "target_word": "碰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小心，别碰热水。", "target_word": "碰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他走过来碰了我一下。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手不小心碰了他的杯子。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫轻轻碰了碰我的脚。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，画还没干，不要碰。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他转身时碰了一下桌子，水洒了。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这花很脆，一碰就掉叶子。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子好奇地碰了碰那只小鸟。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想碰一下你的新手机，可以吗？", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "碰了", "label": "完成体"}, {"form": "碰过", "label": "经历体"}, {"form": "碰碰", "label": "重叠"}, {"form": "碰一碰", "label": "重叠"}], "register": "通用", "sense_fingerprint": "碰：用手或身体轻轻挨到、不小心撞到某物，力度小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47d4b2a1-6f38-41cd-9617-8e355af68395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89687, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "碰", "is_correct": true, "explanation": "碰：轻轻挨到、撞到，是这一读音对应的正确词形。"}, {"text": "朋", "is_correct": false, "explanation": "péng（第二声）与 pèng（第四声）声调不同，意思是朋友。"}, {"text": "蹦", "is_correct": false, "explanation": "bèng（第四声）与 pèng 只有声母不同（b 与 p），意思是跳起来。"}, {"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 pèng 只有声母不同（m 与 p），意思是做梦。"}], "explanations": {"碰": "碰：轻轻挨到、撞到，是这一读音对应的正确词形。", "朋": "péng（第二声）与 pèng（第四声）声调不同，意思是朋友。", "蹦": "bèng（第四声）与 pèng 只有声母不同（b 与 p），意思是跳起来。", "梦": "mèng（第四声）与 pèng 只有声母不同（m 与 p），意思是做梦。"}, "sentence_index": null, "correct_answer": "碰"}, "level_3": {"options": [{"text": "碰", "is_correct": true, "explanation": "碰：轻轻挨到，与“别”后的禁止语气及“我的书包”的对象相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象应是饮品，不能说喝“书包”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象应是食物，不能说吃“书包”。"}, {"text": "问", "is_correct": false, "explanation": "语义：“问”的对象应是人，书包不能被提问。"}], "explanations": {"碰": "碰：轻轻挨到，与“别”后的禁止语气及“我的书包”的对象相符。", "喝": "搭配：“喝”的对象应是饮品，不能说喝“书包”。", "吃": "搭配：“吃”的对象应是食物，不能说吃“书包”。", "问": "语义：“问”的对象应是人，书包不能被提问。"}, "sentence_index": 0, "correct_answer": "碰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他碰了我一拳。", "explanation": "这里应该用〈打〉。碰只表示轻轻挨到，力度很小，不能表示用拳头击打。"}, {"text": "他碰了我一脚。", "explanation": "这里应该用〈踢〉。碰不表示用脚猛力踢，动作和力度都不同。"}, {"text": "他碰了我一顿。", "explanation": "这里应该用〈揍〉。碰不能表示殴打，“揍”指打人，“碰”只是轻轻挨到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89687, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "碰", "is_correct": true, "explanation": "碰：轻轻挨到、撞到，是这一读音对应的正确词形。"}, {"text": "捧", "is_correct": false, "explanation": "pěng（第三声）与 pèng（第四声）声调不同，意思是双手托着。"}, {"text": "烹", "is_correct": false, "explanation": "pēng（第一声）与 pèng（第四声）声调不同，意思是烧煮食物。"}, {"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 pèng 只有声母不同（m 与 p），意思是做梦。"}], "explanations": {"碰": "碰：轻轻挨到、撞到，是这一读音对应的正确词形。", "捧": "pěng（第三声）与 pèng（第四声）声调不同，意思是双手托着。", "烹": "pēng（第一声）与 pèng（第四声）声调不同，意思是烧煮食物。", "梦": "mèng（第四声）与 pèng 只有声母不同（m 与 p），意思是做梦。"}, "sentence_index": null, "correct_answer": "碰"}, "level_3": {"options": [{"text": "碰", "is_correct": true, "explanation": "碰：轻轻挨到桌子，与“转身时”及“水洒了”的情境相符。"}, {"text": "叫", "is_correct": false, "explanation": "搭配：“叫”不能用来表示对桌子的这种动作，这句话说不通。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象应是人或动物，不能用于桌子。"}, {"text": "听", "is_correct": false, "explanation": "语义：桌子不能听，动作的主体和对象不符。"}], "explanations": {"碰": "碰：轻轻挨到桌子，与“转身时”及“水洒了”的情境相符。", "叫": "搭配：“叫”不能用来表示对桌子的这种动作，这句话说不通。", "喂": "搭配：“喂”的对象应是人或动物，不能用于桌子。", "听": "语义：桌子不能听，动作的主体和对象不符。"}, "sentence_index": 6, "correct_answer": "碰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他碰起了我的书包。", "explanation": "这里应该用〈拿〉。碰只表示轻轻挨到，不能表示用手把东西拿起来。"}, {"text": "他碰了我的感情。", "explanation": "这里应该用〈伤〉。碰只表示轻轻挨到，不能表示伤害别人的感情。"}, {"text": "他碰了药，病很快就好了。", "explanation": "这里应该用〈吃〉。碰只表示轻轻挨到，不能表示把药吃下去，服药应说“吃药”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的头碰了到门框。", "corrected_sentence": "我的头碰到了门框。", "error_description": "错误：“到”是结果补语，应紧跟在“碰”后，“了”放在“碰到”之后。正确写作“碰到了门框”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天没碰了你的书包。", "corrected_sentence": "我昨天没碰你的书包。", "error_description": "错误：“没”表示动作未发生，不能与“了”同用。正确写作“我昨天没碰你的书包”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
