INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89688, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体与物体相接触或撞击。", "primary_collocate": null, "pronunciation": "pèng", "ipa": "pʰɤŋ˥˩", "syllable_count": 1, "sentences": [{"text": "两辆车在路口碰在一起了。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球碰了墙，又弹回来了。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开车不小心碰了别人的车。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船碰了石头，裂了一个口。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个杯子一碰，声音很清脆。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两块石头碰在一起，发出很大的声音。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别让两个鸡蛋碰在一起。", "target_word": "碰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个球一碰，一个往左，一个往右。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自行车碰了路边的树，倒在地上。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小船互相碰了几下，都动了起来。", "target_word": "碰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "碰了", "label": "完成体"}, {"form": "碰过", "label": "经历体"}, {"form": "碰碰", "label": "重叠"}, {"form": "碰一碰", "label": "重叠"}], "register": "通用", "sense_fingerprint": "碰：两个物体相互接触、撞击在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47d4b2a1-6f38-41cd-9617-8e355af68395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89688, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "碰", "is_correct": true, "explanation": "碰：物体与物体相接触或撞击，是这一读音对应的正确词形。"}, {"text": "捧", "is_correct": false, "explanation": "pěng（第三声）与 pèng（第四声）声调不同，意思是双手托着。"}, {"text": "烹", "is_correct": false, "explanation": "pēng（第一声）与 pèng（第四声）声调不同，意思是烧煮食物。"}, {"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 pèng 只有声母不同（m 与 p），意思是做梦。"}], "explanations": {"碰": "碰：物体与物体相接触或撞击，是这一读音对应的正确词形。", "捧": "pěng（第三声）与 pèng（第四声）声调不同，意思是双手托着。", "烹": "pēng（第一声）与 pèng（第四声）声调不同，意思是烧煮食物。", "梦": "mèng（第四声）与 pèng 只有声母不同（m 与 p），意思是做梦。"}, "sentence_index": null, "correct_answer": "碰"}, "level_3": {"options": [{"text": "碰", "is_correct": true, "explanation": "碰：两辆车相互接触，与“在一起了”的句意相符。"}, {"text": "笑", "is_correct": false, "explanation": "语义：车不会笑，这一动作的主体应是人。"}, {"text": "睡", "is_correct": false, "explanation": "语义：车不能睡觉，这种说法与两辆车相接触的情境不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象应是食物，不能用于车。"}], "explanations": {"碰": "碰：两辆车相互接触，与“在一起了”的句意相符。", "笑": "语义：车不会笑，这一动作的主体应是人。", "睡": "语义：车不能睡觉，这种说法与两辆车相接触的情境不符。", "煮": "搭配：“煮”的对象应是食物，不能用于车。"}, "sentence_index": 0, "correct_answer": "碰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一伸手，把钱碰进了口袋。", "explanation": "这里应该用〈放〉。碰表示接触或撞击，不能表示把东西放进去。"}, {"text": "他碰了一针，病很快就好了。", "explanation": "这里应该用〈打〉。碰表示接触或撞击，不能表示给人注射。"}, {"text": "她把碗碰在桌子上，准备吃饭。", "explanation": "这里应该用〈摆〉。碰表示物体相接触或撞击，不能表示把东西整齐地放好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89688, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "碰", "is_correct": true, "explanation": "碰：物体与物体相接触或撞击，是这一读音对应的正确词形。"}, {"text": "朋", "is_correct": false, "explanation": "péng（第二声）与 pèng（第四声）声调不同，意思是朋友。"}, {"text": "蹦", "is_correct": false, "explanation": "bèng（第四声）与 pèng 只有声母不同（b 与 p），意思是跳起来。"}, {"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 pèng 只有声母不同（m 与 p），意思是做梦。"}], "explanations": {"碰": "碰：物体与物体相接触或撞击，是这一读音对应的正确词形。", "朋": "péng（第二声）与 pèng（第四声）声调不同，意思是朋友。", "蹦": "bèng（第四声）与 pèng 只有声母不同（b 与 p），意思是跳起来。", "梦": "mèng（第四声）与 pèng 只有声母不同（m 与 p），意思是做梦。"}, "sentence_index": null, "correct_answer": "碰"}, "level_3": {"options": [{"text": "碰", "is_correct": true, "explanation": "碰：两个鸡蛋相互接触，与“别让……在一起”的句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：鸡蛋不能唱歌，这种动作的主体与句子不符。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象应是文字，不能用于鸡蛋。"}, {"text": "哭", "is_correct": false, "explanation": "语义：鸡蛋不会哭，句子中的主体不能做这个动作。"}], "explanations": {"碰": "碰：两个鸡蛋相互接触，与“别让……在一起”的句意相符。", "唱": "语义：鸡蛋不能唱歌，这种动作的主体与句子不符。", "写": "搭配：“写”的对象应是文字，不能用于鸡蛋。", "哭": "语义：鸡蛋不会哭，句子中的主体不能做这个动作。"}, "sentence_index": 6, "correct_answer": "碰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把海报碰在墙上。", "explanation": "这里应该用〈贴〉。碰只表示轻轻接触，不能表示把东西固定在墙上。"}, {"text": "他碰在墙上睡着了。", "explanation": "这里应该用〈靠〉。碰只表示轻轻挨到，不能表示身体倚着墙休息。"}, {"text": "这种胶能把木头碰在一起。", "explanation": "这里应该用〈粘〉。碰只表示接触，不能表示用胶水把东西粘牢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "球碰在了墙，又弹回来了。", "corrected_sentence": "球碰在了墙上，又弹回来了。", "error_description": "错误：“碰在”后面要接表示处所的词语，“墙”是普通名词，须加方位词“上”。正确写作“碰在了墙上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个碗碰了一个，发出清脆的声音。", "corrected_sentence": "两个碗碰了一下，发出清脆的声音。", "error_description": "错误：表示动作次数的量词应用“下”，“个”不能用于动作。正确写作“碰了一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89689, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违抗", "is_correct": true, "explanation": "反义：“违抗”是不听从、对抗，与“信从”的相信并照做相反。"}, {"text": "研究", "is_correct": false, "explanation": "不是反义词：“研究”是探讨问题，与“信从”没有对立关系。"}, {"text": "休息", "is_correct": false, "explanation": "不是反义词：“休息”是停止活动，与“信从”没有对立关系。"}, {"text": "观察", "is_correct": false, "explanation": "不是反义词：“观察”是仔细看，与“信从”没有对立关系。"}], "correct_answer": "违抗", "explanations": {"违抗": "反义：“违抗”是不听从、对抗，与“信从”的相信并照做相反。", "研究": "不是反义词：“研究”是探讨问题，与“信从”没有对立关系。", "休息": "不是反义词：“休息”是停止活动，与“信从”没有对立关系。", "观察": "不是反义词：“观察”是仔细看，与“信从”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89689, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "反义：“怀疑”是不相信，与“信从”的相信并照做相反。"}, {"text": "散步", "is_correct": false, "explanation": "不是反义词：“散步”是悠闲地走路，与“信从”无关。"}, {"text": "收获", "is_correct": false, "explanation": "不是反义词：“收获”是得到成果，与“信从”没有对立关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "不是反义词：“唱歌”是发出乐声，与“信从”没有对立关系。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "反义：“怀疑”是不相信，与“信从”的相信并照做相反。", "散步": "不是反义词：“散步”是悠闲地走路，与“信从”无关。", "收获": "不是反义词：“收获”是得到成果，与“信从”没有对立关系。", "唱歌": "不是反义词：“唱歌”是发出乐声，与“信从”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89689, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "信从是相信一个人，并照他说的去做。", "primary_collocate": null, "pronunciation": "xìn cóng", "ipa": "ɕin⁵¹ tsʰʊŋ³⁵", "syllable_count": 2, "sentences": [{"text": "孩子们都信从老师的话。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很信从自己的朋友。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她信从医生，每天按时吃药。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家信从他，因为他从不说谎。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来不信从陌生人。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我信从过爸爸说的每句话。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟太信从那个人了。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要盲目信从他。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们信从老板，一起加班。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她只信从自己喜欢的老师。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "信从了", "label": "体标"}, {"form": "信从过", "label": "体标"}], "register": "书面", "sense_fingerprint": "相信某人并照他说的去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃老师的话。"}, {"text": "信从", "is_correct": true, "explanation": "正确。信从是相信并照他说的去做，与“孩子们听老师的话”相符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是擦拭物体表面，话不能被擦。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”用于布料、衣物，不能说缝补老师的话。"}], "explanations": {"吃": "搭配：“吃”的对象是食物，不能说吃老师的话。", "信从": "正确。信从是相信并照他说的去做，与“孩子们听老师的话”相符。", "擦": "语义：“擦”是擦拭物体表面，话不能被擦。", "缝补": "搭配：“缝补”用于布料、衣物，不能说缝补老师的话。"}, "sentence_index": 0, "correct_answer": "信从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈很信从这件新衣服。", "explanation": "这里应该用〈喜欢〉。信从的对象是人或权威，衣服不能信从；对衣服的喜爱要用喜欢。"}, {"text": "我信从这个事实。", "explanation": "这里应该用〈承认〉。信从的对象是人或权威，事实要用承认。"}, {"text": "我很信从这家餐厅的菜。", "explanation": "这里应该用〈喜欢〉。信从的对象是人或权威，菜不能信从；对菜的喜爱用喜欢即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说煮一个人。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热食物，与“弟弟太……了”指人的情感不相配。"}, {"text": "信从", "is_correct": true, "explanation": "正确。信从与“弟弟太……了”搭配，表示过分相信并听从那个人。"}, {"text": "腌", "is_correct": false, "explanation": "搭配：“腌”的对象是食物，不能说腌一个人。"}], "explanations": {"煮": "搭配：“煮”的对象是食物，不能说煮一个人。", "烤": "语义：“烤”是加热食物，与“弟弟太……了”指人的情感不相配。", "信从": "正确。信从与“弟弟太……了”搭配，表示过分相信并听从那个人。", "腌": "搭配：“腌”的对象是食物，不能说腌一个人。"}, "sentence_index": 6, "correct_answer": "信从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他信从同学的成绩。", "explanation": "这里应该用〈羡慕〉。信从是相信并照做，不能用于成绩，对别人的成绩表示羡慕要用羡慕。"}, {"text": "我信从这种天气。", "explanation": "这里应该用〈讨厌〉。信从用于相信某个人或权威并照做，天气不能信从。"}, {"text": "志愿者信从灾民。", "explanation": "这里应该用〈帮助〉。信从强调相信对方并照他说的做，不是给予帮助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小王把信从那个朋友。", "corrected_sentence": "小王信从那个朋友。", "error_description": "错误：“信从”前多了“把”。正确：“小王信从那个朋友。”“信从”不是处置动词，不能用“把”字句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把信从过那个人。", "corrected_sentence": "他信从过那个人。", "error_description": "错误：“信从”前多了“把”。正确：“他信从过那个人。”“信从”不是处置动词，不能用“把”字句，“过”紧跟动词即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
