INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89690, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "相信并听从。", "primary_collocate": null, "pronunciation": "xìn cóng", "ipa": "ɕin⁵¹ tsʰʊŋ³⁵", "syllable_count": 2, "sentences": [{"text": "学生们信从老师的安排。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他信从长辈的建议。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们一直信从这位老人。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我信从您的指示，并依此行事。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们信从了那个人的话。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不信从别人的意见。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵信从指挥官的命令。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩很容易信从大人。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家为什么都信从他呢？", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里的人信从这位经理。", "target_word": "信从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "信从了", "label": "体标"}, {"form": "信从过", "label": "体标"}], "register": "书面", "sense_fingerprint": "相信并听从", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于衣物、器物等，不能说洗老师的安排。"}, {"text": "信从", "is_correct": true, "explanation": "正确。信从是相信并听从，与“学生们听老师的安排”相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说煮安排。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指引发燃烧或激起情绪，安排不能被点燃。"}], "explanations": {"洗": "搭配：“洗”用于衣物、器物等，不能说洗老师的安排。", "信从": "正确。信从是相信并听从，与“学生们听老师的安排”相符。", "煮": "搭配：“煮”的对象是食物，不能说煮安排。", "点燃": "语义：“点燃”指引发燃烧或激起情绪，安排不能被点燃。"}, "sentence_index": 0, "correct_answer": "信从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我信从这份礼物。", "explanation": "这里应该用〈接受〉。信从的对象是人或权威，礼物只能接受。"}, {"text": "我信从这首歌。", "explanation": "这里应该用〈喜爱〉。信从指相信并照做，对歌曲的喜欢要用喜爱。"}, {"text": "我很信从这块蛋糕。", "explanation": "这里应该用〈喜欢〉。信从的对象是人或权威，蛋糕不能信从；对食物的喜爱要用喜欢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腌", "is_correct": false, "explanation": "搭配：“腌”用于食物，不能说腌指挥官的命令。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热食物，与士兵和命令无关。"}, {"text": "信从", "is_correct": true, "explanation": "正确。信从是相信并听从，与“士兵听指挥官的命令”相符。"}, {"text": "熨", "is_correct": false, "explanation": "搭配：“熨”用于衣物，不能说熨命令。"}], "explanations": {"腌": "搭配：“腌”用于食物，不能说腌指挥官的命令。", "烤": "语义：“烤”是加热食物，与士兵和命令无关。", "信从": "正确。信从是相信并听从，与“士兵听指挥官的命令”相符。", "熨": "搭配：“熨”用于衣物，不能说熨命令。"}, "sentence_index": 6, "correct_answer": "信从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路人信从那个乞丐。", "explanation": "这里应该用〈同情〉。信从是相信并听从，不是怜悯，对可怜的人要用同情。"}, {"text": "我信从小时候的家。", "explanation": "这里应该用〈怀念〉。信从的对象是人或权威，怀念过去的事物要用怀念。"}, {"text": "大家信从天气。", "explanation": "这里应该用〈抱怨〉。信从是相信并照做，天气不能信从，对不满要用抱怨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
