INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89691, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "除是把东西拿走,去掉。", "primary_collocate": null, "pronunciation": "chú", "ipa": "ʈʂʰu˧˥", "syllable_count": 1, "sentences": [{"text": "冬天早上，爸爸先去院子里除雪。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的草太长了，该除一除了。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用刷子把墙上的灰除掉。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布上的油，怎么也除不掉。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，农民忙着在地里除草。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把墙上的旧漆除干净。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿小刀把铁锅上的锈除掉。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗台上的灰太厚，你帮我除一下。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在用机器除路边的杂草。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药水能除掉衣服上的污渍。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "除掉", "label": "复合"}, {"form": "除草", "label": "复合"}, {"form": "除锈", "label": "复合"}], "register": "中性", "sense_fingerprint": "除|动词|把具体的东西拿走、去掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3ab9ed-a0b5-40d9-895a-567767ad38c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89691, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "除", "is_correct": true, "explanation": "正确：“除”（chú）表示把具体的东西拿走、去掉，与句子意思一致。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 chú 声母不同（zh 与 ch），意思是竹子。"}, {"text": "熟", "is_correct": false, "explanation": "shú（第二声）与 chú 声母不同（sh 与 ch），意思是熟悉、成熟。"}, {"text": "处", "is_correct": false, "explanation": "chǔ（第三声）与 chú（第二声）声调不同，意思是处理、地方。"}, {"text": "初", "is_correct": false, "explanation": "chū（第一声）与 chú（第二声）声调不同，意思是最初。"}, {"text": "触", "is_correct": false, "explanation": "chù（第四声）与 chú（第二声）声调不同，意思是接触。"}], "explanations": {"除": "正确：“除”（chú）表示把具体的东西拿走、去掉，与句子意思一致。", "竹": "zhú（第二声）与 chú 声母不同（zh 与 ch），意思是竹子。", "熟": "shú（第二声）与 chú 声母不同（sh 与 ch），意思是熟悉、成熟。", "处": "chǔ（第三声）与 chú（第二声）声调不同，意思是处理、地方。", "初": "chū（第一声）与 chú（第二声）声调不同，意思是最初。", "触": "chù（第四声）与 chú（第二声）声调不同，意思是接触。"}, "sentence_index": null, "correct_answer": "除"}, "level_3": {"options": [{"text": "除", "is_correct": true, "explanation": "正确：“除雪”表示把雪拿走，与“去院子里清理”的语境相符。"}, {"text": "买", "is_correct": false, "explanation": "语义：雪不是商品，“去院子里买雪”不合常理。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖雪”与清理院子的意思无关，句子说不通。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”不搭配雪，融雪应说“化”，不说“烧雪”。"}], "explanations": {"除": "正确：“除雪”表示把雪拿走，与“去院子里清理”的语境相符。", "买": "语义：雪不是商品，“去院子里买雪”不合常理。", "卖": "语义：“卖雪”与清理院子的意思无关，句子说不通。", "烧": "搭配：“烧”不搭配雪，融雪应说“化”，不说“烧雪”。"}, "sentence_index": 0, "correct_answer": "除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一下子除掉了一个难得的好机会。", "explanation": "这里应该用〈抓住〉。除掉用于拿走不要的东西，不用于应该抓住的好机会。"}, {"text": "老人把珍贵的回忆统统除掉了。", "explanation": "这里应该用〈珍藏〉。除掉用于拿走不要的东西，不用于应当珍藏的回忆。"}, {"text": "他终于除掉了一份好工作。", "explanation": "这里应该用〈获得〉。除掉用于拿走不要的东西，不用于得到好工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89691, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "除", "is_correct": true, "explanation": "正确：“除”（chú）表示把具体的东西拿走、去掉，与句子意思一致。"}, {"text": "逐", "is_correct": false, "explanation": "zhú（第二声）与 chú 声母不同（zh 与 ch），意思是追逐、逐渐。"}, {"text": "赎", "is_correct": false, "explanation": "shú（第二声）与 chú 声母不同（sh 与 ch），意思是赎回。"}, {"text": "储", "is_correct": false, "explanation": "chǔ（第三声）与 chú（第二声）声调不同，意思是储存。"}, {"text": "出", "is_correct": false, "explanation": "chū（第一声）与 chú（第二声）声调不同，意思是出去。"}], "explanations": {"除": "正确：“除”（chú）表示把具体的东西拿走、去掉，与句子意思一致。", "逐": "zhú（第二声）与 chú 声母不同（zh 与 ch），意思是追逐、逐渐。", "赎": "shú（第二声）与 chú 声母不同（sh 与 ch），意思是赎回。", "储": "chǔ（第三声）与 chú（第二声）声调不同，意思是储存。", "出": "chū（第一声）与 chú（第二声）声调不同，意思是出去。"}, "sentence_index": null, "correct_answer": "除"}, "level_3": {"options": [{"text": "除", "is_correct": true, "explanation": "正确：“除掉锈”表示把锈去掉，与“用小刀清理铁锅”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃掉”的对象是食物，不说吃掉铁锈。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，铁锈不能喝。"}, {"text": "咽", "is_correct": false, "explanation": "语义：咽下的是食物，与去掉铁锈的意思无关。"}], "explanations": {"除": "正确：“除掉锈”表示把锈去掉，与“用小刀清理铁锅”的语境相符。", "吃": "搭配：“吃掉”的对象是食物，不说吃掉铁锈。", "喝": "搭配：“喝”的对象是液体，铁锈不能喝。", "咽": "语义：咽下的是食物，与去掉铁锈的意思无关。"}, "sentence_index": 6, "correct_answer": "除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直在除掉丰富的经验。", "explanation": "这里应该用〈积累〉。除掉用于去掉坏的、多余的东西，不用于好的、值得保留的经验。"}, {"text": "我们要除掉这份友谊。", "explanation": "这里应该用〈珍惜〉。除掉用于去掉坏的东西，不能用于应该珍惜的友谊。"}, {"text": "老人除掉了晚年的幸福。", "explanation": "这里应该用〈享受〉。除掉用于去掉坏的、多余的东西，不用于失去幸福这类好的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人正在用机器除了墙上的旧漆。", "corrected_sentence": "工人正在用机器除掉墙上的旧漆。", "error_description": "体标错误：“正在”表示动作进行中，不能再用表示完成的“了”。要表示去掉，应说“除掉”，改为“工人正在用机器除掉墙上的旧漆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们必须这块布上的油除掉。", "corrected_sentence": "他们必须把这块布上的油除掉。", "error_description": "漏掉“把”：宾语提前时要用“把”字句，应改为“他们必须把这块布上的油除掉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
