INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89692, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去掉;消除。", "primary_collocate": null, "pronunciation": "chú", "ipa": "ʈʂʰu˧˥", "syllable_count": 1, "sentences": [{"text": "这个坏习惯很难除掉。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想除掉这个心病。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些隐患必须马上除掉。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把心里的顾虑除掉，他才能安心工作。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把这个毛病彻底除掉。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的坏脾气，怎么也除不掉。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想除掉偏见，就得多接触别人。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要除掉这个祸害。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮他除掉了坏毛病。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想除掉管理上的漏洞。", "target_word": "除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "除掉", "label": "复合"}, {"form": "除去", "label": "复合"}], "register": "中性", "sense_fingerprint": "除|动词|去掉，消除（坏处、隐患等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3ab9ed-a0b5-40d9-895a-567767ad38c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89692, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "除", "is_correct": true, "explanation": "正确：“除”（chú）表示去掉、消除，与句子意思一致。"}, {"text": "熟", "is_correct": false, "explanation": "shú（第二声）与 chú 声母不同（sh 与 ch），意思是熟悉、成熟。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 chú 声母不同（zh 与 ch），意思是竹子。"}, {"text": "处", "is_correct": false, "explanation": "chǔ（第三声）与 chú（第二声）声调不同，意思是处理、地方。"}, {"text": "出", "is_correct": false, "explanation": "chū（第一声）与 chú（第二声）声调不同，意思是出去。"}, {"text": "触", "is_correct": false, "explanation": "chù（第四声）与 chú（第二声）声调不同，意思是接触。"}], "explanations": {"除": "正确：“除”（chú）表示去掉、消除，与句子意思一致。", "熟": "shú（第二声）与 chú 声母不同（sh 与 ch），意思是熟悉、成熟。", "竹": "zhú（第二声）与 chú 声母不同（zh 与 ch），意思是竹子。", "处": "chǔ（第三声）与 chú（第二声）声调不同，意思是处理、地方。", "出": "chū（第一声）与 chú（第二声）声调不同，意思是出去。", "触": "chù（第四声）与 chú（第二声）声调不同，意思是接触。"}, "sentence_index": null, "correct_answer": "除"}, "level_3": {"options": [{"text": "除", "is_correct": true, "explanation": "正确：“除掉”表示去掉，可以搭配“坏习惯”。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒掉”用于液体、垃圾，不说倒掉坏习惯。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”用于衣服鞋袜，不能和坏习惯搭配。"}, {"text": "锯", "is_correct": false, "explanation": "语义：“锯掉”指把物体截断，不能用于习惯。"}], "explanations": {"除": "正确：“除掉”表示去掉，可以搭配“坏习惯”。", "倒": "搭配：“倒掉”用于液体、垃圾，不说倒掉坏习惯。", "穿": "语义：“穿”用于衣服鞋袜，不能和坏习惯搭配。", "锯": "语义：“锯掉”指把物体截断，不能用于习惯。"}, "sentence_index": 0, "correct_answer": "除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该除掉这个好习惯。", "explanation": "这里应该用〈保持〉。除掉用于去掉坏的、多余的东西，好习惯应当保留，不能用“除掉”。"}, {"text": "妈妈一下子除掉了全部的希望。", "explanation": "这里应该用〈保留〉。除掉用于去掉坏的、多余的东西，不用于应当保留的希望。"}, {"text": "命运除掉了他的快乐。", "explanation": "这里应该用〈夺走〉。除掉用于去掉坏的、多余的东西，不用于失去快乐这类好的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89692, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "除", "is_correct": true, "explanation": "正确：“除”（chú）表示去掉、消除，与句子意思一致。"}, {"text": "逐", "is_correct": false, "explanation": "zhú（第二声）与 chú 声母不同（zh 与 ch），意思是追逐、逐渐。"}, {"text": "赎", "is_correct": false, "explanation": "shú（第二声）与 chú 声母不同（sh 与 ch），意思是赎回。"}, {"text": "储", "is_correct": false, "explanation": "chǔ（第三声）与 chú（第二声）声调不同，意思是储存。"}, {"text": "初", "is_correct": false, "explanation": "chū（第一声）与 chú（第二声）声调不同，意思是开始的时候。"}], "explanations": {"除": "正确：“除”（chú）表示去掉、消除，与句子意思一致。", "逐": "zhú（第二声）与 chú 声母不同（zh 与 ch），意思是追逐、逐渐。", "赎": "shú（第二声）与 chú 声母不同（sh 与 ch），意思是赎回。", "储": "chǔ（第三声）与 chú（第二声）声调不同，意思是储存。", "初": "chū（第一声）与 chú（第二声）声调不同，意思是开始的时候。"}, "sentence_index": null, "correct_answer": "除"}, "level_3": {"options": [{"text": "除", "is_correct": true, "explanation": "正确：“除掉偏见”表示去掉偏见，与“多接触别人”的语境相符。"}, {"text": "吐", "is_correct": false, "explanation": "语义：“吐掉”指吐出口中的东西，不能用于偏见。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象多是液体、饮品，不能说喝掉偏见。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：“吞”的对象多为食物或财物，不说吞掉偏见。"}], "explanations": {"除": "正确：“除掉偏见”表示去掉偏见，与“多接触别人”的语境相符。", "吐": "语义：“吐掉”指吐出口中的东西，不能用于偏见。", "喝": "搭配：“喝”的对象多是液体、饮品，不能说喝掉偏见。", "吞": "搭配：“吞”的对象多为食物或财物，不说吞掉偏见。"}, "sentence_index": 6, "correct_answer": "除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为作弊，除掉了自己的荣誉。", "explanation": "这里应该用〈丧失〉。除掉用于去掉坏的、多余的东西，不用于失去荣誉这类好的东西。"}, {"text": "老师一直在除掉学生的兴趣。", "explanation": "这里应该用〈培养〉。除掉不能用于兴趣这类应该保护、发展的东西。"}, {"text": "他很快就除掉了这份喜悦。", "explanation": "这里应该用〈享受〉。除掉表示去掉坏处，不能用来表示享受好的感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想把这个坏毛病除掉了。", "corrected_sentence": "他想把这个坏毛病除掉。", "error_description": "错误：句末多出“了”。“想”表示还没有实现的意愿，和表示完成的“了”相矛盾，应改为“他想把这个坏毛病除掉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们必须这种不良风气除掉。", "corrected_sentence": "我们必须把这种不良风气除掉。", "error_description": "漏掉“把”：宾语提前时要用“把”字句，应改为“我们必须把这种不良风气除掉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
