INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89698, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "商店把新到的商品摆出来出售。", "primary_collocate": null, "pronunciation": "shàng xīn", "ipa": "ʂɑŋ˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这家店每周五上新。", "target_word": "上新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店今天早上上新了一批衣服。", "target_word": "上新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年到了，超市上新了很多零食。", "target_word": "上新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的网店明天晚上八点上新。", "target_word": "上新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员正忙着上新，请你稍等。", "target_word": "上新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家书店每个月都上新一次。", "target_word": "上新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天一到，服装店就开始上新。", "target_word": "上新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈喜欢在商店刚上新的时候去逛。", "target_word": "上新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我关注了这个品牌，一上新就知道。", "target_word": "上新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店长说，周一上新夏天的衣服。", "target_word": "上新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上新了", "label": "体标"}, {"form": "上新过", "label": "体标"}], "register": "口语", "sense_fingerprint": "商店摆出新到的商品出售", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f31afe75-cf81-4a37-a9d7-9dd37dc90485') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上新", "is_correct": true, "explanation": "“上新”指商店把新到的商品摆出来出售，与“每周五”的营业安排相符。"}, {"text": "下课", "is_correct": false, "explanation": "语义：“下课”指学校课程结束，与店铺无关，句子不通。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指学生去学校学习，与店铺无关，句子不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”指人休息，店铺不会睡觉，句子语义不通。"}], "explanations": {"上新": "“上新”指商店把新到的商品摆出来出售，与“每周五”的营业安排相符。", "下课": "语义：“下课”指学校课程结束，与店铺无关，句子不通。", "上学": "语义：“上学”指学生去学校学习，与店铺无关，句子不通。", "睡觉": "语义：“睡觉”指人休息，店铺不会睡觉，句子语义不通。"}, "sentence_index": 0, "correct_answer": "上新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生每周一都在诊室上新。", "explanation": "这里应该用〈坐诊〉。“上新”指店铺把新货摆出来出售，医生在诊室看病要说“坐诊”。"}, {"text": "学生会每年春天都上新，招了很多新成员。", "explanation": "这里应该用〈招新〉。“上新”指店铺把新货摆出来出售，学生会招募新成员要说“招新”。"}, {"text": "快递员每天早上给小区上新。", "explanation": "这里应该用〈送货〉。“送货”指把货物送到客户那里，“上新”指店铺把货摆出来卖，不能用来说快递员的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上新", "is_correct": true, "explanation": "“上新”指服装店摆出新到的商品出售，符合“春天一到”的语境。"}, {"text": "降温", "is_correct": false, "explanation": "语义：“降温”指气温下降，与商店的经营行为无关，且与“春天一到”的语境不符。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指水遇冷变成冰，服装店不会结冰，句子语义不通。"}, {"text": "下班", "is_correct": false, "explanation": "搭配：“下班”的主语须是人，服装店不能下班。"}], "explanations": {"上新": "“上新”指服装店摆出新到的商品出售，符合“春天一到”的语境。", "降温": "语义：“降温”指气温下降，与商店的经营行为无关，且与“春天一到”的语境不符。", "结冰": "语义：“结冰”指水遇冷变成冰，服装店不会结冰，句子语义不通。", "下班": "搭配：“下班”的主语须是人，服装店不能下班。"}, "sentence_index": 6, "correct_answer": "上新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "博物馆的工人下周要上新这幅破旧的古画。", "explanation": "这里应该用〈修复〉。“上新”指店铺把新货摆出来出售，把破旧的古画恢复原样要说“修复”。"}, {"text": "孩子下周上新，要先去报名。", "explanation": "这里应该用〈入学〉。“上新”只用于店铺摆出新货，孩子开始上学要说“入学”。"}, {"text": "我下周去医院上新。", "explanation": "这里应该用〈体检〉。“上新”指店铺摆出新货，个人到医院检查身体不能说“上新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店每周一上新一个次。", "corrected_sentence": "这家店每周一上新一次。", "error_description": "频次补语的动量词应为“次”，前面的数词用“一”。写成“一个次”属于量词错误，应为“上新一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店每周都上新一下。", "corrected_sentence": "这家店每周都上新一次。", "error_description": "“一下”表示短暂尝试，不表示次数；计算“上新”的次数要用动量词“次”，写成“上新一下”错误，应为“上新一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
