INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89699, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种大大圆圆的球，大家把它投进高高的篮子里。", "primary_collocate": null, "pronunciation": "lán qiú", "ipa": "lan˧˥ tɕʰjoʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我生日时，爸爸送了我一个篮球。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个篮球太旧了，需要买新的。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把篮球扔给了我。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球在地上滚到了桌子下面。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里放着三个篮球。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把篮球放进袋子里。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个篮球很重，小孩拿不动。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的篮球没有气了。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个红色的篮球。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟抱着篮球跑进了房间。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "篮球鞋", "label": "复合"}, {"form": "篮球场", "label": "复合"}], "register": "中性", "sense_fingerprint": "打篮球时用的那个球本身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30511e17-00b3-46ac-a6ac-77252451a420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89699, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "篮球", "is_correct": true, "explanation": "篮球：生日时爸爸送的礼物是一个篮球，与“送了我一个”相符，是本句唯一合适的词。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是日期，不能当作礼物送给别人，句子语义不通。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”是季节，不是可以送的东西，句子语义不通。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“送”的对象应是可以赠送的物品，不说送感冒。"}], "explanations": {"篮球": "篮球：生日时爸爸送的礼物是一个篮球，与“送了我一个”相符，是本句唯一合适的词。", "生日": "语义：“生日”是日期，不能当作礼物送给别人，句子语义不通。", "夏天": "语义：“夏天”是季节，不是可以送的东西，句子语义不通。", "感冒": "搭配：“送”的对象应是可以赠送的物品，不说送感冒。"}, "sentence_index": 0, "correct_answer": "篮球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一杆把篮球打进了洞里。", "explanation": "这里应该用〈高尔夫球〉。篮球不用球杆击打，“一杆打进洞”是高尔夫的打法。"}, {"text": "他一脚把篮球踢进了球门。", "explanation": "这里应该用〈足球〉。篮球要用手投或拍，不用脚踢；“一脚踢进球门”是足球的动作。"}, {"text": "他一拍把篮球打过了网。", "explanation": "这里应该用〈排球〉。篮球场中间没有隔开两队的球网，“打过网”是排球的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89699, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "篮球", "is_correct": true, "explanation": "篮球：这个物品很重、小孩拿不动，与“这个”和“很重”相符，是本句唯一合适的词。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”没有重量，不能用“重”来形容。"}, {"text": "天", "is_correct": false, "explanation": "搭配：“重”形容有分量的物体，不说天很重。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”是表情，没有重量，不能说很重。"}], "explanations": {"篮球": "篮球：这个物品很重、小孩拿不动，与“这个”和“很重”相符，是本句唯一合适的词。", "声音": "语义：“声音”没有重量，不能用“重”来形容。", "天": "搭配：“重”形容有分量的物体，不说天很重。", "微笑": "语义：“微笑”是表情，没有重量，不能说很重。"}, "sentence_index": 6, "correct_answer": "篮球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一个乒乓球队的队员用球拍把篮球打了回去。", "explanation": "这里应该用〈乒乓球〉。篮球不能用球拍击打；乒乓球队用球拍击回去的是乒乓球。"}, {"text": "他挥起球棒，把篮球打了出去。", "explanation": "这里应该用〈棒球〉。篮球不用球棒击打，挥棒击出去的是棒球。"}, {"text": "他把篮球放在小桌上，用小拍子打来打去。", "explanation": "这里应该用〈乒乓球〉。篮球又大又重，不能放在小桌上用小拍子打；在桌上用拍子打的是乒乓球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89699, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一本篮球。", "corrected_sentence": "我买了一个篮球。", "error_description": "量词错误：“篮球”是球，量词应用“个”，不能用“本”（“本”用于书籍等），应说“一个篮球”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89699, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹有一本红色的篮球。", "corrected_sentence": "妹妹有一个红色的篮球。", "error_description": "量词错误：“篮球”是球，量词应用“个”，不能用“本”（“本”用于书籍等），应说“一个红色的篮球”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
