INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89700, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "双方各以投球入篮得分的一种球类运动。", "primary_collocate": null, "pronunciation": "lán qiú", "ipa": "lan˧˥ tɕʰjoʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我周末常常和朋友打篮球。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢篮球，每天都练习。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球比赛下午三点开始。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会打篮球吗？", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在学校打过篮球。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球比足球更适合在室内玩。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们不能去打篮球了。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子高，很适合打篮球。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对篮球很感兴趣。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸看了一晚上篮球比赛。", "target_word": "篮球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "篮球赛", "label": "复合"}, {"form": "篮球场", "label": "复合"}, {"form": "篮球鞋", "label": "复合"}], "register": "中性", "sense_fingerprint": "双方投球入篮得分的球类运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30511e17-00b3-46ac-a6ac-77252451a420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "篮球", "is_correct": true, "explanation": "篮球：“打篮球”是常用搭配，指这项球类运动，与“周末常常和朋友”相符。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“钢琴”的动词是“弹”，不说打钢琴，句子语义不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”的动词是“写”或“做”，不说打作业。"}, {"text": "甜点", "is_correct": false, "explanation": "语义：“甜点”是食物，不是可以“打”的活动，句子语义不通。"}], "explanations": {"篮球": "篮球：“打篮球”是常用搭配，指这项球类运动，与“周末常常和朋友”相符。", "钢琴": "搭配：“钢琴”的动词是“弹”，不说打钢琴，句子语义不通。", "作业": "搭配：“作业”的动词是“写”或“做”，不说打作业。", "甜点": "语义：“甜点”是食物，不是可以“打”的活动，句子语义不通。"}, "sentence_index": 0, "correct_answer": "篮球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们每天在游泳池里打篮球，练得很累。", "explanation": "这里应该用〈水球〉。篮球要在陆地上的球场进行，在游泳池里比赛的球类运动是水球。"}, {"text": "他拿着球拍，正在打篮球。", "explanation": "这里应该用〈乒乓球〉。篮球不用球拍，打乒乓球才用球拍。"}, {"text": "他每天在草地上打篮球，一杆把球打进远处的小洞。", "explanation": "这里应该用〈高尔夫球〉。篮球是把球投进篮筐的运动，用杆把球打进小洞的运动是高尔夫球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "篮球", "is_correct": true, "explanation": "篮球：下雨时不能去做的运动，指这项球类运动，与“去打”和“了”相符，是本句唯一合适的词。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：“空调”不是可以“打”的对象，应说“开空调”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”不能“打”，常说“开”或“关”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是体育活动，不能用“打”来搭配，句子语义不通。"}], "explanations": {"篮球": "篮球：下雨时不能去做的运动，指这项球类运动，与“去打”和“了”相符，是本句唯一合适的词。", "空调": "搭配：“空调”不是可以“打”的对象，应说“开空调”。", "冰箱": "搭配：“冰箱”不能“打”，常说“开”或“关”。", "天空": "语义：“天空”不是体育活动，不能用“打”来搭配，句子语义不通。"}, "sentence_index": 6, "correct_answer": "篮球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两队隔着球网，打了一场篮球比赛。", "explanation": "这里应该用〈排球〉。篮球场中间没有隔开两队的球网，隔网对打是排球的特点。"}, {"text": "篮球比赛里，他一棒把球打得很远。", "explanation": "这里应该用〈棒球〉。一棒击球是棒球的动作，篮球不用球棒。"}, {"text": "这场篮球比赛，他用脚把球踢进了球门。", "explanation": "这里应该用〈足球〉。篮球比赛用手投篮得分，用脚把球踢进球门是足球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他打篮球得很好。", "corrected_sentence": "他打篮球打得很好。", "error_description": "补语错误：“打篮球”后面的补语需要重复动词，应说“打篮球打得很好”，不能说“打篮球得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹篮球打的很好。", "corrected_sentence": "妹妹篮球打得很好。", "error_description": "“的”与“得”混用：表示动作达到的程度要用“得”，不能用“的”，应说“打得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
