INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89701, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "伪造是把假的东西做成像真的一样。", "primary_collocate": null, "pronunciation": "wěi zào", "ipa": "weɪ˨˩˦ tsaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "小偷伪造了一把钥匙。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们伪造了车票，在车站被抓住了。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人伪造身份，在国外生活了三年。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同是伪造的，上面的签名不是本人写的。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会伪造各种名牌商品的标签。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伪造了一张医院证明，请了三天假。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把便宜的酒装进名牌瓶子，伪造成名酒。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现，这些钱都是伪造出来的。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把日期改了，伪造了发票。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伪造证据会受到法律的处罚。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "伪造了", "label": "完成体"}, {"form": "伪造过", "label": "经历体"}, {"form": "偽造", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把假的东西做得像真的一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b41ffc-15e7-408c-b241-b02b4f737514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89701, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打开", "is_correct": false, "explanation": "搭配：“打开”针对门、箱子等，不能带“钥匙”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与“钥匙”无关，句子不通。"}, {"text": "伪造", "is_correct": true, "explanation": "正确：“伪造”指把假的钥匙做得像真的，与“小偷”的行为相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“钥匙”作宾语。"}], "explanations": {"打开": "搭配：“打开”针对门、箱子等，不能带“钥匙”作宾语。", "唱": "语义：“唱”与“钥匙”无关，句子不通。", "伪造": "正确：“伪造”指把假的钥匙做得像真的，与“小偷”的行为相合。", "睡觉": "配价：“睡觉”是不及物动词，不能带“钥匙”作宾语。"}, "sentence_index": 0, "correct_answer": "伪造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他伪造成老人，躲过了警察的检查。", "explanation": "这里应该用〈伪装〉。伪造是把假东西做成真的，人装扮成别人要用伪装。"}, {"text": "他伪造了一次跑步，累得满身大汗。", "explanation": "这里应该用〈跑〉。伪造指做假的东西，跑步是动作，不能用伪造。"}, {"text": "他伪造了自己的错误。", "explanation": "这里应该用〈掩饰〉。伪造不能用于错误，掩饰错误要用掩饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89701, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”会毁坏东西，不能“打碎成名酒”，句子不通。"}, {"text": "伪造", "is_correct": true, "explanation": "正确：“伪造”指把便宜的酒做得像真的名酒一样，与“装进名牌瓶子”相合。"}, {"text": "染", "is_correct": false, "explanation": "搭配：“染”多用于颜色、布料，不能说“染成名酒”。"}, {"text": "拆卸", "is_correct": false, "explanation": "语义：“拆卸”指拆开机器零件，与酒无关，句子不通。"}], "explanations": {"打碎": "语义：“打碎”会毁坏东西，不能“打碎成名酒”，句子不通。", "伪造": "正确：“伪造”指把便宜的酒做得像真的名酒一样，与“装进名牌瓶子”相合。", "染": "搭配：“染”多用于颜色、布料，不能说“染成名酒”。", "拆卸": "语义：“拆卸”指拆开机器零件，与酒无关，句子不通。"}, "sentence_index": 6, "correct_answer": "伪造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他伪造了一顿晚饭，全家吃得很开心。", "explanation": "这里应该用〈做〉。伪造指把假东西做得像真的，做饭要用做，不能说伪造。"}, {"text": "她伪造了一阵风，把窗户吹开了。", "explanation": "这里应该用〈刮〉。伪造指做假的东西，风是自然现象，刮起一阵风要用刮，不能说伪造。"}, {"text": "他伪造了一个夏天，带全家去了海边。", "explanation": "这里应该用〈度过〉。伪造指做假的东西，夏天是时间，要用度过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张证件伪造很逼真。", "corrected_sentence": "这张证件伪造得很逼真。", "error_description": "错误形式：“伪造很逼真”，缺少补语标记“得”；正确形式：“伪造得很逼真”，“得”引出情态补语，描述伪造的程度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批旧金属被他们伪造了成古董。", "corrected_sentence": "这批旧金属被他们伪造成了古董。", "error_description": "错误形式：“伪造了成”，结果补语“成”应紧跟动词，“了”放在补语之后；正确形式：“伪造成了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
