INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89702, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "仿照真的东西制造假的，以欺骗他人。", "primary_collocate": null, "pronunciation": "wěi zào", "ipa": "weɪ˨˩˦ tsaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他伪造了老板的签名。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓到了伪造钞票的人。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人伪造证件，想骗别人的钱。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她伪造了一封信，让大家都相信了。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伪造名画，卖给了有钱人。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司伪造账本，骗了很多客户。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为伪造文件被警察带走了。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张票是伪造的，不能进场。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想伪造成绩单，结果被老师发现了。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人伪造名牌包，卖得很便宜。", "target_word": "伪造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "伪造了", "label": "完成体"}, {"form": "伪造过", "label": "经历体"}, {"form": "偽造", "label": "繁体"}], "register": "书面", "sense_fingerprint": "仿照真物制造假的东西去骗人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b41ffc-15e7-408c-b241-b02b4f737514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“签名”无关，句子说不通。"}, {"text": "伪造", "is_correct": true, "explanation": "正确：“伪造”指仿照真的东西做假的，与“签名”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“签名”作宾语。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”不跟“签名”搭配，不能说“吹签名”。"}], "explanations": {"吃": "语义：“吃”与“签名”无关，句子说不通。", "伪造": "正确：“伪造”指仿照真的东西做假的，与“签名”搭配。", "唱": "搭配：“唱”不能带“签名”作宾语。", "吹": "搭配：“吹”不跟“签名”搭配，不能说“吹签名”。"}, "sentence_index": 0, "correct_answer": "伪造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他伪造了一次游泳，游完后很累。", "explanation": "这里应该用〈游〉。伪造指仿照真东西制造假的，游泳是动作，不能用伪造。"}, {"text": "他伪造了一个笑话，逗得大家都笑了。", "explanation": "这里应该用〈编〉。伪造指仿照真的东西做假的去骗人，讲笑话、编故事要用编。"}, {"text": "他在剧中伪造了一位国王。", "explanation": "这里应该用〈扮演〉。伪造指做假的东西，演员扮演角色不能说伪造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”与做假的违法行为相矛盾，句子不通。"}, {"text": "反驳", "is_correct": false, "explanation": "语义：“反驳”针对说法、观点，与“被警察带走”的原因无关，句子不通。"}, {"text": "伪造", "is_correct": true, "explanation": "正确：“伪造”指做假的文件，与“文件”搭配，是被带走的原因。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“文件”作宾语。"}], "explanations": {"原谅": "语义：“原谅”与做假的违法行为相矛盾，句子不通。", "反驳": "语义：“反驳”针对说法、观点，与“被警察带走”的原因无关，句子不通。", "伪造": "正确：“伪造”指做假的文件，与“文件”搭配，是被带走的原因。", "睡觉": "配价：“睡觉”是不及物动词，不能带“文件”作宾语。"}, "sentence_index": 6, "correct_answer": "伪造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她伪造了一片蓝天，让孩子们很开心。", "explanation": "这里应该用〈画〉。伪造指做假的物品，画出蓝天要用画，不能说伪造。"}, {"text": "他伪造了一张桌子，做得很结实。", "explanation": "这里应该用〈做〉。伪造指仿照真东西做假的去骗人，做家具要用做，不能说伪造。"}, {"text": "他伪造了一个蛋糕，给妈妈过生日。", "explanation": "这里应该用〈烤〉。伪造指做假的东西骗人，做蛋糕要用烤，不能说伪造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张签名伪造很像，老板都没看出来。", "corrected_sentence": "这张签名伪造得很像，老板都没看出来。", "error_description": "错误形式：“伪造很像”，缺少补语标记“得”；正确形式：“伪造得很像”，“得”引出情态补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他伪造了出一份合同。", "corrected_sentence": "他伪造出了一份合同。", "error_description": "错误形式：“伪造了出”，趋向补语“出”应紧跟动词，“了”放在补语之后；正确形式：“伪造出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
