INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89705, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把很多电脑连在一起，让大家能在上面看东西。", "primary_collocate": null, "pronunciation": "wǎng lù", "ipa": "wɑŋ˨˩˦ lu˥˩", "syllable_count": 2, "sentences": [{"text": "学校的网路很快，大家都能上网看视频。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司把所有电脑接到一个网路上。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网路让大家能看到同样的文件。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的网路坏了，我看不了新闻。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆有免费网路，学生可以看电子书。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网路连好以后，我们就能看电影。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的网路只有同事可以用。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把电脑接上网路，开始看新闻。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的网路太慢，网页打不开。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店里的网路很好，我常在这儿看东西。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "无线网路", "label": "复合"}, {"form": "网路速度", "label": "复合"}], "register": "中性", "sense_fingerprint": "把许多电脑连在一起、供人上网使用的网", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51f2d4c-4300-4b9b-afac-e322d926561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89705, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网路", "is_correct": true, "explanation": "正确。网路是连接电脑的系统，句子说它很快，大家才能上网看视频。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能“很快”，也不能用来上网看视频。"}, {"text": "校服", "is_correct": false, "explanation": "语义：校服与上网无关，后句说的是“大家都能上网看视频”。"}, {"text": "操场", "is_correct": false, "explanation": "搭配：“很快”不用来形容操场，操场也不能上网看视频。"}], "explanations": {"网路": "正确。网路是连接电脑的系统，句子说它很快，大家才能上网看视频。", "课本": "语义：课本不能“很快”，也不能用来上网看视频。", "校服": "语义：校服与上网无关，后句说的是“大家都能上网看视频”。", "操场": "搭配：“很快”不用来形容操场，操场也不能上网看视频。"}, "sentence_index": 0, "correct_answer": "网路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里的网路老化了，有时会跳闸。", "explanation": "这里应该用〈线路〉。线路指电线、电路，会老化、跳闸；网路指连接电脑的系统，不会跳闸。"}, {"text": "这个网路的标题很好看，我常点进去看。", "explanation": "这里应该用〈网页〉。网页有标题，可以点进去看；网路是连接电脑的系统，没有标题。"}, {"text": "我在浏览器里输入这个网路，打开了网页。", "explanation": "这里应该用〈网址〉。网址是可以在浏览器里输入、用来打开网页的地址；网路是连接电脑的系统，不能输入浏览器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89705, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网路", "is_correct": true, "explanation": "正确。网路是办公室连接电脑的系统，只有同事能用。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不属于办公室，也不能由同事“使用”。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“用”的对象必须是能被使用的东西，月亮不能用。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不能说“只有同事可以用”。"}], "explanations": {"网路": "正确。网路是办公室连接电脑的系统，只有同事能用。", "海洋": "语义：海洋不属于办公室，也不能由同事“使用”。", "月亮": "搭配：“用”的对象必须是能被使用的东西，月亮不能用。", "饺子": "语义：饺子是食物，不能说“只有同事可以用”。"}, "sentence_index": 6, "correct_answer": "网路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把网路插到路由器上。", "explanation": "这里应该用〈网线〉。网线是可以插进路由器的线材；网路是连接电脑的系统，不能插到路由器上。"}, {"text": "公司请了一个网路，专门负责维修电脑。", "explanation": "这里应该用〈网管〉。网管是可以被请来负责维护的人；网路是系统，不能被请来工作。"}, {"text": "这个网路很有见解，常在论坛里发言。", "explanation": "这里应该用〈网民〉。网民是在网上发言、有见解的人；网路是系统，没有见解，也不会发言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把一只网路连好了，就能看电影。", "corrected_sentence": "我们把这个网路连好了，就能看电影。", "error_description": "量词错误：网路常用量词“个”，“只”多用于动物或单个小物件，不能说“一只网路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89705, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经把这根网路修好了。", "corrected_sentence": "他已经把这个网路修好了。", "error_description": "量词错误：网路常用量词“个”，“根”用于细长的东西（如线），不能说“这根网路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
