INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89706, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89706, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由许多计算机互相连接而成的系统（台湾地区常用说法，大陆多作“网络”）。", "primary_collocate": null, "pronunciation": "wǎng lù", "ipa": "wɑŋ˨˩˦ lu˥˩", "syllable_count": 2, "sentences": [{"text": "我家刚装好网路，晚上可以看电影。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司负责全国的电脑网路。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网路安全对银行很重要。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学学习网路技术。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的网路把世界连在一起。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没有网路，就不能聊天。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑连不上公司的网路。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网路出问题时，整个系统都停了。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是做网路工程的，工作很忙。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台北的网路服务很方便，价钱也不高。", "target_word": "网路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "网路安全", "label": "复合"}, {"form": "网路技术", "label": "复合"}], "register": "中性", "sense_fingerprint": "计算机互联而成的系统，台湾常用说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51f2d4c-4300-4b9b-afac-e322d926561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网路", "is_correct": true, "explanation": "正确。网路是可以装好的系统，装好后晚上才能看电影。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子不能“装好”，也与看电影无关。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被装好，句子说的是可以看电影的系统。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“装好”通常不用来说雨伞，雨伞也不能用来看电影。"}], "explanations": {"网路": "正确。网路是可以装好的系统，装好后晚上才能看电影。", "饺子": "语义：饺子不能“装好”，也与看电影无关。", "月亮": "语义：月亮不能被装好，句子说的是可以看电影的系统。", "雨伞": "搭配：“装好”通常不用来说雨伞，雨伞也不能用来看电影。"}, "sentence_index": 0, "correct_answer": "网路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "放学后，他常去网路玩游戏。", "explanation": "这里应该用〈网吧〉。网吧是可以去的场所，网路是系统，不能说去网路。"}, {"text": "这个网路的标题很吸引人，我常点进去看。", "explanation": "这里应该用〈网页〉。网页有标题，可以点进去看；网路是连接电脑的系统，没有标题。"}, {"text": "这个网路我每次都复制下来，很方便。", "explanation": "这里应该用〈网址〉。网址可以复制下来；网路是连接电脑的系统，不能被复制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网路", "is_correct": true, "explanation": "正确。连不上的是公司的网路系统，电脑才会连接它。"}, {"text": "大门", "is_correct": false, "explanation": "语义：电脑不能连接大门，大门不是可以连接的系统。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：电脑不能连接饭菜，句子说的是连接不上的系统。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“连不上”的对象应是网络或设备，窗户不能用“连”。"}], "explanations": {"网路": "正确。连不上的是公司的网路系统，电脑才会连接它。", "大门": "语义：电脑不能连接大门，大门不是可以连接的系统。", "饭菜": "语义：电脑不能连接饭菜，句子说的是连接不上的系统。", "窗户": "搭配：“连不上”的对象应是网络或设备，窗户不能用“连”。"}, "sentence_index": 6, "correct_answer": "网路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把网路放进书包里，带去学校。", "explanation": "这里应该用〈网线〉。网线是可以放进书包的线材；网路是连接电脑的系统，不能放进书包。"}, {"text": "学校请了一个网路，专门负责维护电脑。", "explanation": "这里应该用〈网管〉。网管是可以被请来负责维护的人；网路是系统，不能被请来工作。"}, {"text": "网路老化，容易漏电。", "explanation": "这里应该用〈线路〉。线路指电线，会老化、漏电；网路是连接电脑的系统，不是电线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司的一台网路已经修好了。", "corrected_sentence": "公司的这个网路已经修好了。", "error_description": "量词错误：网路常用量词“个”；“台”多用于机器、设备，不能说“一台网路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只网路我们用了两年。", "corrected_sentence": "这个网路我们用了两年。", "error_description": "量词错误：网路常用量词“个”，不能用“只”（“只”多用于动物或单个小物件）。应说“这个网路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
