INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89708, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有极大本领或力量的人。", "primary_collocate": null, "pronunciation": "dà néng", "ipa": "ta˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他是修仙界的大能，没人能打败他。", "target_word": "大能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大能一出手，大家都看呆了。", "target_word": "大能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里住着一位隐世大能。", "target_word": "大能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论坛里的大能帮我解决了问题。", "target_word": "大能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大能们都来参加这次比赛。", "target_word": "大能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏里有很多大能。", "target_word": "大能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说他是电脑方面的大能。", "target_word": "大能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大能出手，一下子就赢了。", "target_word": "大能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你认识这位大能吗？", "target_word": "大能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想拜一位大能为师。", "target_word": "大能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "大能：本领或力量极大的人，高手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4412296-5735-4d77-9af9-beeaa2149034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大能", "is_correct": true, "explanation": "“大能”指本领极大的人，与“没人能打败他”的描述一致。"}, {"text": "凡人", "is_correct": false, "explanation": "语义：“凡人”指普通人，与“没人能打败他”所描述的强者形象矛盾。"}, {"text": "小兵", "is_correct": false, "explanation": "语义：“小兵”指地位低微的人，与“没人能打败他”的强者形象矛盾。"}, {"text": "路人", "is_correct": false, "explanation": "搭配：“路人”指路上不相识的人，不说“修仙界的路人”。"}], "explanations": {"大能": "“大能”指本领极大的人，与“没人能打败他”的描述一致。", "凡人": "语义：“凡人”指普通人，与“没人能打败他”所描述的强者形象矛盾。", "小兵": "语义：“小兵”指地位低微的人，与“没人能打败他”的强者形象矛盾。", "路人": "搭配：“路人”指路上不相识的人，不说“修仙界的路人”。"}, "sentence_index": 0, "correct_answer": "大能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱是大能，很省电。", "explanation": "这里“大能”指有极大本领的人，不能用来指物品。"}, {"text": "我们班的大能每次考试都不及格。", "explanation": "这里“大能”指本领极大的人，与“每次考试都不及格”的描述矛盾，用法不对。"}, {"text": "这位大能今天考试交了白卷，全班都笑了他。", "explanation": "这里“大能”指本领极大的人，与“交白卷”的描述矛盾，用在这里不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大能", "is_correct": true, "explanation": "“大能”指某方面本领极大的人，符合“老师说他是……”的评价。"}, {"text": "工具", "is_correct": false, "explanation": "语义：“工具”指物品，不能用来形容“他”这个人。"}, {"text": "游戏", "is_correct": false, "explanation": "配价：“是”后面要接能指人的名词，“游戏”不能指人。"}, {"text": "零件", "is_correct": false, "explanation": "搭配：“零件”指机器的部件，不能用来评价一个人在电脑方面的能力。"}], "explanations": {"大能": "“大能”指某方面本领极大的人，符合“老师说他是……”的评价。", "工具": "语义：“工具”指物品，不能用来形容“他”这个人。", "游戏": "配价：“是”后面要接能指人的名词，“游戏”不能指人。", "零件": "搭配：“零件”指机器的部件，不能用来评价一个人在电脑方面的能力。"}, "sentence_index": 6, "correct_answer": "大能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想拜一只大能为师。", "explanation": "这里应该用〈位〉。“只”多用于动物，指人要用“位”。"}, {"text": "他想拜一台大能为师。", "explanation": "这里应该用〈位〉。“台”用于机器、设备，不能用来计量人。"}, {"text": "他想拜一块大能为师。", "explanation": "这里应该用〈位〉。“块”用于块状的东西，不能用来计量人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认识一只大能。", "corrected_sentence": "我认识一位大能。", "error_description": "错误：“大能”指人，量词要用“位”，不能用“只”。正确说法是“一位大能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位大能们都来了。", "corrected_sentence": "三位大能都来了。", "error_description": "错误：前面已有数量词“三位”，“大能”后面不能再加复数词尾“们”。正确说法是“三位大能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
