INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89709, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "先行是比别人先走，或者先做。", "primary_collocate": null, "pronunciation": "xiān xíng", "ipa": "ɕjɛn˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "你们慢慢吃，我先行一步。", "target_word": "先行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有急事，先行离开了。", "target_word": "先行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个方案有疑问，先行提出了意见。", "target_word": "先行", "complexity_tier": "T3", "furigana": "xiān xíng", "sentence_source": "generated"}, {"text": "这件事情复杂，请各位先行商议，明天再定。", "target_word": "先行", "complexity_tier": "T3", "furigana": "xiān xíng", "sentence_source": "generated"}, {"text": "我有点累，想先行告辞。", "target_word": "先行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先行到达了机场，等我们来。", "target_word": "先行", "complexity_tier": "T3", "furigana": "xiān xíng", "sentence_source": "generated"}, {"text": "你们先行吧，我随后就到。", "target_word": "先行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理有事，请各部门先行汇报。", "target_word": "先行", "complexity_tier": "T3", "furigana": "xiān xíng", "sentence_source": "generated"}, {"text": "这笔款项我先行垫付了，你不用还。", "target_word": "先行", "complexity_tier": "T3", "furigana": "xiān xíng", "sentence_source": "generated"}, {"text": "孩子们先行下车，大人在后面。", "target_word": "先行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "先行了", "label": "体标"}, {"form": "先行者", "label": "复合"}], "register": "书面", "sense_fingerprint": "比别人先走或先做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d7edf-4df1-41f1-b1d8-d079da48dec8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89709, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "先行", "is_correct": true, "explanation": "正确：先行（xiān xíng）指比别人先走或先做。"}, {"text": "线性", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）声调不同，xìng 与 xíng 声调也不同，意思是线性。"}, {"text": "显性", "is_correct": false, "explanation": "xiǎn（第三声）与 xiān（第一声）声调不同，xìng 与 xíng 声调也不同，意思是显性。"}, {"text": "新型", "is_correct": false, "explanation": "xīn 与 xiān 韵母不同（-in 与 -ian），意思是新型。"}], "explanations": {"先行": "正确：先行（xiān xíng）指比别人先走或先做。", "线性": "xiàn（第四声）与 xiān（第一声）声调不同，xìng 与 xíng 声调也不同，意思是线性。", "显性": "xiǎn（第三声）与 xiān（第一声）声调不同，xìng 与 xíng 声调也不同，意思是显性。", "新型": "xīn 与 xiān 韵母不同（-in 与 -ian），意思是新型。"}, "sentence_index": null, "correct_answer": "先行"}, "level_3": {"options": [{"text": "先行", "is_correct": true, "explanation": "正确：先行，比别人先走。句中“我先行一步”表示我先走一步。"}, {"text": "先吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“一步”所表示的行走距离不合，“我先吃一步”句意不通。"}, {"text": "先醒", "is_correct": false, "explanation": "语义：“醒”指睡醒，与表示先走的“一步”不搭配，“我先醒一步”在吃饭的语境中不通。"}, {"text": "先唱", "is_correct": false, "explanation": "搭配：“唱”不能与“一步”搭配，句中没有唱歌的语境。"}], "explanations": {"先行": "正确：先行，比别人先走。句中“我先行一步”表示我先走一步。", "先吃": "语义：“吃”指进食，与“一步”所表示的行走距离不合，“我先吃一步”句意不通。", "先醒": "语义：“醒”指睡醒，与表示先走的“一步”不搭配，“我先醒一步”在吃饭的语境中不通。", "先唱": "搭配：“唱”不能与“一步”搭配，句中没有唱歌的语境。"}, "sentence_index": 0, "correct_answer": "先行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在班里的成绩一直先行。", "explanation": "这里应该用〈领先〉。先行指先做或先走，不用来说成绩或名次超过别人；说成绩超前要用“领先”。"}, {"text": "这个孩子先行聪明，学什么都快。", "explanation": "这里应该用〈先天〉。先行表示先做或先去，不能用来说人天生的资质。"}, {"text": "这块地先行肥沃，庄稼长得特别好。", "explanation": "这里应该用〈本来〉。先行表示先去做某事，不能用来说土地原本的性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89709, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "先行", "is_correct": true, "explanation": "正确：先行（xiān xíng）指比别人先走或先做。"}, {"text": "现行", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）声调不同，意思是现行（当前正在实行的）。"}, {"text": "限行", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）声调不同，意思是限行（限制通行）。"}, {"text": "线型", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）声调不同，意思是线型（线条的形状）。"}], "explanations": {"先行": "正确：先行（xiān xíng）指比别人先走或先做。", "现行": "xiàn（第四声）与 xiān（第一声）声调不同，意思是现行（当前正在实行的）。", "限行": "xiàn（第四声）与 xiān（第一声）声调不同，意思是限行（限制通行）。", "线型": "xiàn（第四声）与 xiān（第一声）声调不同，意思是线型（线条的形状）。"}, "sentence_index": null, "correct_answer": "先行"}, "level_3": {"options": [{"text": "先行", "is_correct": true, "explanation": "正确：先行，先走一步。句中“你们先行吧”是让别人先走。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”不能用来请别人做，“你们迟到吧”不通，也与“我随后就到”的先后关系不合。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与“我随后就到”的语境不合，整句意思不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能用于让别人先行的指令语境，“你们唱吧，我随后就到”不通。"}], "explanations": {"先行": "正确：先行，先走一步。句中“你们先行吧”是让别人先走。", "迟到": "语义：“迟到”不能用来请别人做，“你们迟到吧”不通，也与“我随后就到”的先后关系不合。", "哭": "语义：“哭”与“我随后就到”的语境不合，整句意思不通。", "唱": "搭配：“唱”不能用于让别人先行的指令语境，“你们唱吧，我随后就到”不通。"}, "sentence_index": 6, "correct_answer": "先行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里先行有个湖，后来被填平了。", "explanation": "这里应该用〈先前〉。先行表示先去做，不能用来说某地过去存在某物。"}, {"text": "他的体重一直先行，一年胖了十公斤。", "explanation": "这里应该用〈增加〉。先行不表示数量增加，体重上涨要说“增加”。"}, {"text": "这种水果先行便宜了三块钱。", "explanation": "这里应该用〈降价〉。先行不表示价格下降，说“降价”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先行一个步，你们随后来。", "corrected_sentence": "我先行一步，你们随后来。", "error_description": "错误形式是“一个步”，正确形式是“一步”。“步”作量词时，数量短语直接说“一步”，不能加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有事，先行离开着。", "corrected_sentence": "她有事，先行离开了。", "error_description": "错误形式是“先行离开着”，正确形式是“先行离开了”。“先行离开”是已经发生的动作，应用动态助词“了”，不能用“着”表示持续。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你应该做的事。", "primary_collocate": null, "pronunciation": "zhí zé", "ipa": "ʈʂɻ̩˧˥ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "照顾孩子是父母的职责。", "target_word": "职责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都有自己的职责。", "target_word": "职责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护环境也是我们的职责。", "target_word": "职责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做饭不是我的职责，是妈妈的。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照顾老人是子女的职责。", "target_word": "职责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他觉得帮助朋友是自己的职责。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为班长，他想好好完成自己的职责。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子小的时候，爱护他们是大人的职责。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，让家人过得好是他的职责。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经尽到了你的职责，可以休息了。", "target_word": "职责", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项职责", "label": "量词"}, {"form": "工作职责", "label": "复合"}, {"form": "職責", "label": "繁体"}], "register": "中性", "sense_fingerprint": "每个人在家庭或社会中应该做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e68a7552-e561-4b72-8b96-81b1448aa4e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职责", "is_correct": true, "explanation": "正确：“职责”指应尽的责任，照顾孩子正是父母应尽的责任。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是对成绩的回报，不是父母应尽的事，句意不通。"}, {"text": "爱好", "is_correct": false, "explanation": "语义：“爱好”指个人的兴趣，父母照顾孩子不是个人兴趣，句意不通。"}, {"text": "职业", "is_correct": false, "explanation": "搭配：“职业”指谋生的工作，不指所负的责任，与“照顾孩子”不搭配。"}], "explanations": {"职责": "正确：“职责”指应尽的责任，照顾孩子正是父母应尽的责任。", "奖励": "语义：“奖励”是对成绩的回报，不是父母应尽的事，句意不通。", "爱好": "语义：“爱好”指个人的兴趣，父母照顾孩子不是个人兴趣，句意不通。", "职业": "搭配：“职业”指谋生的工作，不指所负的责任，与“照顾孩子”不搭配。"}, "sentence_index": 0, "correct_answer": "职责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有使用公园的职责。", "explanation": "这里应该用〈权利〉。“职责”指应尽的义务，使用公园是可以享有的，要用〈权利〉。"}, {"text": "我的职责是喜欢音乐。", "explanation": "这里应该用〈爱好〉。“职责”指应尽的事，个人喜欢的事不能说成职责。"}, {"text": "他考了第一名，这是他应得的职责。", "explanation": "这里应该用〈奖励〉。“职责”是应尽的事，不是应得的回报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职责", "is_correct": true, "explanation": "正确：“职责”指应尽的责任，“完成自己的职责”就是做好自己该做的事。"}, {"text": "规则", "is_correct": false, "explanation": "语义：“规则”是要遵守的条文，不是可以“完成”的任务，句意不通。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“完成”通常不与“礼物”搭配，应说“准备”或“送出”。"}, {"text": "习惯", "is_correct": false, "explanation": "搭配：“习惯”应说“养成”，不说“完成”，与此句不搭配。"}], "explanations": {"职责": "正确：“职责”指应尽的责任，“完成自己的职责”就是做好自己该做的事。", "规则": "语义：“规则”是要遵守的条文，不是可以“完成”的任务，句意不通。", "礼物": "搭配：“完成”通常不与“礼物”搭配，应说“准备”或“送出”。", "习惯": "搭配：“习惯”应说“养成”，不说“完成”，与此句不搭配。"}, "sentence_index": 6, "correct_answer": "职责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的职责很强，什么难题都能解决。", "explanation": "这里应该用〈能力〉。“职责”不能用来形容人的能力强弱。"}, {"text": "他的职责很温和，大家都喜欢他。", "explanation": "这里应该用〈性格〉。“职责”不能用来形容人的性格。"}, {"text": "这件衣服的职责很高，我买不起。", "explanation": "这里应该用〈价格〉。“职责”不能用来说东西的价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他肩上有一张重要的职责。", "corrected_sentence": "他肩上有一项重要的职责。", "error_description": "“职责”的量词应用“项”，不能用“张”。“张”用于纸、桌子等平面的东西，与抽象的“职责”不搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直认真履行职责们。", "corrected_sentence": "他一直认真履行职责。", "error_description": "“职责”是抽象名词，不能加复数词尾“们”，应说“履行职责”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
