INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89715, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "判刑是法官决定坏人要受到什么惩罚。", "primary_collocate": null, "pronunciation": "pàn xíng", "ipa": "pʰan˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "法官今天对那个小偷判刑。", "target_word": "判刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官会对坏人判刑。", "target_word": "判刑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个小偷偷了很多钱，法官给他判刑。", "target_word": "判刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官还没有对他判刑。", "target_word": "判刑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察抓住了坏人，法官明天判刑。", "target_word": "判刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官看完材料以后才能判刑。", "target_word": "判刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏人做错了事，法官要判刑。", "target_word": "判刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官已经对他判刑了。", "target_word": "判刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说法官下周要对这名被告判刑。", "target_word": "判刑", "complexity_tier": "T3", "furigana": "tīng shuō fǎ guān xià zhōu yào duì zhè míng bèi gào pàn xíng 。", "sentence_source": "generated"}, {"text": "法官正在大声宣布，对他判刑三年。", "target_word": "判刑", "complexity_tier": "T3", "furigana": "fǎ guān zhèng zài dà shēng xuān bù ， duì tā pàn xíng sān nián 。", "sentence_source": "generated"}], "morphological_forms": [{"form": "判了刑", "label": "体标"}, {"form": "判过刑", "label": "体标"}], "register": "正式", "sense_fingerprint": "法官决定坏人要受什么惩罚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a0ab2c6-267b-46f6-963b-75f6b1d7240e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89715, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "判刑", "is_correct": true, "explanation": "正确。判刑是法官对罪犯决定刑罚，符合句意。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：法官不会表扬小偷，表扬用于做好事的人。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”通常直接带宾语，不说“对……感谢”。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：法官向小偷道歉与法庭身份不符。"}], "explanations": {"判刑": "正确。判刑是法官对罪犯决定刑罚，符合句意。", "表扬": "语义：法官不会表扬小偷，表扬用于做好事的人。", "感谢": "配价：“感谢”通常直接带宾语，不说“对……感谢”。", "道歉": "语义：法官向小偷道歉与法庭身份不符。"}, "sentence_index": 0, "correct_answer": "判刑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校判了那个不遵守纪律的学生一年刑。", "explanation": "这里应该用〈处罚〉。判刑只能由法院依法对罪犯定刑，学校对学生的纪律处分用处罚。"}, {"text": "交警判了那个闯红灯的司机一年刑。", "explanation": "这里应该用〈罚款〉。判刑是法院对罪犯的刑罚，交警对闯红灯的司机只能罚款。"}, {"text": "法官判了这起合同纠纷一年刑。", "explanation": "这里应该用〈判决〉。判刑只用于对罪犯定刑，合同纠纷的结果要用判决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "判刑", "is_correct": true, "explanation": "正确。判刑是法官对犯罪者定刑罚，符合“做错事”的语境。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：坏人做错了事，法官不会奖励他。"}, {"text": "表彰", "is_correct": false, "explanation": "语义：表彰用于有功的人，与“做错了事”矛盾。"}, {"text": "赔偿", "is_correct": false, "explanation": "语义：赔偿是加害人向受害人补偿，法官对坏人做赔偿，句意不通。"}], "explanations": {"判刑": "正确。判刑是法官对犯罪者定刑罚，符合“做错事”的语境。", "奖励": "语义：坏人做错了事，法官不会奖励他。", "表彰": "语义：表彰用于有功的人，与“做错了事”矛盾。", "赔偿": "语义：赔偿是加害人向受害人补偿，法官对坏人做赔偿，句意不通。"}, "sentence_index": 6, "correct_answer": "判刑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生判了那个生病的病人一年刑。", "explanation": "这里应该用〈诊断〉。判刑只能由法院对犯罪者定刑，医生只能诊断病情。"}, {"text": "老师判了那个上课说话的学生一年刑。", "explanation": "这里应该用〈批评〉。判刑是法院对罪犯的刑罚，老师对课堂纪律只能批评。"}, {"text": "裁判判了那个犯规的球员一年刑。", "explanation": "这里应该用〈判罚〉。判刑是法院的刑事判决，比赛犯规要用判罚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
