INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89716, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "法院依法对犯罪者宣告刑罚。", "primary_collocate": null, "pronunciation": "pàn xíng", "ipa": "pʰan˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "法院依法对他判刑。", "target_word": "判刑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法院对犯罪者判刑三年。", "target_word": "判刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院昨天对三名罪犯判刑。", "target_word": "判刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院必须依法判刑。", "target_word": "判刑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法院根据法律对犯罪者判刑。", "target_word": "判刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院判刑以前会听律师说话。", "target_word": "判刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院已经对这名被告判刑了。", "target_word": "判刑", "complexity_tier": "T3", "furigana": "fǎ yuàn yǐ jīng duì zhè míng bèi gào pàn xíng le 。", "sentence_source": "generated"}, {"text": "法院没有对他判刑，因为证据不够。", "target_word": "判刑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院对抢劫犯判刑五年。", "target_word": "判刑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院对他们判刑时，很多人在场。", "target_word": "判刑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "判了刑", "label": "体标"}, {"form": "判过刑", "label": "体标"}], "register": "正式", "sense_fingerprint": "法院依法对犯罪者宣告刑罚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a0ab2c6-267b-46f6-963b-75f6b1d7240e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "判刑", "is_correct": true, "explanation": "正确。判刑是法院依法对犯罪者宣告刑罚，符合句意。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：法院不会祝贺被判罪的人，与“依法”的判决语境冲突。"}, {"text": "招待", "is_correct": false, "explanation": "语义：招待用于客人，法院不会招待被告。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”不带“对”介词，“对他感谢”不成立。"}], "explanations": {"判刑": "正确。判刑是法院依法对犯罪者宣告刑罚，符合句意。", "祝贺": "语义：法院不会祝贺被判罪的人，与“依法”的判决语境冲突。", "招待": "语义：招待用于客人，法院不会招待被告。", "感谢": "配价：“感谢”不带“对”介词，“对他感谢”不成立。"}, "sentence_index": 0, "correct_answer": "判刑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察判了那个抢东西的小偷一年刑。", "explanation": "判刑是法院的权力，警察不能判刑，只能抓获嫌疑人。"}, {"text": "老板判了那个迟到的员工一年刑。", "explanation": "这里应该用〈辞退〉。判刑是法院对罪犯的刑罚，老板只能辞退员工。"}, {"text": "法院判了这起合同纠纷一年刑。", "explanation": "这里应该用〈判决〉。判刑只用于对犯罪者定刑，合同纠纷的结果要用判决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "判刑", "is_correct": true, "explanation": "正确。判刑是法院对被告作出刑罚判决，符合句意。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：法院不会表扬被告，与“被告”的身份矛盾。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：赞美用于值得称赞的人，与被告的身份不合。"}, {"text": "感激", "is_correct": false, "explanation": "配价：“感激”需要带感激的对象或内容，“对这名被告感激了”不成立。"}], "explanations": {"判刑": "正确。判刑是法院对被告作出刑罚判决，符合句意。", "表扬": "语义：法院不会表扬被告，与“被告”的身份矛盾。", "赞美": "语义：赞美用于值得称赞的人，与被告的身份不合。", "感激": "配价：“感激”需要带感激的对象或内容，“对这名被告感激了”不成立。"}, "sentence_index": 6, "correct_answer": "判刑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教练判了那个偷懒的队员一年刑。", "explanation": "这里应该用〈批评〉。判刑是法院对罪犯的刑罚，教练对偷懒的队员只能批评。"}, {"text": "收银员判了这笔账单一年刑。", "explanation": "这里应该用〈结算〉。判刑用于对人定刑，账单要结算。"}, {"text": "评委判了这场比赛一年刑。", "explanation": "这里应该用〈评判〉。判刑是对罪犯的刑罚，比赛只能评判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
