INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89717, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用问题向别人打听一件事。", "primary_collocate": null, "pronunciation": "xún wèn", "ipa": "ɕyn˧˥ wən˥˩", "syllable_count": 2, "sentences": [{"text": "她向老师询问考试的时间。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给他打电话，询问路怎么走。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人询问这件衣服的价钱。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察询问他昨天去了哪里。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走到服务台，询问电影几点开始。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈询问孩子今天在学校的情况。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想询问一下火车的时间。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他礼貌地询问那位老人要去哪儿。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们向医生询问药怎么吃。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我询问过那位店员，他说今天不开门。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "询问了", "label": "完成体"}, {"form": "询问过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "提出问题，向别人打听某件具体的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47d4b2a1-6f38-41cd-9617-8e355af68395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "询问", "is_correct": true, "explanation": "询问：向老师打听考试的时间，与“向老师”和“考试的时间”搭配，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是人或作品，不能欣赏“考试的时间”。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”指到某地实地看，“考试的时间”不能被参观。"}, {"text": "颁发", "is_correct": false, "explanation": "搭配：“颁发”指发放奖状、证书，不能颁发“时间”。"}], "explanations": {"询问": "询问：向老师打听考试的时间，与“向老师”和“考试的时间”搭配，符合句意。", "欣赏": "搭配：“欣赏”的对象是人或作品，不能欣赏“考试的时间”。", "参观": "语义：“参观”指到某地实地看，“考试的时间”不能被参观。", "颁发": "搭配：“颁发”指发放奖状、证书，不能颁发“时间”。"}, "sentence_index": 0, "correct_answer": "询问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我询问邻居借了一把剪刀。", "explanation": "这里应该用〈借〉，写作“向邻居借了一把剪刀”。〈询问〉是打听情况，不能用于借东西。"}, {"text": "我询问老人的好心。", "explanation": "这里应该用〈感谢〉。询问是打听情况，表达谢意要用“感谢”，“好心”不能被询问。"}, {"text": "大家询问她的舞姿。", "explanation": "这里应该用〈赞美〉。询问是打听情况，称赞舞姿要用“赞美”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "询问", "is_correct": true, "explanation": "询问：想打听火车的时间，与“想……一下”的语境相符。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，不能购买“时间”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复坏了的东西，“时间”不能被修理。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清除脏物，“时间”不能被打扫。"}], "explanations": {"询问": "询问：想打听火车的时间，与“想……一下”的语境相符。", "购买": "搭配：“购买”的对象是商品，不能购买“时间”。", "修理": "语义：“修理”指修复坏了的东西，“时间”不能被修理。", "打扫": "语义：“打扫”指清除脏物，“时间”不能被打扫。"}, "sentence_index": 6, "correct_answer": "询问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我询问了那本词典。", "explanation": "这里应该用〈查阅〉。〈询问〉是向人打听情况，翻查书籍要用“查阅”，不能询问“那本词典”这样的物。"}, {"text": "妈妈询问了一杯茶。", "explanation": "这里应该用〈泡〉。〈询问〉是向人打听情况，准备饮品要用“泡”，不能询问“一杯茶”这样的物。"}, {"text": "她询问了那辆自行车。", "explanation": "这里应该用〈检查〉。〈询问〉是向人打听情况，检查车辆要用“检查”，不能询问“那辆自行车”这样的物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他询问很详细。", "corrected_sentence": "他询问得很详细。", "error_description": "错误：“询问”后漏掉补语标记“得”。正确：“他询问得很详细。”“得”引出程度补语“很详细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没询问了店员。", "corrected_sentence": "我没询问店员。", "error_description": "错误：“没”否定已经发生的动作时，动词后不能再加“了”。正确：“我没询问店员。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
