INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89718, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "征求意见或打听情况。", "primary_collocate": null, "pronunciation": "xún wèn", "ipa": "ɕyn˧˥ wən˥˩", "syllable_count": 2, "sentences": [{"text": "经理询问大家对这个计划的意见。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师询问同学们的想法。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生询问病人最近的身体情况。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在做决定以前，先询问了员工。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈询问孩子对新学校的看法。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在询问大家对新办法的意见。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该先询问客人的意见。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察询问了几位邻居的情况。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长询问学生们对食堂的看法。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写信询问对方的近况。", "target_word": "询问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "询问了", "label": "完成体"}, {"form": "询问过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "征求别人的意见，或打听某方面的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47d4b2a1-6f38-41cd-9617-8e355af68395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "询问", "is_correct": true, "explanation": "询问：向他人征求意见，与“经理”“大家”和“意见”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，“意见”不能被吃。"}, {"text": "否认", "is_correct": false, "explanation": "搭配：“否认”的对象是事实或指控，不能说“否认大家对计划的意见”。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”用于具体的东西，不能把“意见”扔掉。"}], "explanations": {"询问": "询问：向他人征求意见，与“经理”“大家”和“意见”搭配，符合句意。", "吃": "语义：“吃”指进食，“意见”不能被吃。", "否认": "搭配：“否认”的对象是事实或指控，不能说“否认大家对计划的意见”。", "扔": "搭配：“扔”用于具体的东西，不能把“意见”扔掉。"}, "sentence_index": 0, "correct_answer": "询问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我询问朋友帮我搬家。", "explanation": "这里应该用〈请求〉。询问是打听情况，请朋友帮忙要用“请求”。"}, {"text": "我询问了大家一个好消息。", "explanation": "这里应该用〈告诉〉。询问是向别人征求意见或打听情况，把消息传给别人要用“告诉”。"}, {"text": "经理询问大家明天早点来。", "explanation": "这里应该用〈要求〉。询问是征求意见、打听情况，让别人做某事要用“要求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "询问", "is_correct": true, "explanation": "询问：先征求客人的意见，符合“我们应该先”的语境。"}, {"text": "命令", "is_correct": false, "explanation": "搭配：“命令”的对象是人的行为，不能命令“意见”。"}, {"text": "传染", "is_correct": false, "explanation": "语义：“传染”指疾病在人与人之间传播，“意见”不能被传染。"}, {"text": "抢夺", "is_correct": false, "explanation": "语义：“抢夺”指争抢财物，“意见”不能被抢夺。"}], "explanations": {"询问": "询问：先征求客人的意见，符合“我们应该先”的语境。", "命令": "搭配：“命令”的对象是人的行为，不能命令“意见”。", "传染": "语义：“传染”指疾病在人与人之间传播，“意见”不能被传染。", "抢夺": "语义：“抢夺”指争抢财物，“意见”不能被抢夺。"}, "sentence_index": 6, "correct_answer": "询问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我询问了那把伞。", "explanation": "这里应该用〈查看〉。〈询问〉是向人打听情况，看物品要用“查看”，不能询问“那把伞”这样的物。"}, {"text": "妈妈询问了一杯水。", "explanation": "这里应该用〈倒〉。〈询问〉是向人打听情况，给人倒水要用“倒”，不能询问“一杯水”这样的物品。"}, {"text": "她询问了那台电脑。", "explanation": "这里应该用〈检查〉。〈询问〉是向人打听情况，检查设备要用“检查”，不能询问“那台电脑”这样的物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把医生询问病情。", "corrected_sentence": "他向医生询问病情。", "error_description": "错误：“把”不能引出询问的对象，应改为“向”：“他向医生询问病情。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在询问过老师的意见。", "corrected_sentence": "他正在询问老师的意见。", "error_description": "错误：“正在”表示动作进行，“过”表示经历，二者不能同时用在“询问”上。正确：去掉“过”，写作“他正在询问老师的意见。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
