INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89719, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "判定是经过看和想，决定它是对还是错。", "primary_collocate": null, "pronunciation": "pàn dìng", "ipa": "pʰan˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "裁判判定这个球不算进。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师判定我的答案是对的。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了录像后，裁判判定他犯规了。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么判定这句话是对是错？", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看了检查结果，判定他没有生病。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛双方都不服，等着裁判判定。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们很难只看外表就判定一个人好不好。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他仔细看了看，判定这幅画是假的。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官听完双方的话，判定他没有错。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先看题，再判定学生的做法对不对。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "判定了", "label": "完成体"}, {"form": "判定过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "看过想过之后，决定是对还是错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b41ffc-15e7-408c-b241-b02b4f737514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89719, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "判定", "is_correct": true, "explanation": "判定：裁判对球是否算进作出认定，与句意相合。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是用脚击打，不能用来认定球是否有效。"}, {"text": "接", "is_correct": false, "explanation": "搭配：接是接住，不能带“这个球不算进”这样的判定小句。"}, {"text": "扔", "is_correct": false, "explanation": "配价：扔要把东西抛到某处，不能只带一个判定小句作宾语。"}], "explanations": {"判定": "判定：裁判对球是否算进作出认定，与句意相合。", "踢": "语义：踢是用脚击打，不能用来认定球是否有效。", "接": "搭配：接是接住，不能带“这个球不算进”这样的判定小句。", "扔": "配价：扔要把东西抛到某处，不能只带一个判定小句作宾语。"}, "sentence_index": 0, "correct_answer": "判定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们判定了明天去上海。", "explanation": "这里应该用〈选定〉。判定是对事情的对错、真假作出认定，不用于挑定要去的地方。"}, {"text": "我判定这道菜很好吃，想再吃一碗。", "explanation": "这里应该用〈觉得〉。判定是对事情的对错、真假作出认定，表达自己口味上的感受要用觉得。"}, {"text": "我判定我今天很累。", "explanation": "这里应该用〈感觉〉。判定是对事情的对错、真假作认定，说明自己身体或心情的状态要用感觉，判定不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "判定", "is_correct": true, "explanation": "判定：只看外表就对一个人好不好作出认定，与句意相合。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：收拾指整理或惩治，不能用来评价一个人好不好。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：讨厌表示厌恶的情绪，与“看外表就……好不好”的评价不相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理指修复，不能用来评价一个人好不好。"}], "explanations": {"判定": "判定：只看外表就对一个人好不好作出认定，与句意相合。", "收拾": "搭配：收拾指整理或惩治，不能用来评价一个人好不好。", "讨厌": "语义：讨厌表示厌恶的情绪，与“看外表就……好不好”的评价不相符。", "修理": "搭配：修理指修复，不能用来评价一个人好不好。"}, "sentence_index": 6, "correct_answer": "判定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他判定买这辆车。", "explanation": "这里应该用〈决定〉。判定是对已有事实作对错、真假的认定，不用于安排要买什么。"}, {"text": "妈妈判定了一件外套。", "explanation": "这里应该用〈挑选〉。判定不用于从多件东西中选取。"}, {"text": "我判定了他的声音。", "explanation": "这里应该用〈认出〉。判定是作出结论，不用于辨认人或东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校判定着这个学生的成绩有误。", "corrected_sentence": "学校判定这个学生的成绩有误。", "error_description": "“判定着”错误，应为“判定”。判定表示一次完成的认定，不能加“着”表示持续。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "专家判定得这份样品有毒。", "corrected_sentence": "专家判定这份样品有毒。", "error_description": "错误在于“判定”后面多加了“得”。“判定”是及物动词，后面直接接宾语小句，不能接“得”引出补语。删去“得”，即为“专家判定这份样品有毒。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
