INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过分析、判断后作出决定或认定。", "primary_collocate": null, "pronunciation": "pàn dìng", "ipa": "pʰan˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "专家分析数据后，判定这是一种新病毒。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方判定这起火灾是意外。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据这些证据，法院判定他有罪。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生判定病人需要马上做手术。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司判定这次失败的原因是计划不好。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告判定河水已经被污染了。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过检查，工人判定机器坏了。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师判定他的作业有抄袭的问题。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用仪器判定这块石头的年龄。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过讨论，委员会判定这份申请不符合要求。", "target_word": "判定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "判定了", "label": "完成体"}, {"form": "判定过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "经过分析判断后作出认定或结论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b41ffc-15e7-408c-b241-b02b4f737514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89720, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "判定", "is_correct": true, "explanation": "判定：分析之后作出认定，与句意相合。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植指栽培植物，不能用来对病毒作判断。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：购买要求商品作宾语，不能带“这是一种新病毒”这样的小句。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：打扫要求清扫的场所或物品作宾语，不能只带小句。"}], "explanations": {"判定": "判定：分析之后作出认定，与句意相合。", "种植": "语义：种植指栽培植物，不能用来对病毒作判断。", "购买": "搭配：购买要求商品作宾语，不能带“这是一种新病毒”这样的小句。", "打扫": "配价：打扫要求清扫的场所或物品作宾语，不能只带小句。"}, "sentence_index": 0, "correct_answer": "判定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他判定了去北京的日子。", "explanation": "这里应该用〈挑选〉。判定是对事情作出认定，不用于从几个选项里挑定要做的事。"}, {"text": "他判定了未来的生活。", "explanation": "这里应该用〈想象〉。判定是对具体事情作出认定或决定，宾语应是要认定的事或结论，不能用“未来的生活”这样的泛指名词作宾语；表示对未来生活的构想要用想象。"}, {"text": "她判定自己很高兴。", "explanation": "这里应该用〈感到〉。判定是对事情的对错、真假作认定，表示自己的心情要用感到，判定不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "判定", "is_correct": true, "explanation": "判定：经过检查后作出认定，与句意相合。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹去污物，不能用来指工人对机器状态作认定。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：吃指吃东西，不能带“机器坏了”这样的小句。"}, {"text": "扔", "is_correct": false, "explanation": "配价：扔要把东西抛掉，不能用来认定机器的状态。"}], "explanations": {"判定": "判定：经过检查后作出认定，与句意相合。", "擦": "语义：擦是抹去污物，不能用来指工人对机器状态作认定。", "吃": "搭配：吃指吃东西，不能带“机器坏了”这样的小句。", "扔": "配价：扔要把东西抛掉，不能用来认定机器的状态。"}, "sentence_index": 6, "correct_answer": "判定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她判定明天休息。", "explanation": "这里应该用〈决定〉。判定是对已有事实作对错、真假的认定，不用于安排要做的事。"}, {"text": "我判定了雷声。", "explanation": "这里应该用〈听见〉。判定是作出结论，不用于感知声音。"}, {"text": "她判定了一下桌子。", "explanation": "这里应该用〈检查〉。判定是对事情作出对错、真假的认定，不用于对桌子等物体进行查看或检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院判定着这份合同无效。", "corrected_sentence": "法院判定这份合同无效。", "error_description": "“判定着”错误，应为“判定”。判定表示一次完成的认定，不能加“着”表示持续。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生被判定这味药材是假的。", "corrected_sentence": "医生判定这味药材是假的。", "error_description": "“被”字句用法错误：“医生”是判定的施事，不能放在“被”后面作受事。应为“医生判定这味药材是假的。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
