INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89724, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使脱离危险或灾难；帮助。", "primary_collocate": null, "pronunciation": "jiù", "ipa": "tɕjoʊ˥˩", "syllable_count": 1, "sentences": [{"text": "这笔钱能救公司，也能救工人的饭碗。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想办法救这家快要倒闭的小店。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，再晚送来就救不了了。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们提水来救那间着火的房子。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪太大，没人能救那些牛羊。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在我最难的时候救了我。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱捐给医院，想救更多的病人。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场及时雨救了今年的庄稼。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的几句话救了这个想放弃的学生。", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生，请你一定要救救我的孩子！", "target_word": "救", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "救了", "label": "体标"}, {"form": "救过", "label": "体标"}, {"form": "救救", "label": "重叠"}], "register": "中性", "sense_fingerprint": "使人或事物摆脱危险、灾难或困境，给予帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fca3150-b75d-419f-a155-8fc7061e16d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89724, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "救", "is_correct": true, "explanation": "jiù（第四声），意思是使人或事物摆脱危险、给予帮助，即本词。"}, {"text": "久", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是时间长。"}, {"text": "酒", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是酒水。"}, {"text": "九", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是数字九。"}, {"text": "纠", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是纠正。"}], "explanations": {"救": "jiù（第四声），意思是使人或事物摆脱危险、给予帮助，即本词。", "久": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是时间长。", "酒": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是酒水。", "九": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是数字九。", "纠": "jiū（第一声）与 jiù（第四声）声调不同，意思是纠正。"}, "sentence_index": null, "correct_answer": "救"}, "level_3": {"options": [{"text": "救", "is_correct": true, "explanation": "正确：“救公司”与“救工人的饭碗”构成对照，表示用钱帮助摆脱困境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃不能用于公司，与“救工人的饭碗”的对照语义不成立。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”指拆解，钱不能拆公司，与“能……也能”的正面对照不协调。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”后通常接接收者，“送公司”不成立。"}], "explanations": {"救": "正确：“救公司”与“救工人的饭碗”构成对照，表示用钱帮助摆脱困境。", "吃": "语义：吃不能用于公司，与“救工人的饭碗”的对照语义不成立。", "拆": "搭配：“拆”指拆解，钱不能拆公司，与“能……也能”的正面对照不协调。", "送": "搭配：“送”后通常接接收者，“送公司”不成立。"}, "sentence_index": 0, "correct_answer": "救"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上救着水桶去浇花。", "explanation": "这里应该用〈提〉。救表示使脱离危险或灾难，不表示提拿东西。"}, {"text": "服务员把菜救给客人。", "explanation": "这里应该用〈端〉。救表示使脱离危险或灾难，不表示端送食物。"}, {"text": "他每天认真地救地板。", "explanation": "这里应该用〈擦〉。救表示使脱离危险或灾难，不表示擦洗地板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89724, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "救", "is_correct": true, "explanation": "jiù（第四声），意思是使人或事物摆脱危险、给予帮助，即本词。"}, {"text": "揪", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是揪住、拉拽。"}, {"text": "究", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是探究、追问。"}, {"text": "韭", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是韭菜。"}], "explanations": {"救": "jiù（第四声），意思是使人或事物摆脱危险、给予帮助，即本词。", "揪": "jiū（第一声）与 jiù（第四声）声调不同，意思是揪住、拉拽。", "究": "jiū（第一声）与 jiù（第四声）声调不同，意思是探究、追问。", "韭": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是韭菜。"}, "sentence_index": null, "correct_answer": "救"}, "level_3": {"options": [{"text": "救", "is_correct": true, "explanation": "正确：“想救更多的病人”表示希望帮助更多病人摆脱病痛，与捐钱的善意语境一致。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃病人与捐钱给医院的善意语境完全矛盾。"}, {"text": "打", "is_correct": false, "explanation": "语义：打病人与捐款的善意语境矛盾，不能表示帮助。"}, {"text": "骗", "is_correct": false, "explanation": "搭配：“骗”通常接受骗对象，与“想……更多的病人”的善意目的不协调。"}], "explanations": {"救": "正确：“想救更多的病人”表示希望帮助更多病人摆脱病痛，与捐钱的善意语境一致。", "吃": "语义：吃病人与捐钱给医院的善意语境完全矛盾。", "打": "语义：打病人与捐款的善意语境矛盾，不能表示帮助。", "骗": "搭配：“骗”通常接受骗对象，与“想……更多的病人”的善意目的不协调。"}, "sentence_index": 6, "correct_answer": "救"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店员救了我一杯咖啡，我很感谢他。", "explanation": "这里应该用〈给〉。救表示使脱离危险或灾难，不表示给予。"}, {"text": "他把屋子救得很整齐。", "explanation": "这里应该用〈收拾〉。救表示使脱离危险或灾难，不表示整理屋子。"}, {"text": "他一口气救完了一碗饭。", "explanation": "这里应该用〈吃〉。救表示使脱离危险或灾难，不表示吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生救活得这个孩子。", "corrected_sentence": "医生救得活这个孩子。", "error_description": "补语位置错误：“救活”是结果补语，可能式应说“救得活”，“得”插在“救”和“活”之间，不能说“救活得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位护士救了活一只小鸟。", "corrected_sentence": "这位护士救活了一只小鸟。", "error_description": "补语位置错误：“救活”是结果补语，“了”应放在“活”之后，说“救活了”，不能说“救了活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
