INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89727, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到商店去买东西。", "primary_collocate": null, "pronunciation": "gòu wù", "ipa": "koʊ̯˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "星期六我和妈妈去超市购物。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在商店里购物。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去市中心购物吧。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她陪朋友购物，走了一下午。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年前，大家都去商店购物。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢和朋友一起去商场购物。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在超市购物，买了很多水果。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天人太多，我不想去购物了。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带着孩子去大商场购物。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们昨天去商店购物，花了两百块。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "购物车", "label": "复合"}, {"form": "购物中心", "label": "复合"}, {"form": "购了物", "label": "离合"}], "register": "中性", "sense_fingerprint": "亲自去商店买东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30511e17-00b3-46ac-a6ac-77252451a420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89727, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "购物", "is_correct": true, "explanation": "正确。购物指到商店买东西，是听到的词。"}, {"text": "谷物", "is_correct": false, "explanation": "声调不同：谷（第三声）与购（第四声）不同，谷物指粮食作物。"}, {"text": "购屋", "is_correct": false, "explanation": "第二音节屋（第一声）与物（第四声）声调不同，购屋指买房子。"}, {"text": "狗屋", "is_correct": false, "explanation": "声调不同：狗（第三声）与购（第四声）不同，屋（第一声）与物（第四声）也不同。狗屋指给狗住的小房子。"}], "explanations": {"购物": "正确。购物指到商店买东西，是听到的词。", "谷物": "声调不同：谷（第三声）与购（第四声）不同，谷物指粮食作物。", "购屋": "第二音节屋（第一声）与物（第四声）声调不同，购屋指买房子。", "狗屋": "声调不同：狗（第三声）与购（第四声）不同，屋（第一声）与物（第四声）也不同。狗屋指给狗住的小房子。"}, "sentence_index": null, "correct_answer": "购物"}, "level_3": {"options": [{"text": "购物", "is_correct": true, "explanation": "正确。购物指在超市买东西，与“去超市”一致。"}, {"text": "看病", "is_correct": false, "explanation": "语义：看病要去医院或诊所，不能去超市。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：洗澡要在浴室进行，不能和“去超市”搭配。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：跑步是运动，不是去超市的活动。"}], "explanations": {"购物": "正确。购物指在超市买东西，与“去超市”一致。", "看病": "语义：看病要去医院或诊所，不能去超市。", "洗澡": "搭配：洗澡要在浴室进行，不能和“去超市”搭配。", "跑步": "语义：跑步是运动，不是去超市的活动。"}, "sentence_index": 0, "correct_answer": "购物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房购物，做了一顿饭。", "explanation": "这里应该用〈烹饪〉。在厨房做饭是烹饪，不是买东西，“购物”只指买商品，不能用来表示烹饪。"}, {"text": "他在图书馆购物，借了三本书。", "explanation": "这里应该用〈借阅〉。图书馆提供借阅服务，不卖东西，“购物”只指买商品，不能用来表示借书。"}, {"text": "我在河边购物，钓到了一条鱼。", "explanation": "这里应该用〈垂钓〉。钓鱼是垂钓，不是买东西，“购物”只指买商品，不能用来表示捕鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89727, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "购物", "is_correct": true, "explanation": "正确。在超市购物指在超市买东西，与“买了很多水果”一致。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳要在水里进行，不能在超市进行。"}, {"text": "理发", "is_correct": false, "explanation": "搭配：理发要去理发店，超市里不能理发。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是休息，与“买了很多水果”的行为相矛盾。"}], "explanations": {"购物": "正确。在超市购物指在超市买东西，与“买了很多水果”一致。", "游泳": "语义：游泳要在水里进行，不能在超市进行。", "理发": "搭配：理发要去理发店，超市里不能理发。", "睡觉": "语义：睡觉是休息，与“买了很多水果”的行为相矛盾。"}, "sentence_index": 6, "correct_answer": "购物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天去博物馆购物，听了一下午的讲解。", "explanation": "这里应该用〈参观〉。听讲解、看展品是参观，不是买东西，“购物”只指买商品，不能用于参观博物馆。"}, {"text": "我们昨天去游乐园购物，坐了一下午的过山车。", "explanation": "这里应该用〈玩〉。坐过山车是在游乐园玩，不是买东西，“购物”不能表示玩耍。"}, {"text": "我们昨天去山上购物，欣赏了一下午的日落。", "explanation": "这里应该用〈游览〉。欣赏风景是游览，山上的日落不是商品，“购物”不能表示游览。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈带我去商店购物东西。", "corrected_sentence": "妈妈带我去商店购物。", "error_description": "宾语错误：“购物”是离合词，不能直接带“东西”。正确形式为“妈妈带我去商店购物。”如要说买什么，应说“买东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在超市购物着。", "corrected_sentence": "他正在超市购物。", "error_description": "体标冗余：“正在”已表示动作进行，句末再加“着”与之重复且不自然；去掉“着”即可，正确形式为“他正在超市购物。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
