INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89728, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "购买商品。", "primary_collocate": null, "pronunciation": "gòu wù", "ipa": "koʊ̯˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢在网上购物。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们通过电视购物，买了一台新吸尘器。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月购物都花很多钱。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上购物很方便。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在手机上购物，东西三天就到了。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "购物以前，先看看价格。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多人喜欢网上购物。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这家网站购物时很满意。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不常在国外购物。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上购物时要小心骗子。", "target_word": "购物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "购物车", "label": "复合"}, {"form": "购物中心", "label": "复合"}, {"form": "购了物", "label": "离合"}], "register": "中性", "sense_fingerprint": "购买商品，不限于线下商店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30511e17-00b3-46ac-a6ac-77252451a420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "购物", "is_correct": true, "explanation": "正确。购物指买商品，是听到的词。"}, {"text": "谷物", "is_correct": false, "explanation": "声调不同：谷（第三声）与购（第四声）不同，谷物指粮食作物。"}, {"text": "购屋", "is_correct": false, "explanation": "第二音节屋（第一声）与物（第四声）声调不同，购屋指买房子。"}, {"text": "狗屋", "is_correct": false, "explanation": "声调不同：狗（第三声）与购（第四声）不同，屋（第一声）与物（第四声）也不同。狗屋指给狗住的小房子。"}], "explanations": {"购物": "正确。购物指买商品，是听到的词。", "谷物": "声调不同：谷（第三声）与购（第四声）不同，谷物指粮食作物。", "购屋": "第二音节屋（第一声）与物（第四声）声调不同，购屋指买房子。", "狗屋": "声调不同：狗（第三声）与购（第四声）不同，屋（第一声）与物（第四声）也不同。狗屋指给狗住的小房子。"}, "sentence_index": null, "correct_answer": "购物"}, "level_3": {"options": [{"text": "购物", "is_correct": true, "explanation": "正确。在网上购物指通过网络买东西，与“在网上”一致。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步要在户外走路，不能在网上进行。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是休息，不能在网上进行。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：游泳要在水里进行，不能和“在网上”搭配。"}], "explanations": {"购物": "正确。在网上购物指通过网络买东西，与“在网上”一致。", "散步": "语义：散步要在户外走路，不能在网上进行。", "睡觉": "语义：睡觉是休息，不能在网上进行。", "游泳": "搭配：游泳要在水里进行，不能和“在网上”搭配。"}, "sentence_index": 0, "correct_answer": "购物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去医院购物，等了三个小时。", "explanation": "这里应该用〈看病〉。去医院是为了看病，不是买东西，“购物”只指买商品，不能用来表示就医。"}, {"text": "我去银行购物，排了半个小时的队。", "explanation": "这里应该用〈办理〉。去银行是办理存取款等业务，不是买东西，“购物”只指买商品，不能用来表示办理金融业务。"}, {"text": "他在海边购物，抓到了一条鱼。", "explanation": "这里应该用〈捕捞〉。抓鱼是捕捞，不是买东西，“购物”只指买商品，不能用来表示捕捞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "购物", "is_correct": true, "explanation": "正确。网上购物符合“现在很多人喜欢”和“网上”。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：跑步是运动，不能在网上进行。"}, {"text": "钓鱼", "is_correct": false, "explanation": "语义：钓鱼要在水边进行，网上不能钓鱼。"}, {"text": "理发", "is_correct": false, "explanation": "搭配：理发要到理发店进行，不能说“网上理发”。"}], "explanations": {"购物": "正确。网上购物符合“现在很多人喜欢”和“网上”。", "跑步": "语义：跑步是运动，不能在网上进行。", "钓鱼": "语义：钓鱼要在水边进行，网上不能钓鱼。", "理发": "搭配：理发要到理发店进行，不能说“网上理发”。"}, "sentence_index": 6, "correct_answer": "购物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去工厂购物，看了一下午的生产线。", "explanation": "这里应该用〈参观〉。看生产线是参观，不是买东西；“购物”只指购买商品，不能表示参观。"}, {"text": "他去公园购物了一下午。", "explanation": "这里应该用〈逛〉。公园里没有可买的商品，在公园闲逛要用〈逛〉，不能说“购物”。"}, {"text": "我们去山上购物，拍了很多风景照。", "explanation": "这里应该用〈游览〉。山上不卖东西，欣赏风景是游览，不能说“购物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在超市购物东西。", "corrected_sentence": "我昨天在超市购物。", "error_description": "错误：“购物”是离合词，后面不能直接带“东西”作宾语。正确形式为“我昨天在超市购物。”如要带宾语，应说“买东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在网上购物东西。", "corrected_sentence": "她在网上购物。", "error_description": "错误：“购物”是离合词，后面不能直接带“东西”作宾语。正确形式为“她在网上购物。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89729, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最旧", "is_correct": true, "explanation": "正确：“最旧”与“最新”相对，指最陈旧的。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌好看，与“最新”没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”指价格低，与“最新”没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”形容物体坚固，与“最新”没有反义关系。"}], "correct_answer": "最旧", "explanations": {"最旧": "正确：“最旧”与“最新”相对，指最陈旧的。", "漂亮": "“漂亮”形容外貌好看，与“最新”没有反义关系。", "便宜": "“便宜”指价格低，与“最新”没有反义关系。", "结实": "“结实”形容物体坚固，与“最新”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89729, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旧", "is_correct": true, "explanation": "正确：“旧”与“新”相对，“最新”的反义是陈旧的“旧”。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”形容体型或建筑高，与“最新”没有反义关系。"}, {"text": "灵活", "is_correct": false, "explanation": "“灵活”形容动作敏捷或处理得当，与“最新”没有反义关系。"}, {"text": "轻便", "is_correct": false, "explanation": "“轻便”形容东西分量轻、便于携带，与“最新”没有反义关系。"}], "correct_answer": "旧", "explanations": {"旧": "正确：“旧”与“新”相对，“最新”的反义是陈旧的“旧”。", "高大": "“高大”形容体型或建筑高，与“最新”没有反义关系。", "灵活": "“灵活”形容动作敏捷或处理得当，与“最新”没有反义关系。", "轻便": "“轻便”形容东西分量轻、便于携带，与“最新”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89729, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最新是比所有的都新。", "primary_collocate": null, "pronunciation": "zuì xīn", "ipa": "tswei˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这是店里最新的手机。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的电脑是最新的,你的是去年买的。", "target_word": "最新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是今年最新的衣服。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了一辆最新的车。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店里最新的鞋子在那边。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我们学校最新的教学楼。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书是他最新的一本,上个月才出。", "target_word": "最新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用的是最新的手机吗?", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是公司最新的电脑,别的都比它旧。", "target_word": "最新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最新的那台机器,放在最前面。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "最新：同类东西里比所有的都新", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cbc0dd4-f7ee-4093-b4cd-555297c3b1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89729, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "最新", "is_correct": true, "explanation": "正确：最新，zuì xīn，指同类东西中比所有的都新。"}, {"text": "最亲", "is_correct": false, "explanation": "qīn 与 xīn 声母不同，意思是关系最密切。"}, {"text": "罪行", "is_correct": false, "explanation": "xíng 与 xīn 的韵母和声调都不同，意思是犯罪的行为。"}, {"text": "最凶", "is_correct": false, "explanation": "xiōng 与 xīn 韵母不同，意思是最凶狠。"}], "explanations": {"最新": "正确：最新，zuì xīn，指同类东西中比所有的都新。", "最亲": "qīn 与 xīn 声母不同，意思是关系最密切。", "罪行": "xíng 与 xīn 的韵母和声调都不同，意思是犯罪的行为。", "最凶": "xiōng 与 xīn 韵母不同，意思是最凶狠。"}, "sentence_index": null, "correct_answer": "最新"}, "level_3": {"options": [{"text": "最新", "is_correct": true, "explanation": "正确：“最新”指同类手机中刚推出的款式，与“店里的手机”相符。"}, {"text": "最慈祥", "is_correct": false, "explanation": "语义：“慈祥”形容长辈的神情，手机没有这种特征。"}, {"text": "最年幼", "is_correct": false, "explanation": "搭配：“年幼”只用于人或动物，不说手机。"}, {"text": "最害羞", "is_correct": false, "explanation": "语义：“害羞”形容人的心理状态，手机不会害羞。"}], "explanations": {"最新": "正确：“最新”指同类手机中刚推出的款式，与“店里的手机”相符。", "最慈祥": "语义：“慈祥”形容长辈的神情，手机没有这种特征。", "最年幼": "搭配：“年幼”只用于人或动物，不说手机。", "最害羞": "语义：“害羞”形容人的心理状态，手机不会害羞。"}, "sentence_index": 0, "correct_answer": "最新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师的脾气最新。", "explanation": "“最新”指事物或消息刚出现、比同类都新，不用来描述脾气；这里应说“脾气好”之类的性格描述。"}, {"text": "他的年龄在班里最新。", "explanation": "“最新”不用于年龄，表示年龄大小应说“大”或“小”。"}, {"text": "这条鱼的味道最新，很鲜美。", "explanation": "这里应该用〈新鲜〉。“最新”指事物或消息刚出现、比同类都新，不用来形容食物的口感或状态；形容食物的新鲜程度要用“新鲜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89729, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "最新", "is_correct": true, "explanation": "正确：最新，zuì xīn，指同类东西中比所有的都新。"}, {"text": "罪人", "is_correct": false, "explanation": "rén 与 xīn 声母不同、声调也不同，意思是犯罪的人。"}, {"text": "最想", "is_correct": false, "explanation": "xiǎng 与 xīn 韵母和声调不同，意思是最希望。"}, {"text": "最险", "is_correct": false, "explanation": "xiǎn 与 xīn 韵母和声调都不同，意思是最危险。"}], "explanations": {"最新": "正确：最新，zuì xīn，指同类东西中比所有的都新。", "罪人": "rén 与 xīn 声母不同、声调也不同，意思是犯罪的人。", "最想": "xiǎng 与 xīn 韵母和声调不同，意思是最希望。", "最险": "xiǎn 与 xīn 韵母和声调都不同，意思是最危险。"}, "sentence_index": null, "correct_answer": "最新"}, "level_3": {"options": [{"text": "最新", "is_correct": true, "explanation": "正确：“最新”指书是他刚出版的一本，与“上个月才出”相符。"}, {"text": "最古老", "is_correct": false, "explanation": "语义：“古老”与“上个月才出”矛盾。"}, {"text": "最年迈", "is_correct": false, "explanation": "搭配：“年迈”只用于人，不说书。"}, {"text": "最寒冷", "is_correct": false, "explanation": "语义：“寒冷”说天气，不能形容书。"}], "explanations": {"最新": "正确：“最新”指书是他刚出版的一本，与“上个月才出”相符。", "最古老": "语义：“古老”与“上个月才出”矛盾。", "最年迈": "搭配：“年迈”只用于人，不说书。", "最寒冷": "语义：“寒冷”说天气，不能形容书。"}, "sentence_index": 6, "correct_answer": "最新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小孩的身高最新，比我还矮。", "explanation": "这里不能用〈最新〉形容身材，形容人的身材应说〈高大〉或〈瘦小〉之类。“最新”只指时间上刚出现、比同类都新。"}, {"text": "他的性格最新，很开朗。", "explanation": "这里应该用〈温和〉。“最新”指时间上刚出现、比同类都新，不用来形容性格；形容性格应说〈温和〉〈内向〉之类。"}, {"text": "这把椅子的颜色最新，很好看。", "explanation": "“最新”不用于颜色，颜色应说“鲜艳”“暗淡”等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一台很最新的相机。", "corrected_sentence": "我买了一台最新的相机。", "error_description": "程度词错误：“最”已经表示最高程度，“最新”前面不能再加“很”。正确说法是“一台最新的相机”，不说“一台很最新的相机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书是最新的，比那本最新。", "corrected_sentence": "这本书是最新的，比那本还新。", "error_description": "程度词错误：“最新”是最高级，不能用在“比”字句中。应说“比那本还新”，不说“比那本最新”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
