INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89730, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最近出现的;比其他都新的。", "primary_collocate": null, "pronunciation": "zuì xīn", "ipa": "tswei˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "你看了最新的新闻吗?", "target_word": "最新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是今天最新的消息。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我最新的天气情况。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网站上有最新的电影信息。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "最新一期的杂志已经到了。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想知道这个城市最新的变化。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校发了最新的考试通知。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机会自动更新最新的软件。", "target_word": "最新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天上网看最新的足球比赛结果。", "target_word": "最新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把最新的价格发给我。", "target_word": "最新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "最新：消息、信息等最近出现的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cbc0dd4-f7ee-4093-b4cd-555297c3b1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89730, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "最新", "is_correct": true, "explanation": "正确：最新，zuì xīn，指消息、信息等最近出现的。"}, {"text": "最亲", "is_correct": false, "explanation": "qīn 与 xīn 声母不同，意思是关系最密切。"}, {"text": "最凶", "is_correct": false, "explanation": "xiōng 与 xīn 韵母不同，意思是最凶狠。"}, {"text": "罪行", "is_correct": false, "explanation": "xíng 与 xīn 的韵母和声调都不同，意思是犯罪的行为。"}], "explanations": {"最新": "正确：最新，zuì xīn，指消息、信息等最近出现的。", "最亲": "qīn 与 xīn 声母不同，意思是关系最密切。", "最凶": "xiōng 与 xīn 韵母不同，意思是最凶狠。", "罪行": "xíng 与 xīn 的韵母和声调都不同，意思是犯罪的行为。"}, "sentence_index": null, "correct_answer": "最新"}, "level_3": {"options": [{"text": "最新", "is_correct": true, "explanation": "正确：“最新”指刚出现的新闻，与“你看了……的新闻”相符。"}, {"text": "最害羞", "is_correct": false, "explanation": "语义：“害羞”形容人的心理，新闻不会害羞。"}, {"text": "最寒冷", "is_correct": false, "explanation": "语义：“寒冷”说天气，不能形容新闻。"}, {"text": "最年迈", "is_correct": false, "explanation": "搭配：“年迈”只用于人，不说新闻。"}], "explanations": {"最新": "正确：“最新”指刚出现的新闻，与“你看了……的新闻”相符。", "最害羞": "语义：“害羞”形容人的心理，新闻不会害羞。", "最寒冷": "语义：“寒冷”说天气，不能形容新闻。", "最年迈": "搭配：“年迈”只用于人，不说新闻。"}, "sentence_index": 0, "correct_answer": "最新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫的体重最新，有点胖。", "explanation": "“最新”指消息或事物刚出现，不用来形容体重；形容体重的轻重要用〈轻〉之类的词，不用〈最新〉。"}, {"text": "我的爷爷最新，很健康。", "explanation": "“最新”指消息或事物刚出现，不用来形容人的年龄；形容人的年龄要用〈年轻〉或〈年老〉。"}, {"text": "这座楼的高度最新，很壮观。", "explanation": "“最新”指消息或事物刚出现，不用来形容高度；这里应改用〈高〉之类的形容词，不用〈最新〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89730, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "最新", "is_correct": true, "explanation": "正确：最新，zuì xīn，指消息、信息等最近出现的。"}, {"text": "最亲", "is_correct": false, "explanation": "qīn 与 xīn 声母不同，意思是关系最密切。"}, {"text": "最想", "is_correct": false, "explanation": "xiǎng 与 xīn 韵母和声调不同，意思是最希望。"}, {"text": "罪人", "is_correct": false, "explanation": "rén 与 xīn 声母不同、声调也不同，意思是犯罪的人。"}], "explanations": {"最新": "正确：最新，zuì xīn，指消息、信息等最近出现的。", "最亲": "qīn 与 xīn 声母不同，意思是关系最密切。", "最想": "xiǎng 与 xīn 韵母和声调不同，意思是最希望。", "罪人": "rén 与 xīn 声母不同、声调也不同，意思是犯罪的人。"}, "sentence_index": null, "correct_answer": "最新"}, "level_3": {"options": [{"text": "最新", "is_correct": true, "explanation": "正确：“最新”指学校刚发出的考试通知，与语境相符。"}, {"text": "最慈祥", "is_correct": false, "explanation": "语义：“慈祥”形容长辈的神情，通知不会慈祥。"}, {"text": "最苗条", "is_correct": false, "explanation": "体貌：“苗条”形容人的身材，不能形容通知。"}, {"text": "最年幼", "is_correct": false, "explanation": "搭配：“年幼”只用于人或动物，不说通知。"}], "explanations": {"最新": "正确：“最新”指学校刚发出的考试通知，与语境相符。", "最慈祥": "语义：“慈祥”形容长辈的神情，通知不会慈祥。", "最苗条": "体貌：“苗条”形容人的身材，不能形容通知。", "最年幼": "搭配：“年幼”只用于人或动物，不说通知。"}, "sentence_index": 6, "correct_answer": "最新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈的心情最新，有点高兴。", "explanation": "“最新”不用于心情，心情应说“好”或“不好”之类的描述。"}, {"text": "这条河的深度最新。", "explanation": "“最新”指消息或事物刚出现，不用来说深度；形容河水的深浅应说〈浅〉之类的词，不用〈最新〉。"}, {"text": "这张桌子的重量最新。", "explanation": "“最新”指消息或事物刚出现，不用来形容重量；形容重量的轻重应说〈轻〉之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天读了很最新的报道。", "corrected_sentence": "我昨天读了最新的报道。", "error_description": "程度词错误：“最”已经表示最高程度，“最新”前面不能再加“很”。正确说法是“最新的报道”，不说“很最新的报道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条新闻是最新的，比那条最新。", "corrected_sentence": "这条新闻是最新的，比那条还新。", "error_description": "程度词错误：“最新”是最高级，不能用在“比”字句中。应说“比那条还新”，不说“比那条最新”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89731, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "完好", "is_correct": true, "explanation": "反义：“完好”指没有损坏，与“受损”正相反，可以用来描述这辆车前面的状态。"}, {"text": "坚固", "is_correct": false, "explanation": "无关：“坚固”形容东西结实，与“受损”不构成反义关系。"}, {"text": "美观", "is_correct": false, "explanation": "无关：“美观”说外形好看，与东西是否被弄坏无关。"}, {"text": "灵活", "is_correct": false, "explanation": "无关：“灵活”说动作或反应敏捷，不是“受损”的反义词。"}], "correct_answer": "完好", "explanations": {"完好": "反义：“完好”指没有损坏，与“受损”正相反，可以用来描述这辆车前面的状态。", "坚固": "无关：“坚固”形容东西结实，与“受损”不构成反义关系。", "美观": "无关：“美观”说外形好看，与东西是否被弄坏无关。", "灵活": "无关：“灵活”说动作或反应敏捷，不是“受损”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89731, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "完好", "is_correct": true, "explanation": "反义：“完好”指没有损坏，与“受损的自行车”正相反。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”说光线或颜色亮，与东西是否损坏无关。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”说外貌好看，不是“受损”的反义词。"}, {"text": "响亮", "is_correct": false, "explanation": "无关：“响亮”说声音大而清楚，与损坏的状态无关。"}], "correct_answer": "完好", "explanations": {"完好": "反义：“完好”指没有损坏，与“受损的自行车”正相反。", "明亮": "无关：“明亮”说光线或颜色亮，与东西是否损坏无关。", "漂亮": "无关：“漂亮”说外貌好看，不是“受损”的反义词。", "响亮": "无关：“响亮”说声音大而清楚，与损坏的状态无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89731, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受损是东西被弄坏了，有了坏的地方。", "primary_collocate": null, "pronunciation": "shòu sǔn", "ipa": "ʂou˥˩ suən˨˩˦", "syllable_count": 2, "sentences": [{"text": "暴雨过后，这条路受损很严重。", "target_word": "受损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机掉在地上，屏幕受损了。", "target_word": "受损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚的大风让屋顶受损了。", "target_word": "受损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车前面受损，不能开了。", "target_word": "受损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受损的桥还没有修好。", "target_word": "受损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书放在水里，封面受损了。", "target_word": "受损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，很多房子受损了。", "target_word": "受损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑受损，打不开了。", "target_word": "受损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪让电线受损，村里停电了。", "target_word": "受损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把受损的自行车送去修了。", "target_word": "受损", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受损了", "label": "体标"}, {"form": "受损过", "label": "体标"}], "register": "中性", "sense_fingerprint": "东西或设施被弄坏，出现损坏的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e0884d8-666b-47f2-ad3a-c0e5471c2632') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89731, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受损", "is_correct": true, "explanation": "正确。“受损”指东西被弄坏、有了坏的地方，符合“暴雨过后这条路很严重”的语境。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量或规模，不能说“这条路增加很严重”。"}, {"text": "提高", "is_correct": false, "explanation": "语义：“提高”指水平或质量上升，与暴雨后道路的损坏情况不符。"}, {"text": "感动", "is_correct": false, "explanation": "语义：“感动”是人的心理反应，道路不会被感动，句子不通。"}], "explanations": {"受损": "正确。“受损”指东西被弄坏、有了坏的地方，符合“暴雨过后这条路很严重”的语境。", "增加": "搭配：“增加”说数量或规模，不能说“这条路增加很严重”。", "提高": "语义：“提高”指水平或质量上升，与暴雨后道路的损坏情况不符。", "感动": "语义：“感动”是人的心理反应，道路不会被感动，句子不通。"}, "sentence_index": 0, "correct_answer": "受损"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天认真练习，受损很多，进步特别快。", "explanation": "这里应该用〈受益〉。受损指东西被弄坏或受到损害，进步、得到好处要用〈受益〉。"}, {"text": "这只小猫被鞭炮吓到，受损了，躲进了床底下。", "explanation": "这里应该用〈受惊〉。受损指东西被弄坏，被吓到要用〈受惊〉。"}, {"text": "他在山里迷路，受损了一整夜，又冷又饿。", "explanation": "这里应该用〈受罪〉。受损指受到损害，吃苦、遭罪要用〈受罪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89731, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受损", "is_correct": true, "explanation": "正确。“受损”指房屋被震坏，符合“地震后很多房子”的语境。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指人或动物下落不明，房子不会失踪，句子不通。"}, {"text": "恋爱", "is_correct": false, "explanation": "语义：“恋爱”指人与人之间的感情关系，房子不能恋爱。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”说人或动物的身体变胖，不能用于房子。"}], "explanations": {"受损": "正确。“受损”指房屋被震坏，符合“地震后很多房子”的语境。", "失踪": "语义：“失踪”指人或动物下落不明，房子不会失踪，句子不通。", "恋爱": "语义：“恋爱”指人与人之间的感情关系，房子不能恋爱。", "发胖": "体貌：“发胖”说人或动物的身体变胖，不能用于房子。"}, "sentence_index": 6, "correct_answer": "受损"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他明明没有偷东西，却被抓进派出所，真是受损了。", "explanation": "这里应该用〈受冤枉〉。受损指东西被弄坏，蒙受冤枉要用〈受冤枉〉。"}, {"text": "他上课捣乱，结果受损了，被老师罚站了一节课。", "explanation": "这里应该用〈受罚〉。受损指受到损害，挨罚、受处分要用〈受罚〉。"}, {"text": "这款新手机在学生里很受损，大家都不爱买。", "explanation": "这里应该用〈受欢迎〉。受损指受到损害，说被人喜爱要用〈受欢迎〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只杯子摔在地上，杯口被受损了。", "corrected_sentence": "那只杯子摔在地上，杯口受损了。", "error_description": "错误形式：“杯口被受损了”。正确形式：“杯口受损了”。“受损”本身已经表示东西被弄坏，不能再加“被”，去掉“被”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那台冰箱受潮，把里面的电路受损了。", "corrected_sentence": "那台冰箱受潮，里面的电路受损了。", "error_description": "错误形式：“把里面的电路受损了”。正确形式：“里面的电路受损了”。“受损”是不及物动词，不能用于“把”字句，去掉“把”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89733, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走来", "is_correct": true, "explanation": "正确：“走来”指步行到说话人所在处，与“走去”方向相反。"}, {"text": "坐", "is_correct": false, "explanation": "“坐”指臀部落在座位上，与步行方向无关，不是“走去”的反义词。"}, {"text": "躺", "is_correct": false, "explanation": "“躺”指身体平卧，不是“走去”的反义词。"}, {"text": "飞", "is_correct": false, "explanation": "“飞”指在空中飞行，与“走去”的动作不相对，不是反义词。"}], "correct_answer": "走来", "explanations": {"走来": "正确：“走来”指步行到说话人所在处，与“走去”方向相反。", "坐": "“坐”指臀部落在座位上，与步行方向无关，不是“走去”的反义词。", "躺": "“躺”指身体平卧，不是“走去”的反义词。", "飞": "“飞”指在空中飞行，与“走去”的动作不相对，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89733, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走来", "is_correct": true, "explanation": "正确：“走来”指步行到说话人所在处，与“走去”方向相反。"}, {"text": "游", "is_correct": false, "explanation": "“游”指在水中移动，是另一种移动方式，不是“走去”的反义词。"}, {"text": "跳", "is_correct": false, "explanation": "“跳”指腿部发力跃起，不是“走去”的反义词。"}, {"text": "驶", "is_correct": false, "explanation": "“驶”指车船等行进，不是“走去”的反义词。"}], "correct_answer": "走来", "explanations": {"走来": "正确：“走来”指步行到说话人所在处，与“走去”方向相反。", "游": "“游”指在水中移动，是另一种移动方式，不是“走去”的反义词。", "跳": "“跳”指腿部发力跃起，不是“走去”的反义词。", "驶": "“驶”指车船等行进，不是“走去”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89733, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用脚一步一步向那里走。", "primary_collocate": null, "pronunciation": "zǒu qù", "ipa": "tsou˨˩˦ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "他慢慢向门口走去。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一步一步向妈妈走去。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人拿着花，向小桥走去。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们向山上走去。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一步一步向舞台走去。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他低着头，向教室走去。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩向老师走去，手里拿着书。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家慢慢向湖边走去。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向那座房子走去，敲了敲门。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗一步一步向小主人走去。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走去了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "迈着脚步朝某个方向或目标走过去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47d4b2a1-6f38-41cd-9617-8e355af68395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89733, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走去", "is_correct": true, "explanation": "正确：“走去”指迈步向某处前进，他慢慢向门口走去符合语义。"}, {"text": "冲", "is_correct": false, "explanation": "语义：“冲”指猛烈向前，与“慢慢”矛盾。"}, {"text": "奔", "is_correct": false, "explanation": "语义：“奔”指快速跑，与“慢慢”矛盾。"}, {"text": "驶", "is_correct": false, "explanation": "搭配：“驶”用于车船等交通工具，人不能驶向门口。"}], "explanations": {"走去": "正确：“走去”指迈步向某处前进，他慢慢向门口走去符合语义。", "冲": "语义：“冲”指猛烈向前，与“慢慢”矛盾。", "奔": "语义：“奔”指快速跑，与“慢慢”矛盾。", "驶": "搭配：“驶”用于车船等交通工具，人不能驶向门口。"}, "sentence_index": 0, "correct_answer": "走去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水向低处走去。", "explanation": "这里应该用〈流〉。水靠重力流动，不用脚步行走，应说“水向低处流去”。"}, {"text": "鱼向水底走去。", "explanation": "这里应该用〈游〉。鱼靠鳍在水中游动，不用脚走，应说“游向水底”。"}, {"text": "飞机向北边走去。", "explanation": "这里应该用〈飞〉。飞机在空中飞行，不用脚步行走，应说“飞机向北飞去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89733, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走去", "is_correct": true, "explanation": "正确：“走去”指步行向老师处前进，符合“手里拿着书”的语境。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指凭翅膀或机械在空中移动，小女孩不会飞。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中移动，小女孩在地面上，不能游向老师。"}, {"text": "漂", "is_correct": false, "explanation": "搭配：“漂”用于浮在水面或空中的物体，人不能漂向老师。"}], "explanations": {"走去": "正确：“走去”指步行向老师处前进，符合“手里拿着书”的语境。", "飞": "语义：“飞”指凭翅膀或机械在空中移动，小女孩不会飞。", "游": "语义：“游”指在水中移动，小女孩在地面上，不能游向老师。", "漂": "搭配：“漂”用于浮在水面或空中的物体，人不能漂向老师。"}, "sentence_index": 6, "correct_answer": "走去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车向城里走去。", "explanation": "这里应该用〈开〉。汽车靠发动机行驶，应说“开向城里”，不能用“走去”。"}, {"text": "小船向岸边走去。", "explanation": "这里应该用〈划〉。小船靠桨在水面上前进，不用脚步行走，应说“小船向岸边划去”。"}, {"text": "火车向北走去。", "explanation": "这里应该用〈驶〉。火车在铁轨上行驶，应说“驶向北方”，不能用“走去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把厨房走去。", "corrected_sentence": "妈妈向厨房走去。", "error_description": "错误：“把”不能引出“走去”的处所，应改为“向”：“妈妈向厨房走去。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师一步一步讲台走去。", "corrected_sentence": "老师一步一步向讲台走去。", "error_description": "错误形式：“讲台走去”，漏掉了介词“向”；正确形式：“向讲台走去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89734, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走来", "is_correct": true, "explanation": "正确：“走来”指步行到说话人所在处，与“走去”方向相反。"}, {"text": "骑", "is_correct": false, "explanation": "“骑”指跨坐在车或动物上前进，是乘行方式，不是“走去”的反义词。"}, {"text": "飞", "is_correct": false, "explanation": "“飞”指在空中飞行，不是“走去”的反义词。"}, {"text": "躺", "is_correct": false, "explanation": "“躺”指身体平卧，不是“走去”的反义词。"}], "correct_answer": "走来", "explanations": {"走来": "正确：“走来”指步行到说话人所在处，与“走去”方向相反。", "骑": "“骑”指跨坐在车或动物上前进，是乘行方式，不是“走去”的反义词。", "飞": "“飞”指在空中飞行，不是“走去”的反义词。", "躺": "“躺”指身体平卧，不是“走去”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89734, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走来", "is_correct": true, "explanation": "正确：“走来”指步行到说话人所在处，与“走去”方向相反。"}, {"text": "游", "is_correct": false, "explanation": "“游”指在水中移动，不是“走去”的反义词。"}, {"text": "驶", "is_correct": false, "explanation": "“驶”指车船行进，不是“走去”的反义词。"}, {"text": "跳", "is_correct": false, "explanation": "“跳”指腿部发力跃起，不是“走去”的反义词。"}], "correct_answer": "走来", "explanations": {"走来": "正确：“走来”指步行到说话人所在处，与“走去”方向相反。", "游": "“游”指在水中移动，不是“走去”的反义词。", "驶": "“驶”指车船行进，不是“走去”的反义词。", "跳": "“跳”指腿部发力跃起，不是“走去”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89734, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "步行前往某处。", "primary_collocate": null, "pronunciation": "zǒu qù", "ipa": "tsou˨˩˦ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "我们走去车站吧，不太远。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天走去学校。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走去商店买了牛奶。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从我家走去公司要二十分钟。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天不坐车，我们走去公园。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走去银行取钱。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想走去那家饭店吃饭。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨不大，我走去地铁站。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们走去操场玩球。", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你走去超市要多久？", "target_word": "走去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走去了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "不坐车，靠步行前往某个地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47d4b2a1-6f38-41cd-9617-8e355af68395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走去", "is_correct": true, "explanation": "正确：“走去”指步行前往，我们走去车站吧，不太远符合语义。"}, {"text": "飞到", "is_correct": false, "explanation": "语义：“飞到”指在空中飞行到达，人不能飞到车站。"}, {"text": "游到", "is_correct": false, "explanation": "语义：“游到”指在水中游动到达，车站在陆地上。"}, {"text": "驶到", "is_correct": false, "explanation": "搭配：“驶到”用于车船，“我们”作主语不搭配。"}], "explanations": {"走去": "正确：“走去”指步行前往，我们走去车站吧，不太远符合语义。", "飞到": "语义：“飞到”指在空中飞行到达，人不能飞到车站。", "游到": "语义：“游到”指在水中游动到达，车站在陆地上。", "驶到": "搭配：“驶到”用于车船，“我们”作主语不搭配。"}, "sentence_index": 0, "correct_answer": "走去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我开车走去学校。", "explanation": "这里应该用〈开车去〉。“走去”指步行前往，已经开车就不能说“走去”。"}, {"text": "我骑车走去学校。", "explanation": "这里应该用〈骑车去〉。“走去”指步行前往，骑车不是步行，不能说“走去”。"}, {"text": "我坐公交车走去学校。", "explanation": "这里应该用〈坐公交车去〉。“走去”指步行前往，已经坐车就不能用“走去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走去", "is_correct": true, "explanation": "正确：“走去”指步行前往，我想走去那家饭店吃饭符合语义。"}, {"text": "爬到", "is_correct": false, "explanation": "语义：“爬到”指手脚贴地移动，与去饭店吃饭的正常前往不符。"}, {"text": "漂到", "is_correct": false, "explanation": "语义：“漂到”指随水或风飘动到达，人不能漂到饭店。"}, {"text": "流到", "is_correct": false, "explanation": "搭配：“流到”多用于液体，“我”作主语不搭配。"}], "explanations": {"走去": "正确：“走去”指步行前往，我想走去那家饭店吃饭符合语义。", "爬到": "语义：“爬到”指手脚贴地移动，与去饭店吃饭的正常前往不符。", "漂到": "语义：“漂到”指随水或风飘动到达，人不能漂到饭店。", "流到": "搭配：“流到”多用于液体，“我”作主语不搭配。"}, "sentence_index": 6, "correct_answer": "走去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我打车走去学校。", "explanation": "这里应该用〈打车去〉。“走去”指步行前往，打车就不能用“走去”。"}, {"text": "我乘地铁走去学校。", "explanation": "这里应该用〈坐地铁去〉。“走去”指步行，乘地铁时不能说“走去”。"}, {"text": "我乘船走去岛上。", "explanation": "这里应该用〈坐船去〉。“走去”指步行，乘船要说“坐船去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们走去了食堂吧。", "corrected_sentence": "我们走去食堂吧。", "error_description": "错误形式：“走去了食堂吧”；正确形式：“走去食堂吧”。“吧”表示建议，说的是还没发生的事，“走去”后不能加表示完成的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天走去了上班。", "corrected_sentence": "他每天走去上班。", "error_description": "错误：“每天”表示反复发生的习惯，与表示已完成的“了”搭配不当，应去掉“了”，写作“他每天走去上班。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c4e906f-ef51-4419-ac4c-3ebb58a1f7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
