INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "涉及诉讼或违法犯罪的事件。", "primary_collocate": null, "pronunciation": "àn jiàn", "ipa": "an˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "法院今天审理了一起经济案件。", "target_word": "案件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师正在准备这起案件的材料。", "target_word": "案件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类案件一般需要几个月才能审完。", "target_word": "案件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官认真地听了案件双方的话。", "target_word": "案件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起案件涉及很多钱。", "target_word": "案件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他处理过很多刑事案件。", "target_word": "案件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案件已经交给法院了。", "target_word": "案件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方把案件送到了检察院。", "target_word": "案件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院要根据法律判断这个案件。", "target_word": "案件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在法院工作，每天都要看案件材料。", "target_word": "案件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起", "label": "量词"}, {"form": "经济案件", "label": "复合"}], "register": "正式", "sense_fingerprint": "法律上涉及诉讼或违法犯罪、由法院或检察机关处理的事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4412296-5735-4d77-9af9-beeaa2149034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "案件", "is_correct": true, "explanation": "“经济”修饰“案件”，构成“经济案件”，指涉及诉讼的经济类事件，法院可以审理。"}, {"text": "水果", "is_correct": false, "explanation": "语义：法院不审理水果，“审理”的对象只能是诉讼事项。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：量词“起”用于事件，窗户应该用“扇”，不能说“一起窗户”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：法院不会审理蛋糕，“审理”与“蛋糕”的意思不相容。"}], "explanations": {"案件": "“经济”修饰“案件”，构成“经济案件”，指涉及诉讼的经济类事件，法院可以审理。", "水果": "语义：法院不审理水果，“审理”的对象只能是诉讼事项。", "窗户": "搭配：量词“起”用于事件，窗户应该用“扇”，不能说“一起窗户”。", "蛋糕": "语义：法院不会审理蛋糕，“审理”与“蛋糕”的意思不相容。"}, "sentence_index": 0, "correct_answer": "案件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校的植物课上，老师用这个案件说明了植物是怎样生长的。", "explanation": "这里应该用〈案例〉。案件指涉及诉讼或违法犯罪的事件，案例指用来说明道理的实例。这里讲的是植物生长的道理，应该用案例。"}, {"text": "夜空中出现了一起罕见的案件。", "explanation": "这里应该用〈事件〉。案件指涉及诉讼或违法犯罪的事件，天文现象不属于这类事件，应说事件。"}, {"text": "学校上周举办了一起很受欢迎的案件。", "explanation": "这里应该用〈讲座〉。“举办”搭配讲座、比赛等活动。案件是涉及诉讼或违法犯罪的事件，不能举办，也不能说很受欢迎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是需要法院处理的事项，不能交给法院。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能交给法院处理。"}, {"text": "案件", "is_correct": true, "explanation": "正确：“案件”指涉及诉讼或违法犯罪的事件，可以交给法院处理。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天是季节，不能交给法院处理。"}], "explanations": {"月亮": "语义：月亮是天体，不是需要法院处理的事项，不能交给法院。", "天气": "语义：天气是自然现象，不能交给法院处理。", "案件": "正确：“案件”指涉及诉讼或违法犯罪的事件，可以交给法院处理。", "夏天": "语义：夏天是季节，不能交给法院处理。"}, "sentence_index": 6, "correct_answer": "案件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一生都献给了音乐案件。", "explanation": "这里应该用〈事业〉。案件指涉及诉讼或违法犯罪的事件，献身的应是音乐事业，不能说“音乐案件”。"}, {"text": "这场洪水是一起严重的案件，很多人失去了家园。", "explanation": "这里应该用〈灾难〉。案件指涉及诉讼或违法犯罪的事件，洪水是自然灾害，不能称为案件，应说灾难。"}, {"text": "公园里的案件真美，我们拍了很多照片。", "explanation": "这里应该用〈景色〉。案件指涉及诉讼或违法犯罪的事件，不能形容为“美”，也不能拍照欣赏，应说景色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警方正在追查这本案件的嫌疑人。", "corrected_sentence": "警方正在追查这起案件的嫌疑人。", "error_description": "量词错误：“案件”的量词是“起”，“本”用于书籍，应说“这起案件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院已经开始审理这本案件了。", "corrected_sentence": "法院已经开始审理这起案件了。", "error_description": "量词错误：“案件”的量词是“起”，“本”用于书籍，应说“这起案件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
