INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89737, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "另有是说除了这个，还有别的。", "primary_collocate": null, "pronunciation": "lìng yǒu", "ipa": "liŋ˥˩ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "盘子里有鱼，另有一碗汤。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有一只猫，另有两只小鸟。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板给了他工资，另有一份奖金。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里坐着二十个学生，另有三个人站在门外。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了手机，他包里另有一台电脑。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司有两个办公室，另有一个仓库在城外。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单上有米饭和面条，另有几种饺子。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业是写字，另有一篇课文要读。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行有三天在北京，另有两天在上海。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每周有三节英语课，另有两节法语课。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "说除了这个以外，还有别的东西或人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b41ffc-15e7-408c-b241-b02b4f737514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另有", "is_correct": true, "explanation": "另有：表示除了盘子里的鱼，还有一碗汤，与句意相合。"}, {"text": "踩", "is_correct": false, "explanation": "语义：踩是用脚压，与“盘子里有鱼”的语境不合。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：咳嗽是不及物动词，不能带“一碗汤”作宾语。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿用于衣物、鞋袜，不能用于汤。"}], "explanations": {"另有": "另有：表示除了盘子里的鱼，还有一碗汤，与句意相合。", "踩": "语义：踩是用脚压，与“盘子里有鱼”的语境不合。", "咳嗽": "配价：咳嗽是不及物动词，不能带“一碗汤”作宾语。", "穿": "搭配：穿用于衣物、鞋袜，不能用于汤。"}, "sentence_index": 0, "correct_answer": "另有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗的结尾另有深意，读的人要慢慢体会。", "explanation": "这里的“另有”表示〈另有深意〉，即背后有别的含义，与本义“除此以外还有”不同。"}, {"text": "他这样做，另有隐情。", "explanation": "这里的“另有”表示〈另有隐情〉，即背后还有不为人知的原因，与本义“除此以外还有”不同。"}, {"text": "这件事我另有安排。", "explanation": "这里的“另有”表示〈另有安排〉，即有别的打算，与本义“除此以外还有”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另有", "is_correct": true, "explanation": "另有：表示除了米饭和面条，还有几种饺子，与句意相合。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔指使物体落下，与“菜单上”列举食物的语境不合。"}, {"text": "缝", "is_correct": false, "explanation": "语义：缝是用针线连缀，与菜单列举的语境不合。"}, {"text": "打", "is_correct": false, "explanation": "搭配：打不能用于菜单上列举饺子的语境。"}], "explanations": {"另有": "另有：表示除了米饭和面条，还有几种饺子，与句意相合。", "摔": "语义：摔指使物体落下，与“菜单上”列举食物的语境不合。", "缝": "语义：缝是用针线连缀，与菜单列举的语境不合。", "打": "搭配：打不能用于菜单上列举饺子的语境。"}, "sentence_index": 6, "correct_answer": "另有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子的主人另有其人。", "explanation": "这里的“另有”表示〈另有其人〉，即是别的人，与本义“除此以外还有”不同。"}, {"text": "这个小镇的夜景另有一番风味。", "explanation": "这里的“另有”表示〈另有一番风味〉，即别具特色，与本义“除此以外还有”不同。"}, {"text": "这幅画的笔法另有韵味。", "explanation": "这里的“另有”表示〈另有韵味〉，即别有一种韵致，与本义“除此以外还有”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "篮子里有苹果，另有有一串葡萄。", "corrected_sentence": "篮子里有苹果，另有一串葡萄。", "error_description": "“另有有”错误，应为“另有”。“另有”本身已含“有”，后面不能再加“有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冰箱里有牛奶，另有了几个鸡蛋。", "corrected_sentence": "冰箱里有牛奶，另有几个鸡蛋。", "error_description": "“另有了”错误，应为“另有”。“另有”表示除此以外还有，是对存在的补充说明，后面不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
