INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89738, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "除已提到的以外还有。", "primary_collocate": null, "pronunciation": "lìng yǒu", "ipa": "liŋ˥˩ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "桌上有一本书，另有一支笔。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了红色的，另有蓝色的可以选。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖水果，另有一些小吃。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有两个哥哥，另有一个妹妹。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有一个大操场，另有两个篮球场。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们三本书，另有一本给小王。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了苹果和香蕉，另有一些葡萄。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园里有一个湖，另有一座小山。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天有数学考试，后天另有一场英语考试。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他留下了钥匙，另有一张纸条。", "target_word": "另有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "在已经提到的事物之外，再补充还有别的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b41ffc-15e7-408c-b241-b02b4f737514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另有", "is_correct": true, "explanation": "另有：表示除了桌上的书，还有一支笔，与句意相合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿啃，与“桌上有一本书”的存在语境不合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿用于衣物、鞋袜，不能用于笔。"}, {"text": "摘", "is_correct": false, "explanation": "配价：摘要求果实、花草之类的宾语，不能用于文具。"}], "explanations": {"另有": "另有：表示除了桌上的书，还有一支笔，与句意相合。", "咬": "语义：咬是用牙齿啃，与“桌上有一本书”的存在语境不合。", "穿": "搭配：穿用于衣物、鞋袜，不能用于笔。", "摘": "配价：摘要求果实、花草之类的宾语，不能用于文具。"}, "sentence_index": 0, "correct_answer": "另有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话另有所指，大家都听懂了。", "explanation": "这里的“另有”表示〈另有所指〉，即话里暗含别的意思，与本义“除此以外还有”不同，不能用来补充事物。"}, {"text": "他另有所图，不是真心想帮我。", "explanation": "这里的“另有”表示〈另有所图〉，即暗藏别的企图，与本义“除此以外还有”不同，不能用来补充事物。"}, {"text": "他听了我的建议，另有打算。", "explanation": "这里的“另有”表示〈另有打算〉，即有与原来不同的计划，与本义“除此以外还有”不同，不能用来补充事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另有", "is_correct": true, "explanation": "另有：表示除了已买的苹果和香蕉，还有一些葡萄，与句意相合。"}, {"text": "缝", "is_correct": false, "explanation": "语义：缝是用针线连缀，与“买了苹果和香蕉”的语境不合。"}, {"text": "打", "is_correct": false, "explanation": "搭配：打不能与“葡萄”组成买东西的动作。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：咳嗽是不及物动词，不能带“一些葡萄”作宾语。"}], "explanations": {"另有": "另有：表示除了已买的苹果和香蕉，还有一些葡萄，与句意相合。", "缝": "语义：缝是用针线连缀，与“买了苹果和香蕉”的语境不合。", "打": "搭配：打不能与“葡萄”组成买东西的动作。", "咳嗽": "配价：咳嗽是不及物动词，不能带“一些葡萄”作宾语。"}, "sentence_index": 6, "correct_answer": "另有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事不是我做的，另有其人。", "explanation": "这里的“另有”表示〈另有其人〉，即是别的人（不是这个人），与本义“除此以外还有”不同。"}, {"text": "这道菜味道很特别，另有一番风味。", "explanation": "这里的“另有”表示〈另有一番风味〉，即别有特色，与本义“除此以外还有”不同。"}, {"text": "他对这个问题另有高见。", "explanation": "这里的“另有”表示〈另有高见〉，即有不同的见解，与本义“除此以外还有”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书架上有几本小说，另有了几本杂志。", "corrected_sentence": "书架上有几本小说，另有几本杂志。", "error_description": "“另有了”错误，应为“另有”。另有是固定词，后面不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里有一张床，另有有一个柜子。", "corrected_sentence": "屋里有一张床，另有一个柜子。", "error_description": "“另有有”错误，应为“另有”。“另有”本身已含“有”，后面不能再加“有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进", "is_correct": true, "explanation": "进与退为反义：进指向前，退指向后。"}, {"text": "停", "is_correct": false, "explanation": "停是停止，与退的“向后走”义没有反义关系。"}, {"text": "坐", "is_correct": false, "explanation": "坐是落座，与“向后走”义无反义关系。"}, {"text": "来", "is_correct": false, "explanation": "来指到来，与“向后走”义无反义关系。"}], "correct_answer": "进", "explanations": {"进": "进与退为反义：进指向前，退指向后。", "停": "停是停止，与退的“向后走”义没有反义关系。", "坐": "坐是落座，与“向后走”义无反义关系。", "来": "来指到来，与“向后走”义无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前进", "is_correct": true, "explanation": "前进与后退为反义，退的“向后走”义与之正相反。"}, {"text": "跑", "is_correct": false, "explanation": "跑是奔跑，不与“向后走”构成反义。"}, {"text": "站", "is_correct": false, "explanation": "站是站立，不与“向后走”构成反义。"}, {"text": "放", "is_correct": false, "explanation": "放是放置，不与“向后走”构成反义。"}], "correct_answer": "前进", "explanations": {"前进": "前进与后退为反义，退的“向后走”义与之正相反。", "跑": "跑是奔跑，不与“向后走”构成反义。", "站": "站是站立，不与“向后走”构成反义。", "放": "放是放置，不与“向后走”构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向后走，离开前面。", "primary_collocate": null, "pronunciation": "tuì", "ipa": "tʰuei˥˩", "syllable_count": 1, "sentences": [{"text": "前面有水，请大家往后退。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吓得退了两步。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车太近了，你再退一点。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请往后退一步。”", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到大狗，小女孩马上往后退。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边说话，一边向后退。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的路不通，我们往后退吧。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机把车往后退了一点。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火太大了，大家都退到门外。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们怕得退到妈妈身后。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "退了", "label": "体标"}, {"form": "退过", "label": "体标"}, {"form": "退着", "label": "体标"}, {"form": "退后", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或车向后走几步，离开前面的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d6f595-c5fd-45de-a729-3a0510ed58f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "退", "is_correct": true, "explanation": "退（tuì）意思是向后移动，即本词条。"}, {"text": "推", "is_correct": false, "explanation": "推（tuī，第一声）与退（tuì，第四声）声调不同，意思是用力使物体移动。"}, {"text": "腿", "is_correct": false, "explanation": "腿（tuǐ，第三声）与退（tuì，第四声）声调不同，意思是身体的下肢。"}, {"text": "对", "is_correct": false, "explanation": "对（duì）与退的声母不同（d 与 t），意思是正确、对待。"}, {"text": "脆", "is_correct": false, "explanation": "脆（cuì）与退的声母不同（c 与 t），意思是易碎、松脆。"}], "explanations": {"退": "退（tuì）意思是向后移动，即本词条。", "推": "推（tuī，第一声）与退（tuì，第四声）声调不同，意思是用力使物体移动。", "腿": "腿（tuǐ，第三声）与退（tuì，第四声）声调不同，意思是身体的下肢。", "对": "对（duì）与退的声母不同（d 与 t），意思是正确、对待。", "脆": "脆（cuì）与退的声母不同（c 与 t），意思是易碎、松脆。"}, "sentence_index": null, "correct_answer": "退"}, "level_3": {"options": [{"text": "退", "is_correct": true, "explanation": "正确。退指向后移动，与“往后”相合。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝指把液体咽下，不能表示向后移动，“请大家往后喝”说不通。"}, {"text": "躺", "is_correct": false, "explanation": "语义：躺指身体平卧，是姿势而非有秩序地向后移动，不符合“请大家往后”的指令。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔指跌落，不是有意地向后移动。"}], "explanations": {"退": "正确。退指向后移动，与“往后”相合。", "喝": "语义：喝指把液体咽下，不能表示向后移动，“请大家往后喝”说不通。", "躺": "语义：躺指身体平卧，是姿势而非有秩序地向后移动，不符合“请大家往后”的指令。", "摔": "语义：摔指跌落，不是有意地向后移动。"}, "sentence_index": 0, "correct_answer": "退"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一进门就把外套退了下来。", "explanation": "这里应该用〈脱〉。退指向后移动，脱衣服要用脱。"}, {"text": "他一步一步退上了山。", "explanation": "这里应该用〈爬〉。退表示向后移动或离开，不能表示向上行进；往上攀登要用爬。"}, {"text": "他看见蛇，马上退了草地。", "explanation": "这里应该用〈离开〉。退表示向后走或离开前面，不能以“草地”这类场所作宾语表示离去；离开草地要用离开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "退", "is_correct": true, "explanation": "退（tuì）意思是向后移动，即本词条。"}, {"text": "队", "is_correct": false, "explanation": "队（duì）与退的声母不同（d 与 t），意思是队伍。"}, {"text": "最", "is_correct": false, "explanation": "最（zuì）与退的声母不同（z 与 t），意思是程度最高。"}, {"text": "碎", "is_correct": false, "explanation": "碎（suì）与退的声母不同（s 与 t），意思是破碎。"}, {"text": "翠", "is_correct": false, "explanation": "翠（cuì）与退的声母不同（c 与 t），意思是翠绿色。"}], "explanations": {"退": "退（tuì）意思是向后移动，即本词条。", "队": "队（duì）与退的声母不同（d 与 t），意思是队伍。", "最": "最（zuì）与退的声母不同（z 与 t），意思是程度最高。", "碎": "碎（suì）与退的声母不同（s 与 t），意思是破碎。", "翠": "翠（cuì）与退的声母不同（c 与 t），意思是翠绿色。"}, "sentence_index": null, "correct_answer": "退"}, "level_3": {"options": [{"text": "退", "is_correct": true, "explanation": "正确。退指向后移动，与“前面的路不通”的结论相合。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：踢需要宾语，“往后踢”表示用脚击打，不是移动路线。"}, {"text": "扑", "is_correct": false, "explanation": "语义：扑指身体猛然向前或向某处扑去，与“我们往后退吧”的有秩序后退不符。"}, {"text": "吐", "is_correct": false, "explanation": "语义：吐指从口中排出，与移动无关。"}], "explanations": {"退": "正确。退指向后移动，与“前面的路不通”的结论相合。", "踢": "搭配：踢需要宾语，“往后踢”表示用脚击打，不是移动路线。", "扑": "语义：扑指身体猛然向前或向某处扑去，与“我们往后退吧”的有秩序后退不符。", "吐": "语义：吐指从口中排出，与移动无关。"}, "sentence_index": 6, "correct_answer": "退"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力把柜门退开了。", "explanation": "这里应该用〈推〉。推指用力使物体移动，退指人或车自己向后移动。"}, {"text": "他用布把桌子退干净了。", "explanation": "这里应该用〈擦〉。退表示向后走或离开，不能用来表示擦去污渍；擦桌子要用擦。"}, {"text": "他往前退了一步，走到了桌子边。", "explanation": "这里应该用〈走〉。退是向后移动，不能和“往前”连用；往前移动要说“往前走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他往后了退两步，让出了路。", "corrected_sentence": "他往后退了两步，让出了路。", "error_description": "错误形式：“了”放在“退”前；正确形式：“退了两步”；原因：体标“了”须紧跟动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车子往后了退一步，大家松了口气。", "corrected_sentence": "车子往后退了一步，大家松了口气。", "error_description": "错误形式：“往后了退一步”；正确形式：“往后退了一步”；原因：体标“了”须紧跟动词“退”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进", "is_correct": true, "explanation": "进与退为反义：退指向后离开，进指向前进入。"}, {"text": "停", "is_correct": false, "explanation": "停是停止，与退的“离开”义没有反义关系。"}, {"text": "坐", "is_correct": false, "explanation": "坐是落座，与退的任何义项都不构成反义。"}, {"text": "来", "is_correct": false, "explanation": "来指到来，与退不构成反义，其反义是去。"}], "correct_answer": "进", "explanations": {"进": "进与退为反义：退指向后离开，进指向前进入。", "停": "停是停止，与退的“离开”义没有反义关系。", "坐": "坐是落座，与退的任何义项都不构成反义。", "来": "来指到来，与退不构成反义，其反义是去。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "涨", "is_correct": true, "explanation": "涨与退为反义，水涨与水退相对，如“潮涨潮退”。"}, {"text": "跑", "is_correct": false, "explanation": "跑是奔跑，与退的水退义没有反义关系。"}, {"text": "站", "is_correct": false, "explanation": "站是站立，与水退义无反义关系。"}, {"text": "放", "is_correct": false, "explanation": "放是放置，与退的任何义项都不构成反义。"}], "correct_answer": "涨", "explanations": {"涨": "涨与退为反义，水涨与水退相对，如“潮涨潮退”。", "跑": "跑是奔跑，与退的水退义没有反义关系。", "站": "站是站立，与水退义无反义关系。", "放": "放是放置，与退的任何义项都不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向后移动；离开。", "primary_collocate": null, "pronunciation": "tuì", "ipa": "tʰuei˥˩", "syllable_count": 1, "sentences": [{"text": "大水慢慢退了，路又能走了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上海边的潮水已经退了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人打不过我们，只好退了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤了，比赛中途就退了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮以后，大雾慢慢退了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水退了以后，地上都是泥。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累了，想从队伍里退下来休息。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队打了败仗，一直退到河边。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组他不喜欢，上个月就退了。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水退了，村民们回家打扫房子。", "target_word": "退", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "退了", "label": "体标"}, {"form": "退过", "label": "体标"}, {"form": "退着", "label": "体标"}, {"form": "退后", "label": "复合"}], "register": "中性", "sense_fingerprint": "水、军队、人从原处向后移动或离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d6f595-c5fd-45de-a729-3a0510ed58f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "退", "is_correct": true, "explanation": "退（tuì）意思是向后移动或离开，即本词条。"}, {"text": "推", "is_correct": false, "explanation": "推（tuī，第一声）与退（tuì，第四声）声调不同，意思是用力使物体移动。"}, {"text": "腿", "is_correct": false, "explanation": "腿（tuǐ，第三声）与退（tuì，第四声）声调不同，意思是身体的下肢。"}, {"text": "对", "is_correct": false, "explanation": "对（duì）与退的声母不同（d 与 t），意思是正确、对待。"}, {"text": "脆", "is_correct": false, "explanation": "脆（cuì）与退的声母不同（c 与 t），意思是易碎、松脆。"}], "explanations": {"退": "退（tuì）意思是向后移动或离开，即本词条。", "推": "推（tuī，第一声）与退（tuì，第四声）声调不同，意思是用力使物体移动。", "腿": "腿（tuǐ，第三声）与退（tuì，第四声）声调不同，意思是身体的下肢。", "对": "对（duì）与退的声母不同（d 与 t），意思是正确、对待。", "脆": "脆（cuì）与退的声母不同（c 与 t），意思是易碎、松脆。"}, "sentence_index": null, "correct_answer": "退"}, "level_3": {"options": [{"text": "退", "is_correct": true, "explanation": "正确。退指水位下降、离开原处，所以路又能走了。"}, {"text": "涨", "is_correct": false, "explanation": "语义：涨指水位上升，与“路又能走了”的结果相矛盾。"}, {"text": "进", "is_correct": false, "explanation": "语义：进指水流入，水流进来不会让路变得能走，与语境不符。"}, {"text": "冲", "is_correct": false, "explanation": "语义：冲指水流猛烈地冲击、奔涌，与“慢慢”的缓慢态势不合，也不会让路变得能走。"}], "explanations": {"退": "正确。退指水位下降、离开原处，所以路又能走了。", "涨": "语义：涨指水位上升，与“路又能走了”的结果相矛盾。", "进": "语义：进指水流入，水流进来不会让路变得能走，与语境不符。", "冲": "语义：冲指水流猛烈地冲击、奔涌，与“慢慢”的缓慢态势不合，也不会让路变得能走。"}, "sentence_index": 0, "correct_answer": "退"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天的气温退了不少。", "explanation": "这里应该用〈降低〉。退用于水、军队、人等向后移动或离开，气温下降要用降低。"}, {"text": "工厂的产量退了不少。", "explanation": "这里应该用〈减少〉。退不用来指数量下降，产量减少要用减少。"}, {"text": "他一下班就退了办公室。", "explanation": "这里应该用〈离开〉。退表示向后移动或退出，不能直接以“办公室”这类场所作宾语表示离去；下班离开办公室要用离开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "退", "is_correct": true, "explanation": "退（tuì）意思是向后移动或离开，即本词条。"}, {"text": "队", "is_correct": false, "explanation": "队（duì）与退的声母不同（d 与 t），意思是队伍。"}, {"text": "最", "is_correct": false, "explanation": "最（zuì）与退的声母不同（z 与 t），意思是程度最高。"}, {"text": "碎", "is_correct": false, "explanation": "碎（suì）与退的声母不同（s 与 t），意思是破碎。"}, {"text": "翠", "is_correct": false, "explanation": "翠（cuì）与退的声母不同（c 与 t），意思是翠绿色。"}], "explanations": {"退": "退（tuì）意思是向后移动或离开，即本词条。", "队": "队（duì）与退的声母不同（d 与 t），意思是队伍。", "最": "最（zuì）与退的声母不同（z 与 t），意思是程度最高。", "碎": "碎（suì）与退的声母不同（s 与 t），意思是破碎。", "翠": "翠（cuì）与退的声母不同（c 与 t），意思是翠绿色。"}, "sentence_index": null, "correct_answer": "退"}, "level_3": {"options": [{"text": "退", "is_correct": true, "explanation": "正确。退下来指主动离开队伍，与“想休息”相合。"}, {"text": "掉", "is_correct": false, "explanation": "语义：掉指失足或意外坠落，不是主动离开队伍。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：扔是抛出，人不能用“扔”的方式从队伍里下来。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔指跌倒受伤，与“想休息”的主动意愿相反。"}], "explanations": {"退": "正确。退下来指主动离开队伍，与“想休息”相合。", "掉": "语义：掉指失足或意外坠落，不是主动离开队伍。", "扔": "搭配：扔是抛出，人不能用“扔”的方式从队伍里下来。", "摔": "语义：摔指跌倒受伤，与“想休息”的主动意愿相反。"}, "sentence_index": 6, "correct_answer": "退"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在河里退了一个下午的泳。", "explanation": "这里应该用〈游〉。退表示向后移动或离开，游泳要用游。"}, {"text": "他把垃圾退了。", "explanation": "这里应该用〈扔〉。退表示向后移动或离开，丢掉垃圾要用扔。"}, {"text": "他用力把门退开了。", "explanation": "这里应该用〈推〉。推指用力使物体移动，退指人或车自己向后移动，不能用来推门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洪水慢慢了退，屋子里的泥也干了。", "corrected_sentence": "洪水慢慢退了，屋子里的泥也干了。", "error_description": "错误形式：“了”放在“退”前；正确形式：“退了”；原因：体标“了”须紧跟动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "军队打了败仗，一路了退三里路。", "corrected_sentence": "军队打了败仗，一路退了三里路。", "error_description": "错误形式：“了”放在“退”前，写作“一路了退三里路”；正确形式：“一路退了三里路”；原因：体标“了”须紧跟动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89741, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89741, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89741, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一个成年男子。", "primary_collocate": null, "pronunciation": "nán xìng", "ipa": "nan˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "门口站着一位男性，他在等人。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位男性穿着黑色的外套。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这位男性需要多休息。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位年轻男性帮我拿了行李。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位男性问我去车站怎么走。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察看见一位男性跑了过来。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位男性每天骑车去上班。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗边坐着一位戴眼镜的男性。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识那位男性，他是我的邻居。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位老年男性正在公园里散步。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "男性朋友", "label": "复合"}], "register": "中性", "sense_fingerprint": "指具体的一个男人，常说“一位男性”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4412296-5735-4d77-9af9-beeaa2149034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89741, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "男星", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，“男星”指男演员或男明星。"}, {"text": "男性", "is_correct": true, "explanation": "正确：“男性”读 nán xìng，指成年男子。"}, {"text": "难行", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，“难行”指难以通行。"}, {"text": "南行", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，“南行”指向南走。"}], "explanations": {"男星": "xīng（第一声）与 xìng（第四声）声调不同，“男星”指男演员或男明星。", "男性": "正确：“男性”读 nán xìng，指成年男子。", "难行": "xíng（第二声）与 xìng（第四声）声调不同，“难行”指难以通行。", "南行": "xíng（第二声）与 xìng（第四声）声调不同，“南行”指向南走。"}, "sentence_index": null, "correct_answer": "男性"}, "level_3": {"options": [{"text": "女性", "is_correct": false, "explanation": "语义：后句的“他”指男性，与“女性”的性别不符。"}, {"text": "男性", "is_correct": true, "explanation": "正确：“他”与“一位男性”性别一致，指成年男子。"}, {"text": "女孩", "is_correct": false, "explanation": "语义：“女孩”指年幼的女性，且与后句“他”的所指冲突。"}, {"text": "妇女", "is_correct": false, "explanation": "语域：“妇女”偏书面、群体化；且与后句“他”的性别冲突。"}], "explanations": {"女性": "语义：后句的“他”指男性，与“女性”的性别不符。", "男性": "正确：“他”与“一位男性”性别一致，指成年男子。", "女孩": "语义：“女孩”指年幼的女性，且与后句“他”的所指冲突。", "妇女": "语域：“妇女”偏书面、群体化；且与后句“他”的性别冲突。"}, "sentence_index": 0, "correct_answer": "男性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位歌手是一位男性高音。", "explanation": "这里应该用〈男高音〉。声部名称要说“男高音”，不说“男性高音”。"}, {"text": "这只猫是男性，喜欢在院子里睡觉。", "explanation": "这里应该用〈雄性〉。“男性”只指人，说动物要用“雄性”。"}, {"text": "一个小男性帮我拿了行李。", "explanation": "这里应该用〈男孩〉。指儿童要说“男孩”；“男性”指成年男子，不能加“小”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89741, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生去学校上学，与“上班”不符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客不会每天上班，与“每天骑车去上班”矛盾。"}, {"text": "男性", "is_correct": true, "explanation": "正确：“这位男性”指成年男子，可以每天骑车上班。"}, {"text": "小孩", "is_correct": false, "explanation": "搭配：“这位”是敬称，多用于成人；小孩不宜“每天去上班”。"}], "explanations": {"学生": "语义：学生去学校上学，与“上班”不符。", "游客": "语义：游客不会每天上班，与“每天骑车去上班”矛盾。", "男性": "正确：“这位男性”指成年男子，可以每天骑车上班。", "小孩": "搭配：“这位”是敬称，多用于成人；小孩不宜“每天去上班”。"}, "sentence_index": 6, "correct_answer": "男性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校有男性篮球队和女子篮球队。", "explanation": "这里应该用〈男子〉。体育队名要说“男子”，不说“男性”。"}, {"text": "他很有男性味，大家都很喜欢他。", "explanation": "这里应该用〈男人味〉。表示气质要说“男人味”，不说“男性味”。"}, {"text": "他安慰我说：“男性有泪不轻弹。”", "explanation": "这里应该用〈男儿〉。“男儿有泪不轻弹”是固定说法，“男性”不能替换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "超市门口站着一只男性。", "corrected_sentence": "超市门口站着一位男性。", "error_description": "量词错误：“男性”指人，计量应用“位”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我有一只男性朋友。", "corrected_sentence": "我有一位男性朋友。", "error_description": "量词错误：“男性朋友”指人，应用“位”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89742, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "女性", "is_correct": true, "explanation": "正确：“男性”与“女性”互为反义，分别指人类中的两性。"}, {"text": "孩子", "is_correct": false, "explanation": "无反义关系：“孩子”指年幼的人，与“男性”不构成反义。"}, {"text": "老人", "is_correct": false, "explanation": "无反义关系：“老人”指年长的人，与“男性”不构成反义。"}, {"text": "学生", "is_correct": false, "explanation": "无反义关系：“学生”指求学的人，与“男性”不构成反义。"}], "correct_answer": "女性", "explanations": {"女性": "正确：“男性”与“女性”互为反义，分别指人类中的两性。", "孩子": "无反义关系：“孩子”指年幼的人，与“男性”不构成反义。", "老人": "无反义关系：“老人”指年长的人，与“男性”不构成反义。", "学生": "无反义关系：“学生”指求学的人，与“男性”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89742, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "女性", "is_correct": true, "explanation": "正确：“男性”与“女性”互为反义，分别指人类中的两性。"}, {"text": "工人", "is_correct": false, "explanation": "无反义关系：“工人”指从事体力或生产劳动的人，与“男性”不构成反义。"}, {"text": "医生", "is_correct": false, "explanation": "无反义关系：“医生”指从事医疗工作的人，与“男性”不构成反义。"}, {"text": "厨师", "is_correct": false, "explanation": "无反义关系：“厨师”指以烹饪为职业的人，与“男性”不构成反义。"}], "correct_answer": "女性", "explanations": {"女性": "正确：“男性”与“女性”互为反义，分别指人类中的两性。", "工人": "无反义关系：“工人”指从事体力或生产劳动的人，与“男性”不构成反义。", "医生": "无反义关系：“医生”指从事医疗工作的人，与“男性”不构成反义。", "厨师": "无反义关系：“厨师”指以烹饪为职业的人，与“男性”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人类中的男人一方。", "primary_collocate": null, "pronunciation": "nán xìng", "ipa": "nan˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "男性的平均寿命一般比女性短。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店主要经营男性用品。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查显示，男性更喜欢看足球比赛。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男性和女性都可以报名参加。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志的读者大多是男性。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男性的声音一般比女性低。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里男性比女性多一些。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种运动更受男性欢迎。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男性的身高平均比女性高。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作对男性和女性一样开放。", "target_word": "男性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "男性用品", "label": "复合"}], "register": "中性", "sense_fingerprint": "指人类中与女性相对的男人这一群体或性别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4412296-5735-4d77-9af9-beeaa2149034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89742, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "男星", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，“男星”指男演员或男明星。"}, {"text": "男性", "is_correct": true, "explanation": "正确：“男性”读 nán xìng，指人类中的男人一方。"}, {"text": "难行", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，“难行”指难以通行。"}, {"text": "南行", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，“南行”指向南走。"}], "explanations": {"男星": "xīng（第一声）与 xìng（第四声）声调不同，“男星”指男演员或男明星。", "男性": "正确：“男性”读 nán xìng，指人类中的男人一方。", "难行": "xíng（第二声）与 xìng（第四声）声调不同，“难行”指难以通行。", "南行": "xíng（第二声）与 xìng（第四声）声调不同，“南行”指向南走。"}, "sentence_index": null, "correct_answer": "男性"}, "level_3": {"options": [{"text": "女性", "is_correct": false, "explanation": "语义：“比女性短”是同类比较，主语不能也是女性。"}, {"text": "男性", "is_correct": true, "explanation": "正确：“男性”指人类中的男人一方，可以与“女性”比较寿命。"}, {"text": "雄性", "is_correct": false, "explanation": "语域：“雄性”多用于动物，指人类应说“男性”。"}, {"text": "妇女", "is_correct": false, "explanation": "语义：“妇女”与“女性”同指，“妇女比女性短”是同类自我比较，不成立。"}], "explanations": {"女性": "语义：“比女性短”是同类比较，主语不能也是女性。", "男性": "正确：“男性”指人类中的男人一方，可以与“女性”比较寿命。", "雄性": "语域：“雄性”多用于动物，指人类应说“男性”。", "妇女": "语义：“妇女”与“女性”同指，“妇女比女性短”是同类自我比较，不成立。"}, "sentence_index": 0, "correct_answer": "男性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛分为男性组和女子组。", "explanation": "这里应该用〈男子〉。体育比赛分组要说“男子组”，“男性组”不这么用。"}, {"text": "他忍住眼泪，小声说：“男性有泪不轻弹。”", "explanation": "这里应该用〈男儿〉。“男儿有泪不轻弹”是固定说法，“男性”不能替换。"}, {"text": "合唱团里有一位很出色的男性高音。", "explanation": "这里应该用〈男高音〉。声部名称要说“男高音”，不说“男性高音”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "儿童", "is_correct": false, "explanation": "语义：儿童不在公司里工作，与“比女性多”的比较不成立。"}, {"text": "男性", "is_correct": true, "explanation": "正确：“男性”指人类中的男人一方，可以与“女性”比较人数。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不是人，无法与女性比较人数。"}, {"text": "男孩", "is_correct": false, "explanation": "语义：“男孩”指男童，公司里不会有男童工作，句意不成立。"}], "explanations": {"儿童": "语义：儿童不在公司里工作，与“比女性多”的比较不成立。", "男性": "正确：“男性”指人类中的男人一方，可以与“女性”比较人数。", "植物": "语义：植物不是人，无法与女性比较人数。", "男孩": "语义：“男孩”指男童，公司里不会有男童工作，句意不成立。"}, "sentence_index": 6, "correct_answer": "男性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店的男性童装很便宜。", "explanation": "这里应该用〈男童〉。“童装”指儿童服装，应说“男童装”；“男性”指成年男子，不用于儿童。"}, {"text": "这位主持人很有男性味，观众都很喜欢他。", "explanation": "这里应该用〈男人味〉。形容气质要说“男人味”，不说“男性味”。"}, {"text": "超市货架上有男性卫生巾。", "explanation": "这里应该用〈女性〉。卫生巾是女性用品，应说“女性卫生巾”；“男性”不能用于女性专用物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家商场有很多男性们用品。", "corrected_sentence": "这家商场有很多男性用品。", "error_description": "错误：“男性”后面多加了“们”。“们”只用于指人名词表示复数，不能放在修饰“用品”的“男性”之后。正确说法是“男性用品”，应删去“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种运动很受一男性欢迎。", "corrected_sentence": "这种运动很受男性欢迎。", "error_description": "错误：数词“一”直接接在“男性”前，中间缺少量词。这里应删去“一”，正确说法是“很受男性欢迎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
