INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89743, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件事一次又一次出现，每一次要花的时间。", "primary_collocate": null, "pronunciation": "zhōu qī", "ipa": "tʂoʊ˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "这种手机的更新周期很短。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做一件新衣服的周期大概是两个星期。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂的生产周期是三天。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说复习的周期不要太长。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司每个月开一次会，这个周期不变。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买新车的周期，一般人是五年左右。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸的出版周期是一天，杂志是一个月。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电视剧的拍摄周期很长，用了两年。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "换牙刷的周期最好是三个月。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋糕店新品的更换周期是一个月。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个周期", "label": "量词"}, {"form": "周期性", "label": "复合"}, {"form": "週期", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事或某种安排每重复一次所需的时间，如生产周期、更新周期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30511e17-00b3-46ac-a6ac-77252451a420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89743, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周期", "is_correct": true, "explanation": "正确。周期指每次更新所需的时间，与“很短”一致。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”说快慢，不能说“更新速度很短”这种时间的长短。"}, {"text": "距离", "is_correct": false, "explanation": "语义：距离指空间的远近，不能用来描述更新所需的时间。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说高低，不能说“很短”。"}], "explanations": {"周期": "正确。周期指每次更新所需的时间，与“很短”一致。", "速度": "搭配：“速度”说快慢，不能说“更新速度很短”这种时间的长短。", "距离": "语义：距离指空间的远近，不能用来描述更新所需的时间。", "价格": "搭配：“价格”说高低，不能说“很短”。"}, "sentence_index": 0, "correct_answer": "周期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的童年周期很快乐。", "explanation": "这里应该用〈时期〉。周期指一件事反复出现一次所需的时间，说人生的一段阶段要用〈时期〉。"}, {"text": "这次旅行的周期是三天。", "explanation": "这里应该用〈行程〉。旅行只进行一次，不是反复循环，应说行程。"}, {"text": "这首歌的周期是四分钟。", "explanation": "这里应该用〈时长〉。歌曲只播放一遍，不是循环重复，应说时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89743, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "周期", "is_correct": true, "explanation": "正确。周期指出版一次所需的时间，与“报纸的出版”一致。"}, {"text": "高度", "is_correct": false, "explanation": "语义：“高度”说高低，不能用来表示出版所需的时间。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能表示时间的长短。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说高低，不能说“出版价格是一天”。"}], "explanations": {"周期": "正确。周期指出版一次所需的时间，与“报纸的出版”一致。", "高度": "语义：“高度”说高低，不能用来表示出版所需的时间。", "颜色": "语义：颜色不能表示时间的长短。", "价格": "搭配：“价格”说高低，不能说“出版价格是一天”。"}, "sentence_index": 6, "correct_answer": "周期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的周期是三天。", "explanation": "这里应该用〈会期〉。会议只召开这一次，不是循环重复，应说会期。"}, {"text": "这次讲座的周期是两个小时。", "explanation": "这里应该用〈时长〉。讲座只举行一次，不存在重复循环，应说时长。"}, {"text": "我家到学校的周期是三公里。", "explanation": "这里应该用〈距离〉。周期是一件事反复出现的时间，两地之间的长短要说距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
