INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物运动、变化一次所经历的时间。", "primary_collocate": null, "pronunciation": "zhōu qī", "ipa": "tʂoʊ˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "地球绕太阳转一圈，周期是一年。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月亮圆缺变化的周期大约是三十天。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钟摆来回摆动一次的周期很固定。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水星绕太阳运动的周期比地球短。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种蝉的生长周期是十七年。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "潮水涨落有固定的周期。", "target_word": "周期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "季节变化的周期是一年。", "target_word": "周期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个星星发光的周期是五天，很有规律。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳黑子的活动周期大约是十一年。", "target_word": "周期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家算出了这颗彗星的周期，大约七十六年。", "target_word": "周期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个周期", "label": "量词"}, {"form": "周期性", "label": "复合"}, {"form": "週期", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天体、摆动、潮汐等自然现象运动或变化一整圈所用的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30511e17-00b3-46ac-a6ac-77252451a420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周期", "is_correct": true, "explanation": "正确。周期指转一圈所需的时间，与“是一年”一致。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”常说快慢，不能说“速度是一年”。"}, {"text": "距离", "is_correct": false, "explanation": "语义：距离指空间的长度，不能用来表示转一圈所需的时间。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度指冷热，与“转一圈是一年”的意思不符。"}], "explanations": {"周期": "正确。周期指转一圈所需的时间，与“是一年”一致。", "速度": "搭配：“速度”常说快慢，不能说“速度是一年”。", "距离": "语义：距离指空间的长度，不能用来表示转一圈所需的时间。", "温度": "语义：温度指冷热，与“转一圈是一年”的意思不符。"}, "sentence_index": 0, "correct_answer": "周期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次聚会的周期很短。", "explanation": "这里应该用〈时长〉。聚会只举行一次，不是循环重复，应说时长。"}, {"text": "这辆车的周期是每小时一百公里。", "explanation": "这里应该用〈速度〉。周期指运动一次所需的时间，表示每小时行驶多远要说〈速度〉。"}, {"text": "这场比赛的周期是两小时。", "explanation": "这里应该用〈赛程〉。比赛只进行一次，不循环，应说赛程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "周期", "is_correct": true, "explanation": "正确。周期指季节变化一次所需的时间，与“是一年”一致。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积指空间的大小，不能表示季节变化所需的时间。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能表示时间的长短。"}, {"text": "宽度", "is_correct": false, "explanation": "搭配：“宽度”说空间的宽窄，不能说“宽度是一年”。"}], "explanations": {"周期": "正确。周期指季节变化一次所需的时间，与“是一年”一致。", "体积": "语义：体积指空间的大小，不能表示季节变化所需的时间。", "味道": "语义：味道不能表示时间的长短。", "宽度": "搭配：“宽度”说空间的宽窄，不能说“宽度是一年”。"}, "sentence_index": 6, "correct_answer": "周期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋大楼的周期是五十年。", "explanation": "这里应该用〈寿命〉。大楼只存在一次，不会循环，说周期不对。"}, {"text": "这次航行的周期是七十六天。", "explanation": "这里应该用〈航程〉。航行只完成一次，不是循环，应说航程。"}, {"text": "这座桥的周期是一百年。", "explanation": "这里应该用〈年限〉。桥只建造一次，不是循环重复，应说年限。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "月亮的一场周期大约是二十七天。", "corrected_sentence": "月亮的一个周期大约是二十七天。", "error_description": "量词错误：周期要用“个”，不用“场”。正确形式为“月亮的一个周期大约是二十七天。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
