INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89745, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可动是说能动，可以移动或转动。", "primary_collocate": null, "pronunciation": "kě dòng", "ipa": "kʰɤ˨˩˦ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个玩偶的手和脚都是可动的。", "target_word": "可动", "complexity_tier": "T3", "furigana": "zhè ge wán ǒu de shǒu hé jiǎo dōu shì kě dòng de.", "sentence_source": "generated"}, {"text": "这种机器人有二十个可动关节。", "target_word": "可动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的这一块板是可动的，可以拉出来。", "target_word": "可动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子喜欢可动的玩具。", "target_word": "可动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门是可动的，可以推开。", "target_word": "可动", "complexity_tier": "T3", "furigana": "zhè shàn mén shì kě dòng de, kě yǐ tuī kāi.", "sentence_source": "generated"}, {"text": "机器的可动部分要常常加油。", "target_word": "可动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个娃娃的头不是可动的，转不了。", "target_word": "可动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一个可动的机器人模型。", "target_word": "可动", "complexity_tier": "T3", "furigana": "tā mǎi le yí gè kě dòng de jī qì rén mó xíng.", "sentence_source": "generated"}, {"text": "这张椅子有可动的扶手。", "target_word": "可动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥的中间有一段可动的部分，船来了就升起来。", "target_word": "可动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物体的某个部分能够移动或转动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b41ffc-15e7-408c-b241-b02b4f737514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”说刀刃、边缘，不说玩偶的手和脚。"}, {"text": "可动", "is_correct": true, "explanation": "可动：指部件能够移动或转动，符合玩偶手脚的特点。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”描述声音，与玩偶的手和脚无关。"}, {"text": "辛苦", "is_correct": false, "explanation": "语义：“辛苦”形容人的劳累，不用来形容玩偶的肢体。"}], "explanations": {"锋利": "搭配：“锋利”说刀刃、边缘，不说玩偶的手和脚。", "可动": "可动：指部件能够移动或转动，符合玩偶手脚的特点。", "响亮": "语义：“响亮”描述声音，与玩偶的手和脚无关。", "辛苦": "语义：“辛苦”形容人的劳累，不用来形容玩偶的肢体。"}, "sentence_index": 0, "correct_answer": "可动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人的思路很可动。", "explanation": "这里应该用〈灵活〉。可动只说物体的部件能否移动或转动，形容人的思路要用灵活。"}, {"text": "这个小男孩很可动。", "explanation": "这里应该用〈活泼〉。可动不用来形容人的性格或举止，说小孩活跃要用活泼。"}, {"text": "这位木匠的手艺很可动。", "explanation": "这里应该用〈灵巧〉。可动指部件能移动，形容手艺精巧要用灵巧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”形容环境安静，不用来形容娃娃的头。"}, {"text": "凶猛", "is_correct": false, "explanation": "语义：“凶猛”形容凶狠的动物或人，不能形容娃娃的头。"}, {"text": "苦涩", "is_correct": false, "explanation": "搭配：“苦涩”形容味道，不说头的状态。"}, {"text": "可动", "is_correct": true, "explanation": "可动：指能移动或转动。句中“转不了”说明头不能转，所以“不是可动的”。"}], "explanations": {"寂静": "语义：“寂静”形容环境安静，不用来形容娃娃的头。", "凶猛": "语义：“凶猛”形容凶狠的动物或人，不能形容娃娃的头。", "苦涩": "搭配：“苦涩”形容味道，不说头的状态。", "可动": "可动：指能移动或转动。句中“转不了”说明头不能转，所以“不是可动的”。"}, "sentence_index": 6, "correct_answer": "可动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的夜市很可动。", "explanation": "这里应该用〈活跃〉。可动说部件能否移动，形容集市热闹要用活跃。"}, {"text": "这座楼的结构很可动。", "explanation": "这里应该用〈稳定〉。可动说部件能移动，说结构牢固、不晃要用稳定。"}, {"text": "他的反应很可动。", "explanation": "这里应该用〈灵敏〉。可动不用来形容反应快慢，说反应快要用灵敏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电视的支架是不可动的，可以转向。", "corrected_sentence": "这台电视的支架是可动的，可以转向。", "error_description": "“不”否定了“可动”，与后句“可以转向”矛盾。应去掉“不”，说“是可动的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把椅子的靠背是可动，可以放倒。", "corrected_sentence": "这把椅子的靠背是可动的，可以放倒。", "error_description": "“可动”是非谓形容词，不能直接放在“是”后面作谓语，要说“是可动的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89747, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "醒", "is_correct": true, "explanation": "醒：与“睡”互为反义，指睡眠结束、恢复清醒。"}, {"text": "走", "is_correct": false, "explanation": "“走”与“睡”没有反义关系，只表示迈步前进。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“睡”没有反义关系，只表示用笔记录文字。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”与“睡”没有反义关系，只表示把食物咽下去。"}], "correct_answer": "醒", "explanations": {"醒": "醒：与“睡”互为反义，指睡眠结束、恢复清醒。", "走": "“走”与“睡”没有反义关系，只表示迈步前进。", "写": "“写”与“睡”没有反义关系，只表示用笔记录文字。", "吃": "“吃”与“睡”没有反义关系，只表示把食物咽下去。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
