INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89747, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "睡是闭上眼睛,休息,不动也不知道。", "primary_collocate": null, "pronunciation": "shuì", "ipa": "ʂweɪ˥˩", "syllable_count": 1, "sentences": [{"text": "我想在沙发上睡一会儿。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫睡在我的腿上。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累了，躺下就睡。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子已经睡了，请小声说话。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午我习惯睡半个小时。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你睡那张床，我睡沙发。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡得很香，没听到电话。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡在地上，身上盖着衣服。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在车上睡了一路。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡到中午才起床。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "睡了", "label": "完成体"}, {"form": "睡过", "label": "经历体"}, {"form": "睡觉", "label": "复合词"}, {"form": "睡眠", "label": "复合词"}], "register": "口语", "sense_fingerprint": "闭眼躺着休息，身体不动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85beadd-467a-48ea-b48a-dbf1be933464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89747, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "睡", "is_correct": true, "explanation": "shuì（第四声）指闭眼休息、身体不动，是目标词。"}, {"text": "水", "is_correct": false, "explanation": "shuǐ（第三声）与 shuì（第四声）声调不同，意思是水。"}, {"text": "谁", "is_correct": false, "explanation": "shuí（第二声）与 shuì（第四声）声调不同，意思是谁。"}, {"text": "帅", "is_correct": false, "explanation": "shuài（第四声）与 shuì 韵母不同（ai 与 ui），意思是英俊、帅气。"}, {"text": "岁", "is_correct": false, "explanation": "suì 与 shuì 声母不同（s 与 sh），意思是年龄、岁数。"}], "explanations": {"睡": "shuì（第四声）指闭眼休息、身体不动，是目标词。", "水": "shuǐ（第三声）与 shuì（第四声）声调不同，意思是水。", "谁": "shuí（第二声）与 shuì（第四声）声调不同，意思是谁。", "帅": "shuài（第四声）与 shuì 韵母不同（ai 与 ui），意思是英俊、帅气。", "岁": "suì 与 shuì 声母不同（s 与 sh），意思是年龄、岁数。"}, "sentence_index": null, "correct_answer": "睡"}, "level_3": {"options": [{"text": "睡", "is_correct": true, "explanation": "睡：闭眼躺下休息，与“在沙发上”“一会儿”搭配，符合句意。"}, {"text": "游", "is_correct": false, "explanation": "搭配：“游”需要水域，沙发上不能游。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁身体或物品，在沙发上洗一会儿说不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热做熟食物，与在沙发上休息无关。"}], "explanations": {"睡": "睡：闭眼躺下休息，与“在沙发上”“一会儿”搭配，符合句意。", "游": "搭配：“游”需要水域，沙发上不能游。", "洗": "语义：“洗”指清洁身体或物品，在沙发上洗一会儿说不通。", "煮": "语义：“煮”指用水加热做熟食物，与在沙发上休息无关。"}, "sentence_index": 0, "correct_answer": "睡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他睡在路边等公交车。", "explanation": "这里应该用〈站〉。睡表示闭眼休息、不知道周围的事，等车需要清醒地看车；站在路边等车要用〈站〉。"}, {"text": "妈妈睡在窗前织毛衣。", "explanation": "这里应该用〈坐〉。睡表示入睡，织毛衣需要清醒；坐在窗前做事要用〈坐〉。"}, {"text": "他睡在台上唱歌。", "explanation": "这里应该用〈站〉。睡表示入睡，唱歌需要清醒；站在台上表演要用〈站〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89747, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "睡", "is_correct": true, "explanation": "shuì（第四声）指闭眼休息、进入睡眠，是目标词。"}, {"text": "碎", "is_correct": false, "explanation": "suì 与 shuì 声母不同（s 与 sh），意思是破碎。"}, {"text": "穗", "is_correct": false, "explanation": "suì 与 shuì 声母不同（s 与 sh），意思是谷物的穗子。"}, {"text": "锐", "is_correct": false, "explanation": "ruì 与 shuì 声母不同（r 与 sh），意思是锋利、敏锐。"}, {"text": "瑞", "is_correct": false, "explanation": "ruì 与 shuì 声母不同（r 与 sh），意思是吉祥、祥瑞。"}], "explanations": {"睡": "shuì（第四声）指闭眼休息、进入睡眠，是目标词。", "碎": "suì 与 shuì 声母不同（s 与 sh），意思是破碎。", "穗": "suì 与 shuì 声母不同（s 与 sh），意思是谷物的穗子。", "锐": "ruì 与 shuì 声母不同（r 与 sh），意思是锋利、敏锐。", "瑞": "ruì 与 shuì 声母不同（r 与 sh），意思是吉祥、祥瑞。"}, "sentence_index": null, "correct_answer": "睡"}, "level_3": {"options": [{"text": "睡", "is_correct": true, "explanation": "睡：入睡状态好，与“得很香”搭配，并与后句“没听到电话”相符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“香”形容吃、睡等舒适的状态，不能用来形容哭，“哭得很香”说不通。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑得很香”说不通，“香”不能用来形容跑步。"}, {"text": "听", "is_correct": false, "explanation": "语义：“听得很香”与后句“没听到电话”自相矛盾。"}], "explanations": {"睡": "睡：入睡状态好，与“得很香”搭配，并与后句“没听到电话”相符。", "哭": "语义：“香”形容吃、睡等舒适的状态，不能用来形容哭，“哭得很香”说不通。", "跑": "搭配：“跑得很香”说不通，“香”不能用来形容跑步。", "听": "语义：“听得很香”与后句“没听到电话”自相矛盾。"}, "sentence_index": 6, "correct_answer": "睡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一睡就起床了。", "explanation": "这里应该用〈醒〉。睡表示入睡，入睡之后不能立刻起床；醒来后起床要用〈醒〉。"}, {"text": "他睡在门口抽烟。", "explanation": "这里应该用〈蹲〉。睡表示入睡，入睡时不能抽烟；蹲在门口抽烟要用〈蹲〉。"}, {"text": "他一边睡一边打电话。", "explanation": "这里应该用〈走〉。睡表示入睡，不能同时进行打电话这类清醒的活动；边走边打电话要用〈走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我午饭后在沙发上睡觉了一会儿。", "corrected_sentence": "我午饭后在沙发上睡了一会儿。", "error_description": "“睡觉”是离合词，“觉”不能插在时段前。应说“睡了一会儿”，不能说“睡觉了一会儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨晚我睡很香，没做梦。", "corrected_sentence": "昨晚我睡得很香，没做梦。", "error_description": "表示程度的补语前要加“得”。应说“睡得很香”，不能说“睡很香”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
