INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89748, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "闭上眼睛,大脑休息,进入睡眠状态。", "primary_collocate": null, "pronunciation": "shuì", "ipa": "ʂweɪ˥˩", "syllable_count": 1, "sentences": [{"text": "我昨天晚上十一点就睡了。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天睡八个小时。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我太累了，一上床就睡。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么还不睡？已经很晚了。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她吃了药，很快就睡了。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听着音乐慢慢睡了。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我睡了一个晚上，现在好多了。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子要早点睡。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太吵，我睡不好。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我睡得很早，所以今天不累。", "target_word": "睡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "睡了", "label": "完成体"}, {"form": "睡过", "label": "经历体"}, {"form": "睡觉", "label": "复合词"}, {"form": "睡眠", "label": "复合词"}], "register": "口语", "sense_fingerprint": "进入睡眠状态，到点入睡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85beadd-467a-48ea-b48a-dbf1be933464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89748, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "睡", "is_correct": true, "explanation": "shuì（第四声）指进入睡眠状态，是目标词。"}, {"text": "水", "is_correct": false, "explanation": "shuǐ（第三声）与 shuì（第四声）声调不同，意思是水。"}, {"text": "谁", "is_correct": false, "explanation": "shuí（第二声）与 shuì（第四声）声调不同，意思是谁。"}, {"text": "帅", "is_correct": false, "explanation": "shuài（第四声）与 shuì 韵母不同（ai 与 ui），意思是英俊、帅气。"}, {"text": "岁", "is_correct": false, "explanation": "suì 与 shuì 声母不同（s 与 sh），意思是年龄、岁数。"}], "explanations": {"睡": "shuì（第四声）指进入睡眠状态，是目标词。", "水": "shuǐ（第三声）与 shuì（第四声）声调不同，意思是水。", "谁": "shuí（第二声）与 shuì（第四声）声调不同，意思是谁。", "帅": "shuài（第四声）与 shuì 韵母不同（ai 与 ui），意思是英俊、帅气。", "岁": "suì 与 shuì 声母不同（s 与 sh），意思是年龄、岁数。"}, "sentence_index": null, "correct_answer": "睡"}, "level_3": {"options": [{"text": "睡", "is_correct": true, "explanation": "睡：入睡，与“十一点就”“了”搭配，符合日常作息。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”是一次性的人生阶段，不能用在晚上十一点的日常行为中。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”是一生一次的事件，与“昨天晚上十一点就”的日常时间不搭。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指结束职业生涯，不可能发生在晚上十一点的日常时段。"}], "explanations": {"睡": "睡：入睡，与“十一点就”“了”搭配，符合日常作息。", "毕业": "语义：“毕业”是一次性的人生阶段，不能用在晚上十一点的日常行为中。", "出生": "语义：“出生”是一生一次的事件，与“昨天晚上十一点就”的日常时间不搭。", "退休": "语义：“退休”指结束职业生涯，不可能发生在晚上十一点的日常时段。"}, "sentence_index": 0, "correct_answer": "睡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他睡在桌前写字。", "explanation": "这里应该用〈站〉。睡表示入睡，与“写字”这种清醒活动矛盾；站在桌前做事要用〈站〉。"}, {"text": "我早上一睡就去跑步。", "explanation": "这里应该用〈醒〉。睡表示入睡，与之后的“去跑步”顺序矛盾；早上醒来后去跑步要用〈醒〉。"}, {"text": "奶奶睡在门口择菜。", "explanation": "这里应该用〈坐〉。睡表示入睡，择菜需要清醒；坐在门口做事要用〈坐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89748, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "睡", "is_correct": true, "explanation": "shuì（第四声）指进入睡眠状态，是目标词。"}, {"text": "碎", "is_correct": false, "explanation": "suì 与 shuì 声母不同（s 与 sh），意思是破碎。"}, {"text": "穗", "is_correct": false, "explanation": "suì 与 shuì 声母不同（s 与 sh），意思是谷物的穗子。"}, {"text": "锐", "is_correct": false, "explanation": "ruì 与 shuì 声母不同（r 与 sh），意思是锋利、敏锐。"}, {"text": "瑞", "is_correct": false, "explanation": "ruì 与 shuì 声母不同（r 与 sh），意思是吉祥、祥瑞。"}], "explanations": {"睡": "shuì（第四声）指进入睡眠状态，是目标词。", "碎": "suì 与 shuì 声母不同（s 与 sh），意思是破碎。", "穗": "suì 与 shuì 声母不同（s 与 sh），意思是谷物的穗子。", "锐": "ruì 与 shuì 声母不同（r 与 sh），意思是锋利、敏锐。", "瑞": "ruì 与 shuì 声母不同（r 与 sh），意思是吉祥、祥瑞。"}, "sentence_index": null, "correct_answer": "睡"}, "level_3": {"options": [{"text": "睡", "is_correct": true, "explanation": "睡：一个晚上的入睡，与“现在好多了”相符，表示休息后恢复。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”指争执或喧闹，与“现在好多了”的恢复语境矛盾。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物或水，“煮了一个晚上”说不通。"}, {"text": "选", "is_correct": false, "explanation": "配价：“选”需要宾语，“选了一个晚上”说不通。"}], "explanations": {"睡": "睡：一个晚上的入睡，与“现在好多了”相符，表示休息后恢复。", "吵": "语义：“吵”指争执或喧闹，与“现在好多了”的恢复语境矛盾。", "煮": "搭配：“煮”的对象是食物或水，“煮了一个晚上”说不通。", "选": "配价：“选”需要宾语，“选了一个晚上”说不通。"}, "sentence_index": 6, "correct_answer": "睡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她睡在河边洗衣服。", "explanation": "这里应该用〈蹲〉。睡表示入睡，洗衣服需要清醒；蹲在河边洗衣服要用〈蹲〉。"}, {"text": "他睡在椅子上吃午饭。", "explanation": "这里应该用〈坐〉。睡表示进入睡眠状态，吃饭需要清醒；坐在椅子上吃饭要用〈坐〉。"}, {"text": "他睡在墙边读报。", "explanation": "这里应该用〈靠〉。睡表示入睡，读报需要清醒；靠着墙读报要用〈靠〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一躺下就睡了着。", "corrected_sentence": "他一躺下就睡着了。", "error_description": "结果补语“着”要紧跟动词，应说“睡着了”，不能说“睡了着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天晚上睡没好。", "corrected_sentence": "我昨天晚上没睡好。", "error_description": "否定副词“没”要放在动词前，应说“没睡好”，不能说“睡没好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
