INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89749, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "吸引力是让人想靠近、想看的那种力量。", "primary_collocate": null, "pronunciation": "xī yǐn lì", "ipa": "ɕi˥ in˨˩˦ li˥˩", "syllable_count": 3, "sentences": [{"text": "这家店的灯很漂亮，很有吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的封面对孩子有吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红色的包对女孩子很有吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小公园对老人有吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的笑容有一种吸引力。", "target_word": "吸引力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部电影的海报没有吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新鲜的水果对小朋友有吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片的颜色很有吸引力，大家都停下来看。", "target_word": "吸引力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱歌的声音很有吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家餐厅的门口很有吸引力，我想进去看看。", "target_word": "吸引力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种吸引力", "label": "量词"}], "register": "中性", "sense_fingerprint": "事物让人想靠近、想看的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc84aebc-8278-4ecb-bb1f-1683bde98033') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89749, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吸引力", "is_correct": true, "explanation": "正确：“很有吸引力”说灯让人想看、想靠近，与“很漂亮”相符。"}, {"text": "压力", "is_correct": false, "explanation": "语义：“压力”指使人紧张的负担，灯不会给人压力，与“很漂亮”的语境不合。"}, {"text": "能力", "is_correct": false, "explanation": "搭配：“很有能力”的主语应是人，灯没有能力，不能这样说。"}, {"text": "责任", "is_correct": false, "explanation": "语义：“责任”指应承担的义务，灯不承担责任，与句意不符。"}], "explanations": {"吸引力": "正确：“很有吸引力”说灯让人想看、想靠近，与“很漂亮”相符。", "压力": "语义：“压力”指使人紧张的负担，灯不会给人压力，与“很漂亮”的语境不合。", "能力": "搭配：“很有能力”的主语应是人，灯没有能力，不能这样说。", "责任": "语义：“责任”指应承担的义务，灯不承担责任，与句意不符。"}, "sentence_index": 0, "correct_answer": "吸引力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公司里很有吸引力，大家都听他的。", "explanation": "这里应该用〈影响力〉。吸引力指让人想靠近、想看的力量，不指让人听从的作用。"}, {"text": "这位队长的吸引力很强，一呼百应。", "explanation": "这里应该用〈号召力〉。号召力指召集、带动大家行动的力量；吸引力只说让人靠近、注意。"}, {"text": "这个学生的吸引力很强，一节课能专心听两个小时。", "explanation": "这里应该用〈注意力〉。注意力指集中精神的能力；吸引力指让人想靠近、想看，不指专心听讲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89749, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸引力", "is_correct": true, "explanation": "正确：水果新鲜、小朋友喜欢，所以说水果对小朋友有吸引力。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，水果没有脾气，不能对小朋友有脾气。"}, {"text": "信心", "is_correct": false, "explanation": "语义：“信心”是人对自己或事情的确信，水果不能对小朋友有信心。"}, {"text": "义务", "is_correct": false, "explanation": "语义：“义务”指人应尽的责任，水果不承担义务，与句意不符。"}], "explanations": {"吸引力": "正确：水果新鲜、小朋友喜欢，所以说水果对小朋友有吸引力。", "脾气": "语义：“脾气”指人的性情，水果没有脾气，不能对小朋友有脾气。", "信心": "语义：“信心”是人对自己或事情的确信，水果不能对小朋友有信心。", "义务": "语义：“义务”指人应尽的责任，水果不承担义务，与句意不符。"}, "sentence_index": 6, "correct_answer": "吸引力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的吸引力很强，背课文一遍就记住了。", "explanation": "这里应该用〈记忆力〉。吸引力指让人想靠近、想看，不指记住东西的能力。"}, {"text": "他做事很有吸引力，敢拍板。", "explanation": "这里应该用〈魄力〉。吸引力指让人想靠近、想看，不指做事的果断。"}, {"text": "这台吸尘器的吸引力很大，地毯上的灰都吸进去了。", "explanation": "这里应该用〈吸力〉。吸引力指让人想靠近的力量，吸尘器的抽吸作用要用〈吸力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅画有一只吸引力，很多人愿意停下来看。", "corrected_sentence": "这幅画有一种吸引力，很多人愿意停下来看。", "error_description": "量词错误：“吸引力”前应用〈种〉，〈只〉用于动物等具体事物，不能用于“吸引力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89749, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家书店的橱窗很吸引力，路过的人都会停下来。", "corrected_sentence": "这家书店的橱窗很有吸引力，路过的人都会停下来。", "error_description": "错误形式：“很吸引力”，漏掉了“有”；正确形式：“很有吸引力”。“吸引力”是名词，“很”不能直接修饰它，需要用“很有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
