INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使人喜爱、注意或向往的力量。", "primary_collocate": null, "pronunciation": "xī yǐn lì", "ipa": "ɕi˥ in˨˩˦ li˥˩", "syllable_count": 3, "sentences": [{"text": "大城市对年轻人有很大的吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作的工资高，对我很有吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行对他来说有很大的吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的文化有特别的吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的广告要有吸引力，才能让人注意。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家对留学生的吸引力越来越大。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司对好学生很有吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校想提高对学生的吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时间久了，这个游戏失去了吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话很有意思，对大家有吸引力。", "target_word": "吸引力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种吸引力", "label": "量词"}], "register": "中性", "sense_fingerprint": "使人喜爱、注意或向往的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc84aebc-8278-4ecb-bb1f-1683bde98033') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吸引力", "is_correct": true, "explanation": "正确：“很大的吸引力”说大城市让年轻人向往，与句意相符。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”指平面的大小，不能用来说城市对年轻人的作用。"}, {"text": "手术", "is_correct": false, "explanation": "语义：“手术”是医疗行为，大城市对年轻人不能有“很大的手术”。"}, {"text": "地震", "is_correct": false, "explanation": "语义：“地震”是自然灾害，不能说大城市对年轻人有“很大的地震”。"}], "explanations": {"吸引力": "正确：“很大的吸引力”说大城市让年轻人向往，与句意相符。", "面积": "语义：“面积”指平面的大小，不能用来说城市对年轻人的作用。", "手术": "语义：“手术”是医疗行为，大城市对年轻人不能有“很大的手术”。", "地震": "语义：“地震”是自然灾害，不能说大城市对年轻人有“很大的地震”。"}, "sentence_index": 0, "correct_answer": "吸引力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位校长的吸引力很大，他一句话就能改变学校的规定。", "explanation": "这里应该用〈影响力〉。吸引力指让人喜爱、向往，不指让人听从、改变决定的作用。"}, {"text": "这位社长的吸引力很强，一呼百应。", "explanation": "这里应该用〈号召力〉。号召力指带动大家行动，吸引力指让人喜爱、向往。"}, {"text": "这位同学的吸引力很强，一堂课的内容都能背下来。", "explanation": "这里应该用〈记忆力〉。吸引力指使人喜爱、注意或向往的力量，不指记住内容的能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸引力", "is_correct": true, "explanation": "正确：“很有吸引力”说这家公司让好学生向往，与句意相符。"}, {"text": "力气", "is_correct": false, "explanation": "语义：“力气”指身体的力量，公司对学生不能用“很有力气”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人身体的温度，“对好学生很有体温”不成话，与句意不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指大气的冷暖阴晴，公司不是天气，句子不通。"}], "explanations": {"吸引力": "正确：“很有吸引力”说这家公司让好学生向往，与句意相符。", "力气": "语义：“力气”指身体的力量，公司对学生不能用“很有力气”。", "体温": "语义：“体温”指人身体的温度，“对好学生很有体温”不成话，与句意不符。", "天气": "语义：“天气”指大气的冷暖阴晴，公司不是天气，句子不通。"}, "sentence_index": 6, "correct_answer": "吸引力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学生的吸引力很强，老师讲一遍就懂了。", "explanation": "这里应该用〈理解力〉。吸引力指让人喜爱、向往，不指理解问题的能力。"}, {"text": "这位主管做事很有吸引力，敢做决定。", "explanation": "这里应该用〈魄力〉。吸引力指让人喜爱、向往，不指做事的果断。"}, {"text": "这台吸尘器的吸引力很大，连沙发缝里的灰都吸出来了。", "explanation": "这里应该用〈吸力〉。吸尘器的抽吸作用要用〈吸力〉，吸引力指让人喜爱、向往。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个节目对年轻人很吸引力，收视率很高。", "corrected_sentence": "这个节目对年轻人很有吸引力，收视率很高。", "error_description": "错误形式：“很吸引力”，漏掉了“有”；正确形式：“很有吸引力”。“吸引力”是名词，“很”不能直接修饰它，需要用“很有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目有一只吸引力，很多人愿意看。", "corrected_sentence": "这个节目有一种吸引力，很多人愿意看。", "error_description": "量词错误：“吸引力”的量词应为〈种〉或〈股〉，〈只〉用于动物等具体事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
