INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89751, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脸上眼睛上面的地方。", "primary_collocate": null, "pronunciation": "é", "ipa": "ɤ˧˥", "syllable_count": 1, "sentences": [{"text": "他的额上有一颗小痣。", "target_word": "额", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他热得额上直冒汗。", "target_word": "额", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子摔了一跤，额上起了个包。", "target_word": "额", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一阵风吹过，她额上的头发轻轻飘起。", "target_word": "额", "complexity_tier": "T3", "furigana": "yí zhèn fēng chuī guò, tā é shàng de tóu fà qīng qīng piāo qǐ.", "sentence_source": "generated"}, {"text": "他皱起眉头，额上出现了三道线。", "target_word": "额", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟在我的额上画了一朵花。", "target_word": "额", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的额很白，像雪一样。", "target_word": "额", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把帽子往下拉，遮住了额上的伤。", "target_word": "额", "complexity_tier": "T3", "furigana": "tā bǎ mào zi wǎng xià lā, zhē zhù le é shàng de shāng.", "sentence_source": "generated"}, {"text": "运动以后，他的额红红的。", "target_word": "额", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗的额上有一块白毛。", "target_word": "额", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "額", "label": "繁体"}, {"form": "额头", "label": "复合"}, {"form": "前额", "label": "复合"}], "register": "书面", "sense_fingerprint": "脸上眼睛和眉毛上方的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30511e17-00b3-46ac-a6ac-77252451a420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89751, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "额", "is_correct": true, "explanation": "额（第二声）指脸上眼睛上方的位置。"}, {"text": "饿", "is_correct": false, "explanation": "è（第四声）与 é（第二声）声调不同，意思是饿。"}, {"text": "哦", "is_correct": false, "explanation": "ó 与 é 韵母不同，“哦”是感叹词。"}, {"text": "恶", "is_correct": false, "explanation": "è（第四声）与 é（第二声）声调不同，意思是厌恶、丑恶。"}], "explanations": {"额": "额（第二声）指脸上眼睛上方的位置。", "饿": "è（第四声）与 é（第二声）声调不同，意思是饿。", "哦": "ó 与 é 韵母不同，“哦”是感叹词。", "恶": "è（第四声）与 é（第二声）声调不同，意思是厌恶、丑恶。"}, "sentence_index": null, "correct_answer": "额"}, "level_3": {"options": [{"text": "额", "is_correct": true, "explanation": "额指眼睛上方的位置，“他的额上有一颗小痣”符合句意。"}, {"text": "桌", "is_correct": false, "explanation": "语义：桌子上有痣不合常理，痣长在人身上。"}, {"text": "窗", "is_correct": false, "explanation": "语义：窗户上不会长痣，痣长在人身上。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：痣不长在鞋上，“鞋上有一颗小痣”不这么说。"}], "explanations": {"额": "额指眼睛上方的位置，“他的额上有一颗小痣”符合句意。", "桌": "语义：桌子上有痣不合常理，痣长在人身上。", "窗": "语义：窗户上不会长痣，痣长在人身上。", "鞋": "搭配：痣不长在鞋上，“鞋上有一颗小痣”不这么说。"}, "sentence_index": 0, "correct_answer": "额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的额浓浓的，很有精神。", "explanation": "这里应该用〈眉毛〉。“浓”形容眉毛，额上不能说“浓”。"}, {"text": "他的额又高又挺，很有特点。", "explanation": "这里应该用〈鼻子〉。“又高又挺”形容鼻子，额不能这样形容。"}, {"text": "她的额又长又软，像只小兔子。", "explanation": "这里应该用〈耳朵〉。“又长又软，像只小兔子”形容耳朵，额不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89751, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "额", "is_correct": true, "explanation": "额（第二声）指脸上眼睛上方的位置。"}, {"text": "儿", "is_correct": false, "explanation": "ér 只比 é 多了卷舌韵尾 r，意思是儿子、孩子。"}, {"text": "而", "is_correct": false, "explanation": "ér 与 é 只差卷舌韵尾 r，意思是“而且”。"}, {"text": "厄", "is_correct": false, "explanation": "è（第四声）与 é（第二声）声调不同，意思是困境、灾难。"}, {"text": "扼", "is_correct": false, "explanation": "è（第四声）与 é（第二声）声调不同，意思是掐住、扼制。"}], "explanations": {"额": "额（第二声）指脸上眼睛上方的位置。", "儿": "ér 只比 é 多了卷舌韵尾 r，意思是儿子、孩子。", "而": "ér 与 é 只差卷舌韵尾 r，意思是“而且”。", "厄": "è（第四声）与 é（第二声）声调不同，意思是困境、灾难。", "扼": "è（第四声）与 é（第二声）声调不同，意思是掐住、扼制。"}, "sentence_index": null, "correct_answer": "额"}, "level_3": {"options": [{"text": "额", "is_correct": true, "explanation": "额指眼睛上方的位置，“她的额很白，像雪一样”符合句意。"}, {"text": "雪", "is_correct": false, "explanation": "语义：“她的雪”不合常理，雪不能属于人。"}, {"text": "冰", "is_correct": false, "explanation": "搭配：“她的冰很白”说不通，冰不属于人。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能用颜色“白”来形容，“她的声音很白”句意不通。"}], "explanations": {"额": "额指眼睛上方的位置，“她的额很白，像雪一样”符合句意。", "雪": "语义：“她的雪”不合常理，雪不能属于人。", "冰": "搭配：“她的冰很白”说不通，冰不属于人。", "声音": "语义：声音不能用颜色“白”来形容，“她的声音很白”句意不通。"}, "sentence_index": 6, "correct_answer": "额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的额很大，能跳得很高。", "explanation": "这里应该用〈腿〉。“能跳得很高”形容腿，额不能这样形容。"}, {"text": "他的额很厚，能扛起一袋米。", "explanation": "这里应该用〈肩膀〉。“能扛起一袋米”形容肩膀，额不能这样形容。"}, {"text": "她的额很长，能弹好几首钢琴曲。", "explanation": "这里应该用〈手指〉。“能弹好几首钢琴曲”形容手指，额不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他额的上有一颗痣，很显眼。", "corrected_sentence": "他额上有一颗痣，很显眼。", "error_description": "“额上”是方位词组，“额”与“上”之间不能加“的”。错误：额的上；正确：额上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她跑完步，额里的头发都湿了。", "corrected_sentence": "她跑完步，额上的头发都湿了。", "error_description": "方位词错误：额是身体表面，要说“额上”，不能说“额里”。错误：额里；正确：额上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
