INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89752, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "眉毛以上、头发以下的部分；前额。", "primary_collocate": null, "pronunciation": "é", "ipa": "ɤ˧˥", "syllable_count": 1, "sentences": [{"text": "他的额上全是汗。", "target_word": "额", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的额上有几根碎发。", "target_word": "额", "complexity_tier": "T3", "furigana": "tā de é shàng yǒu jǐ gēn suì fà.", "sentence_source": "generated"}, {"text": "老人的额上有很深的皱纹。", "target_word": "额", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生的手按在他的额上，说他有点发烧。", "target_word": "额", "complexity_tier": "T3", "furigana": "yī shēng de shǒu àn zài tā de é shàng, shuō tā yǒu diǎn fā shāo.", "sentence_source": "generated"}, {"text": "他的额很宽，眼睛很大。", "target_word": "额", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "汗从他的额上流了下来。", "target_word": "额", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她额上贴着一块白布。", "target_word": "额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他额上有一道长长的疤。", "target_word": "额", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她用手擦了擦额上的汗。", "target_word": "额", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈俯下身，在孩子的额上亲了一下。", "target_word": "额", "complexity_tier": "T3", "furigana": "mā ma fǔ xià shēn, zài hái zi de é shàng qīn le yí xià.", "sentence_source": "generated"}], "morphological_forms": [{"form": "額", "label": "繁体"}, {"form": "额头", "label": "复合"}, {"form": "前额", "label": "复合"}], "register": "书面", "sense_fingerprint": "人脸上眉毛以上、头发以下的部位，即前额", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30511e17-00b3-46ac-a6ac-77252451a420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89752, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "额", "is_correct": true, "explanation": "额（第二声）指眉毛以上、头发以下的部位，即前额。"}, {"text": "饿", "is_correct": false, "explanation": "è（第四声）与 é（第二声）声调不同，意思是饿。"}, {"text": "哦", "is_correct": false, "explanation": "ó 与 é 韵母不同，“哦”是感叹词。"}, {"text": "恶", "is_correct": false, "explanation": "è（第四声）与 é（第二声）声调不同，意思是厌恶、丑恶。"}], "explanations": {"额": "额（第二声）指眉毛以上、头发以下的部位，即前额。", "饿": "è（第四声）与 é（第二声）声调不同，意思是饿。", "哦": "ó 与 é 韵母不同，“哦”是感叹词。", "恶": "è（第四声）与 é（第二声）声调不同，意思是厌恶、丑恶。"}, "sentence_index": null, "correct_answer": "额"}, "level_3": {"options": [{"text": "额", "is_correct": true, "explanation": "额指前额，“他的额上全是汗”符合句意。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不会出汗，“上全是汗”说的是人的身体部位。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不会出汗，句中的人才是出汗的主体。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：“鞋上全是汗”不这么说，汗多附着在人的身体上。"}], "explanations": {"额": "额指前额，“他的额上全是汗”符合句意。", "书": "语义：书不会出汗，“上全是汗”说的是人的身体部位。", "墙": "语义：墙不会出汗，句中的人才是出汗的主体。", "鞋": "搭配：“鞋上全是汗”不这么说，汗多附着在人的身体上。"}, "sentence_index": 0, "correct_answer": "额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的额又细又弯。", "explanation": "这里应该用〈眉毛〉。“又细又弯”形容眉毛，额是眉毛以上的部位，不能这样形容。"}, {"text": "他的额又粗又短，像个运动员。", "explanation": "这里应该用〈脖子〉。“又粗又短”形容脖子，额不能这样形容。"}, {"text": "他的额又大又厚，能一口气吃下三碗饭。", "explanation": "这里应该用〈胃口〉。“能一口气吃下三碗饭”形容胃口，额不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89752, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "额", "is_correct": true, "explanation": "额（第二声）指眉毛以上、头发以下的部位，即前额。"}, {"text": "儿", "is_correct": false, "explanation": "ér 只比 é 多了卷舌韵尾 r，意思是儿子、孩子。"}, {"text": "而", "is_correct": false, "explanation": "ér 与 é 只差卷舌韵尾 r，意思是“而且”。"}, {"text": "厄", "is_correct": false, "explanation": "è（第四声）与 é（第二声）声调不同，意思是困境、灾难。"}, {"text": "扼", "is_correct": false, "explanation": "è（第四声）与 é（第二声）声调不同，意思是掐住、扼制。"}], "explanations": {"额": "额（第二声）指眉毛以上、头发以下的部位，即前额。", "儿": "ér 只比 é 多了卷舌韵尾 r，意思是儿子、孩子。", "而": "ér 与 é 只差卷舌韵尾 r，意思是“而且”。", "厄": "è（第四声）与 é（第二声）声调不同，意思是困境、灾难。", "扼": "è（第四声）与 é（第二声）声调不同，意思是掐住、扼制。"}, "sentence_index": null, "correct_answer": "额"}, "level_3": {"options": [{"text": "额", "is_correct": true, "explanation": "额指前额，“她额上贴着一块白布”符合句意。"}, {"text": "天", "is_correct": false, "explanation": "语义：“天”不能被“她”拥有，也不能贴白布。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能被“她”拥有，句意不通。"}, {"text": "云", "is_correct": false, "explanation": "搭配：云上不能“贴”东西，“贴着一块白布”与云不搭配。"}], "explanations": {"额": "额指前额，“她额上贴着一块白布”符合句意。", "天": "语义：“天”不能被“她”拥有，也不能贴白布。", "水": "语义：水不能被“她”拥有，句意不通。", "云": "搭配：云上不能“贴”东西，“贴着一块白布”与云不搭配。"}, "sentence_index": 6, "correct_answer": "额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的额很尖，像个小尖刀。", "explanation": "这里应该用〈下巴〉。“很尖”形容下巴，额不能这样形容。"}, {"text": "他的额又长又细，很灵巧。", "explanation": "这里应该用〈手指〉。“又长又细、很灵巧”形容手指，额不能这样形容。"}, {"text": "他吃多了，额胀得直不起腰。", "explanation": "这里应该用〈肚子〉。“胀得直不起腰”形容肚子，额不能这样胀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e08a4f1-4df4-4e50-a772-ae4229890b9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
